+  <script>
+    (() => {
+      const viewport = document.querySelector('.pan-viewport');
+      if (!viewport) return;
+
+      // Center map initially on Downtown Roastery
+      const centerOnCard = (card, smooth = false) => {
+        if (!card) return;
+        const targetLeft = card.offsetLeft + card.offsetWidth / 2 - viewport.clientWidth / 2;
+        const targetTop = card.offsetTop + card.offsetHeight / 2 - viewport.clientHeight / 2;
+        if (smooth && 'scrollTo' in viewport) {
+          viewport.scrollTo({ left: targetLeft, top: targetTop, behavior: 'smooth' });
+        } else {
+          viewport.scrollLeft = targetLeft;
+          viewport.scrollTop = targetTop;
+        }
+      };
+
+      const initialCard = document.getElementById('loc-roastery');
+      centerOnCard(initialCard, false);
+
+      // Jump pills navigation
+      const pills = document.querySelectorAll('.jump-pill');
+      pills.forEach((pill) => {
+        pill.addEventListener('click', () => {
+          pills.forEach((p) => p.setAttribute('aria-pressed', 'false'));
+          pill.setAttribute('aria-pressed', 'true');
+          const targetId = pill.getAttribute('data-target');
+          const targetCard = document.getElementById(targetId);
+          centerOnCard(targetCard, true);
+        });
+      });
+
+      // Only attach the main-thread gesture fallback when native scroll-axis-lock support is missing
+      if (!CSS.supports('scroll-axis-lock', 'none')) {
+        let lastPointer = null;
+
+        // 1. Trackpad and mouse wheel fallback
+        viewport.addEventListener(
+          'wheel',
+          (e) => {
+            if (e.ctrlKey) return; // Ctrl+wheel and trackpad pinch zoom the page
+            e.preventDefault();
+            viewport.scrollLeft += e.deltaX;
+            viewport.scrollTop += e.deltaY;
+          },
+          { passive: false }
+        );
+
+        // 2. Touch and pointer drag fallback
+        viewport.addEventListener('pointerdown', (e) => {
+          // Ignore interactive links inside the map or non-primary buttons / native scrollbars
+          if (e.target.closest('a, button')) return;
+          const rect = viewport.getBoundingClientRect();
+          if (
+            !e.isPrimary ||
+            e.button !== 0 ||
+            e.clientX - rect.left - viewport.clientLeft >= viewport.clientWidth ||
+            e.clientY - rect.top - viewport.clientTop >= viewport.clientHeight
+          ) {
+            return;
+          }
+          lastPointer = { x: e.clientX, y: e.clientY };
+          viewport.classList.add('is-panning');
+          viewport.setPointerCapture(e.pointerId);
+        });
+
+        viewport.addEventListener('pointermove', (e) => {
+          if (!lastPointer) return;
+          viewport.scrollLeft -= e.clientX - lastPointer.x;
+          viewport.scrollTop -= e.clientY - lastPointer.y;
+          lastPointer = { x: e.clientX, y: e.clientY };
+        });
+
+        const endPointerPan = () => {
+          lastPointer = null;
+          viewport.classList.remove('is-panning');
+        };
+        viewport.addEventListener('pointerup', endPointerPan);
+        viewport.addEventListener('pointercancel', endPointerPan);
+      }
+    })();
+  </script>
 </body>

