+      if (!faqSection) return;
+
+      const items = Array.from(faqSection.querySelectorAll('.accordion-item'));
+
+      function setItemState(item, isOpen) {
+        const trigger = item.querySelector('.accordion-trigger');
+        const panel = item.querySelector('.accordion-panel');
+        item.classList.toggle('active', isOpen);
+        trigger.setAttribute('aria-expanded', String(isOpen));
+        panel.style.maxHeight = isOpen ? panel.scrollHeight + 'px' : '0px';
+      }
+
+      // Initialize panel heights
+      items.forEach((item) => {
+        setItemState(item, item.classList.contains('active'));
+      });
+
+      items.forEach((item) => {
+        const trigger = item.querySelector('.accordion-trigger');
+        trigger.addEventListener('click', () => {
+          const isCurrentlyOpen = item.classList.contains('active');
+          items.forEach((otherItem) => {
+            setItemState(otherItem, otherItem === item ? !isCurrentlyOpen : false);
+          });
+        });
+      });
+
+      window.addEventListener('resize', () => {
+        const activeItem = faqSection.querySelector('.accordion-item.active');
+        if (activeItem) {
+          const panel = activeItem.querySelector('.accordion-panel');
