+          .replace(/"/g, '&quot;')
+          .replace(/'/g, '&#39;');
+      }
+
+      const form = document.getElementById('coffee-quick-order-form');
+      const resultContainer = document.getElementById('order-result');
+
+      if (!form || !resultContainer) return;
+
+      form.addEventListener('submit', function (event) {
+        event.preventDefault();
+
+        const formData = new FormData(form);
+        const rawDrink = (formData.get('drink') || 'maple-oat-latte').toString();
+        const roast = (formData.get('roast') || 'medium').toString();
+        const temperature = (formData.get('temperature') || 'hot').toString();
+        const size = (formData.get('size') || 'medium').toString();
+        const milk = (formData.get('milk') || 'oat').toString();
+        const sweetness = (formData.get('sweetness') || 'maple').toString();
+        const quantity = Math.max(1, parseInt(formData.get('quantity'), 10) || 1);
+        const customerName = (formData.get('customer_name') || '').toString().trim() || 'Valued Guest';
+        const notes = (formData.get('notes') || '').toString().trim();
+
+        const matchedDrink = resolveRecommendedDrink(rawDrink, roast, temperature, sweetness);
+        const unitPrice = matchedDrink.basePrice + (SIZE_UPCHARGE[size] || 0);
+        const totalPrice = (unitPrice * quantity).toFixed(2);
+        const orderId = 'DG-' + Math.floor(100000 + Math.random() * 900000);
+
+        const orderSummary = {
+          status: 'confirmed',
+          orderId: orderId,
+          agentInvoked: Boolean(event.agentInvoked),
+          customerName: customerName,
+          drink: matchedDrink.name,
+          drinkId: matchedDrink.key,
+          roast: roast,
+          temperature: temperature,
+          size: size,
+          milk: milk,
+          sweetness: sweetness,
+          quantity: quantity,
+          totalPrice: '$' + totalPrice,
+          tastingNotes: matchedDrink.tastingNotes,
+          notes: notes || 'Standard preparation',
+          estimatedPickupMinutes: 5 + Math.min(10, quantity * 2)
+        };
+
+        resultContainer.innerHTML =
+          '<h3>Order Ready for Pickup Soon <span class="order-badge">' + escapeHtml(orderSummary.orderId) + '</span></h3>' +
+          '<p><strong>Matched Beverage:</strong> ' + escapeHtml(orderSummary.drink) + ' &mdash; <em>' + escapeHtml(orderSummary.tastingNotes) + '</em></p>' +
+          '<div class="order-result-details">' +
+            '<div><strong>Customer:</strong> ' + escapeHtml(orderSummary.customerName) + '</div>' +
+            '<div><strong>Customization:</strong> ' + escapeHtml(orderSummary.size) + ', ' + escapeHtml(orderSummary.temperature) + ', ' + escapeHtml(orderSummary.roast) + ' roast</div>' +
+            '<div><strong>Milk &amp; Flavor:</strong> ' + escapeHtml(orderSummary.milk) + ' milk, ' + escapeHtml(orderSummary.sweetness) + '</div>' +
+            '<div><strong>Quantity &amp; Total:</strong> ' + escapeHtml(orderSummary.quantity) + ' &times; $' + unitPrice.toFixed(2) + ' = <strong>' + escapeHtml(orderSummary.totalPrice) + '</strong></div>' +
+            '<div><strong>Notes:</strong> ' + escapeHtml(orderSummary.notes) + '</div>' +
+            '<div><strong>Est. Prep Time:</strong> ~' + escapeHtml(orderSummary.estimatedPickupMinutes) + ' mins</div>' +
+          '</div>';
+        resultContainer.classList.add('visible');
+
+        if (typeof event.respondWith === 'function') {
+          event.respondWith(Promise.resolve(orderSummary));
+        }
+      });
+
+      form.addEventListener('reset', function () {
+        resultContainer.classList.remove('visible');
+        resultContainer.innerHTML = '';
+      });
+    })();
+  </script>
