+        5: 'Level 5: Dark Espresso Roast'
+      };
+
+      function updateSliderProgress() {
+        const min = Number(roastSlider.min) || 1;
+        const max = Number(roastSlider.max) || 5;
+        const val = Number(roastSlider.value) || 3;
+        const pct = ((val - min) / (max - min)) * 100;
+        roastSlider.style.setProperty('--progress', `${pct}%`);
+        roastOutput.textContent = roastNames[val] || `Level ${val}`;
+      }
+
+      function updateSetupProgress(submitted = false) {
+        if (submitted) {
+          progressBar.value = 100;
+          progressBar.textContent = '100%';
+          progressLabel.textContent = '100% Complete';
+          return;
+        }
+        const hasFrequency = Array.from(frequencyRadios).some((r) => r.checked);
+        const hasRoast = Boolean(roastSlider.value);
+        const hasEmailChoice = emailCheckbox.checked;
+
+        let score = 25;
+        if (hasFrequency) score += 25;
+        if (hasRoast) score += 25;
+        if (hasEmailChoice) score += 25;
+
+        progressBar.value = score;
+        progressBar.textContent = `${score}%`;
+        progressLabel.textContent = `${score}% Complete`;
+      }
+
+      roastSlider.addEventListener('input', () => {
+        updateSliderProgress();
+        feedback.textContent = '';
+        updateSetupProgress(false);
+      });
+
+      frequencyRadios.forEach((radio) => {
+        radio.addEventListener('change', () => {
+          feedback.textContent = '';
+          updateSetupProgress(false);
+        });
+      });
+
+      emailCheckbox.addEventListener('change', () => {
+        feedback.textContent = '';
+        updateSetupProgress(false);
+      });
+
