+        barBestAroma.style.width = `${p.aroma}%`;
+      }
+
+      function renderResultsTable(blends) {
+        const query = (blendFilterInput.value || '').trim().toLowerCase();
+        const filtered = blends.filter((b) => {
+          if (!query) return true;
+          const inName = b.name.toLowerCase().includes(query) || b.id.toLowerCase().includes(query);
+          const inOrigins = b.components.some((c) => c.origin.toLowerCase().includes(query));
+          const inNotes = b.notes.some((n) => n.toLowerCase().includes(query));
+          return inName || inOrigins || inNotes;
+        });
+
+        if (filtered.length === 0) {
+          resultsTableBody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 20px; color: var(--muted);">No simulated blends match "${blendFilterInput.value}".</td></tr>`;
+          return;
+        }
+
+        const rowsHtml = filtered.map((b, idx) => {
+          const originsStr = b.components.map((c) => `${c.percentage}% ${c.origin}`).join(', ');
+          const notesHtml = b.notes.map((n) => `<span class="note-tag">${n}</span>`).join('');
+          return `
+            <tr>
+              <td><strong>#${idx + 1}</strong></td>
+              <td>
+                <strong>${b.name}</strong>
+                <div style="font-size: 0.75rem; color: var(--muted);">${b.id}</div>
+              </td>
+              <td>${originsStr}</td>
+              <td>Roast ${b.roastLevel} &middot; ${b.grindMicrons}&mu;m</td>
+              <td>${b.extractionYield}% Yield &middot; ${b.tds}% TDS</td>
+              <td>${notesHtml}</td>
+              <td><span class="score-pill">${b.matchScore}%</span></td>
+            </tr>
+          `;
+        }).join('');
+
+        resultsTableBody.innerHTML = rowsHtml;
+      }
+
+      blendFilterInput.addEventListener('input', () => {
+        renderResultsTable(currentTopBlends);
+      });
+
+      function createSimulationWorker() {
+        try {
+          return new Worker('simulator-worker.js');
+        } catch (err) {
+          return null;
+        }
+      }
+
+      function getSimulationConfig() {
+        return {
+          batchSize: Number(batchSizeSelect.value) || 10000,
+          brewMethod: brewMethodSelect.value,
+          roastLevel: Number(roastLevelInput.value),
+          targetAcidity: Number(targetAcidity.value),
+          targetBody: Number(targetBody.value),
+          targetSweetness: Number(targetSweetness.value),
+          targetBitterness: Number(targetBitterness.value),
+          seed: 20261118 + (runSeedCounter++) * 7919
+        };
+      }
+
+      function applyProgressToDom(data) {
+        const pct = data.progressPct;
+        progressPct.textContent = `${pct}%`;
+        progressEl.value = pct;
+        progressAria.setAttribute('aria-valuenow', String(pct));
+        progressFill.style.width = `${pct}%`;
+        processedCountEl.textContent = data.processed.toLocaleString();
+        batchTotalEl.textContent = data.batchSize.toLocaleString();
+        elapsedTimeEl.textContent = `${data.elapsedMs} ms`;
+        const rate = Math.round((data.processed / Math.max(1, data.elapsedMs)) * 1000);
+        throughputRateEl.textContent = `${rate.toLocaleString()} blends/s`;
+        statusText.textContent = `Simulating batch recipes in background worker... (${data.processed.toLocaleString()} / ${data.batchSize.toLocaleString()})`;
+        if (data.bestScoreSoFar) {
+          statBestScore.textContent = `${data.bestScoreSoFar}%`;
+        }
+        if (data.currentBestBlend) {
+          updateBestBlendVisualizer(data.currentBestBlend);
+        }
+      }
+
+      function handleWorkerMessage(e) {
+        const data = e.data;
+        if (!data) return;
+
+        if (data.type === 'PROGRESS') {
+          latestProgressData = data;
+          if (!pendingRafProgress) {
+            pendingRafProgress = requestAnimationFrame(() => {
+              pendingRafProgress = null;
+              if (isSimulating && latestProgressData) {
+                applyProgressToDom(latestProgressData);
+              }
+            });
+          }
+        } else if (data.type === 'COMPLETE') {
+          isSimulating = false;
+          if (pendingRafProgress) {
+            cancelAnimationFrame(pendingRafProgress);
+            pendingRafProgress = null;
+          }
+          runBtn.disabled = false;
+          runBtn.textContent = 'Simulate Flavor Profiles';
+          cancelBtn.disabled = true;
+
+          progressPct.textContent = '100%';
+          progressEl.value = 100;
+          progressAria.setAttribute('aria-valuenow', '100');
+          progressFill.style.width = '100%';
+          processedCountEl.textContent = data.batchSize.toLocaleString();
+          batchTotalEl.textContent = data.batchSize.toLocaleString();
+          elapsedTimeEl.textContent = `${data.elapsedMs} ms`;
+          const rate = Math.round((data.batchSize / Math.max(1, data.elapsedMs)) * 1000);
+          throughputRateEl.textContent = `${rate.toLocaleString()} blends/s`;
+
+          statusText.textContent = `Completed simulation of ${data.batchSize.toLocaleString()} recipe blends in ${data.elapsedMs} ms`;
+          statusBadge.textContent = 'Completed';
+          statusBadge.style.color = 'var(--success)';
+          threadStatusText.textContent = 'Main Thread Responsive (0 ms Blocking)';
+
+          statTotalBlends.textContent = data.summary.totalBlends.toLocaleString();
+          statBestScore.textContent = `${data.summary.bestMatchScore}%`;
+          statAvgYield.textContent = `${data.summary.avgExtractionYield}%`;
+          statHighMatch.textContent = data.summary.highMatchCount.toLocaleString();
+
+          currentTopBlends = data.topBlends || [];
+          if (currentTopBlends.length > 0) {
+            updateBestBlendVisualizer(currentTopBlends[0]);
+          }
+          renderResultsTable(currentTopBlends);
+        } else if (data.type === 'CANCELLED') {
+          isSimulating = false;
+          runBtn.disabled = false;
+          runBtn.textContent = 'Simulate Flavor Profiles';
+          cancelBtn.disabled = true;
+          statusText.textContent = `Simulation stopped at ${data.processed.toLocaleString()} / ${data.batchSize.toLocaleString()} blends`;
+          statusBadge.textContent = 'Stopped';
+          statusBadge.style.color = '#d84315';
+          threadStatusText.textContent = 'Main Thread Responsive (Worker Idle)';
+        }
+      }
+
+      function startBatchSimulation() {
+        if (isSimulating) return;
+        isSimulating = true;
+
+        const config = getSimulationConfig();
+        runBtn.disabled = true;
+        runBtn.textContent = 'Simulating Batch...';
+        cancelBtn.disabled = false;
+
+        statusBadge.textContent = 'Running in Worker';
+        statusBadge.style.color = '#e65100';
+        threadStatusText.textContent = 'Worker Active · Main Thread Unblocked';
+        progressPct.textContent = '0%';
+        progressEl.value = 0;
+        progressAria.setAttribute('aria-valuenow', '0');
+        progressFill.style.width = '0%';
+        processedCountEl.textContent = '0';
+        batchTotalEl.textContent = config.batchSize.toLocaleString();
+        statusText.textContent = `Starting batch simulation of ${config.batchSize.toLocaleString()} blends...`;
+
+        if (!worker) {
+          worker = createSimulationWorker();
+          if (worker) {
+            worker.onmessage = handleWorkerMessage;
+          }
+        }
+
+        if (worker) {
+          worker.postMessage({ type: 'START', config });
+        }
+      }
+
+      runBtn.addEventListener('click', startBatchSimulation);
+
+      cancelBtn.addEventListener('click', () => {
+        if (worker && isSimulating) {
+          worker.postMessage({ type: 'CANCEL' });
+        }
+      });
+
+      // Initialize UI with default baseline data
+      updateSliderLabels();
+      renderResultsTable(currentTopBlends);
+    })();
+  </script>
 </body>

 </html>

