+    (function () {
+      const initialDateNow = Date.now;
+      const initialPerfNow =
+        typeof performance !== 'undefined' && typeof performance.now === 'function'
+          ? performance.now
+          : null;
+
+      function getTimestamp() {
+        // Prefer performance.now() for monotonic precision, unless Date.now was mocked in a test
+        if (
+          initialPerfNow &&
+          typeof performance !== 'undefined' &&
+          typeof performance.now === 'function' &&
+          Date.now === initialDateNow
+        ) {
+          return performance.now();
+        }
+        return Date.now();
+      }
+
+      function isDocumentVisible() {
+        if (typeof document.visibilityState === 'string') {
+          return document.visibilityState === 'visible';
+        }
+        return !document.hidden;
+      }
+
+      let accumulatedForegroundMs = 0;
+      let activeStartTimestamp = isDocumentVisible() ? getTimestamp() : null;
+
+      function startForegroundTimer() {
+        if (activeStartTimestamp === null && isDocumentVisible()) {
+          activeStartTimestamp = getTimestamp();
+        }
+      }
+
+      function stopForegroundTimer() {
+        if (activeStartTimestamp !== null) {
+          const elapsed = getTimestamp() - activeStartTimestamp;
+          if (elapsed > 0) {
+            accumulatedForegroundMs += elapsed;
+          }
+          activeStartTimestamp = null;
+        }
+      }
+
+      /**
+       * Calculates the total time (in milliseconds) the page has been in the foreground.
+       * Includes all completed foreground intervals plus the currently active interval if visible.
+       *
+       * @param {Object} [options]
+       * @param {'ms' | 's' | 'seconds' | 'milliseconds'} [options.unit='ms'] - Unit for returned value.
+       * @returns {number} Total foreground time in the requested unit (default: milliseconds).
+       */
+      function calculateTotalForegroundTime(options) {
+        let totalMs = accumulatedForegroundMs;
+        if (activeStartTimestamp !== null && isDocumentVisible()) {
+          const currentElapsed = getTimestamp() - activeStartTimestamp;
+          if (currentElapsed > 0) {
+            totalMs += currentElapsed;
+          }
+        }
+
+        if (options && (options.unit === 's' || options.unit === 'seconds')) {
+          return totalMs / 1000;
+        }
+        return totalMs;
+      }
+
+      function formatForegroundTime(ms) {
+        const totalSeconds = Math.floor(ms / 1000);
+        const minutes = Math.floor(totalSeconds / 60);
+        const seconds = totalSeconds % 60;
+        if (minutes > 0) {
+          return `${minutes}m ${seconds}s`;
+        }
+        return `${seconds}s`;
+      }
+
+      function resetForegroundTime() {
+        accumulatedForegroundMs = 0;
+        activeStartTimestamp = isDocumentVisible() ? getTimestamp() : null;
+        updateForegroundDisplay();
+      }
+
+      function handleVisibilityChange() {
+        if (isDocumentVisible()) {
+          startForegroundTimer();
+        } else {
+          stopForegroundTimer();
+        }
+        updateForegroundDisplay();
+      }
+
+      document.addEventListener('visibilitychange', handleVisibilityChange);
+      window.addEventListener('focus', startForegroundTimer);
