+  <script>
+    (function () {
+      const PICKUP_TIME_STORAGE_KEY = 'dailyGrind_pickupReminderTime';
+      const ANNIVERSARY_DATE_STORAGE_KEY = 'dailyGrind_coffeeAnniversaryDate';
+
+      const MONTH_NAMES = [
+        'January', 'February', 'March', 'April', 'May', 'June',
+        'July', 'August', 'September', 'October', 'November', 'December'
+      ];
+
+      /**
+       * Formats an ISO plain wall-clock time string ("HH:MM") without constructing
+       * a Date object or applying any UTC/time-zone offset conversion.
+       */
+      function formatPlainTime(plainTimeStr) {
+        if (!plainTimeStr || typeof plainTimeStr !== 'string') return '';
+        const parts = plainTimeStr.trim().split(':');
+        if (parts.length < 2) return plainTimeStr;
+        const hours24 = parseInt(parts[0], 10);
+        const minutes = parseInt(parts[1], 10);
+        if (Number.isNaN(hours24) || Number.isNaN(minutes)) return plainTimeStr;
+
+        const period = hours24 >= 12 ? 'PM' : 'AM';
+        const hours12 = hours24 % 12 === 0 ? 12 : hours24 % 12;
+        const paddedMinutes = String(minutes).padStart(2, '0');
+        const canonical24 = String(hours24).padStart(2, '0') + ':' + paddedMinutes;
+        return `${hours12}:${paddedMinutes} ${period} (${canonical24})`;
+      }
+
+      /**
+       * Formats an ISO plain calendar date string ("YYYY-MM-DD") directly from its
+       * year, month, and day components without using new Date(dateString), avoiding
+       * UTC midnight parsing that shifts dates in negative/positive time zones.
+       */
+      function formatPlainDate(plainDateStr) {
+        if (!plainDateStr || typeof plainDateStr !== 'string') return '';
+        const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(plainDateStr.trim());
+        if (!match) return plainDateStr;
+
+        const year = parseInt(match[1], 10);
+        const monthIndex = parseInt(match[2], 10) - 1;
+        const day = parseInt(match[3], 10);
+
+        if (monthIndex < 0 || monthIndex > 11 || day < 1 || day > 31) {
+          return plainDateStr;
+        }
+
+        const monthName = MONTH_NAMES[monthIndex];
+        return `${monthName} ${day}, ${year} (${plainDateStr.trim()})`;
+      }
+
+      const pickupInput = document.getElementById('pickup-time-input');
+      const pickupFormatted = document.getElementById('pickup-time-formatted');
+      const savePickupBtn = document.getElementById('save-pickup-btn');
+
+      const anniversaryInput = document.getElementById('anniversary-date-input');
+      const anniversaryFormatted = document.getElementById('anniversary-date-formatted');
+      const saveAnniversaryBtn = document.getElementById('save-anniversary-btn');
+
+      function updatePickupTime(rawTimeValue, persist) {
+        if (!rawTimeValue) return;
+        // Keep only HH:MM wall-clock representation
+        const normalizedTime = rawTimeValue.trim().slice(0, 5);
+        pickupInput.value = normalizedTime;
+        pickupFormatted.textContent = formatPlainTime(normalizedTime);
+        pickupInput.setAttribute('data-plain-time', normalizedTime);
+        if (persist) {
+          try {
+            localStorage.setItem(PICKUP_TIME_STORAGE_KEY, normalizedTime);
+          } catch (e) {
+            // Ignore storage errors in restricted environments
+          }
+        }
+      }
+
+      function updateAnniversaryDate(rawDateValue, persist) {
+        if (!rawDateValue) return;
+        // Keep exact YYYY-MM-DD calendar representation
+        const normalizedDate = rawDateValue.trim().slice(0, 10);
+        anniversaryInput.value = normalizedDate;
+        anniversaryFormatted.textContent = formatPlainDate(normalizedDate);
+        anniversaryInput.setAttribute('data-plain-date', normalizedDate);
+        if (persist) {
+          try {
+            localStorage.setItem(ANNIVERSARY_DATE_STORAGE_KEY, normalizedDate);
+          } catch (e) {
+            // Ignore storage errors in restricted environments
+          }
+        }
+      }
+
+      // Initialize from saved location-agnostic plain strings if available
+      let initialTime = pickupInput.value || '08:00';
+      let initialDate = anniversaryInput.value || '2023-05-15';
+      try {
+        const storedTime = localStorage.getItem(PICKUP_TIME_STORAGE_KEY);
+        if (storedTime && /^\d{2}:\d{2}$/.test(storedTime)) {
+          initialTime = storedTime;
+        }
+        const storedDate = localStorage.getItem(ANNIVERSARY_DATE_STORAGE_KEY);
+        if (storedDate && /^\d{4}-\d{2}-\d{2}$/.test(storedDate)) {
+          initialDate = storedDate;
+        }
+      } catch (e) {
+        // Ignore storage errors
+      }
+
+      updatePickupTime(initialTime, true);
+      updateAnniversaryDate(initialDate, true);
+
+      pickupInput.addEventListener('input', function (e) {
+        updatePickupTime(e.target.value, true);
+      });
+      pickupInput.addEventListener('change', function (e) {
+        updatePickupTime(e.target.value, true);
+      });
+      savePickupBtn.addEventListener('click', function () {
+        updatePickupTime(pickupInput.value, true);
+      });
+
+      anniversaryInput.addEventListener('input', function (e) {
+        updateAnniversaryDate(e.target.value, true);
+      });
+      anniversaryInput.addEventListener('change', function (e) {
+        updateAnniversaryDate(e.target.value, true);
+      });
+      saveAnniversaryBtn.addEventListener('click', function () {
+        updateAnniversaryDate(anniversaryInput.value, true);
+      });
+    })();
+  </script>
