+  <script>
+    (() => {
+      const supportsHas = typeof CSS !== 'undefined' && typeof CSS.supports === 'function' && CSS.supports('selector(:has(*))');
+      const cards = document.querySelectorAll('.card');
+      const orderSummary = document.getElementById('order-summary');
+      let totalItems = 0;
+      let totalAmount = 0;
+
+      cards.forEach((card) => {
+        if (!supportsHas) {
+          if (card.querySelector(':scope > img')) {
+            card.classList.add('has-image');
+          }
+          card.querySelectorAll('.size-option').forEach((label) => {
+            const radio = label.querySelector('input[type="radio"]');
+            if (radio) {
+              label.classList.toggle('is-selected', radio.checked);
+            }
+          });
+        }
+
+        const priceDisplay = card.querySelector('[data-price]');
+        const form = card.querySelector('.order-form');
+        if (!form) return;
+
+        form.addEventListener('change', (event) => {
+          const target = event.target;
+          if (target instanceof HTMLInputElement && target.name === 'size') {
+            if (priceDisplay && target.dataset.price) {
+              priceDisplay.textContent = `$${Number(target.dataset.price).toFixed(2)}`;
+            }
+            if (!supportsHas) {
+              card.querySelectorAll('.size-option').forEach((label) => {
+                const radio = label.querySelector('input[type="radio"]');
+                if (radio) {
+                  label.classList.toggle('is-selected', radio.checked);
+                }
+              });
+            }
+          }
+        });
+
+        form.addEventListener('submit', (event) => {
+          event.preventDefault();
+          const formData = new FormData(form);
+          const drink = formData.get('drink') || 'Drink';
+          const size = String(formData.get('size') || 'medium');
+          const selectedRadio = form.querySelector('input[name="size"]:checked');
+          const price = selectedRadio ? Number(selectedRadio.dataset.price || 0) : 0;
+          const formattedSize = size.charAt(0).toUpperCase() + size.slice(1);
+
+          totalItems += 1;
+          totalAmount += price;
+
+          if (orderSummary) {
+            const itemWord = totalItems === 1 ? 'item' : 'items';
+            orderSummary.textContent = `Order: ${totalItems} ${itemWord} ($${totalAmount.toFixed(2)})`;
+          }
+
+          const feedback = form.querySelector('.order-feedback');
+          if (feedback) {
+            feedback.textContent = `Added ${formattedSize} ${drink} ($${price.toFixed(2)})`;
+          }
+
+          if (!supportsHas) {
+            card.classList.add('is-ordered');
+          }
+        });
+      });
+    })();
+  </script>
