+const KEM_PUBLIC_KEY_ALGORITHMS = {
+  1184: 'ML-KEM-768',
+  1216: 'MLKEM768-X25519',
+  1568: 'ML-KEM-1024',
+};
+
+const DB_NAME = 'daily-grind-crypto-store';
+const STORE_NAME = 'kem-keys';
+const KEY_ID = 'recipient-kem-key';
+
+/**
+ * Checks if the browser supports Hybrid Post-Quantum KEM ('MLKEM768-X25519')
+ * with 'ChaCha20-Poly1305' via the static SubtleCrypto.supports() method.
+ */
+export function supportsPostQuantumEnvelope() {
+  return (
+    typeof globalThis.SubtleCrypto?.supports === 'function' &&
+    SubtleCrypto.supports('encapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305')
+  );
+}
+
+/**
+ * Encodes a Uint8Array into a Base64 string using Uint8Array.prototype.toBase64 when available.
+ * @param {Uint8Array} bytes
+ */
+export function bytesToBase64(bytes) {
+  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+  if (typeof arr.toBase64 === 'function') {
+    return arr.toBase64();
+  }
+  let binary = '';
+  for (let i = 0; i < arr.byteLength; i++) {
+    binary += String.fromCharCode(arr[i]);
+  }
+  return btoa(binary);
+}
+
+/**
+ * Opens IndexedDB to persist non-extractable CryptoKeyPair objects across sessions
+ * via structured cloning without ever exporting private key bytes.
+ */
+function openKeyDatabase() {
+  return new Promise((resolve, reject) => {
+    if (typeof indexedDB === 'undefined') {
+      resolve(null);
+      return;
+    }
+    const request = indexedDB.open(DB_NAME, 1);
+    request.onupgradeneeded = () => {
+      const db = request.result;
+      if (!db.objectStoreNames.contains(STORE_NAME)) {
+        db.createObjectStore(STORE_NAME);
+      }
+    };
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => resolve(null);
+  });
+}
+
+async function loadStoredKeyPair() {
+  const db = await openKeyDatabase();
+  if (!db) return null;
+  return new Promise((resolve) => {
+    const tx = db.transaction(STORE_NAME, 'readonly');
+    const store = tx.objectStore(STORE_NAME);
+    const req = store.get(KEY_ID);
+    req.onsuccess = () => resolve(req.result || null);
+    req.onerror = () => resolve(null);
+  });
+}
+
+async function saveKeyPair(recipientKeyPair) {
+  const db = await openKeyDatabase();
+  if (!db) return;
+  return new Promise((resolve) => {
+    const tx = db.transaction(STORE_NAME, 'readwrite');
+    const store = tx.objectStore(STORE_NAME);
+    store.put(recipientKeyPair, KEY_ID);
+    tx.oncomplete = () => resolve();
+    tx.onerror = () => resolve();
+  });
+}
+
+/**
+ * Generates (or loads from IndexedDB) the recipient key pair and exports the public key bytes.
+ * Uses 'MLKEM768-X25519' (hybrid post-quantum ML-KEM-768 + classical X25519) with
+ * extractable: false and ['encapsulateKey', 'decapsulateKey'] when supported,
+ * falling back to classical 'X25519' key agreement + 'HKDF' + 'AES-GCM'.
+ *
+ * @param {boolean} [forceRotate=false]
+ */
+export async function generateRecipientKeys(forceRotate = false) {
+  const pqSupported = supportsPostQuantumEnvelope();
+  const expectedAlgo = pqSupported ? 'MLKEM768-X25519' : 'X25519';
+
+  if (!forceRotate) {
+    const cachedKeyPair = await loadStoredKeyPair();
+    if (cachedKeyPair?.privateKey?.algorithm?.name === expectedAlgo) {
+      const format = pqSupported ? 'raw-public' : 'raw';
+      let pubKey = cachedKeyPair.publicKey;
+      if (!pubKey && typeof crypto.subtle.getPublicKey === 'function') {
+        pubKey = await crypto.subtle.getPublicKey(cachedKeyPair.privateKey, ['encapsulateKey']);
+      }
+      const publicKeyBytes = new Uint8Array(await crypto.subtle.exportKey(format, pubKey));
+      return {
+        suite: pqSupported ? 'MLKEM768-X25519+ChaCha20-Poly1305' : 'X25519+HKDF+AES-GCM',
+        keyPair: cachedKeyPair,
+        publicKeyBytes,
+        publicKeyFormat: format,
+      };
+    }
+  }
+
+  if (pqSupported) {
+    const recipientKeyPair = await crypto.subtle.generateKey(
+      'MLKEM768-X25519',
+      false,
+      ['encapsulateKey', 'decapsulateKey'],
+    );
+    await saveKeyPair(recipientKeyPair);
+    const recipientPublicKeyBytes = await crypto.subtle.exportKey(
+      'raw-public',
+      recipientKeyPair.publicKey,
+    );
+    return {
+      suite: 'MLKEM768-X25519+ChaCha20-Poly1305',
+      keyPair: recipientKeyPair,
+      publicKeyBytes: new Uint8Array(recipientPublicKeyBytes),
+      publicKeyFormat: 'raw-public',
+    };
+  }
+
+  // Classical fallback: X25519 key agreement + HKDF + AES-GCM
+  const keyPair = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  await saveKeyPair(keyPair);
+  const publicKeyBytes = new Uint8Array(
+    await crypto.subtle.exportKey('raw', keyPair.publicKey),
+  );
+  return {
+    suite: 'X25519+HKDF+AES-GCM',
+    keyPair,
+    publicKeyBytes,
+    publicKeyFormat: 'raw',
+  };
+}
+
+/**
+ * Derives a 256-bit AES-GCM key from an X25519 shared secret passed through HKDF (SHA-256).
+ */
+async function deriveFallbackAesKey(privateKey, peerPublicKey, infoBytes = new Uint8Array(0)) {
+  const sharedSecret = await crypto.subtle.deriveBits(
+    { name: 'X25519', public: peerPublicKey },
+    privateKey,
+    256,
+  );
+  const hkdfKey = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey(
+    {
+      name: 'HKDF',
+      hash: 'SHA-256',
+      salt: new Uint8Array(32),
+      info: infoBytes,
+    },
+    hkdfKey,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+/**
+ * Encapsulates a one-time shared AEAD key and returns `{ sharedKey, capsuleBytes }`.
+ * Imports KEM public keys using explicit `'raw-public'` format and `['encapsulateKey']` usage.
+ */
+export async function encapsulateEnvelopeKey(
+  recipientPublicKeyOrBytes,
+  infoBytes = new Uint8Array(0),
+) {
+  const pubKey =
+    recipientPublicKeyOrBytes instanceof CryptoKey
+      ? recipientPublicKeyOrBytes
+      : await (() => {
+          const bytes =
+            recipientPublicKeyOrBytes instanceof Uint8Array
+              ? recipientPublicKeyOrBytes
+              : new Uint8Array(recipientPublicKeyOrBytes);
+          const kemName = KEM_PUBLIC_KEY_ALGORITHMS[bytes.byteLength];
+          return kemName
+            ? crypto.subtle.importKey('raw-public', bytes, kemName, true, ['encapsulateKey'])
+            : crypto.subtle.importKey('raw', bytes, 'X25519', true, []);
+        })();
+
+  if (pubKey.algorithm.name !== 'X25519') {
+    const { sharedKey, ciphertext } = await crypto.subtle.encapsulateKey(
+      pubKey.algorithm.name,
+      pubKey,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt', 'decrypt'],
+    );
+    return { sharedKey, capsuleBytes: new Uint8Array(ciphertext) };
+  }
+
+  // Classical fallback: generate ephemeral X25519 key pair and send ephemeral public key as capsule
+  const ephemeral = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  const capsuleBytes = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeral.publicKey));
+  const sharedKey = await deriveFallbackAesKey(ephemeral.privateKey, pubKey, infoBytes);
+  return { sharedKey, capsuleBytes };
+}
+
+/**
+ * Decapsulates the ciphertext capsule on the recipient to recover the shared AEAD key.
+ */
+export async function decapsulateEnvelopeKey(
+  recipientPrivateKey,
+  capsuleBytes,
+  infoBytes = new Uint8Array(0),
+) {
+  if (recipientPrivateKey.algorithm.name !== 'X25519') {
+    return crypto.subtle.decapsulateKey(
+      recipientPrivateKey.algorithm.name,
+      recipientPrivateKey,
+      capsuleBytes,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt', 'decrypt'],
+    );
+  }
+
+  const ephemeralPubKey = await crypto.subtle.importKey('raw', capsuleBytes, 'X25519', true, []);
+  return deriveFallbackAesKey(recipientPrivateKey, ephemeralPubKey, infoBytes);
+}
+
+/**
+ * Encrypts UTF-8 text with an AEAD CryptoKey ('ChaCha20-Poly1305' or 'AES-GCM')
+ * and a fresh 12-byte (96-bit) random IV, binding unencrypted metadata via additionalData (AAD).
+ *
+ * @param {CryptoKey} key
+ * @param {string} plaintext
+ * @param {Uint8Array} [additionalData]
+ */
+export async function encryptMessage(key, plaintext, additionalData = new Uint8Array(0)) {
+  const iv = crypto.getRandomValues(new Uint8Array(12));
+  const encoded = new TextEncoder().encode(plaintext);
+
+  const ciphertextBuffer = await crypto.subtle.encrypt(
+    {
+      name: key.algorithm.name,
+      iv,
+      additionalData,
+    },
+    key,
+    encoded,
+  );
+
+  return { iv, ciphertext: new Uint8Array(ciphertextBuffer) };
+}
+
+/**
+ * Decrypts and authenticates an AEAD payload. Throws OperationError if ciphertext or AAD is tampered.
+ *
+ * @param {CryptoKey} key
+ * @param {Uint8Array} iv
+ * @param {Uint8Array} ciphertext
+ * @param {Uint8Array} [additionalData]
+ */
+export async function decryptMessage(key, iv, ciphertext, additionalData = new Uint8Array(0)) {
+  const plaintextBuffer = await crypto.subtle.decrypt(
+    {
+      name: key.algorithm.name,
+      iv,
+      additionalData,
+    },
+    key,
+    ciphertext,
+  );
+
+  return new TextDecoder().decode(plaintextBuffer);
+}
+
+/**
+ * High-level envelope encryption helper: imports recipient public key bytes, encapsulates
+ * a fresh one-time shared secret, and encrypts the delivery note with AAD.
+ */
+export async function encryptDeliveryNoteEnvelope(
+  recipientPublicKeyBytes,
+  notePlaintext,
+  orderRef = '',
+) {
+  const aadBytes = new TextEncoder().encode(orderRef);
+  const infoBytes = new TextEncoder().encode('daily-grind-delivery-note-v1');
+  const { sharedKey, capsuleBytes } = await encapsulateEnvelopeKey(
+    recipientPublicKeyBytes,
+    infoBytes,
+  );
+  const { iv, ciphertext } = await encryptMessage(sharedKey, notePlaintext, aadBytes);
+  return { capsule: capsuleBytes, iv, ciphertext, orderRef };
+}
+
+/**
+ * High-level envelope decryption helper: decapsulates the shared key using the recipient's
+ * non-extractable private key and verifies + decrypts the delivery note with AAD.
+ */
+export async function decryptDeliveryNoteEnvelope(recipientPrivateKey, envelope, orderRefOverride) {
+  const aadText = orderRefOverride !== undefined ? orderRefOverride : envelope.orderRef;
+  const aadBytes = new TextEncoder().encode(aadText);
+  const infoBytes = new TextEncoder().encode('daily-grind-delivery-note-v1');
+  const recipientKey = await decapsulateEnvelopeKey(
+    recipientPrivateKey,
+    envelope.capsule,
+    infoBytes,
+  );
+  return decryptMessage(recipientKey, envelope.iv, envelope.ciphertext, aadBytes);
+}
+
+// Initialize UI bindings when loaded in a browser document
+if (typeof document !== 'undefined') {
+  let currentRecipient = null;
+  let currentEnvelope = null;
+
+  const suiteBadge = document.getElementById('crypto-suite-badge');
+  const pubkeyFormatLabel = document.getElementById('pubkey-format-label');
+  const pubkeyDisplay = document.getElementById('recipient-pubkey-display');
+  const capsuleSizeLabel = document.getElementById('capsule-size-label');
+  const capsuleDisplay = document.getElementById('capsule-display');
+  const ciphertextDisplay = document.getElementById('ciphertext-display');
+  const decryptedStatus = document.getElementById('decrypted-status');
+  const form = document.getElementById('delivery-note-form');
+  const orderInput = document.getElementById('order-reference');
+  const noteInput = document.getElementById('delivery-note-input');
+  const decryptBtn = document.getElementById('decrypt-note-btn');
+  const rotateBtn = document.getElementById('rotate-keys-btn');
+
+  async function handleEncryptAndDisplay() {
+    if (!currentRecipient) return;
+    try {
+      const orderRef = orderInput.value.trim();
+      const plaintext = noteInput.value;
+      currentEnvelope = await encryptDeliveryNoteEnvelope(
+        currentRecipient.publicKeyBytes,
+        plaintext,
+        orderRef,
+      );
+
+      capsuleSizeLabel.textContent = `${currentEnvelope.capsule.byteLength} bytes`;
+      capsuleDisplay.textContent = bytesToBase64(currentEnvelope.capsule);
+      ciphertextDisplay.textContent = `IV (${currentEnvelope.iv.byteLength}B): ${bytesToBase64(
+        currentEnvelope.iv,
+      )} | Ciphertext (${currentEnvelope.ciphertext.byteLength}B): ${bytesToBase64(
+        currentEnvelope.ciphertext,
+      )}`;
+
+      const verifiedPlaintext = await decryptDeliveryNoteEnvelope(
+        currentRecipient.keyPair.privateKey,
+        currentEnvelope,
+        orderRef,
+      );
+      decryptedStatus.classList.remove('error');
+      decryptedStatus.textContent = `[AAD: ${orderRef || 'none'}] ${verifiedPlaintext}`;
+    } catch (err) {
+      decryptedStatus.classList.add('error');
+      decryptedStatus.textContent = `Encryption/Decryption failed: ${err.message || err}`;
+    }
+  }
+
+  async function initDeliveryNotesCrypto(forceRotate = false) {
+    try {
+      currentRecipient = await generateRecipientKeys(forceRotate);
+      suiteBadge.textContent = currentRecipient.suite;
+      pubkeyFormatLabel.textContent = `${currentRecipient.publicKeyFormat}, ${currentRecipient.publicKeyBytes.byteLength} bytes`;
+      pubkeyDisplay.textContent = bytesToBase64(currentRecipient.publicKeyBytes);
+      await handleEncryptAndDisplay();
+    } catch (err) {
+      suiteBadge.textContent = 'WebCrypto Error';
+      decryptedStatus.classList.add('error');
+      decryptedStatus.textContent = `Initialization error: ${err.message || err}`;
+    }
+  }
+
+  form?.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    await handleEncryptAndDisplay();
+  });
+
+  decryptBtn?.addEventListener('click', async () => {
+    if (!currentRecipient || !currentEnvelope) return;
+    try {
+      const currentOrderRef = orderInput.value.trim();
+      const plaintext = await decryptDeliveryNoteEnvelope(
+        currentRecipient.keyPair.privateKey,
+        currentEnvelope,
+        currentOrderRef,
+      );
+      decryptedStatus.classList.remove('error');
+      decryptedStatus.textContent = `[AAD Verified: ${currentOrderRef || 'none'}] ${plaintext}`;
+    } catch (err) {
+      decryptedStatus.classList.add('error');
+      decryptedStatus.textContent = `Authentication failed (${err.name || 'OperationError'}): Ciphertext or Order Reference AAD was modified.`;
+    }
+  });
+
+  rotateBtn?.addEventListener('click', async () => {
+    await initDeliveryNotesCrypto(true);
+  });
+
+  initDeliveryNotesCrypto(false);
+}
