+        let decryptedBuffer;
+        if (aeadBlock.cipher === 'ChaCha20-Poly1305') {
+          try {
+            const chachaKey = await crypto.subtle.importKey('raw', keyInfo.derivedKeyBytes, 'ChaCha20-Poly1305', false, ['encrypt', 'decrypt']);
+            decryptedBuffer = await crypto.subtle.decrypt(
+              { name: 'ChaCha20-Poly1305', iv, additionalData: aadBytes, tagLength: 128 },
+              chachaKey,
+              combinedBytes
+            );
+          } catch (err) {
+            if (err && err.name === 'OperationError') throw err;
+            decryptedBuffer = await ChaCha20Poly1305Fallback.decrypt(keyInfo.derivedKeyBytes, iv, aadBytes, combinedBytes);
+          }
+        } else {
+          decryptedBuffer = await crypto.subtle.decrypt(
+            { name: 'AES-GCM', iv, additionalData: aadBytes, tagLength: 128 },
+            keyInfo.aesKey,
+            combinedBytes
+          );
+        }
+
+        const jsonStr = decoder.decode(decryptedBuffer);
+        return JSON.parse(jsonStr);
+      }
+
+      // DOM Elements
+      const formEl = document.getElementById('delivery-note-form');
+      const kemModeSelect = document.getElementById('kem-mode-select');
+      const aeadCipherSelect = document.getElementById('aead-cipher-select');
+      const orderRefInput = document.getElementById('order-reference-input');
+      const dropLocationSelect = document.getElementById('drop-location-select');
+      const accessCodeInput = document.getElementById('access-code-input');
+      const contactPhoneInput = document.getElementById('contact-phone-input');
+      const deliveryNoteInput = document.getElementById('delivery-note-input');
+      const rotateKeysBtn = document.getElementById('rotate-recipient-keys-btn');
+      const decryptVerifyBtn = document.getElementById('decrypt-verify-btn');
+      const tamperTestBtn = document.getElementById('tamper-test-btn');
+      const clearSavedBtn = document.getElementById('clear-saved-notes-btn');
+
+      const suiteBadgeEl = document.getElementById('active-suite-badge');
+      const providerIndicatorEl = document.getElementById('kem-provider-indicator');
+      const statusBannerEl = document.getElementById('crypto-status-banner');
+      const pkFingerprintEl = document.getElementById('recipient-pk-fingerprint');
+      const encKeySummaryEl = document.getElementById('encapsulated-key-summary');
+      const sharedSecretFpEl = document.getElementById('shared-secret-fingerprint');
+      const aeadIvTagEl = document.getElementById('aead-iv-tag-summary');
+      const envelopeOutputEl = document.getElementById('encrypted-envelope-output');
+      const decryptedContainerEl = document.getElementById('courier-decrypted-container');
+      const decryptedMetaEl = document.getElementById('courier-decrypted-meta');
+      const decryptedOutputEl = document.getElementById('courier-decrypted-output');
+      const savedNotesListEl = document.getElementById('saved-notes-list');
+
+      let currentEnvelope = null;
+
+      function setStatus(message, type) {
+        statusBannerEl.textContent = message;
+        statusBannerEl.className = 'status-banner' + (type ? ' ' + type : '');
+      }
+
+      function loadVaultNotes() {
+        try {
+          const raw = localStorage.getItem(STORAGE_KEY);
+          return raw ? JSON.parse(raw) : [];
+        } catch (_) {
+          return [];
+        }
+      }
+
+      function saveEnvelopeToVault(envelope) {
+        try {
+          const existing = loadVaultNotes();
+          const filtered = existing.filter((item) => item.envelopeId !== envelope.envelopeId);
+          filtered.unshift(envelope);
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered.slice(0, 10)));
+          renderSavedVaultNotes();
+        } catch (_) {}
+      }
+
+      function renderSavedVaultNotes() {
+        const items = loadVaultNotes();
+        savedNotesListEl.innerHTML = '';
+        if (!items.length) {
+          const empty = document.createElement('div');
+          empty.style.fontSize = '0.8rem';
+          empty.style.color = '#795548';
+          empty.textContent = 'No encrypted notes stored in local vault yet.';
+          savedNotesListEl.appendChild(empty);
+          return;
+        }
+        items.forEach((env) => {
+          const row = document.createElement('div');
+          row.className = 'saved-note-item';
+          const info = document.createElement('div');
+          info.className = 'saved-note-info';
+          info.innerHTML = '<strong>' + escapeHtml(env.orderId) + '</strong> &middot; ' +
+            escapeHtml(env.keyEstablishment.mode) + ' &middot; ' +
+            escapeHtml(env.aead.cipher) + ' &middot; Tag <code>' + escapeHtml(env.aead.authTagHex.slice(0, 12)) + '...</code>';
+          const loadBtn = document.createElement('button');
+          loadBtn.type = 'button';
+          loadBtn.className = 'chip-btn';
+          loadBtn.textContent = 'Inspect';
+          loadBtn.addEventListener('click', () => {
+            currentEnvelope = JSON.parse(JSON.stringify(env));
+            envelopeOutputEl.textContent = JSON.stringify(currentEnvelope, null, 2);
+            verifyCurrentEnvelope();
+          });
+          row.appendChild(info);
+          row.appendChild(loadBtn);
+          savedNotesListEl.appendChild(row);
+        });
+      }
+
+      function escapeHtml(str) {
+        return String(str || '')
+          .replace(/&/g, '&amp;')
+          .replace(/</g, '&lt;')
+          .replace(/>/g, '&gt;')
+          .replace(/"/g, '&quot;');
+      }
+
+      async function refreshSuiteTelemetryHeader() {
+        const mode = kemModeSelect.value;
+        const cipher = aeadCipherSelect.value;
+        suiteBadgeEl.textContent = mode + ' + ' + cipher;
+        const pkInfo = await getActiveRecipientFingerprint(mode);
+        pkFingerprintEl.textContent = courierKeys.keyId + ' (' + pkInfo.fingerprint.slice(0, 16) + '... / ' + pkInfo.byteLength + 'B)';
+      }
+
+      async function encryptAndDisplayDeliveryNote() {
+        const mode = kemModeSelect.value;
+        const aeadCipher = aeadCipherSelect.value;
+        const orderId = (orderRefInput.value || 'DG-2026-8841').trim();
+        const dropLocation = dropLocationSelect.value;
+        const accessCode = (accessCodeInput.value || '').trim();
+        const contactPhone = (contactPhoneInput.value || '').trim();
+        const noteText = (deliveryNoteInput.value || '').trim();
+
+        if (!noteText) {
+          setStatus('Please enter delivery instructions before encrypting.', 'error');
+          return null;
+        }
+
+        await refreshSuiteTelemetryHeader();
+
+        const keyInfo = await establishSenderSharedSecret(mode, orderId, aeadCipher);
+        const aadString = 'order:' + orderId + '|zone:' + dropLocation + '|mode:' + mode;
+
+        const sensitivePayload = {
+          orderId,
+          dropLocation,
+          accessCode,
+          contactPhone,
+          instructions: noteText,
+          encryptedAt: new Date().toISOString()
+        };
+
+        const aeadBlock = await aeadEncryptPayload(aeadCipher, keyInfo, aadString, sensitivePayload);
+
+        const envelope = {
+          envelopeId: 'env-' + aeadBlock.ivHex.slice(0, 12),
+          version: '1.0-pq-hybrid',
+          recipientKeyId: courierKeys.keyId,
+          orderId,
+          dropLocation,
+          keyEstablishment: keyInfo.encapsulationData,
+          kdf: {
+            algorithm: 'HKDF-SHA256',
+            saltHex: keyInfo.saltHex,
+            info: keyInfo.info,
+            ikmByteLength: keyInfo.ikmByteLength
+          },
+          aead: aeadBlock
+        };
+
+        currentEnvelope = envelope;
+        providerIndicatorEl.textContent = keyInfo.providerLabel;
+
+        const encParts = [];
+        if (keyInfo.encapsulationData.ephemeralPublicKeyHex) {
+          encParts.push('EphPK:' + keyInfo.encapsulationData.ephemeralPublicKeyHex.slice(0, 14) + '...');
+        }
+        if (keyInfo.encapsulationData.kemCiphertextByteLength) {
+          encParts.push(keyInfo.encapsulationData.kemAlgorithm + ' CT:' + keyInfo.encapsulationData.kemCiphertextByteLength + 'B');
+        }
+        encKeySummaryEl.textContent = encParts.join(' | ');
+        sharedSecretFpEl.textContent = 'sha256:' + keyInfo.sharedSecretFingerprint.slice(0, 28) + '... (' + keyInfo.ikmByteLength + 'B IKM)';
+        aeadIvTagEl.textContent = 'IV:' + aeadBlock.ivHex.slice(0, 12) + '... Tag:' + aeadBlock.authTagHex.slice(0, 14) + '...';
+        envelopeOutputEl.textContent = JSON.stringify(envelope, null, 2);
+
+        saveEnvelopeToVault(envelope);
+        await verifyCurrentEnvelope(keyInfo.sharedSecretFingerprint);
+        setStatus('Shared secret established (' + mode + ') & delivery note encrypted with ' + aeadBlock.cipher + '.', 'success');
+        return envelope;
+      }
+
+      async function verifyCurrentEnvelope(senderSharedFp) {
+        if (!currentEnvelope) {
+          setStatus('No encrypted delivery note available to verify.', 'error');
+          return false;
+        }
+        try {
+          const recoveredKeyInfo = await recoverRecipientSharedSecret(currentEnvelope);
+          if (senderSharedFp && recoveredKeyInfo.sharedSecretFingerprint !== senderSharedFp) {
+            throw new Error('Decapsulated shared secret mismatch');
+          }
+          const plaintextObj = await aeadDecryptPayload(currentEnvelope.aead, recoveredKeyInfo);
+          decryptedContainerEl.classList.remove('tampered');
+          decryptedMetaEl.textContent = 'Authenticated & Decapsulated (' +
+            currentEnvelope.keyEstablishment.mode + ' -> ' +
+            currentEnvelope.aead.cipher + ' | Secret FP: ' +
+            recoveredKeyInfo.sharedSecretFingerprint.slice(0, 12) + '...)';
+          decryptedOutputEl.innerHTML =
+            '<strong>Order:</strong> ' + escapeHtml(plaintextObj.orderId) +
+            ' &nbsp;|&nbsp; <strong>Zone:</strong> ' + escapeHtml(plaintextObj.dropLocation) +
+            ' &nbsp;|&nbsp; <strong>Access Code:</strong> <code>' + escapeHtml(plaintextObj.accessCode || 'N/A') + '</code>' +
+            (plaintextObj.contactPhone ? ' &nbsp;|&nbsp; <strong>Contact:</strong> ' + escapeHtml(plaintextObj.contactPhone) : '') +
+            '<br/><strong>Decrypted Note:</strong> ' + escapeHtml(plaintextObj.instructions);
+          return true;
+        } catch (err) {
+          decryptedContainerEl.classList.add('tampered');
+          decryptedMetaEl.textContent = 'AEAD Authentication / Decapsulation Failed — Tampered Ciphertext, Tag, or Key Rejected!';
+          decryptedOutputEl.textContent = 'Integrity Error: Authenticated decryption rejected modified payload (' +
+            (err && err.message ? err.message : 'AEAD tag verification failed') + '). Plaintext withheld.';
+          setStatus('Tamper / integrity violation detected! AEAD rejected modified ciphertext or authentication tag.', 'error');
+          return false;
+        }
+      }
+
+      async function tamperWithCurrentEnvelope() {
+        if (!currentEnvelope) {
+          await encryptAndDisplayDeliveryNote();
+        }
+        if (!currentEnvelope) return;
+
+        const ctBytes = base64ToBytes(currentEnvelope.aead.ciphertextBase64);
+        if (ctBytes.length > 0) {
+          ctBytes[0] ^= 0xff;
+          currentEnvelope.aead.ciphertextBase64 = bytesToBase64(ctBytes);
+        } else {
+          const tagBytes = hexToBytes(currentEnvelope.aead.authTagHex);
+          tagBytes[0] ^= 0xff;
+          currentEnvelope.aead.authTagHex = bytesToHex(tagBytes);
+        }
+        envelopeOutputEl.textContent = JSON.stringify(currentEnvelope, null, 2);
+        await verifyCurrentEnvelope();
+      }
+
+      // Wire UI Events
+      formEl.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        await encryptAndDisplayDeliveryNote();
+      });
+
+      kemModeSelect.addEventListener('change', async () => {
+        await encryptAndDisplayDeliveryNote();
+      });
+
+      aeadCipherSelect.addEventListener('change', async () => {
+        await encryptAndDisplayDeliveryNote();
+      });
+
+      rotateKeysBtn.addEventListener('click', async () => {
+        await initCourierKeyRegistry();
+        await encryptAndDisplayDeliveryNote();
+        setStatus('Rotated courier recipient public/private keypairs and re-encapsulated delivery note.', 'success');
+      });
+
+      decryptVerifyBtn.addEventListener('click', async () => {
+        const ok = await verifyCurrentEnvelope();
+        if (ok) {
+          setStatus('Decapsulated shared secret and verified AEAD authentication tag + AAD.', 'success');
+        }
+      });
+
+      tamperTestBtn.addEventListener('click', async () => {
+        await tamperWithCurrentEnvelope();
+      });
+
+      clearSavedBtn.addEventListener('click', () => {
+        try {
+          localStorage.removeItem(STORAGE_KEY);
+        } catch (_) {}
+        renderSavedVaultNotes();
+        setStatus('Cleared saved encrypted notes from local browser vault.', '');
+      });
+
+      document.querySelectorAll('.preset-note-btn').forEach((btn) => {
+        btn.addEventListener('click', async () => {
+          const code = btn.getAttribute('data-code') || '';
+          const note = btn.getAttribute('data-note') || '';
+          accessCodeInput.value = code;
+          deliveryNoteInput.value = note;
+          await encryptAndDisplayDeliveryNote();
+        });
+      });
+
+      // Expose programmatic API on window for automated verification or integrations
+      window.DailyGrindDeliveryCrypto = {
+        initCourierKeyRegistry,
+        establishSenderSharedSecret,
+        recoverRecipientSharedSecret,
+        aeadEncryptPayload,
+        aeadDecryptPayload,
+        encryptAndDisplayDeliveryNote,
+        verifyCurrentEnvelope,
+        tamperWithCurrentEnvelope,
+        getCurrentEnvelope: () => currentEnvelope
+      };
+
+      // Initialize on load so an encrypted delivery note and shared secret are immediately established
+      renderSavedVaultNotes();
+      initCourierKeyRegistry().then(() => encryptAndDisplayDeliveryNote());
+    })();
+  </script>
+
 </body>

