+
+        const hubs = getHubsForRender(hostTz);
+        let idealCount = 0;
+
+        const cardsHtml = hubs.map(hub => {
+          const parts = getZonedParts(epochMs, hub.tz);
+          const dstInfo = getDstInfo(epochMs, hub.tz, parts.year);
+          const shortTz = getTzShortName(epochMs, hub.tz);
+          const isHost = hub.tz === hostTz;
+
+          const time12h = new Intl.DateTimeFormat('en-US', {
+            timeZone: hub.tz,
+            hour: 'numeric',
+            minute: '2-digit',
+            hour12: true
+          }).format(new Date(epochMs));
+
+          const time24h = `${String(parts.hour).padStart(2, '0')}:${String(parts.minute).padStart(2, '0')}`;
