+            weekday: 'short',
+            year: 'numeric',
+            month: 'short',
+            day: 'numeric'
+          }).format(new Date(epochMs));
+
+          const dayDiffLabel = computeDayDifferenceLabel(hostParts, parts);
+          const windowStatus = getTastingWindowStatus(parts.hour);
+          if (windowStatus.className === 'status-ideal') {
+            idealCount++;
+          }
+
+          const diffFromHostMinutes = dstInfo.offsetMinutes - hostDst.offsetMinutes;
+          const diffHours = diffFromHostMinutes / 60;
+          const relOffsetText = diffFromHostMinutes === 0
+            ? 'Same time as host'
+            : `${diffHours > 0 ? '+' : ''}${Number.isInteger(diffHours) ? diffHours : diffHours.toFixed(1)}h from host`;
+
+          const dstBadgeText = dstInfo.observesDst
+            ? (dstInfo.isDst ? 'DST Active' : 'Standard Time')
+            : 'No DST';
+          const dstBadgeClass = dstInfo.isDst ? 'badge-dst' : 'badge-std';
+
+          return `
+            <article class="card ${isHost ? 'is-host' : ''}" data-tz="${hub.tz}" data-city="${hub.city}">
+              <div>
+                <div class="card-top">
+                  <div class="city-info">
+                    <h3>${hub.city}, ${hub.country}</h3>
+                    <div class="tz-identifier">${hub.tz} (${shortTz || dstInfo.offsetFormatted})</div>
+                  </div>
+                  <div class="badge-group">
+                    ${isHost ? '<span class="badge badge-host">Host</span>' : ''}
+                    <span class="badge ${dstBadgeClass}">${dstBadgeText}</span>
+                    ${dayDiffLabel !== 'Same Day' ? `<span class="badge badge-day-shift">${dayDiffLabel}</span>` : ''}
+                  </div>
+                </div>
+
+                <div class="converted-time">
+                  <span>${time12h}</span>
+                  <span class="time-24h">(${time24h})</span>
+                </div>
+                <div class="converted-date">${fullDate} • ${dayDiffLabel}</div>
+                <div class="roastery-note">${hub.roastery} — ${hub.specialty}</div>
+              </div>
