+              <div class="card-meta">
+                <span>${dstInfo.offsetFormatted} (${relOffsetText})</span>
+                <span class="tasting-status ${windowStatus.className}">${windowStatus.label}</span>
+              </div>
+            </article>
+          `;
+        }).join('');
+
+        grid.innerHTML = cardsHtml;
+        hubSummary.textContent = `${hubs.length} global hubs synchronized (${idealCount} in ideal daytime cupping hours)`;
+      }
+
+      // Event Listeners
+      dateInput.addEventListener('input', renderSchedule);
+      dateInput.addEventListener('change', renderSchedule);
+      timeInput.addEventListener('input', renderSchedule);
+      timeInput.addEventListener('change', renderSchedule);
+      hostTzSelect.addEventListener('change', renderSchedule);
+      hostTzSelect.addEventListener('input', renderSchedule);
+
+      // Quick preset buttons for testing DST and global schedules
+      document.querySelectorAll('.preset-btn').forEach(btn => {
+        btn.addEventListener('click', () => {
+          const { date, time, tz } = btn.dataset;
+          if (date) dateInput.value = date;
+          if (time) timeInput.value = time;
+          if (tz) hostTzSelect.value = tz;
+          renderSchedule();
+        });
+      });
+
+      // Initial render
+      renderSchedule();
+    })();
+  </script>
+
 </body>

