+const canvas = document.getElementById('smallpt-canvas');
+const ctx = canvas.getContext('2d');
+const randomizeBtn = document.getElementById('randomize-colors-btn');
+const resetBtn = document.getElementById('reset-colors-btn');
+const samplesSelect = document.getElementById('samples-select');
+const statusText = document.getElementById('render-status');
+const swatchContainer = document.getElementById('sphere-swatches');
+
+const WIDTH = 200;
+const HEIGHT = 150;
+canvas.width = WIDTH;
+canvas.height = HEIGHT;
+
+const SPHERE_LABELS = [
+  { index: 0, name: 'Left WallSphere' },
+  { index: 1, name: 'Right WallSphere' },
+  { index: 2, name: 'Back WallSphere' },
+  { index: 4, name: 'Floor Sphere' },
+  { index: 5, name: 'Ceiling Sphere' },
+  { index: 6, name: 'Mirror Sphere' },
+  { index: 7, name: 'Glass Sphere' },
+];
+
+const DEFAULT_COLORS = [
+  { index: 0, r: 0.75, g: 0.25, b: 0.25 },
+  { index: 1, r: 0.25, g: 0.25, b: 0.75 },
+  { index: 2, r: 0.75, g: 0.75, b: 0.75 },
+  { index: 4, r: 0.75, g: 0.75, b: 0.75 },
+  { index: 5, r: 0.75, g: 0.75, b: 0.75 },
+  { index: 6, r: 0.999, g: 0.999, b: 0.999 },
+  { index: 7, r: 0.999, g: 0.999, b: 0.999 },
+];
+
+let currentColors = structuredClone(DEFAULT_COLORS);
+let isRendering = false;
+
+const worker = new Worker(new URL('./worker.js', import.meta.url), {
+  type: 'module',
+});
+
+function toCssRgb({ r, g, b }) {
+  const toByte = (v) => Math.round(Math.pow(Math.min(1, Math.max(0, v)), 1 / 2.2) * 255);
+  return `rgb(${toByte(r)}, ${toByte(g)}, ${toByte(b)})`;
+}
+
+function updateSwatches(colors) {
+  if (!swatchContainer) return;
+  const elements = colors.map((col) => {
+    const meta = SPHERE_LABELS.find((s) => s.index === col.index);
+    const pill = document.createElement('span');
+    pill.className = 'swatch-pill';
+    const dot = document.createElement('span');
+    dot.className = 'swatch-dot';
+    dot.style.backgroundColor = toCssRgb(col);
+    const label = document.createElement('span');
+    label.textContent = meta ? meta.name : `Sphere #${col.index}`;
+    pill.append(dot, label);
+    return pill;
+  });
+  swatchContainer.replaceChildren(...elements);
+}
+
+function randomBrightColor(minChannel = 0.15, maxChannel = 0.92) {
+  const span = maxChannel - minChannel;
+  return {
+    r: Number((minChannel + Math.random() * span).toFixed(3)),
+    g: Number((minChannel + Math.random() * span).toFixed(3)),
+    b: Number((minChannel + Math.random() * span).toFixed(3)),
+  };
+}
+
+function generateRandomizedColors() {
+  return [
+    { index: 0, ...randomBrightColor(0.15, 0.9) },
+    { index: 1, ...randomBrightColor(0.15, 0.9) },
+    { index: 2, ...randomBrightColor(0.25, 0.9) },
+    { index: 4, ...randomBrightColor(0.25, 0.9) },
+    { index: 5, ...randomBrightColor(0.35, 0.95) },
+    { index: 6, ...randomBrightColor(0.45, 0.999) },
+    { index: 7, ...randomBrightColor(0.45, 0.999) },
+  ];
+}
+
+function setUiBusy(busy, message) {
+  isRendering = busy;
+  randomizeBtn.disabled = busy;
+  if (resetBtn) resetBtn.disabled = busy;
+  if (samplesSelect) samplesSelect.disabled = busy;
+  if (statusText && message) {
+    statusText.textContent = message;
+  }
+}
+
+function triggerRender(colors) {
+  if (isRendering) return;
+  currentColors = structuredClone(colors);
+  updateSwatches(currentColors);
+  const samples = Number(samplesSelect?.value || 16);
+  setUiBusy(true, `Tracing rays in WebAssembly (${WIDTH}×${HEIGHT}, ${samples} spp)...`);
+  worker.postMessage({
+    width: WIDTH,
+    height: HEIGHT,
+    samples,
+    colors: currentColors,
+  });
+}
+
+worker.addEventListener('message', (event) => {
+  const data = event.data;
+  if (data.status === 'done') {
+    const imageData = new ImageData(data.pixels, data.width, data.height);
+    ctx.putImageData(imageData, 0, 0);
+    setUiBusy(
+      false,
+      `Rendered ${data.width}×${data.height} (${data.samples} spp) in ${data.durationMs} ms via Wasm Worker`,
+    );
+  } else if (data.status === 'error') {
+    setUiBusy(false, `Render error: ${data.message}`);
+  }
+});
+
+worker.addEventListener('error', (err) => {
+  setUiBusy(false, `Worker error: ${err.message || 'Unknown error'}`);
+});
+
+randomizeBtn.addEventListener('click', () => {
+  triggerRender(generateRandomizedColors());
+});
+
+if (resetBtn) {
+  resetBtn.addEventListener('click', () => {
+    triggerRender(DEFAULT_COLORS);
+  });
+}
+
+if (samplesSelect) {
+  samplesSelect.addEventListener('change', () => {
+    triggerRender(currentColors);
+  });
+}
+
+triggerRender(DEFAULT_COLORS);
