+  <script src="smallpt.js"></script>
+  <script>
+    const SPHERE_LABELS = [
+      { index: 0, name: "Left Wall" },
+      { index: 1, name: "Right Wall" },
+      { index: 2, name: "Back Wall" },
+      { index: 4, name: "Floor" },
+      { index: 5, name: "Ceiling" },
+      { index: 6, name: "Mirror Sphere" },
+      { index: 7, name: "Glass Sphere" }
+    ];

+    const canvas = document.getElementById("render-canvas");
+    const ctx = canvas.getContext("2d");
+    const statusText = document.getElementById("status-text");
+    const statusDot = document.getElementById("status-dot");
+    const renderStats = document.getElementById("render-stats");
+    const progressBar = document.getElementById("progress-bar");
+    const swatchList = document.getElementById("swatch-list");
+    const resolutionSelect = document.getElementById("resolution-select");
+    const samplesSelect = document.getElementById("samples-select");
+    const randomizeBtn = document.getElementById("randomize-btn");
+    const resetBtn = document.getElementById("reset-btn");
+
+    let wasmReady = false;
+    let currentJobId = 0;
+
+    function toSrgbByte(linear) {
+      const clamped = Math.max(0, Math.min(1, linear));
+      return Math.round(Math.pow(clamped, 1 / 2.2) * 255);
+    }
+
+    function rgbToHex(r, g, b) {
+      return "#" + [r, g, b].map(v => v.toString(16).padStart(2, "0")).join("");
+    }
+
+    function updateSwatches() {
+      if (!wasmReady) return;
+      swatchList.innerHTML = "";
+      for (const item of SPHERE_LABELS) {
+        const r = toSrgbByte(Module._get_sphere_color_channel(item.index, 0));
+        const g = toSrgbByte(Module._get_sphere_color_channel(item.index, 1));
+        const b = toSrgbByte(Module._get_sphere_color_channel(item.index, 2));
+        const hex = rgbToHex(r, g, b);
+
+        const el = document.createElement("div");
+        el.className = "swatch-item";
+        el.innerHTML = `
+          <span class="swatch-color" style="background:${hex}"></span>
+          <div class="swatch-meta">
+            <span class="swatch-name">${item.name}</span>
+            <span class="swatch-hex">${hex}</span>
+          </div>
+        `;
+        swatchList.appendChild(el);
+      }
+    }
+
+    function getResolution() {
+      const [w, h] = resolutionSelect.value.split("x").map(Number);
+      return { w, h };
+    }
+
+    function startRender() {
+      if (!wasmReady) return;
+      const jobId = ++currentJobId;
+      const { w, h } = getResolution();
+      const targetSpp = parseInt(samplesSelect.value, 10) || 16;
+
+      if (canvas.width !== w || canvas.height !== h) {
+        canvas.width = w;
+        canvas.height = h;
+      }
+
+      Module._init_renderer(w, h);
+      updateSwatches();
+
+      const totalPasses = Math.max(1, Math.ceil(targetSpp / 4));
+      let completedPasses = 0;
+      const startTime = performance.now();
+
+      statusDot.classList.add("rendering");
+      statusText.textContent = "Rendering path traced passes...";
+      progressBar.style.width = "0%";
+
+      function stepPass() {
+        if (jobId !== currentJobId) return;
+
+        const seed = Math.floor(Math.random() * 0x7fffffff) + completedPasses * 1337 + 1;
+        const ptr = Module._render_pass(1, seed);
+        completedPasses++;
+
+        const totalSpp = Module._get_total_samples();
+        const byteLength = w * h * 4;
+        const pixels = new Uint8ClampedArray(Module.HEAPU8.buffer, ptr, byteLength);
+        const imageData = new ImageData(new Uint8ClampedArray(pixels), w, h);
+        ctx.putImageData(imageData, 0, 0);
+
+        const elapsed = Math.round(performance.now() - startTime);
+        const pct = Math.min(100, Math.round((completedPasses / totalPasses) * 100));
+        progressBar.style.width = pct + "%";
+        renderStats.innerHTML = `${totalSpp} / ${totalPasses * 4} spp &bull; ${elapsed} ms`;
+
+        if (completedPasses < totalPasses) {
+          requestAnimationFrame(stepPass);
+        } else {
+          statusDot.classList.remove("rendering");
+          statusText.textContent = `Render complete (${w}×${h} @ ${totalSpp} spp)`;
+        }
+      }
+
+      requestAnimationFrame(stepPass);
+    }
+
+    randomizeBtn.addEventListener("click", () => {
+      if (!wasmReady) return;
+      const seed = (Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0;
+      Module._randomize_sphere_colors(seed);
+      startRender();
+    });
+
+    resetBtn.addEventListener("click", () => {
+      if (!wasmReady) return;
+      Module._reset_scene_colors();
+      startRender();
+    });
+
+    resolutionSelect.addEventListener("change", () => startRender());
+    samplesSelect.addEventListener("change", () => startRender());
+
+    function onWasmReady() {
+      if (wasmReady) return;
+      wasmReady = true;
+      startRender();
+    }
+
+    if (typeof Module !== "undefined") {
+      if (Module.calledRun) {
+        onWasmReady();
+      } else {
+        const prevInit = Module.onRuntimeInitialized;
+        Module.onRuntimeInitialized = function () {
+          if (prevInit) prevInit();
+          onWasmReady();
+        };
+      }
+    }
+  </script>
