+          <canvas id="smallpt-canvas" width="200" height="150"></canvas>
+        </div>
+        <div class="panel">
+          <div id="render-status">Initializing WebAssembly Worker...</div>
+          <div class="swatches" id="sphere-swatches"></div>
+        </div>
+      </div>
+    </main>
+
+    <script type="module">
+      const canvas = document.getElementById('smallpt-canvas');
+      const ctx = canvas.getContext('2d');
+      const randomizeBtn = document.getElementById('randomize-spheres-btn');
+      const resetBtn = document.getElementById('reset-spheres-btn');
+      const statusEl = document.getElementById('render-status');
+      const swatchesEl = document.getElementById('sphere-swatches');
+
+      const labels = [
+        { index: 0, label: 'Left Wall' },
+        { index: 1, label: 'Right Wall' },
+        { index: 2, label: 'Back Wall' },
+        { index: 4, label: 'Floor' },
