+import React, { useEffect, useRef, useState, useCallback } from 'react';
+
+interface RenderMessage {
+  type: 'rendered' | 'error';
+  requestId: number;
+  pixels?: Uint8ClampedArray;
+  width?: number;
+  height?: number;
+  samples?: number;
+  durationMs?: number;
+  sphereColors?: number[][];
+  randomized?: boolean;
+  message?: string;
+}
+
+const SPHERE_LABELS: { index: number; label: string }[] = [
+  { index: 0, label: 'Left Wall' },
+  { index: 1, label: 'Right Wall' },
+  { index: 2, label: 'Back Wall' },
+  { index: 4, label: 'Floor' },
+  { index: 6, label: 'Mirror Sphere' },
+  { index: 7, label: 'Glass Sphere' },
+];
+
+export default function SmallptPathTracer() {
+  const canvasRef = useRef<HTMLCanvasElement | null>(null);
+  const workerRef = useRef<Worker | null>(null);
+  const requestIdRef = useRef(0);
+
+  const [resolution, setResolution] = useState<'160x120' | '240x180' | '320x240'>('200x150' as '160x120');
+  const [width, setWidth] = useState(200);
+  const [height, setHeight] = useState(150);
+  const [samples, setSamples] = useState(8);
+  const [isRendering, setIsRendering] = useState(true);
+  const [durationMs, setDurationMs] = useState<number | null>(null);
+  const [renderCount, setRenderCount] = useState(0);
+  const [sphereColors, setSphereColors] = useState<number[][] | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  const triggerRender = useCallback(
+    (opts: { w?: number; h?: number; s?: number; randomize?: boolean; reset?: boolean } = {}) => {
+      if (!workerRef.current) return;
+      const targetWidth = opts.w ?? width;
+      const targetHeight = opts.h ?? height;
+      const targetSamples = opts.s ?? samples;
+      const nextRequestId = ++requestIdRef.current;
+
+      setIsRendering(true);
+      setErrorMessage(null);
+
+      const randomSeed =
+        opts.randomize
+          ? ((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0) || 1
+          : 0;
+
+      workerRef.current.postMessage({
+        width: targetWidth,
+        height: targetHeight,
+        samples: targetSamples,
+        randomize: Boolean(opts.randomize),
+        reset: Boolean(opts.reset),
+        seed: randomSeed,
+        requestId: nextRequestId,
+      });
+    },
+    [width, height, samples],
+  );
+
+  useEffect(() => {
+    const worker = new Worker(
+      new URL('../wasm/smallpt-worker.js', import.meta.url),
+      { type: 'module' },
+    );
+    workerRef.current = worker;
+
+    worker.addEventListener('message', (event: MessageEvent<RenderMessage>) => {
+      const data = event.data;
+      if (data.type === 'error') {
+        setErrorMessage(data.message ?? 'WebAssembly path tracer error');
+        setIsRendering(false);
+        return;
+      }
+
+      if (data.type === 'rendered' && data.pixels && data.width && data.height) {
+        const canvas = canvasRef.current;
+        if (canvas) {
+          canvas.width = data.width;
+          canvas.height = data.height;
+          const ctx = canvas.getContext('2d');
+          if (ctx) {
+            const clamped =
+              data.pixels instanceof Uint8ClampedArray
+                ? data.pixels
+                : new Uint8ClampedArray(data.pixels);
+            const imageData = new ImageData(clamped, data.width, data.height);
+            ctx.putImageData(imageData, 0, 0);
+          }
+        }
+        setDurationMs(data.durationMs ?? null);
+        if (data.sphereColors) {
+          setSphereColors(data.sphereColors);
+        }
+        setRenderCount((prev) => prev + 1);
+        setIsRendering(false);
+      }
+    });
+
+    // Run initial path trace on mount
+    const initialRequestId = ++requestIdRef.current;
+    worker.postMessage({
+      width: 200,
+      height: 150,
+      samples: 8,
+      randomize: false,
+      reset: true,
+      requestId: initialRequestId,
+    });
+
+    return () => {
+      worker.terminate();
+      workerRef.current = null;
+    };
+  }, []);
+
+  const handleRandomize = () => {
+    triggerRender({ randomize: true });
+  };
+
+  const handleReset = () => {
+    triggerRender({ reset: true });
+  };
+
+  const handleResolutionChange = (value: string) => {
+    const [wStr, hStr] = value.split('x');
+    const nextW = Number(wStr) || 200;
+    const nextH = Number(hStr) || 150;
+    setResolution(value as '160x120');
+    setWidth(nextW);
+    setHeight(nextH);
+    triggerRender({ w: nextW, h: nextH });
+  };
+
+  const handleSamplesChange = (nextSamples: number) => {
+    setSamples(nextSamples);
+    triggerRender({ s: nextSamples });
+  };
+
+  return (
