+          </span>
+          <h2 id="smallpt-heading" className="text-xl sm:text-2xl font-bold text-white">
+            smallpt C++ Path Tracer (WebAssembly)
+          </h2>
+          <p className="text-sm text-slate-400">
+            Kevin Beason&apos;s Monte Carlo path tracer compiled from C++ to WebAssembly and running client-side in a Web Worker.
+          </p>
+        </div>
+
+        <div className="flex flex-wrap items-center gap-3">
+          <button
+            type="button"
+            id="randomize-spheres-btn"
+            onClick={handleRandomize}
+            disabled={isRendering}
+            className="inline-flex items-center gap-2 rounded-lg bg-amber-400 px-4 py-2.5 text-sm font-bold text-slate-950 shadow hover:bg-amber-300 focus:outline-none focus:ring-2 focus:ring-amber-400 focus:ring-offset-2 focus:ring-offset-slate-950 disabled:opacity-60 cursor-pointer"
+          >
+            {isRendering ? 'Path Tracing...' : 'Randomize Sphere Colors'}
+          </button>
+          <button
+            type="button"
+            id="reset-spheres-btn"
+            onClick={handleReset}
+            disabled={isRendering}
+            className="inline-flex items-center rounded-lg border border-slate-700 bg-slate-800 px-3.5 py-2.5 text-sm font-medium text-slate-200 hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-slate-500 disabled:opacity-60 cursor-pointer"
+          >
+            Reset Classic Colors
+          </button>
+        </div>
+      </div>
+
+      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 p-6 items-center">
+        <div className="lg:col-span-7 flex flex-col items-center justify-center">
+          <div className="relative w-full max-w-[480px] aspect-[4/3] rounded-lg overflow-hidden border border-slate-800 bg-black shadow-inner flex items-center justify-center">
+            <canvas
+              ref={canvasRef}
+              id="smallpt-canvas"
+              width={width}
+              height={height}
+              className="w-full h-full object-contain"
+              style={{ imageRendering: 'auto' }}
+            />
+            {isRendering && (
+              <div className="absolute inset-0 bg-slate-950/60 backdrop-blur-[2px] flex flex-col items-center justify-center gap-2">
+                <div className="h-8 w-8 animate-spin rounded-full border-4 border-amber-400 border-t-transparent" />
+                <span className="text-xs font-medium tracking-wide text-amber-200">
+                  Tracing rays in WebAssembly Worker...
+                </span>
+              </div>
+            )}
+          </div>
+        </div>
+
+        <div className="lg:col-span-5 flex flex-col gap-5">
+          <div className="rounded-lg border border-slate-800 bg-slate-900/60 p-4 space-y-3">
+            <h3 className="text-xs font-semibold uppercase tracking-wider text-slate-400">
+              Render Settings
+            </h3>
+
+            <div className="grid grid-cols-2 gap-3">
+              <label className="block text-xs text-slate-300">
+                <span className="block mb-1 font-medium">Resolution</span>
+                <select
+                  value={resolution}
+                  onChange={(e) => handleResolutionChange(e.target.value)}
+                  disabled={isRendering}
+                  className="w-full rounded border border-slate-700 bg-slate-800 px-2.5 py-1.5 text-sm text-white focus:border-amber-400 focus:outline-none"
+                >
+                  <option value="160x120">160 × 120 (Fastest)</option>
+                  <option value="200x150">200 × 150 (Default)</option>
+                  <option value="320x240">320 × 240 (Detailed)</option>
+                </select>
+              </label>
+
+              <label className="block text-xs text-slate-300">
+                <span className="block mb-1 font-medium">Samples / Pixel</span>
+                <select
+                  value={samples}
+                  onChange={(e) => handleSamplesChange(Number(e.target.value))}
+                  disabled={isRendering}
+                  className="w-full rounded border border-slate-700 bg-slate-800 px-2.5 py-1.5 text-sm text-white focus:border-amber-400 focus:outline-none"
+                >
+                  <option value={4}>4 spp (Draft)</option>
+                  <option value={8}>8 spp (Balanced)</option>
