diff --git a/src/wasm/smallpt-worker.js b/src/wasm/smallpt-worker.js
new file mode 100644
index 0000000..706528a
--- /dev/null
+++ b/src/wasm/smallpt-worker.js
@@ -0,0 +1,95 @@
+import initSmallpt from './smallpt.js';
+
+let wasmPromise = null;
+
+function getWasmModule() {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt();
+  }
+  return wasmPromise;
+}
+
+function readSphereColors(wasm) {
+  const count = 9 * 3;
+  const byteLength = count * Float64Array.BYTES_PER_ELEMENT;
+  const ptr = wasm._malloc(byteLength);
+  try {
+    wasm._get_sphere_colors(ptr);
+    const values = new Float64Array(wasm.HEAPF64.buffer, ptr, count);
+    const colors = [];
+    for (let i = 0; i < 9; i++) {
+      colors.push([
+        Math.round(Math.pow(Math.min(1, Math.max(0, values[i * 3])), 1 / 2.2) * 255),
+        Math.round(Math.pow(Math.min(1, Math.max(0, values[i * 3 + 1])), 1 / 2.2) * 255),
+        Math.round(Math.pow(Math.min(1, Math.max(0, values[i * 3 + 2])), 1 / 2.2) * 255),
+      ]);
+    }
+    return colors;
+  } finally {
+    wasm._free(ptr);
+  }
+}
+
+self.addEventListener('message', async (event) => {
+  const {
+    width = 320,
+    height = 240,
+    samples = 16,
+    randomize = false,
+    reset = false,
+    seed = 0,
+    requestId = 0,
+  } = event.data ?? {};
+
+  try {
+    const wasm = await getWasmModule();
+
+    if (reset) {
+      wasm._reset_spheres();
+    } else if (randomize) {
+      const actualSeed =
+        (seed >>> 0) ||
+        ((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0) ||
+        1;
+      wasm._randomize_spheres(actualSeed);
+    }
+
+    const sphereColors = readSphereColors(wasm);
+    const byteLength = width * height * 4;
+    const ptr = wasm._malloc(byteLength);
+    const startTime = performance.now();
+
+    try {
+      wasm._render_frame(ptr, width, height, samples);
+      const durationMs = Math.round(performance.now() - startTime);
+      const pixels = new Uint8ClampedArray(
+        wasm.HEAPU8.buffer,
+        ptr,
+        byteLength,
+      ).slice();
+
+      self.postMessage(
+        {
+          type: 'rendered',
+          requestId,
+          pixels,
+          width,
+          height,
+          samples,
+          durationMs,
+          sphereColors,
+          randomized: Boolean(randomize),
+        },
+        [pixels.buffer],
+      );
+    } finally {
+      wasm._free(ptr);
+    }
+  } catch (error) {
+    self.postMessage({
+      type: 'error',
+      requestId,
+      message: error instanceof Error ? error.message : String(error),
+    });
+  }
+});
