+  auto nextUnit = [&]() {
+    return static_cast<double>(xorshift32(state) & 0xFFFFFFU) /
+           static_cast<double>(0x1000000U);
+  };
+  double r = minVal + (maxVal - minVal) * nextUnit();
+  double g = minVal + (maxVal - minVal) * nextUnit();
+  double b = minVal + (maxVal - minVal) * nextUnit();
+  return Vec(r, g, b);
+}
