+  spheres[0].c = randomVividColor(state, 0.15, 0.85);  // Left wall
+  spheres[1].c = randomVividColor(state, 0.15, 0.85);  // Right wall
+  spheres[2].c = randomVividColor(state, 0.25, 0.85);  // Back wall
+  spheres[4].c = randomVividColor(state, 0.25, 0.85);  // Floor
+  spheres[5].c = randomVividColor(state, 0.45, 0.90);  // Ceiling
+  // Randomize mirror and glass sphere surface tints
+  spheres[6].c = randomVividColor(state, 0.35, 0.999);  // Mirror sphere
+  spheres[7].c = randomVividColor(state, 0.35, 0.999);  // Glass sphere
+}
+
+void get_sphere_colors(double* out_rgb) {
+  if (!out_rgb) return;
+  for (int i = 0; i < 9; ++i) {
+    out_rgb[i * 3 + 0] = spheres[i].c.x;
+    out_rgb[i * 3 + 1] = spheres[i].c.y;
+    out_rgb[i * 3 + 2] = spheres[i].c.z;
+  }
+}
+
+void render_frame(uint8_t* out_rgba, int width, int height, int samples) {
+  if (!out_rgba || width <= 0 || height <= 0) return;
+  int samps = samples / 4;
+  if (samps < 1) samps = 1;
+
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm());
+  Vec cx = Vec(width * .5135 / height);
+  Vec cy = (cx % cam.d).norm() * .5135;
+  size_t total_pixels = static_cast<size_t>(width) * static_cast<size_t>(height);
+  Vec* c = static_cast<Vec*>(std::calloc(total_pixels, sizeof(Vec)));
+  if (!c) return;
+
+  for (int y = 0; y < height; ++y) {
+    unsigned short Xi[3] = {
+        0, 0, static_cast<unsigned short>(y * y * y)};
+    for (int x = 0; x < width; ++x) {
+      int i = (height - y - 1) * width + x;
+      for (int sy = 0; sy < 2; ++sy) {
+        for (int sx = 0; sx < 2; ++sx) {
+          Vec r;
+          for (int s = 0; s < samps; ++s) {
+            double r1 = 2.0 * smallpt_erand48(Xi);
+            double dx = r1 < 1.0 ? std::sqrt(r1) - 1.0 : 1.0 - std::sqrt(2.0 - r1);
+            double r2 = 2.0 * smallpt_erand48(Xi);
+            double dy = r2 < 1.0 ? std::sqrt(r2) - 1.0 : 1.0 - std::sqrt(2.0 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2.0 + x) / width - .5) +
+                    cy * (((sy + .5 + dy) / 2.0 + y) / height - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140.0, d.norm()), 0, Xi) *
+                        (1.0 / samps);
+          }
+          c[i] = c[i] + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+        }
+      }
+    }
+  }
+
+  for (size_t i = 0; i < total_pixels; ++i) {
+    out_rgba[i * 4 + 0] = toByte(c[i].x);
+    out_rgba[i * 4 + 1] = toByte(c[i].y);
+    out_rgba[i * 4 + 2] = toByte(c[i].z);
+    out_rgba[i * 4 + 3] = 255;
+  }
+  std::free(c);
+}
+
+}  // extern "C"
