+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+static uint8_t *framebuffer = NULL;
+static int fb_size = 0;
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE
+void reset_sphere_colors() {
+  int n = sizeof(spheres) / sizeof(Sphere);
+  for (int i = 0; i < n; i++) {
+    spheres[i].c = default_colors[i];
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int index, double r, double g, double b) {
+  int n = sizeof(spheres) / sizeof(Sphere);
+  if (index >= 0 && index < n) {
+    spheres[index].c = Vec(clamp(r), clamp(g), clamp(b));
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color(int index, int channel) {
+  int n = sizeof(spheres) / sizeof(Sphere);
+  if (index < 0 || index >= n) return 0.0;
+  if (channel == 0) return spheres[index].c.x;
+  if (channel == 1) return spheres[index].c.y;
+  if (channel == 2) return spheres[index].c.z;
+  return 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(unsigned int seed) {
+  unsigned short Xi[3] = {
+    (unsigned short)(seed & 0xFFFF),
+    (unsigned short)((seed >> 16) & 0xFFFF),
+    (unsigned short)((seed ^ 0xA5A5) & 0xFFFF)
+  };
+  // Advance PRNG a few times to mix seed
+  for (int k = 0; k < 8; k++) erand48(Xi);
+
+  // Randomize visible diffuse wall spheres (0: Left, 1: Right, 2: Back, 4: Bottom, 5: Top)
+  int wall_indices[] = {0, 1, 2, 4, 5};
+  for (int idx = 0; idx < 5; idx++) {
+    int i = wall_indices[idx];
+    double r = 0.15 + 0.75 * erand48(Xi);
+    double g = 0.15 + 0.75 * erand48(Xi);
+    double b = 0.15 + 0.75 * erand48(Xi);
+    spheres[i].c = Vec(r, g, b);
+  }
+
+  // Randomize foreground Mirror (6) and Glass (7) spheres with bright saturated tints
+  for (int i = 6; i <= 7; i++) {
+    double r = 0.35 + 0.649 * erand48(Xi);
+    double g = 0.35 + 0.649 * erand48(Xi);
+    double b = 0.35 + 0.649 * erand48(Xi);
