+    else if (boost == 1) g = 0.9 + 0.099 * erand48(Xi);
+    else b = 0.9 + 0.099 * erand48(Xi);
+    spheres[i].c = Vec(r, g, b);
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_framebuffer() {
+  return framebuffer;
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render_smallpt(int w, int h, int samps) {
+  if (w <= 0) w = 320;
+  if (h <= 0) h = 240;
+  if (samps <= 0) samps = 1;
+
+  int needed = w * h * 4;
+  if (framebuffer == NULL || fb_size < needed) {
+    if (framebuffer) free(framebuffer);
+    framebuffer = (uint8_t*)malloc(needed);
+    fb_size = needed;
+  }
+
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  Vec *c = new Vec[w*h];
+
+  for (int y=0; y<h; y++){                       // Loop over image rows
+    for (unsigned short x=0, Xi[3]={0,0,(unsigned short)(y*y*y)}; x<w; x++)   // Loop cols
