+    const roastSelect = document.getElementById('roast-select');
+    if (roastSelect) {
+      roastSelect.addEventListener('keydown', (e) => {
+        if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
+        const options = Array.from(roastSelect.querySelectorAll('option'));
+        const active = document.activeElement;
+        const currentIndex = options.indexOf(active);
+        if (currentIndex === -1) return;
+
+        const currentRect = active.getBoundingClientRect();
+        const isRight = e.key === 'ArrowRight';
+
+        const candidates = options
+          .filter((opt) => opt !== active)
+          .map((opt) => ({ opt, rect: opt.getBoundingClientRect() }))
+          .filter(({ rect }) =>
+            isRight
+              ? rect.left >= currentRect.right - 2
+              : rect.right <= currentRect.left + 2
+          )
+          .sort((a, b) => {
+            const distA = Math.hypot(
+              a.rect.left - currentRect.left,
+              a.rect.top - currentRect.top
+            );
+            const distB = Math.hypot(
+              b.rect.left - currentRect.left,
+              b.rect.top - currentRect.top
+            );
+            return distA - distB;
+          });
+
