+  <script>
+    (function () {
+      const toggleBtn = document.getElementById('theme-toggle');
+      const iconEl = toggleBtn.querySelector('.theme-icon');
+      const labelEl = toggleBtn.querySelector('.theme-label');
+      const rootEl = document.documentElement;
+      const bodyEl = document.body;
+      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function getEffectiveTheme() {
+        const manualTheme = rootEl.getAttribute('data-theme');
+        if (manualTheme === 'dark' || manualTheme === 'light') {
+          return manualTheme;
+        }
+        return mediaQuery.matches ? 'dark' : 'light';
+      }
+
+      function applyTheme(theme, persist) {
+        rootEl.setAttribute('data-theme', theme);
+        bodyEl.setAttribute('data-theme', theme);
+        rootEl.classList.toggle('dark-mode', theme === 'dark');
+        rootEl.classList.toggle('light-mode', theme === 'light');
+        bodyEl.classList.toggle('dark-mode', theme === 'dark');
+        bodyEl.classList.toggle('light-mode', theme === 'light');
+
+        if (persist) {
+          try {
+            localStorage.setItem('theme', theme);
+          } catch (e) {}
+        }
+
+        updateToggleUI(theme);
+      }
+
+      function updateToggleUI(theme) {
+        const isDark = theme === 'dark';
+        toggleBtn.setAttribute('aria-pressed', String(isDark));
+        toggleBtn.setAttribute('aria-label', isDark ? 'Switch to light mode' : 'Switch to dark mode');
+        if (iconEl) iconEl.textContent = isDark ? '☀️' : '🌙';
+        if (labelEl) labelEl.textContent = isDark ? 'Light Mode' : 'Dark Mode';
+      }
+
+      // Initialize from saved user preference or system preference
+      let savedTheme = null;
+      try {
+        savedTheme = localStorage.getItem('theme');
+      } catch (e) {}
+
+      if (savedTheme === 'dark' || savedTheme === 'light') {
+        applyTheme(savedTheme, false);
+      } else {
+        updateToggleUI(getEffectiveTheme());
+      }
+
+      toggleBtn.addEventListener('click', function () {
+        const nextTheme = getEffectiveTheme() === 'dark' ? 'light' : 'dark';
+        applyTheme(nextTheme, true);
+      });
+
+      mediaQuery.addEventListener('change', function () {
+        if (!rootEl.hasAttribute('data-theme')) {
+          updateToggleUI(getEffectiveTheme());
+        }
+      });
+    })();
