+      async function generateLatticeKeypair() {
+        const matrixSeed = window.crypto.getRandomValues(new Uint8Array(32));
+        const A = deriveMatrixA(matrixSeed);
+        const s = [];
+        const randBuf = window.crypto.getRandomValues(new Uint8Array(LATTICE_DIM));
+        for (let i = 0; i < LATTICE_DIM; i++) {
+          s.push((randBuf[i] % 1024) + 1);
+        }
+        const t = matVecMulModQ(A, s);
+        const wots = await generateWotsKeypair();
+        return {
+          matrixSeedHex: bufToHex(matrixSeed),
+          s,
+          t,
+          wots
+        };
+      }
+
+      async function signLattice(payloadBytes, latticeKey) {
+        const matrixSeed = hexToBytes(latticeKey.matrixSeedHex);
+        const A = deriveMatrixA(matrixSeed);
