+        const msgDigest = await sha256Bytes(payloadBytes);
+        const y = [];
+        for (let i = 0; i < LATTICE_DIM; i++) {
+          y.push(((msgDigest[i] << 8) | msgDigest[i + 16]) % 32768 + 512);
+        }
+        const w = matVecMulModQ(A, y);
+        // Challenge c in [1..63] from H(w || msgDigest || t)
+        const challengeDigest = await sha256Bytes(encoder.encode(w.join(',') + '|' + bufToHex(msgDigest) + '|' + latticeKey.t.join(',')));
+        const c = (challengeDigest[0] & 0x3f) + 1;
+        // Response vector z = y + c * s mod q
+        const z = y.map((yi, idx) => (yi + c * latticeKey.s[idx]) % LATTICE_Q);
+        // Bind response vector z and message digest via WOTS signature so z cannot be forged without secret
+        const bindingDigest = await sha256Bytes(encoder.encode(bufToHex(msgDigest) + ':' + c + ':' + z.join(',')));
+        const wotsSigHex = await signWots(bindingDigest, latticeKey.wots);
+        return JSON.stringify({
+          scheme: 'PQ-LATTICE-MLDSA-v1',
+          c,
+          z,
+          wotsProof: wotsSigHex
+        });
+      }
