+          const matrixSeed = hexToBytes(pubObj.matrixSeedHex);
+          const A = deriveMatrixA(matrixSeed);
+          const Az = matVecMulModQ(A, parsed.z);
+          // Reconstruct w' = A*z - c*t mod q
+          const wPrime = Az.map((azi, idx) => {
+            const ct = (parsed.c * pubObj.t[idx]) % LATTICE_Q;
