+          });
+          const msgDigest = await sha256Bytes(payloadBytes);
+          const expectedCDigest = await sha256Bytes(encoder.encode(wPrime.join(',') + '|' + bufToHex(msgDigest) + '|' + pubObj.t.join(',')));
+          const expectedC = (expectedCDigest[0] & 0x3f) + 1;
+          if (expectedC !== parsed.c) return false;
