+          const bindingDigest = await sha256Bytes(encoder.encode(bufToHex(msgDigest) + ':' + parsed.c + ':' + parsed.z.join(',')));
+          return await verifyWots(bindingDigest, parsed.wotsProof, pubObj.wotsPubRoot);
+        } catch (e) {
+          return false;
+        }
+      }
