+import React, { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStory {
+  id: string;
+  data: {
+    title: string;
+    date: Date | string;
+    category?: string;
+    summary?: string;
+  };
+}
+
+interface TopStoriesCarouselProps {
+  stories: TopStory[];
+  baseUrl?: string;
+}
+
+export default function TopStoriesCarousel({
+  stories,
+  baseUrl = import.meta.env.BASE_URL || '/',
+}: TopStoriesCarouselProps) {
+  const [currentIndex, setCurrentIndex] = useState(0);
+  const [direction, setDirection] = useState<'next' | 'prev' | null>(null);
+  const [step, setStep] = useState(0);
+
+  if (!stories || stories.length === 0) {
+    return null;
+  }
+
+  const handlePrevious = () => {
+    setDirection('prev');
+    setStep((prev) => prev + 1);
+    setCurrentIndex((prevIndex) => (prevIndex - 1 + stories.length) % stories.length);
+  };
+
+  const handleNext = () => {
+    setDirection('next');
+    setStep((prev) => prev + 1);
+    setCurrentIndex((prevIndex) => (prevIndex + 1) % stories.length);
+  };
+
+  const currentStory = stories[currentIndex];
+  const normalizedBaseUrl = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+  const formattedDate = new Date(currentStory.data.date).toLocaleDateString();
+
+  const animationClass =
+    direction === 'next'
+      ? 'slide-in-right'
+      : direction === 'prev'
+      ? 'slide-in-left'
+      : '';
+
+  return (
+    <section
+      aria-label="Top Stories"
+      aria-roledescription="carousel"
+      className="bg-white border-b border-gray-300"
+    >
+      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
+        <div className="flex items-center justify-between gap-4">
+          <div className="flex items-center gap-3 shrink-0">
+            <span className="text-xs font-semibold uppercase tracking-wider text-amber-800 hidden sm:inline-block">
+              Top Stories
+            </span>
+            <button
+              type="button"
+              onClick={handlePrevious}
+              aria-label="Previous"
+              className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-semibold text-gray-700 bg-gray-100 hover:bg-amber-400 hover:text-gray-900 rounded transition-colors cursor-pointer"
+            >
+              <ChevronLeftIcon className="w-4 h-4" aria-hidden="true" />
+              <span>Previous</span>
+            </button>
+          </div>
+
+          <div
+            className="flex-1 overflow-hidden relative min-w-0"
+            aria-live="polite"
+            aria-atomic="true"
+          >
+            <div
+              key={`${currentStory.id}-${step}`}
+              data-direction={direction ?? 'none'}
+              data-story-index={currentIndex}
+              className={`w-full ${animationClass}`}
+            >
+              <div className="flex flex-col sm:flex-row sm:items-baseline sm:justify-between gap-1 sm:gap-4 px-2">
+                <a
+                  href={`${normalizedBaseUrl}articles/${currentStory.id}`}
+                  className="truncate"
+                >
+                  <h3 className="font-bold text-gray-900 hover:text-amber-400 transition-colors cursor-pointer truncate">
+                    {currentStory.data.title}
+                  </h3>
+                </a>
+                <span className="text-xs text-gray-500 shrink-0">
+                  {formattedDate}
+                </span>
+              </div>
+            </div>
+          </div>
+
+          <div className="flex items-center gap-3 shrink-0">
+            <span
+              className="text-xs text-gray-500 tabular-nums hidden md:inline-block"
+              aria-label={`Story ${currentIndex + 1} of ${stories.length}`}
+            >
+              {currentIndex + 1} / {stories.length}
+            </span>
+            <button
+              type="button"
+              onClick={handleNext}
+              aria-label="Next"
+              className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-semibold text-gray-700 bg-gray-100 hover:bg-amber-400 hover:text-gray-900 rounded transition-colors cursor-pointer"
+            >
+              <span>Next</span>
+              <ChevronRightIcon className="w-4 h-4" aria-hidden="true" />
+            </button>
+          </div>
+        </div>
+      </div>
+    </section>
+  );
+}
