+        if (!card || !grid.contains(card)) return;
+        activeCard = card;
+        isNativeDrag = false;
+        lastDisplacedCard = null;
+        startX = clientX || 0;
+        didReorderOrMove = false;
+      }
+
+      function onPointerMove(clientX, targetEl) {
+        if (!activeCard || isNativeDrag) return;
+        if (typeof clientX === 'number' && clientX > 0) {
+          if (Math.abs(clientX - startX) > 5) {
+            activeCard.classList.add('dragging');
+            didReorderOrMove = true;
+            moveCardToClientX(activeCard, clientX);
+          }
+        } else if ((!clientX || clientX === 0) && targetEl) {
+          const targetCard = targetEl.closest?.('.card');
+          if (targetCard && targetCard !== activeCard) {
+            activeCard.classList.add('dragging');
+            moveCardRelativeToTarget(activeCard, targetCard);
+          }
+        }
+      }
+
+      function onPointerEnd(clientX, targetEl) {
+        if (!activeCard || isNativeDrag) return;
+        if (typeof clientX === 'number' && clientX > 0 && Math.abs(clientX - startX) > 5) {
+          moveCardToClientX(activeCard, clientX);
+        } else if ((!clientX || clientX === 0) && targetEl) {
+          const targetCard = targetEl.closest?.('.card');
+          moveCardRelativeToTarget(activeCard, targetCard);
+        }
+        activeCard.classList.remove('dragging');
+        activeCard = null;
+        lastDisplacedCard = null;
+      }
