+      // Prevent accidental link navigation right after dragging a card
+      grid.addEventListener('click', (e) => {
+        if (didReorderOrMove) {
+          e.preventDefault();
+          didReorderOrMove = false;
+        }
+      }, true);
+    })();
+  </script>
