+        const maxLeft = Math.max(0, window.innerWidth - draggable.offsetWidth);
+        const maxTop = Math.max(0, window.innerHeight - draggable.offsetHeight);
+
+        const clampedLeft = Math.max(0, Math.min(left, maxLeft));
+        const clampedTop = Math.max(0, Math.min(top, maxTop));
+
+        draggable.style.right = 'auto';
+        draggable.style.bottom = 'auto';
+        draggable.style.margin = '0';
+        draggable.style.left = `${Math.round(clampedLeft)}px`;
+        draggable.style.top = `${Math.round(clampedTop)}px`;
+      }
+
+      function announceMove(description) {
+        if (!liveRegion || !description) return;
+        if (announceTimeoutId) {
+          clearTimeout(announceTimeoutId);
+        }
+        liveRegion.textContent = `Quick Order Cart ${description}`;
+        announceTimeoutId = setTimeout(() => {
+          liveRegion.textContent = '';
+        }, 1000);
+      }
+
+      function describeDelta(prevLeft, prevTop, nextLeft, nextTop) {
+        const dx = nextLeft - prevLeft;
+        const dy = nextTop - prevTop;
+        if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return '';
+        const parts = [];
+        if (dy <= -4) parts.push('up');
+        else if (dy >= 4) parts.push('down');
+        if (dx <= -4) parts.push('left');
+        else if (dx >= 4) parts.push('right');
+        return parts.length > 0 ? `moved ${parts.join(' and ')}` : 'moved';
+      }
+
+      // Initialize starting position in clamped left/top coordinates with room on all 4 sides
+      const initialRect = draggable.getBoundingClientRect();
+      moveTo(initialRect.left, initialRect.top);
+
+      // Pointer dragging via dedicated handle with pointer capture
+      handle.addEventListener('pointerdown', (event) => {
+        const control = event.target.closest('button, input, select, textarea, a');
+        if (event.button !== 0 || (control && control !== handle)) return;
+
+        const rect = draggable.getBoundingClientRect();
+        startLeft = rect.left;
+        startTop = rect.top;
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        isDragging = true;
+        movedDuringDrag = false;
+        activePointerId = event.pointerId;
+
+        try {
+          handle.setPointerCapture(event.pointerId);
+        } catch {
+          // Synthetic PointerEvents without active hardware pointerId fall back to isDragging
+        }
+      });
+
+      function onPointerMove(event) {
+        const hasCapture = (() => {
+          try {
+            return handle.hasPointerCapture(event.pointerId);
+          } catch {
+            return false;
+          }
+        })();
+        if (!hasCapture && !isDragging) return;
+        if (activePointerId !== null && event.pointerId !== undefined && event.pointerId !== activePointerId) return;
+
+        handle.classList.add('dragging');
+        movedDuringDrag = true;
+        moveTo(event.clientX - offsetX, event.clientY - offsetY);
+      }
+
+      function finishDrag() {
+        if (!isDragging && !handle.classList.contains('dragging')) return;
+        const didMove = movedDuringDrag;
+        isDragging = false;
+        movedDuringDrag = false;
+        activePointerId = null;
+        handle.classList.remove('dragging');
+
+        if (didMove) {
+          const rect = draggable.getBoundingClientRect();
+          const desc = describeDelta(startLeft, startTop, rect.left, rect.top);
+          if (desc) announceMove(desc);
+        }
+      }
+
+      handle.addEventListener('pointermove', onPointerMove);
+      document.addEventListener('pointermove', (event) => {
+        if (!isDragging) return;
+        if (event.target === handle || handle.contains(event.target)) return;
+        onPointerMove(event);
+      });
+
+      handle.addEventListener('lostpointercapture', finishDrag);
+      handle.addEventListener('pointerup', finishDrag);
+      handle.addEventListener('pointercancel', finishDrag);
+      document.addEventListener('pointerup', finishDrag);
+      document.addEventListener('pointercancel', finishDrag);
+
+      // Keyboard movement on handle focus with arrow keys
+      handle.addEventListener('keydown', (event) => {
+        const rect = draggable.getBoundingClientRect();
+        let nextLeft = rect.left;
+        let nextTop = rect.top;
+        let direction = '';
+
+        switch (event.key) {
+          case 'ArrowLeft':
+            nextLeft -= KEYBOARD_STEP;
+            direction = 'moved left';
+            break;
+          case 'ArrowRight':
+            nextLeft += KEYBOARD_STEP;
+            direction = 'moved right';
+            break;
+          case 'ArrowUp':
+            nextTop -= KEYBOARD_STEP;
+            direction = 'moved up';
+            break;
+          case 'ArrowDown':
+            nextTop += KEYBOARD_STEP;
+            direction = 'moved down';
+            break;
+          default:
+            return;
+        }
+
+        event.preventDefault();
+        moveTo(nextLeft, nextTop);
+        announceMove(direction);
+      });
+
+      // Re-clamp current position when viewport or panel size changes
+      function reclampPosition() {
+        const rect = draggable.getBoundingClientRect();
+        moveTo(rect.left, rect.top);
+      }
+
+      window.addEventListener('resize', reclampPosition);
+      if (typeof ResizeObserver !== 'undefined') {
+        const resizeObserver = new ResizeObserver(() => {
+          reclampPosition();
+        });
+        resizeObserver.observe(draggable);
+      }
+
+      // Single-pointer Move / Dock drawer & Keyboard Help drawer toggles
+      const repositionBtn = document.getElementById('reposition-toggle-btn');
+      const repositionDrawer = document.getElementById('reposition-drawer');
+      const helpBtn = document.getElementById('drag-help-btn');
+      const helpDrawer = document.getElementById('drag-help-drawer');
+      const collapseBtn = document.getElementById('collapse-cart-btn');
+      const cartBody = document.getElementById('quick-order-body');
+
+      if (repositionBtn && repositionDrawer) {
+        repositionBtn.addEventListener('click', () => {
+          const isOpen = repositionBtn.getAttribute('aria-expanded') === 'true';
+          repositionBtn.setAttribute('aria-expanded', String(!isOpen));
+          repositionDrawer.hidden = isOpen;
+          reclampPosition();
+        });
+
+        repositionDrawer.addEventListener('click', (event) => {
+          const actionBtn = event.target.closest('[data-move-action]');
+          if (!actionBtn) return;
+          const action = actionBtn.getAttribute('data-move-action');
+          const rect = draggable.getBoundingClientRect();
+          const maxLeft = Math.max(0, window.innerWidth - draggable.offsetWidth);
+          const maxTop = Math.max(0, window.innerHeight - draggable.offsetHeight);
+
+          switch (action) {
+            case 'dock-left':
+              moveTo(EDGE_PADDING, rect.top);
+              announceMove('docked left');
+              break;
+            case 'dock-right':
+              moveTo(Math.max(0, maxLeft - EDGE_PADDING), rect.top);
+              announceMove('docked right');
+              break;
+            case 'dock-top':
+              moveTo(rect.left, EDGE_PADDING);
+              announceMove('docked top');
+              break;
+            case 'dock-bottom':
+              moveTo(rect.left, Math.max(0, maxTop - EDGE_PADDING));
+              announceMove('docked bottom');
+              break;
+            case 'move-left':
+              moveTo(rect.left - SINGLE_CLICK_STEP, rect.top);
+              announceMove('moved left');
+              break;
+            case 'move-right':
+              moveTo(rect.left + SINGLE_CLICK_STEP, rect.top);
+              announceMove('moved right');
+              break;
+            case 'move-up':
+              moveTo(rect.left, rect.top - SINGLE_CLICK_STEP);
+              announceMove('moved up');
+              break;
+            case 'move-down':
+              moveTo(rect.left, rect.top + SINGLE_CLICK_STEP);
+              announceMove('moved down');
+              break;
+          }
+        });
+      }
+
+      if (helpBtn && helpDrawer) {
+        helpBtn.addEventListener('click', () => {
+          const isOpen = helpBtn.getAttribute('aria-expanded') === 'true';
+          helpBtn.setAttribute('aria-expanded', String(!isOpen));
+          helpDrawer.hidden = isOpen;
+          reclampPosition();
+        });
+      }
+
+      if (collapseBtn && cartBody) {
+        collapseBtn.addEventListener('click', () => {
+          const isExpanded = collapseBtn.getAttribute('aria-expanded') === 'true';
+          collapseBtn.setAttribute('aria-expanded', String(!isExpanded));
+          collapseBtn.setAttribute(
+            'aria-label',
+            isExpanded ? 'Expand Quick Order Cart' : 'Minimize Quick Order Cart'
+          );
+          collapseBtn.textContent = isExpanded ? '+' : '\u2212';
+          cartBody.hidden = isExpanded;
+          reclampPosition();
+        });
+      }
+
+      // Interactive Quick-Order Cart Logic
+      const form = document.getElementById('quick-order-form');
+      const badgeEl = document.getElementById('cart-count-badge');
+      const totalEl = document.getElementById('cart-total-display');
+      const checkoutBtn = document.getElementById('checkout-btn');
+      const clearBtn = document.getElementById('clear-cart-btn');
+      const statusEl = document.getElementById('order-status');
+      const pickupInput = document.getElementById('pickup-name');
+      const pickupError = document.getElementById('pickup-name-error');
+      let pickupVisited = false;
+
+      function updateCartTotals() {
+        const rows = draggable.querySelectorAll('.cart-item-row');
+        let totalQty = 0;
+        let itemsBaseSubtotal = 0;
+
+        rows.forEach((row) => {
+          const unitPrice = parseFloat(row.getAttribute('data-item-price') || '0');
+          const qtyOutput = row.querySelector('.qty-value');
+          const qty = parseInt(qtyOutput ? qtyOutput.textContent : '0', 10) || 0;
+          totalQty += qty;
+          itemsBaseSubtotal += qty * unitPrice;
+        });
+
+        const selectedSize = form.querySelector('input[name="cup_size"]:checked');
+        const sizeUpcharge = selectedSize ? parseFloat(selectedSize.value || '0') : 0;
+
+        let addonUpcharge = 0;
+        form.querySelectorAll('input[type="checkbox"]:checked').forEach((box) => {
+          addonUpcharge += parseFloat(box.value || '0');
+        });
+
+        const perCupExtra = totalQty > 0 ? totalQty * (sizeUpcharge + addonUpcharge) : 0;
+        const grandTotal = itemsBaseSubtotal + perCupExtra;
+        const formattedTotal = `$${grandTotal.toFixed(2)}`;
+
+        if (badgeEl) {
+          badgeEl.textContent = `${totalQty} ${totalQty === 1 ? 'item' : 'items'}`;
+        }
+        if (totalEl) {
+          totalEl.textContent = formattedTotal;
+        }
+        if (checkoutBtn) {
+          checkoutBtn.textContent = `Pay ${formattedTotal}`;
+          checkoutBtn.disabled = false;
+        }
+      }
+
+      draggable.querySelectorAll('.qty-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const row = btn.closest('.cart-item-row');
+          if (!row) return;
+          const delta = parseInt(btn.getAttribute('data-qty-delta') || '0', 10);
+          const output = row.querySelector('.qty-value');
+          const hiddenInput = row.querySelector('input[type="hidden"]');
+          const currentQty = parseInt(output ? output.textContent : '0', 10) || 0;
+          const nextQty = Math.max(0, Math.min(20, currentQty + delta));
+
+          if (output) output.textContent = String(nextQty);
+          if (hiddenInput) hiddenInput.value = String(nextQty);
+          if (statusEl) statusEl.hidden = true;
+          updateCartTotals();
+        });
+      });
+
+      if (form) {
+        form.addEventListener('change', (event) => {
+          if (event.target.matches('input[type="radio"], input[type="checkbox"]')) {
+            if (statusEl) statusEl.hidden = true;
+            updateCartTotals();
+          }
+        });
+      }
+
+      function validatePickupName() {
+        if (!pickupInput || !pickupError) return true;
+        const valid = pickupInput.value.trim().length > 0;
+        if (!valid) {
+          pickupInput.setAttribute('aria-invalid', 'true');
+          pickupError.hidden = false;
+        } else {
+          pickupInput.removeAttribute('aria-invalid');
+          pickupError.hidden = true;
+        }
+        return valid;
+      }
+
+      if (pickupInput) {
+        pickupInput.addEventListener('blur', () => {
+          pickupVisited = true;
+          validatePickupName();
+        });
+        pickupInput.addEventListener('input', () => {
+          if (pickupVisited || pickupInput.getAttribute('aria-invalid') === 'true') {
+            if (pickupInput.value.trim().length > 0) {
+              pickupInput.removeAttribute('aria-invalid');
+              if (pickupError) pickupError.hidden = true;
+            }
+          }
+        });
+      }
+
+      if (clearBtn && form) {
+        clearBtn.addEventListener('click', () => {
+          draggable.querySelectorAll('.cart-item-row').forEach((row, index) => {
+            const defaultQty = index === 0 ? 1 : 0;
+            const output = row.querySelector('.qty-value');
+            const hiddenInput = row.querySelector('input[type="hidden"]');
+            if (output) output.textContent = String(defaultQty);
+            if (hiddenInput) hiddenInput.value = String(defaultQty);
+          });
+          const mediumRadio = document.getElementById('size-medium');
+          if (mediumRadio) mediumRadio.checked = true;
+          form.querySelectorAll('input[type="checkbox"]').forEach((box) => {
+            box.checked = false;
+          });
+          if (statusEl) {
+            statusEl.hidden = true;
+            statusEl.textContent = '';
+          }
+          updateCartTotals();
+        });
+      }
+
+      if (form) {
+        form.addEventListener('submit', (event) => {
+          event.preventDefault();
+          if (!validatePickupName()) {
+            pickupInput.focus();
+            return;
+          }
+          const rows = draggable.querySelectorAll('.cart-item-row');
+          let totalQty = 0;
+          rows.forEach((row) => {
+            const output = row.querySelector('.qty-value');
+            totalQty += parseInt(output ? output.textContent : '0', 10) || 0;
+          });
+          if (totalQty === 0) {
+            if (statusEl) {
+              statusEl.hidden = false;
+              statusEl.textContent = 'Add at least 1 coffee drink to place your order.';
+            }
+            return;
+          }
+          const totalText = totalEl ? totalEl.textContent : '';
+          const customerName = pickupInput ? pickupInput.value.trim() : 'Guest';
+          if (statusEl) {
+            statusEl.hidden = false;
+            statusEl.textContent = `Order confirmed for ${customerName} (${totalQty} ${totalQty === 1 ? 'drink' : 'drinks'}, ${totalText})! Ready in ~5 mins.`;
+          }
+          reclampPosition();
+        });
+      }
+
+      updateCartTotals();
+    })();
+  </script>
+
 </body>

