+
+  <script>
+    (function () {
+      const panel = document.querySelector('[data-draggable]');
+      const handle = panel ? panel.querySelector('[data-drag-handle]') : null;
+
+      if (panel && handle) {
+        let isDragging = false;
+        let startX = 0;
+        let startY = 0;
+        let initialLeft = 0;
+        let initialTop = 0;
+
+        // Normalize initial coordinates to explicit px values so dragging works seamlessly
+        function ensureExplicitPosition() {
+          const rect = panel.getBoundingClientRect();
+          panel.style.left = rect.left + 'px';
+          panel.style.top = rect.top + 'px';
+          panel.style.right = 'auto';
+          panel.style.bottom = 'auto';
+          panel.style.margin = '0';
+        }
+
+        ensureExplicitPosition();
+
+        function startDrag(clientX, clientY) {
+          const rect = panel.getBoundingClientRect();
+          isDragging = true;
+          startX = clientX;
+          startY = clientY;
+          initialLeft = rect.left;
+          initialTop = rect.top;
+          panel.style.left = initialLeft + 'px';
+          panel.style.top = initialTop + 'px';
+          panel.style.right = 'auto';
+          panel.style.bottom = 'auto';
+          panel.classList.add('is-dragging');
+          panel.setAttribute('data-dragging', 'true');
+        }
+
+        function moveDrag(clientX, clientY) {
+          if (!isDragging) return;
+          const dx = clientX - startX;
+          const dy = clientY - startY;
+          const nextLeft = initialLeft + dx;
+          const nextTop = initialTop + dy;
+          panel.style.left = nextLeft + 'px';
+          panel.style.top = nextTop + 'px';
+        }
+
+        function endDrag() {
+          if (!isDragging) return;
+          isDragging = false;
+          panel.classList.remove('is-dragging');
+          panel.setAttribute('data-dragging', 'false');
+        }
+
+        handle.addEventListener('mousedown', function (e) {
+          if (e.button !== undefined && e.button !== 0) return;
+          startDrag(e.clientX, e.clientY);
+          e.preventDefault();
+        });
+
+        window.addEventListener('mousemove', function (e) {
+          if (!isDragging) return;
+          moveDrag(e.clientX, e.clientY);
+        });
+
+        window.addEventListener('mouseup', function () {
+          endDrag();
+        });
+
+        handle.addEventListener('pointerdown', function (e) {
+          if (e.button !== undefined && e.button !== 0) return;
+          if (!isDragging) {
+            startDrag(e.clientX, e.clientY);
+          }
+        });
+
+        window.addEventListener('pointermove', function (e) {
+          if (!isDragging) return;
+          moveDrag(e.clientX, e.clientY);
+        });
+
+        window.addEventListener('pointerup', function () {
+          endDrag();
+        });
+
+        handle.addEventListener('touchstart', function (e) {
+          if (e.touches && e.touches.length > 0) {
+            startDrag(e.touches[0].clientX, e.touches[0].clientY);
+          }
+        }, { passive: true });
+
+        window.addEventListener('touchmove', function (e) {
+          if (!isDragging || !e.touches || e.touches.length === 0) return;
+          moveDrag(e.touches[0].clientX, e.touches[0].clientY);
+        }, { passive: true });
+
+        window.addEventListener('touchend', function () {
+          endDrag();
+        });
+      }
+
+      // Interactive Cart Logic
+      const state = {
+        items: {
+          'maple-oat-latte': { name: 'Maple Oat Latte', basePrice: 5.25, qty: 1 },
+          'dark-roast-espresso': { name: 'Dark Roast Espresso', basePrice: 3.50, qty: 0 },
+          'cold-brew': { name: 'Cold Brew', basePrice: 4.50, qty: 1 }
+        }
+      };
+
+      const sizeSelect = document.getElementById('cup-size-select');
+      const milkSelect = document.getElementById('milk-choice-select');
+      const rewardsCheckbox = document.getElementById('apply-rewards-checkbox');
+      const countBadge = document.getElementById('cart-count-badge');
+      const subtotalEl = document.getElementById('cart-subtotal');
+      const totalEl = document.getElementById('cart-total');
+      const statusMsgEl = document.getElementById('order-status-msg');
+      const clearBtn = document.getElementById('clear-cart-btn');
+      const checkoutBtn = document.getElementById('place-order-btn');
+
+      function updateCartUI() {
+        const sizeUpcharge = parseFloat(sizeSelect ? sizeSelect.value : '0') || 0;
+        let totalCount = 0;
+        let subtotal = 0;
+
+        Object.keys(state.items).forEach(function (id) {
+          const item = state.items[id];
+          const qtyEl = document.getElementById('qty-' + id);
+          if (qtyEl) {
+            qtyEl.textContent = String(item.qty);
+          }
+          totalCount += item.qty;
+          subtotal += item.qty * (item.basePrice + sizeUpcharge);
+        });
+
+        const discount = (rewardsCheckbox && rewardsCheckbox.checked && subtotal > 0) ? 1.0 : 0;
+        const finalTotal = Math.max(0, subtotal - discount);
+
+        if (countBadge) {
+          countBadge.textContent = totalCount + (totalCount === 1 ? ' item' : ' items');
+        }
+        if (subtotalEl) {
+          subtotalEl.textContent = '$' + subtotal.toFixed(2);
+        }
+        if (totalEl) {
+          totalEl.textContent = '$' + finalTotal.toFixed(2);
+        }
+      }
+
+      document.querySelectorAll('.qty-btn').forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          const id = btn.getAttribute('data-target');
+          const action = btn.getAttribute('data-action');
+          if (!id || !state.items[id]) return;
+
+          if (action === 'increment') {
+            state.items[id].qty += 1;
+          } else if (action === 'decrement') {
+            state.items[id].qty = Math.max(0, state.items[id].qty - 1);
+          }
+          if (statusMsgEl) statusMsgEl.textContent = '';
+          updateCartUI();
+        });
+      });
+
+      if (sizeSelect) {
+        sizeSelect.addEventListener('change', function () {
+          if (statusMsgEl) statusMsgEl.textContent = '';
+          updateCartUI();
+        });
+      }
+
+      if (milkSelect) {
+        milkSelect.addEventListener('change', function () {
+          if (statusMsgEl) statusMsgEl.textContent = '';
+          updateCartUI();
+        });
+      }
+
+      if (rewardsCheckbox) {
+        rewardsCheckbox.addEventListener('change', function () {
+          if (statusMsgEl) statusMsgEl.textContent = '';
+          updateCartUI();
+        });
+      }
+
+      if (clearBtn) {
+        clearBtn.addEventListener('click', function () {
+          Object.keys(state.items).forEach(function (id) {
+            state.items[id].qty = 0;
+          });
+          if (statusMsgEl) statusMsgEl.textContent = 'Cart cleared.';
+          updateCartUI();
+        });
+      }
+
+      if (checkoutBtn) {
+        checkoutBtn.addEventListener('click', function () {
+          const totalItems = Object.keys(state.items).reduce(function (acc, id) {
+            return acc + state.items[id].qty;
+          }, 0);
+          if (totalItems === 0) {
