+            return;
+          }
+          const milk = milkSelect ? milkSelect.value : 'Oat Milk';
+          if (statusMsgEl) {
+            statusMsgEl.textContent = 'Order placed for ' + totalItems + (totalItems === 1 ? ' drink' : ' drinks') + ' (' + milk + ')!';
+          }
+        });
+      }
+
+      updateCartUI();
+    })();
+  </script>
+
