+        const glowGrad = ctx.createRadialGradient(cx, h + 10, 15, cx, cy, w * 0.55);
+        const heatIntensity = 0.22 + ((currentTemp - 370) / 75) * 0.2;
+        glowGrad.addColorStop(0, `rgba(255, 110, 30, ${heatIntensity.toFixed(3)})`);
+        glowGrad.addColorStop(0.5, 'rgba(62, 39, 35, 0.25)');
+        glowGrad.addColorStop(1, 'rgba(18, 9, 6, 0.95)');
+        ctx.fillStyle = glowGrad;
+        ctx.fillRect(0, 0, w, h);
+
+        // Roaster drum rings and rotating paddles
+        ctx.save();
+        ctx.translate(cx, cy);
+        ctx.strokeStyle = 'rgba(215, 204, 200, 0.18)';
+        ctx.lineWidth = 3;
+        ctx.beginPath();
+        ctx.ellipse(0, 0, w * 0.42, h * 0.42, 0, 0, Math.PI * 2);
+        ctx.stroke();
+
+        const drumAngle = frameTick * 0.015;
+        for (let p = 0; p < 6; p++) {
+          const a = drumAngle + (p * Math.PI) / 3;
+          ctx.beginPath();
+          ctx.moveTo(Math.cos(a) * (w * 0.36), Math.sin(a) * (h * 0.36));
+          ctx.lineTo(Math.cos(a) * (w * 0.42), Math.sin(a) * (h * 0.42));
+          ctx.strokeStyle = 'rgba(255, 171, 64, 0.28)';
+          ctx.lineWidth = 2;
+          ctx.stroke();
+        }
+        ctx.restore();
+
+        // Update and draw tumbling coffee beans
+        const maxRx = w * 0.38;
+        const maxRy = h * 0.36;
+
+        for (let i = 0; i < beans.length; i++) {
+          const b = beans[i];
+          b.x += b.vx;
+          b.y += b.vy + Math.sin((frameTick + i * 7) * 0.06) * 0.35;
+          b.rotation += b.rotationSpeed;
+
+          const dx = (b.x - cx) / maxRx;
+          const dy = (b.y - cy) / maxRy;
+          const distSq = dx * dx + dy * dy;
+          if (distSq > 1) {
+            const norm = Math.sqrt(distSq);
+            b.x = cx + (dx / norm) * maxRx * 0.95;
+            b.y = cy + (dy / norm) * maxRy * 0.95;
+            b.vx = -b.vx * 0.9 + (Math.cos(frameTick * 0.05 + i) * 0.4);
+            b.vy = -b.vy * 0.9 + (Math.sin(frameTick * 0.05 + i) * 0.4);
+          }
+
+          ctx.save();
+          ctx.translate(b.x, b.y);
+          ctx.rotate(b.rotation);
+
+          // Bean body
+          ctx.fillStyle = getBeanColor(currentTemp, b.shadeOffset);
+          ctx.beginPath();
+          ctx.ellipse(0, 0, b.rx, b.ry, 0, 0, Math.PI * 2);
+          ctx.fill();
+
+          ctx.strokeStyle = 'rgba(20, 10, 5, 0.65)';
+          ctx.lineWidth = 1.2;
+          ctx.stroke();
+
+          // Bean center crease
+          ctx.beginPath();
+          ctx.moveTo(-b.rx * 0.72, 0);
+          ctx.quadraticCurveTo(0, b.ry * 0.38, b.rx * 0.72, 0);
+          ctx.strokeStyle = 'rgba(25, 12, 6, 0.85)';
+          ctx.lineWidth = 1.4;
+          ctx.stroke();
+
+          ctx.restore();
+        }
+      }
+
+      function updateTemperature() {
+        if (!isRunning) return;
+        currentTemp += tempDirection * 1.5;
+        if (currentTemp >= 445.0) {
+          currentTemp = 445.0;
+          tempDirection = -1;
+        } else if (currentTemp <= 370.0) {
+          currentTemp = 370.0;
+          tempDirection = 1;
+        }
+
+        tempValueEl.textContent = `${currentTemp.toFixed(1)}°F`;
+
+        if (stageValueEl) {
+          if (currentTemp < 395) {
+            stageValueEl.textContent = 'Cinnamon · Light Roast';
+          } else if (currentTemp < 415) {
+            stageValueEl.textContent = 'First Crack · Medium Roast';
+          } else if (currentTemp < 430) {
+            stageValueEl.textContent = 'Full City · Medium-Dark';
+          } else {
+            stageValueEl.textContent = 'Second Crack · Dark Espresso';
+          }
+        }
+      }
+
+      function animateLoop() {
+        if (!isRunning) return;
+        drawRoasterFrame();
+        animationFrameId = window.requestAnimationFrame(animateLoop);
+      }
+
+      function startSimulation() {
+        if (isRunning) return;
+        isRunning = true;
+        widget.dataset.roastingState = 'running';
+        widget.dataset.paused = 'false';
+
+        if (statusBadgeEl) {
+          statusBadgeEl.textContent = 'LIVE ROASTING';
+          statusBadgeEl.classList.remove('paused');
+        }
+
+        if (animationFrameId === null) {
+          animationFrameId = window.requestAnimationFrame(animateLoop);
+        }
+
+        if (tempIntervalId === null) {
+          tempIntervalId = window.setInterval(updateTemperature, 200);
+        }
+      }
+
+      function pauseSimulation() {
+        isRunning = false;
+        widget.dataset.roastingState = 'paused';
+        widget.dataset.paused = 'true';
+
+        if (statusBadgeEl) {
+          statusBadgeEl.textContent = 'PAUSED (OFFSCREEN)';
+          statusBadgeEl.classList.add('paused');
+        }
+
+        if (animationFrameId !== null) {
+          window.cancelAnimationFrame(animationFrameId);
+          animationFrameId = null;
+        }
+
+        if (tempIntervalId !== null) {
+          window.clearInterval(tempIntervalId);
+          tempIntervalId = null;
+        }
+      }
+
+      // Render initial frame and start simulation
+      drawRoasterFrame();
+      startSimulation();
+
+      const supportsContentVisibilityStateChange =
+        'oncontentvisibilityautostatechange' in window ||
+        'oncontentvisibilityautostatechange' in HTMLElement.prototype ||
+        'ContentVisibilityAutoStateChangeEvent' in window;
+
+      let hasScrolled = false;
+      window.addEventListener(
+        'scroll',
+        () => {
+          hasScrolled = true;
+        },
+        { passive: true }
+      );
+
+      if (supportsContentVisibilityStateChange) {
+        widget.addEventListener('contentvisibilityautostatechange', (event) => {
+          const isSkipped = Boolean(
+            event.skipped !== undefined
+              ? event.skipped
+              : event.detail && event.detail.skipped
+          );
+          if (isSkipped) {
+            pauseSimulation();
+          } else {
+            startSimulation();
+          }
+        });
+      }
+
+      // Fallback for older browsers lacking contentvisibilityautostatechange,
+      // and viewport intersection sync when scrolling within pre-render margins.
+      if ('IntersectionObserver' in window) {
+        const observer = new IntersectionObserver(
+          (entries) => {
+            entries.forEach((entry) => {
+              if (entry.target !== widget) return;
+              if (entry.isIntersecting) {
+                startSimulation();
+              } else if (!supportsContentVisibilityStateChange || hasScrolled) {
+                pauseSimulation();
+              }
+            });
+          },
+          { threshold: 0.05 }
+        );
+        observer.observe(widget);
+      } else if (!supportsContentVisibilityStateChange) {
+        const handleScrollFallback = () => {
+          const rect = widget.getBoundingClientRect();
+          const viewHeight = window.innerHeight || document.documentElement.clientHeight;
+          if (rect.bottom > 0 && rect.top < viewHeight) {
+            startSimulation();
+          } else {
+            pauseSimulation();
+          }
+        };
+        window.addEventListener('scroll', handleScrollFallback, { passive: true });
+        window.addEventListener('resize', handleScrollFallback, { passive: true });
+      }
+    })();
+  </script>
+
 </body>

 </html>

