+      function getOrCreateView(viewKey) {
+        if (viewCache.has(viewKey)) {
+          return viewCache.get(viewKey);
+        }
+        const builder = viewBuilders[viewKey];
+        if (!builder) {
+          return viewCache.get('home');
+        }
+        const viewElement = builder();
+        viewElement.hidden = true;
+        appViewsHost.appendChild(viewElement);
+        viewCache.set(viewKey, viewElement);
+        return viewElement;
+      }
+
+      function updateActiveNavLinks(viewKey) {
+        document.querySelectorAll('nav a[data-spa-link]').forEach(link => {
+          const isMatch = link.dataset.spaLink === viewKey && viewKey !== 'home';
+          link.classList.toggle('active', isMatch);
+          if (isMatch) {
+            link.setAttribute('aria-current', 'page');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function navigateToView(viewKey, options = {}) {
+        const { pushHistory = true, replaceHistory = false } = options;
+        const targetKey = VIEW_TITLES[viewKey] ? viewKey : 'home';
+
+        // Save current view's scroll position before hiding it
+        scrollPositions.set(currentViewKey, window.scrollY || 0);
+
+        // Ensure target view exists in the DOM cache
+        const targetViewEl = getOrCreateView(targetKey);
+
+        // Toggle visibility across cached views without removing or rebuilding DOM nodes
+        viewCache.forEach((el, key) => {
+          const isActive = key === targetKey;
+          el.hidden = !isActive;
+          el.setAttribute('aria-hidden', isActive ? 'false' : 'true');
+        });
+
+        currentViewKey = targetKey;
+        document.title = VIEW_TITLES[targetKey];
+        updateActiveNavLinks(targetKey);
+
+        const targetPath = VIEW_PATHS[targetKey] || '/';
+        if (window.location.protocol !== 'file:') {
+          try {
+            if (replaceHistory) {
+              window.history.replaceState({ view: targetKey }, '', targetPath);
+            } else if (pushHistory && window.location.pathname !== targetPath) {
+              window.history.pushState({ view: targetKey }, '', targetPath);
+            }
+          } catch (_) {
+            // Fallback silently if history pushState is restricted
+          }
+        }
+
+        // Restore preserved scroll position if returning to a previously visited view
+        const savedScroll = scrollPositions.get(targetKey) ?? 0;
+        window.scrollTo(0, savedScroll);
+      }
+
+      function resolveViewFromLocation() {
+        const hash = window.location.hash.replace(/^#\/?/, '').toLowerCase();
+        if (hash && VIEW_TITLES[hash]) {
+          return hash;
+        }
+        const path = window.location.pathname.replace(/\/+$/, '') || '/';
+        return ROUTE_MAP[path] || 'home';
+      }
+
+      // Intercept clicks on SPA navigation links
+      document.addEventListener('click', (event) => {
+        const link = event.target.closest('a');
+        if (!link) return;
+
+        // Ignore modified clicks (new tab / window)
+        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) {
+          return;
+        }
+
+        const explicitView = link.dataset.spaLink;
+        const href = link.getAttribute('href') || '';
+        const mappedView = explicitView || ROUTE_MAP[href];
+
+        if (mappedView) {
+          event.preventDefault();
+          navigateToView(mappedView, { pushHistory: true });
+        }
+      });
+
+      // Handle browser Back/Forward buttons
+      window.addEventListener('popstate', (event) => {
+        const targetView = (event.state && event.state.view) || resolveViewFromLocation();
+        navigateToView(targetView, { pushHistory: false });
+      });
