+      // Expose SPA router helper for programmatic inspection if needed
+      window.DailyGrindSPA = {
+        navigateToView,
+        getCachedViews: () => Array.from(viewCache.keys()),
+        getCurrentView: () => currentViewKey
+      };
+
+      // Initialize initial route
+      const initialView = resolveViewFromLocation();
+      navigateToView(initialView, { pushHistory: false, replaceHistory: true });
+    })();
+  </script>
