+    <script>
+        const VALID_VIEWS = new Set(['top-news', 'world', 'politics', 'multimedia', 'reports']);
+
+        function applyViewDOM(viewId: string) {
+            const views = document.querySelectorAll<HTMLElement>('.spa-view');
+            views.forEach(view => {
+                view.classList.add('inactive');
+                view.setAttribute('aria-hidden', 'true');
+                view.setAttribute('inert', 'inert');
+            });
+
+            const activeView = document.getElementById(`view-${viewId}`);
+            if (activeView) {
+                activeView.classList.remove('inactive');
+                activeView.setAttribute('aria-hidden', 'false');
+                activeView.removeAttribute('inert');
+            }
+            return activeView;
+        }
+
+        function switchToView(viewId: string, options: { pushState?: boolean; moveFocus?: boolean } = {}) {
+            const { pushState = false, moveFocus = true } = options;
+            if (!VALID_VIEWS.has(viewId)) return;
+
+            const targetEl = document.getElementById(`view-${viewId}`);
+            if (!targetEl) return;
+
+            if (pushState) {
+                const url = new URL(window.location.href);
+                url.searchParams.set('view', viewId);
+                window.history.pushState({ viewId }, '', url.toString());
+            }
+
+            const focusTarget = () => {
+                if (moveFocus) {
+                    targetEl.focus({ preventScroll: true });
+                }
+                window.dispatchEvent(new CustomEvent('spa-view-changed', { detail: { viewId } }));
+            };
+
+            if (!document.startViewTransition) {
+                applyViewDOM(viewId);
+                focusTarget();
+                return;
+            }
+
+            const transition = document.startViewTransition(() => {
+                applyViewDOM(viewId);
+            });
+
+            transition.finished.finally(() => {
+                focusTarget();
+            });
+        }
+
+        function initSpaViews() {
+            const params = new URLSearchParams(window.location.search);
+            const hashView = window.location.hash.replace(/^#/, '');
+            const initial = params.get('view') || hashView;
+            if (initial && VALID_VIEWS.has(initial)) {
+                applyViewDOM(initial);
+                window.dispatchEvent(new CustomEvent('spa-view-changed', { detail: { viewId: initial } }));
+            }
+        }
+
+        window.addEventListener('spa-navigate', (e: Event) => {
+            const detail = (e as CustomEvent<{ viewId: string; pushState?: boolean }>).detail;
+            if (detail?.viewId) {
+                switchToView(detail.viewId, { pushState: detail.pushState ?? true, moveFocus: true });
+            }
+        });
+
+        window.addEventListener('popstate', () => {
+            const params = new URLSearchParams(window.location.search);
+            const hashView = window.location.hash.replace(/^#/, '');
+            const viewId = params.get('view') || hashView || 'top-news';
+            if (VALID_VIEWS.has(viewId)) {
+                switchToView(viewId, { pushState: false, moveFocus: true });
+            }
+        });
+
+        document.addEventListener('astro:page-load', initSpaViews);
+        initSpaViews();
