+              mark.textContent = parts[i];
+              el.appendChild(mark);
+            } else if (parts[i]) {
+              el.appendChild(document.createTextNode(parts[i]));
+            }
+          }
+        });
+      }
+
+      searchInput.addEventListener('input', updateHighlights);
+      searchInput.addEventListener('keyup', updateHighlights);
+    })();
