+/* Hides content visually but keeps it in the accessibility tree.
+   :focus-within / :active opt elements out — useful for skip links and
+   any focusable content wrapped in this class. */
+.visually-hidden:where(:not(:focus-within, :active)) {
+  position: absolute !important;
+  clip-path: inset(50%) !important;
+  overflow: hidden !important;
+  width: 1px !important;
+  height: 1px !important;
+  margin: -1px !important;
+  padding: 0 !important;
+  border: 0 !important;
+  white-space: nowrap !important;
+}
+
+.skip-link:is(:focus-within, :active) {
+  position: fixed;
+  top: 0.75rem;
+  left: 0.75rem;
+  z-index: 100000;
+  background-color: #111827;
+  color: #ffffff;
+  padding: 0.5rem 1rem;
+  border-radius: 0.25rem;
+  font-weight: 600;
+  text-decoration: none;
+}
+
+/* High contrast focus ring for interactive controls */
+:where(a:any-link, button, input, select, textarea):focus-visible {
+  outline: 3px solid #f59e0b;
+  outline-offset: 2px;
+}
+
+/* Native dialog modal scroll containment and backdrop styling */
+dialog:modal {
+  overscroll-behavior: contain;
+}
+
+dialog::backdrop {
+  overflow: hidden;
+  overscroll-behavior: contain;
+  background-color: rgba(255, 255, 255, 0.3);
+  backdrop-filter: blur(4px);
+}
+
+/* Popover styling compatibility with @oddbird/popover-polyfill */
+[popover]:is(:popover-open, .\:popover-open) {
+  display: block;
+}
+
+/* Anchor positioning for category flyout popovers */
+@supports (position-area: block-end) {
+  [popover].category-popover {
+    position-area: block-end;
+    position-try-fallbacks: flip-block;
+    inset: auto;
+    margin: 0;
+  }
+}
+
+@supports not (position-area: block-end) {
+  [popover].category-popover {
+    position: absolute;
+    inset: auto 0 auto 0;
+    margin: 0;
+  }
+}
+
+/* Inert state visual cue */
+[inert], [inert] * {
+  opacity: 0.5;
+  cursor: default;
+  user-select: none;
