+          nextBtn.textContent = nextStatus === 'brewing' ? 'Start Brewing →' : 'Mark Ready →';
+          nextBtn.addEventListener('click', (e) => {
+            e.stopPropagation();
+            moveOrder(order.id, order.status, nextStatus);
+          });
+          actions.appendChild(nextBtn);
+        } else {
+          const completeBtn = document.createElement('button');
+          completeBtn.type = 'button';
+          completeBtn.className = 'move-btn';
+          completeBtn.textContent = '✓ Picked Up';
+          completeBtn.addEventListener('click', (e) => {
+            e.stopPropagation();
+            removeOrder(order.id, order.status);
+          });
+          actions.appendChild(completeBtn);
+        }
+
+        card.appendChild(actions);
+
+        card.addEventListener('dragstart', (e) => {
+          draggedOrderId = order.id;
+          draggedSourceStatus = order.status;
+          card.classList.add('dragging');
+          if (e.dataTransfer) {
+            e.dataTransfer.effectAllowed = 'move';
+            e.dataTransfer.setData('text/plain', order.id);
+          }
+        });
+
+        card.addEventListener('dragend', () => {
+          card.classList.remove('dragging');
+          draggedOrderId = null;
+          draggedSourceStatus = null;
+          document.querySelectorAll('.board-column.drag-over').forEach(col => {
+            col.classList.remove('drag-over');
+          });
+        });
+
+        return card;
+      }
