+        columnEl.addEventListener('dragleave', (e) => {
+          if (!columnEl.contains(e.relatedTarget)) {
+            columnEl.classList.remove('drag-over');
+          }
+        });
+
+        columnEl.addEventListener('drop', (e) => {
+          e.preventDefault();
+          columnEl.classList.remove('drag-over');
+          const transferredId = (e.dataTransfer && e.dataTransfer.getData('text/plain')) || draggedOrderId;
+          if (!transferredId) return;
+          moveOrder(transferredId, draggedSourceStatus, targetStatus);
+        });
+      });
+
+      // Handle new order creation (only re-renders the 'queued' column)
+      const newOrderForm = document.getElementById('new-order-form');
+      if (newOrderForm) {
+        newOrderForm.addEventListener('submit', (e) => {
+          e.preventDefault();
+          const customerInput = document.getElementById('order-customer');
+          const drinkSelect = document.getElementById('order-drink');
+          const notesInput = document.getElementById('order-notes');
+
+          const customer = customerInput.value.trim();
+          if (!customer) return;
+
+          const newOrder = {
+            id: `ORD-${nextOrderNumber++}`,
+            customer,
+            drink: drinkSelect.value,
+            size: 'Medium',
+            notes: notesInput.value.trim() || 'Standard preparation',
+            time: 'Just now',
+            status: 'queued'
+          };
+
+          columnsState.queued.push(newOrder);
+          renderColumn('queued');
+
+          customerInput.value = '';
+          notesInput.value = '';
+        });
+      }
+
+      // Initial render for each column in isolation
+      STATUS_ORDER.forEach(status => renderColumn(status));
+    })();
+  </script>
