+      gl.bindTexture(gl.TEXTURE_2D, texture);
+      const textureState = { width: 0, height: 0 };
+      let hasUploadedTexture = false;
+
+      // Matrix math helpers (column-major Float32Array)
+      function createPerspective(fovRad, aspect, near, far) {
+        const f = 1.0 / Math.tan(fovRad / 2);
+        const nf = 1 / (near - far);
+        return new Float32Array([
+          f / aspect, 0, 0, 0,
+          0, f, 0, 0,
+          0, 0, (far + near) * nf, -1,
+          0, 0, 2 * far * near * nf, 0
+        ]);
+      }
