+        return new Float32Array([
+          domMat.m11, domMat.m12, domMat.m13, domMat.m14,
+          domMat.m21, domMat.m22, domMat.m23, domMat.m24,
+          domMat.m31, domMat.m32, domMat.m33, domMat.m34,
+          domMat.m41, domMat.m42, domMat.m43, domMat.m44
+        ]);
+      }
