+      // Coffee box dimensions in 3D space (front/back width & height match form aspect ratio)
+      const boxW = 1.55;
+      const boxH = 1.95;
+      const boxD = 0.72;
+
+      const boxFaces = [
+        // Front face (interactive HTML form face at +Z)
+        {
+          isHtmlFace: true,
+          color: [0.98, 0.96, 0.93],
+          localMatrix: new DOMMatrix().translate(0, 0, boxD / 2).scale(boxW, boxH, 1)
+        },
+        // Back face (-Z)
+        {
+          isHtmlFace: false,
+          color: [0.31, 0.20, 0.18],
+          localMatrix: new DOMMatrix().translate(0, 0, -boxD / 2).rotate(0, 180, 0).scale(boxW, boxH, 1)
+        },
+        // Right side face (+X)
+        {
+          isHtmlFace: false,
+          color: [0.38, 0.25, 0.22],
+          localMatrix: new DOMMatrix().translate(boxW / 2, 0, 0).rotate(0, 90, 0).scale(boxD, boxH, 1)
