+      ];
+
+      let isRotating = true;
+      let elapsedTime = 0;
+      let lastFrameTime = performance.now();
+
+      toggleRotationBtn.addEventListener("click", () => {
+        isRotating = !isRotating;
+        toggleRotationBtn.setAttribute("aria-pressed", String(isRotating));
+        toggleRotationBtn.textContent = isRotating ? "Pause Box Rotation" : "Resume Box Rotation";
+      });
+
+      resetAngleBtn.addEventListener("click", () => {
+        elapsedTime = 0;
+        if (supportsHtmlInCanvas && typeof canvas.requestPaint === "function") {
+          canvas.requestPaint();
+        }
+      });
+
+      function renderSceneAndGetFrontMVP() {
+        gl.viewport(0, 0, canvas.width, canvas.height);
+        gl.clearColor(0.92, 0.89, 0.87, 1.0);
+        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+        gl.enable(gl.DEPTH_TEST);
+
+        gl.useProgram(program);
+        gl.bindVertexArray(vao);
+
+        const aspect = canvas.width > 0 && canvas.height > 0 ? canvas.width / canvas.height : 1;
+        const projArray = createPerspective((42 * Math.PI) / 180, aspect, 0.1, 20.0);
+        const projDOM = new DOMMatrix(Array.from(projArray));
+
+        // Gentle oscillating 3D rotation so the front HTML form face stays visible and clickable as the box rotates
+        const yawDeg = Math.sin(elapsedTime * 0.85) * 26;
+        const pitchDeg = Math.cos(elapsedTime * 0.6) * 9 - 4;
+
+        const viewModelBox = new DOMMatrix()
+          .translate(0, 0, -3.5)
+          .rotate(pitchDeg, yawDeg, 0);
+
+        let frontFaceMVP = null;
+
+        for (const face of boxFaces) {
+          const modelDOM = viewModelBox.multiply(face.localMatrix);
+          const mvpDOM = projDOM.multiply(modelDOM);
+          const mvpArray = toFloat32Mat4(mvpDOM);
+          const modelArray = toFloat32Mat4(modelDOM);
+
+          gl.uniformMatrix4fv(uMVPLoc, false, mvpArray);
+          gl.uniformMatrix4fv(uModelLoc, false, modelArray);
+          gl.uniform3fv(uBaseColorLoc, face.color);
