+        if (supportsHtmlInCanvas && typeof canvas.requestPaint === "function") {
+          canvas.requestPaint();
+        } else {
+          renderSceneAndGetFrontMVP();
+        }
+        requestAnimationFrame(render);
+      }
+      requestAnimationFrame(render);
+    })();
+  </script>
 </body>

 </html>

