+      function renderBoxTransform() {
+        if (isFallbackMode) return;
+        const roundedYaw = Math.round(yaw * 100) / 100;
+        const roundedPitch = Math.round(pitch * 100) / 100;
+        box3d.style.transform = `rotateX(${roundedPitch}deg) rotateY(${roundedYaw}deg)`;
+        if (shadow) {
+          const shadowScale = 1 + Math.abs(Math.sin((roundedYaw * Math.PI) / 180)) * 0.12;
+          shadow.style.transform = `scaleX(${shadowScale.toFixed(3)})`;
