+      // Animation loop keeping the box smoothly rotating while form remains interactive
+      let lastFrameTime = performance.now();
+      function animateLoop(now) {
+        const dt = Math.min((now - lastFrameTime) / 1000, 0.1);
+        lastFrameTime = now;
+
+        if (!isFallbackMode && !isDragging) {
