+            if (Math.abs(dy) < 0.25 && Math.abs(dp) < 0.25) {
+              yaw = normalizeAngle(targetYaw);
+              pitch = targetPitch;
+              targetYaw = null;
+              targetPitch = null;
+            } else {
+              yaw += dy * Math.min(1, dt * 8);
+              pitch += dp * Math.min(1, dt * 8);
+            }
+            renderBoxTransform();
+          } else if (isAutoRotating && !isFormFocused) {
+            // Smooth continuous showcase oscillation that keeps the front form accessible
+            // or full gentle rotation
+            yaw = normalizeAngle(yaw + spinDirection * dt * 14);
+            if (yaw > 32) {
+              yaw = 32;
+              spinDirection = -1;
