+        card.addEventListener('pointermove', updateSpotlight);
+        card.addEventListener('mouseenter', updateSpotlight);
+        card.addEventListener('mousemove', updateSpotlight);
+        card.addEventListener('pointerleave', hideSpotlight);
+        card.addEventListener('mouseleave', hideSpotlight);
