+          card.style.setProperty('--inner-size', INNER_HOVER_SIZE);
+          card.style.setProperty('--outer-size', OUTER_HOVER_SIZE);
+        });
+
+        card.addEventListener('focusout', (event) => {
+          if (!card.contains(event.relatedTarget) && !card.matches(':hover')) {
+            hideSpotlight();
+          }
+        });
+      });
