+      const initialParams = new URLSearchParams(window.location.search);
+      const customSortParamValue = initialParams.get('sort');
+
+      // Ensure sort option values accommodate exact URL param value if an alias was supplied
+      if (customSortParamValue) {
+        const canonical = normalizeSortMode(customSortParamValue);
+        const matchingOption = Array.from(sortSelectEl.options).find(function (opt) {
+          return opt.value === canonical;
+        });
+        if (matchingOption && matchingOption.value !== customSortParamValue) {
+          matchingOption.value = customSortParamValue;
+        }
+      }
+
+      // Active filter state
+      const filterState = {
+        category: 'all',
+        sort: sortSelectEl.options[0].value,
+        reverse: false,
+        groupByCategory: false
+      };
+
+      function readStateFromUrl() {
+        const params = new URLSearchParams(window.location.search);
+
+        const rawCategory = params.get('category') || params.get('filter');
+        const validCategories = ['all', 'seasonal', 'espresso', 'cold-brew'];
+        filterState.category = validCategories.includes(rawCategory) ? rawCategory : 'all';
+
+        const rawSort = params.get('sort');
+        const canonicalSort = normalizeSortMode(rawSort);
+        const matchedOption = Array.from(sortSelectEl.options).find(function (opt) {
+          return normalizeSortMode(opt.value) === canonicalSort;
+        });
+        filterState.sort = matchedOption ? matchedOption.value : sortSelectEl.options[0].value;
+
+        const rawReverse = params.has('reverse')
+          ? params.get('reverse')
+          : params.has('reversed')
+            ? params.get('reversed')
+            : params.get('reverseOrder');
+        filterState.reverse = parseBoolParam(rawReverse);
+
+        const rawGroup = params.has('group')
+          ? params.get('group')
+          : params.has('grouped')
+            ? params.get('grouped')
+            : params.has('groupByCategory')
+              ? params.get('groupByCategory')
+              : params.get('group-by-category');
+        filterState.groupByCategory = parseBoolParam(rawGroup);
+      }
+
+      function syncControlsWithState() {
+        categorySelectEl.value = filterState.category;
+        sortSelectEl.value = filterState.sort;
+        reverseToggleEl.checked = filterState.reverse;
+        reverseToggleEl.setAttribute('aria-checked', String(filterState.reverse));
+        groupToggleEl.checked = filterState.groupByCategory;
+        groupToggleEl.setAttribute('aria-checked', String(filterState.groupByCategory));
+      }
+
+      function syncUrlWithState() {
+        const params = new URLSearchParams(window.location.search);
+        params.set('category', filterState.category);
+        params.set('sort', filterState.sort);
+        params.set('reverse', String(filterState.reverse));
+        params.set('group', String(filterState.groupByCategory));
+
+        if (params.has('reversed')) params.set('reversed', String(filterState.reverse));
+        if (params.has('reverseOrder')) params.set('reverseOrder', String(filterState.reverse));
+        if (params.has('grouped')) params.set('grouped', String(filterState.groupByCategory));
+        if (params.has('groupByCategory')) params.set('groupByCategory', String(filterState.groupByCategory));
+
+        const newSearch = params.toString();
+        const newUrl = window.location.pathname + (newSearch ? '?' + newSearch : '') + window.location.hash;
+        window.history.replaceState(null, '', newUrl);
+      }
+
+      // Compute derived menu items without mutating MENU_DATA
+      function getProcessedMenuItems() {
+        const filtered = MENU_DATA.filter(function (item) {
+          return filterState.category === 'all' || item.category === filterState.category;
+        });
+
+        const sortMode = normalizeSortMode(filterState.sort);
+        const sorted = filtered.slice().sort(function (a, b) {
+          if (sortMode === 'price-asc') {
+            return a.price - b.price || a.featuredIndex - b.featuredIndex;
+          }
+          if (sortMode === 'price-desc') {
+            return b.price - a.price || a.featuredIndex - b.featuredIndex;
+          }
+          return a.featuredIndex - b.featuredIndex;
+        });
+
+        const finalItems = filterState.reverse ? sorted.slice().reverse() : sorted;
+        return finalItems;
+      }
+
+      // Maintain flat grid & grouped section elements for clean in-place updates
+      const flatGridEl = document.createElement('div');
+      flatGridEl.className = 'grid menu-grid';
+      flatGridEl.id = 'menu-grid';
+
+      const groupedContainerEl = document.createElement('div');
+      groupedContainerEl.className = 'grouped-menu-container';
+      groupedContainerEl.id = 'grouped-menu';
+
+      const categoryGroupMap = new Map();
+      CATEGORIES.forEach(function (cat) {
+        const section = document.createElement('section');
+        section.className = 'category-group';
+        section.dataset.category = cat.key;
+
+        const header = document.createElement('div');
+        header.className = 'category-group-header';
+
+        const heading = document.createElement('h3');
+        heading.className = 'category-group-title';
+        heading.textContent = cat.label;
+
+        const countBadge = document.createElement('span');
+        countBadge.className = 'category-count';
+        countBadge.dataset.categoryCount = cat.key;
+
+        header.append(heading, countBadge);
+
+        const groupGrid = document.createElement('div');
+        groupGrid.className = 'grid category-grid';
+
+        const emptyMsg = document.createElement('p');
+        emptyMsg.className = 'empty-category-message';
+        emptyMsg.textContent = 'No matching drinks in ' + cat.label + ' (0 items).';
+
+        section.append(header, groupGrid, emptyMsg);
+        categoryGroupMap.set(cat.key, {
+          section: section,
+          heading: heading,
+          countBadge: countBadge,
+          groupGrid: groupGrid,
+          emptyMsg: emptyMsg,
+          label: cat.label
+        });
+      });
+
+      function renderMenu() {
+        const items = getProcessedMenuItems();
+
+        if (!filterState.groupByCategory) {
+          const cards = items.map(getOrCreateCardElement);
+          flatGridEl.replaceChildren.apply(flatGridEl, cards);
+          if (menuContainerEl.firstElementChild !== flatGridEl || menuContainerEl.childElementCount !== 1) {
+            menuContainerEl.replaceChildren(flatGridEl);
+          }
+        } else {
+          const orderedCategories = filterState.reverse ? CATEGORIES.slice().reverse() : CATEGORIES.slice();
+          const sections = orderedCategories.map(function (cat) {
+            const groupEntry = categoryGroupMap.get(cat.key);
+            const catItems = items.filter(function (item) {
+              return item.category === cat.key;
+            });
+            const count = catItems.length;
+            const itemWord = count === 1 ? 'item' : 'items';
+
+            groupEntry.section.dataset.count = String(count);
+            groupEntry.heading.textContent = groupEntry.label + ' (' + count + ')';
+            groupEntry.countBadge.textContent = count + ' ' + itemWord;
+
+            const cards = catItems.map(getOrCreateCardElement);
+            groupEntry.groupGrid.replaceChildren.apply(groupEntry.groupGrid, cards);
+
+            if (count === 0) {
+              groupEntry.groupGrid.hidden = true;
+              groupEntry.emptyMsg.hidden = false;
+            } else {
+              groupEntry.groupGrid.hidden = false;
+              groupEntry.emptyMsg.hidden = true;
+            }
+
+            return groupEntry.section;
+          });
+
+          groupedContainerEl.replaceChildren.apply(groupedContainerEl, sections);
+          if (menuContainerEl.firstElementChild !== groupedContainerEl || menuContainerEl.childElementCount !== 1) {
+            menuContainerEl.replaceChildren(groupedContainerEl);
+          }
+        }
+
+        return items;
+      }
+
+      function dispatchFilterChangeEvent(matchedItems) {
+        const detail = {
+          category: filterState.category,
+          filter: filterState.category,
+          sort: filterState.sort,
+          sortBy: filterState.sort,
+          reverse: filterState.reverse,
+          reversed: filterState.reverse,
+          reverseOrder: filterState.reverse,
+          group: filterState.groupByCategory,
+          grouped: filterState.groupByCategory,
+          groupByCategory: filterState.groupByCategory,
+          count: matchedItems.length,
+          items: matchedItems.map(function (item) { return Object.assign({}, item); })
+        };
+
+        const event = new CustomEvent('daily-grind:filter-change', {
+          bubbles: true,
+          composed: true,
+          detail: detail
+        });
+        menuControlsEl.dispatchEvent(event);
+      }
+
+      function handleControlChange() {
+        filterState.category = categorySelectEl.value;
+        filterState.sort = sortSelectEl.value;
+        filterState.reverse = Boolean(reverseToggleEl.checked);
+        filterState.groupByCategory = Boolean(groupToggleEl.checked);
+
+        reverseToggleEl.setAttribute('aria-checked', String(filterState.reverse));
+        groupToggleEl.setAttribute('aria-checked', String(filterState.groupByCategory));
+
+        syncUrlWithState();
+        const matchedItems = renderMenu();
+        dispatchFilterChangeEvent(matchedItems);
+      }
+
+      categorySelectEl.addEventListener('change', handleControlChange);
+      sortSelectEl.addEventListener('change', handleControlChange);
+      reverseToggleEl.addEventListener('change', handleControlChange);
+      groupToggleEl.addEventListener('change', handleControlChange);
+
+      window.addEventListener('popstate', function () {
+        readStateFromUrl();
+        syncControlsWithState();
+        const matchedItems = renderMenu();
+        dispatchFilterChangeEvent(matchedItems);
+      });
+
+      // Draft Order State & Deep-Copied Snapshot Management
+      let activeOrder = [];
+      let savedSnapshot = null;
+      let orderSequence = 1;
+
+      function createOrderItem(drink) {
+        const selectedMilk = customizationSelectEl.value || 'Whole';
+        const customerNote = (customerNoteInputEl.value || '').trim();
+        const timestamp = new Date().toISOString();
+
+        return {
+          orderItemId: 'order-item-' + (orderSequence++),
+          drinkId: drink.id,
+          name: drink.name,
+          category: drink.category,
+          price: drink.price,
+          timestamp: timestamp,
+          options: {
+            milk: selectedMilk,
+            customization: selectedMilk,
+            note: customerNote
+          }
+        };
+      }
+
+      function addDrinkToOrder(drink) {
+        const newOrderItem = createOrderItem(drink);
+        activeOrder.push(newOrderItem);
+        renderDraftOrder();
+      }
+
+      function renderDraftOrder() {
+        const count = activeOrder.length;
+        const total = activeOrder.reduce(function (sum, item) {
+          return sum + Number(item.price || 0);
+        }, 0);
+
+        draftOrderCountEl.textContent = count + (count === 1 ? ' item' : ' items');
+        draftOrderTotalEl.textContent = formatPrice(total);
+        draftOrderEmptyEl.hidden = count > 0;
+
+        const itemNodes = activeOrder.map(function (entry, index) {
+          const li = document.createElement('li');
+          li.className = 'order-item';
+          li.dataset.orderItemId = entry.orderItemId;
+          li.dataset.drinkId = entry.drinkId;
+          li.dataset.milk = entry.options.milk;
+          li.dataset.note = entry.options.note;
+          li.dataset.timestamp = entry.timestamp;
+
+          const topRow = document.createElement('div');
+          topRow.className = 'order-item-top';
+
+          const nameSpan = document.createElement('span');
+          nameSpan.className = 'order-item-name';
+          nameSpan.textContent = entry.name;
+
+          const priceSpan = document.createElement('span');
+          priceSpan.className = 'order-item-price';
+          priceSpan.textContent = formatPrice(entry.price);
+
+          topRow.append(nameSpan, priceSpan);
+
+          const metaRow = document.createElement('div');
+          metaRow.className = 'order-item-meta';
+          metaRow.textContent = 'Milk: ' + entry.options.milk;
+
+          const noteRow = document.createElement('div');
+          noteRow.className = 'order-item-note';
+          noteRow.textContent = entry.options.note ? 'Note: ' + entry.options.note : 'Note: None';
+
+          const footerRow = document.createElement('div');
+          footerRow.className = 'order-item-footer';
+
+          const timeEl = document.createElement('time');
+          timeEl.className = 'order-item-timestamp';
+          timeEl.dateTime = entry.timestamp;
+          timeEl.textContent = entry.timestamp;
+
+          const actionsDiv = document.createElement('div');
+          actionsDiv.className = 'order-item-actions';
+
+          const switchMilkBtn = document.createElement('button');
+          switchMilkBtn.type = 'button';
+          switchMilkBtn.className = 'btn-xs edit-item-milk-btn';
+          switchMilkBtn.textContent = 'Toggle Milk';
+          switchMilkBtn.addEventListener('click', function () {
+            // Mutate nested options on activeOrder item in-place to verify snapshot isolation
+            entry.options.milk = entry.options.milk === 'Whole' ? 'Oat' : 'Whole';
+            entry.options.customization = entry.options.milk;
+            renderDraftOrder();
+          });
+
+          const removeBtn = document.createElement('button');
+          removeBtn.type = 'button';
+          removeBtn.className = 'btn-xs remove-item-btn';
+          removeBtn.textContent = 'Remove';
+          removeBtn.addEventListener('click', function () {
+            activeOrder.splice(index, 1);
+            renderDraftOrder();
+          });
+
+          actionsDiv.append(switchMilkBtn, removeBtn);
+          footerRow.append(timeEl, actionsDiv);
+
+          li.append(topRow, metaRow, noteRow, footerRow);
+          return li;
+        });
+
+        draftOrderListEl.replaceChildren.apply(draftOrderListEl, itemNodes);
+      }
+
+      function saveOrderSnapshot() {
+        savedSnapshot = deepClone(activeOrder);
+        const snapCount = savedSnapshot.length;
+        snapshotStatusEl.textContent = 'Snapshot saved (' + snapCount + (snapCount === 1 ? ' item' : ' items') + ').';
+      }
+
+      function restoreOrderSnapshot() {
+        if (savedSnapshot === null) {
+          snapshotStatusEl.textContent = 'No snapshot available to restore.';
+          return;
+        }
+        activeOrder = deepClone(savedSnapshot);
+        const restoredCount = activeOrder.length;
+        snapshotStatusEl.textContent = 'Snapshot restored (' + restoredCount + (restoredCount === 1 ? ' item' : ' items') + ').';
+        renderDraftOrder();
+      }
+
+      function clearDraftOrder() {
+        activeOrder = [];
+        renderDraftOrder();
+      }
+
+      saveSnapshotBtnEl.addEventListener('click', saveOrderSnapshot);
+      restoreSnapshotBtnEl.addEventListener('click', restoreOrderSnapshot);
+      clearOrderBtnEl.addEventListener('click', clearDraftOrder);
+
+      // Expose structured helper references for programmatic inspection
+      window.dailyGrindMenu = MENU_DATA;
+      window.dailyGrindApp = {
+        menuData: MENU_DATA,
+        getFilterState: function () { return Object.assign({}, filterState); },
+        getActiveOrder: function () { return activeOrder; },
+        getSavedSnapshot: function () { return savedSnapshot; },
+        saveSnapshot: saveOrderSnapshot,
+        restoreSnapshot: restoreOrderSnapshot,
+        clearOrder: clearDraftOrder
+      };
+
+      // Initialize from URL query string on initial load
+      readStateFromUrl();
+      syncControlsWithState();
+      syncUrlWithState();
+      const initialMatched = renderMenu();
+      renderDraftOrder();
+      dispatchFilterChangeEvent(initialMatched);
+    })();
+  </script>
 </body>

