+                  showResult(`Downloading language detection model (${pct}%)...`);
+                });
+              },
+            });
+          }
+
+          const results = await detectorInstance.detect(text);
+          if (results && results.length > 0) {
+            const top = results[0];
+            const confidencePct = (top.confidence * 100).toFixed(1);
+            const langLabel = formatLanguageName(top.detectedLanguage);
+            showResult(`Detected Language: ${langLabel} — ${confidencePct}% confidence`);
+          } else {
+            showResult('Could not determine the language of the message.');
+          }
+        } catch (err) {
+          showResult('Unable to detect language at this time.');
+        } finally {
+          detectBtn.disabled = false;
+        }
+      });
