+export type LnaPermissionName = 'local-network' | 'loopback-network';
+export type LnaAddressSpace = 'local' | 'loopback';
+export type LnaPermissionState = PermissionState | 'unsupported';
+
+/**
+ * Queries the granular Local Network Access permission ('local-network' or 'loopback-network')
+ * with feature-detection fallback and live change subscription.
+ * Never queries the legacy combined 'local-network-access' name, which crashes older Chromium renderers.
+ */
+export async function monitorLnaPermission(
+  permissionName: LnaPermissionName,
+  onChange?: (state: PermissionState) => void
+): Promise<{ state: PermissionState; cleanup: () => void }> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    return { state: 'prompt', cleanup: () => {} };
+  }
+
+  try {
+    const status = await navigator.permissions.query({
+      name: permissionName as PermissionName,
+    });
+
+    const handleChange = () => {
+      onChange?.(status.state);
+    };
+
+    status.addEventListener('change', handleChange);
+    onChange?.(status.state);
+
+    return {
+      state: status.state,
+      cleanup: () => status.removeEventListener('change', handleChange),
+    };
+  } catch {
+    // Browser does not recognize 'local-network' or 'loopback-network';
+    // treat as 'prompt' so requests remain gated on an explicit user gesture.
+    return { state: 'prompt', cleanup: () => {} };
+  }
+}
+
+/**
+ * Connects to a hardware test device on the user's private Wi-Fi LAN (RFC 1918 / .local).
+ * Explicitly sets targetAddressSpace: 'local' for Mixed Content exemption and IP space verification.
+ */
+export async function fetchLocalDeviceDiagnostics(
+  deviceUrl = 'http://192.168.1.100:8080/api/diagnostics',
+  signal?: AbortSignal
+): Promise<Record<string, unknown>> {
+  const request = new Request(deviceUrl, {
+    method: 'GET',
+    mode: 'cors',
+    targetAddressSpace: 'local',
+    signal,
+  });
+
+  const response = await fetch(request);
+  if (!response.ok) {
+    throw new Error(`LAN hardware device responded with HTTP ${response.status}`);
+  }
+  return (await response.json()) as Record<string, unknown>;
+}
+
+/**
+ * Connects to a local companion CLI daemon running on the user's machine (127.0.0.1 / [::1] / localhost).
+ * Explicitly sets targetAddressSpace: 'loopback' for Mixed Content exemption and IP space verification.
+ */
+export async function fetchLoopbackCompanionCli(
+  cliUrl = 'http://127.0.0.1:45678/health',
+  signal?: AbortSignal
+): Promise<Record<string, unknown>> {
+  const request = new Request(cliUrl, {
+    method: 'GET',
+    mode: 'cors',
+    targetAddressSpace: 'loopback',
+    signal,
+  });
+
+  const response = await fetch(request);
+  if (!response.ok) {
+    throw new Error(`Companion CLI responded with HTTP ${response.status}`);
+  }
+  return (await response.json()) as Record<string, unknown>;
+}
+
+/**
+ * Opens a real-time telemetry WebSocket to a local LAN device or loopback companion CLI.
+ * Only passes subprotocol string(s) as the second argument (never an options object, which throws SyntaxError).
+ */
+export function openDiagnosticsWebSocket(
+  wsUrl: string,
+  subprotocols: string[] = ['v1.telemetry']
+): WebSocket {
+  return new WebSocket(wsUrl, subprotocols);
+}

