+import React, { useState, useEffect, useCallback, useRef } from 'react';
+import type { TargetAddressSpace, LocalNetworkPermissionName } from '../../global';
+
+export type PermissionStateValue = PermissionState | 'unsupported' | 'checking';
+
+export type ConnectionState =
+  | 'idle'
+  | 'connecting'
+  | 'connected'
+  | 'error';
+
+export interface EndpointDiagnostics {
+  id: 'lan-device' | 'loopback-cli';
+  label: string;
+  subtitle: string;
+  url: string;
+  addressSpace: TargetAddressSpace;
+  permissionName: 'local-network' | 'loopback-network';
+  resolvedPermissionName: LocalNetworkPermissionName;
+  permissionState: PermissionStateValue;
+  connectionState: ConnectionState;
+  latencyMs: number | null;
+  statusCode: number | null;
+  responsePreview: string | null;
+  errorMessage: string | null;
+  lastCheckedAt: string | null;
+}
+
+export interface DiagnosticLogEntry {
+  id: string;
+  timestamp: string;
+  target: 'lan-device' | 'loopback-cli' | 'system';
+  level: 'info' | 'success' | 'warning' | 'error';
+  message: string;
+  details?: string;
+}
+
+interface Props {
+  mode?: 'inline' | 'flyout';
+  onClose?: () => void;
+}
+
+const LAN_PRESETS = [
+  { label: 'Hardware Rig (192.168.1.100)', url: 'http://192.168.1.100:8080/diagnostics' },
+  { label: 'LAN Gateway (192.168.1.1)', url: 'http://192.168.1.1/api/status' },
+  { label: 'mDNS Test Node (test-device.local)', url: 'http://test-device.local:8080/diagnostics' },
+];
+
+const LOOPBACK_PRESETS = [
+  { label: 'Companion CLI (127.0.0.1:9229)', url: 'http://127.0.0.1:9229/status' },
+  { label: 'Local Agent (127.0.0.1:8080)', url: 'http://127.0.0.1:8080/health' },
+  { label: 'Loopback Host (localhost:9229)', url: 'http://localhost:9229/status' },
+];
+
+export default function DiagnosticsWidget({ mode = 'inline', onClose }: Props) {
+  const [isSecureContextState, setIsSecureContextState] = useState<boolean>(true);
+  const [showReference, setShowReference] = useState<boolean>(false);
+  const [timeoutMs, setTimeoutMs] = useState<number>(4000);
+
+  const [lanEndpoint, setLanEndpoint] = useState<EndpointDiagnostics>({
+    id: 'lan-device',
+    label: 'Hardware Test Device (Private Wi-Fi LAN)',
+    subtitle: 'RFC 1918 Private Network (192.168.1.x / .local)',
+    url: 'http://192.168.1.100:8080/diagnostics',
+    addressSpace: 'local',
+    permissionName: 'local-network',
+    resolvedPermissionName: 'local-network',
+    permissionState: 'checking',
+    connectionState: 'idle',
+    latencyMs: null,
+    statusCode: null,
+    responsePreview: null,
+    errorMessage: null,
+    lastCheckedAt: null,
+  });
+
+  const [cliEndpoint, setCliEndpoint] = useState<EndpointDiagnostics>({
+    id: 'loopback-cli',
+    label: 'Local Companion CLI (Loopback)',
+    subtitle: 'Local Machine Loopback Interface (127.0.0.1 / localhost)',
+    url: 'http://127.0.0.1:9229/status',
+    addressSpace: 'loopback',
+    permissionName: 'loopback-network',
+    resolvedPermissionName: 'loopback-network',
+    permissionState: 'checking',
+    connectionState: 'idle',
+    latencyMs: null,
+    statusCode: null,
+    responsePreview: null,
+    errorMessage: null,
+    lastCheckedAt: null,
+  });
+
+  const [logs, setLogs] = useState<DiagnosticLogEntry[]>([]);
+  const permissionStatusRefs = useRef<PermissionStatus[]>([]);
+
+  const appendLog = useCallback(
+    (
+      target: DiagnosticLogEntry['target'],
+      level: DiagnosticLogEntry['level'],
+      message: string,
+      details?: string
+    ) => {
+      const entry: DiagnosticLogEntry = {
+        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
+        timestamp: new Date().toLocaleTimeString(),
+        target,
+        level,
+        message,
+        details,
+      };
+      setLogs((prev) => [entry, ...prev].slice(0, 25));
+    },
+    []
+  );
+
+  const querySinglePermission = useCallback(
+    async (
+      primaryName: 'local-network' | 'loopback-network',
+      onUpdate: (state: PermissionStateValue, resolvedName: LocalNetworkPermissionName) => void
+    ) => {
+      if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+        onUpdate('unsupported', primaryName);
+        return;
+      }
+
+      // First query the granular split permission ('local-network' or 'loopback-network')
+      try {
+        const status = await navigator.permissions.query({
+          name: primaryName as unknown as PermissionName,
+        });
+        permissionStatusRefs.current.push(status);
+        onUpdate(status.state, primaryName);
+        status.onchange = () => {
+          onUpdate(status.state, primaryName);
+        };
+        return;
+      } catch {
+        // Fallback for browsers that still use the unified 'local-network-access' permission name
+        try {
+          const fallbackStatus = await navigator.permissions.query({
+            name: 'local-network-access' as unknown as PermissionName,
+          });
+          permissionStatusRefs.current.push(fallbackStatus);
+          onUpdate(fallbackStatus.state, 'local-network-access');
+          fallbackStatus.onchange = () => {
+            onUpdate(fallbackStatus.state, 'local-network-access');
+          };
+          return;
+        } catch {
+          onUpdate('unsupported', primaryName);
+        }
+      }
+    },
+    []
+  );
+
+  const refreshPermissions = useCallback(async () => {
+    permissionStatusRefs.current.forEach((status) => {
+      status.onchange = null;
+    });
+    permissionStatusRefs.current = [];
+
+    await Promise.all([
+      querySinglePermission('local-network', (state, resolvedName) => {
+        setLanEndpoint((prev) => ({
+          ...prev,
+          permissionState: state,
+          resolvedPermissionName: resolvedName,
+        }));
+      }),
+      querySinglePermission('loopback-network', (state, resolvedName) => {
+        setCliEndpoint((prev) => ({
+          ...prev,
+          permissionState: state,
+          resolvedPermissionName: resolvedName,
+        }));
+      }),
+    ]);
+  }, [querySinglePermission]);
+
+  useEffect(() => {
+    if (typeof window !== 'undefined') {
+      setIsSecureContextState(Boolean(window.isSecureContext));
+    }
+    refreshPermissions();
+
+    return () => {
+      permissionStatusRefs.current.forEach((status) => {
+        status.onchange = null;
+      });
+    };
+  }, [refreshPermissions]);
+
+  useEffect(() => {
+    if (mode !== 'flyout' || !onClose) return;
+    const handleKeyDown = (event: KeyboardEvent) => {
+      if (event.key === 'Escape') {
+        onClose();
+      }
+    };
+    window.addEventListener('keydown', handleKeyDown);
+    return () => window.removeEventListener('keydown', handleKeyDown);
+  }, [mode, onClose]);
+
+  const connectToEndpoint = async (targetId: 'lan-device' | 'loopback-cli') => {
+    const isLan = targetId === 'lan-device';
+    const current = isLan ? lanEndpoint : cliEndpoint;
+    const setEndpoint = isLan ? setLanEndpoint : setCliEndpoint;
+
+    const trimmedUrl = current.url.trim();
+    if (!trimmedUrl) {
+      setEndpoint((prev) => ({
+        ...prev,
+        connectionState: 'error',
+        errorMessage: 'Please enter a valid endpoint URL.',
+      }));
+      return;
+    }
+
+    setEndpoint((prev) => ({
+      ...prev,
+      connectionState: 'connecting',
+      errorMessage: null,
+      responsePreview: null,
+      statusCode: null,
+      latencyMs: null,
+    }));
+
+    appendLog(
+      targetId,
+      'info',
+      `Connecting to ${trimmedUrl}`,
+      `fetch("${trimmedUrl}", { mode: "cors", targetAddressSpace: "${current.addressSpace}" }) • Permission: ${current.permissionName}`
+    );
+
+    const controller = new AbortController();
+    const timer = window.setTimeout(() => controller.abort(), timeoutMs);
+    const startTime = performance.now();
+
+    try {
+      const response = await fetch(trimmedUrl, {
+        method: 'GET',
+        mode: 'cors',
+        headers: {
+          Accept: 'application/json, text/plain, */*',
+        },
+        targetAddressSpace: current.addressSpace,
+        signal: controller.signal,
+      });
+
+      const elapsed = Math.round(performance.now() - startTime);
+      const rawText = await response.text();
+      let formattedPreview = rawText;
+
+      try {
+        const parsed = JSON.parse(rawText);
+        formattedPreview = JSON.stringify(parsed, null, 2);
+      } catch {
+        formattedPreview = rawText.slice(0, 600) || `HTTP ${response.status} ${response.statusText || 'OK'}`;
+      }
+
+      setEndpoint((prev) => ({
+        ...prev,
+        connectionState: response.ok ? 'connected' : 'error',
+        latencyMs: elapsed,
+        statusCode: response.status,
+        responsePreview: formattedPreview,
+        errorMessage: response.ok
+          ? null
+          : `Endpoint returned HTTP ${response.status} ${response.statusText}`,
+        lastCheckedAt: new Date().toLocaleTimeString(),
+      }));
+
+      appendLog(
+        targetId,
+        response.ok ? 'success' : 'warning',
+        `Received HTTP ${response.status} from ${trimmedUrl} in ${elapsed}ms`,
+        formattedPreview.slice(0, 240)
+      );
+    } catch (err: unknown) {
+      const elapsed = Math.round(performance.now() - startTime);
+      const isAbort = err instanceof DOMException && err.name === 'AbortError';
+
+      let diagnosis = 'Network request failed.';
+      if (!isSecureContextState) {
+        diagnosis =
+          'Blocked: Local Network Access requires the page to be served from a secure context (HTTPS or localhost).';
+      } else if (isAbort) {
+        diagnosis = `Connection timed out after ${timeoutMs}ms. Verify that the ${
+          isLan ? 'LAN hardware test device' : 'local companion CLI'
+        } is running and reachable at ${trimmedUrl}.`;
+      } else if (current.permissionState === 'denied') {
+        diagnosis = `Blocked by browser permission: "${current.permissionName}" is denied. Re-enable "${current.permissionName}" in your browser's site settings and retry.`;
+      } else {
+        diagnosis = `Failed to reach ${trimmedUrl} (targetAddressSpace: "${current.addressSpace}"). Check that the ${
+          isLan ? 'hardware test device on your private Wi-Fi LAN' : 'local companion CLI on 127.0.0.1'
+        } is online, allows the "${current.permissionName}" prompt, and responds with CORS headers (Access-Control-Allow-Origin).`;
+      }
+
+      setEndpoint((prev) => ({
+        ...prev,
+        connectionState: 'error',
+        latencyMs: elapsed,
+        statusCode: null,
+        responsePreview: null,
+        errorMessage: diagnosis,
+        lastCheckedAt: new Date().toLocaleTimeString(),
+      }));
+
+      appendLog(
+        targetId,
+        'error',
+        `Connection error for ${trimmedUrl} (${elapsed}ms)`,
+        diagnosis
+      );
+    } finally {
+      window.clearTimeout(timer);
+      refreshPermissions();
+    }
+  };
+
+  const connectBoth = async () => {
