+          </span>
+        );
+    }
+  };
+
+  const renderEndpointCard = (
+    endpoint: EndpointDiagnostics,
+    setEndpoint: React.Dispatch<React.SetStateAction<EndpointDiagnostics>>,
+    presets: { label: string; url: string }[]
