+        <div>
+          {/* Card Header */}
+          <div className="flex flex-wrap items-start justify-between gap-2 mb-2">
+            <div>
+              <div className="flex items-center gap-2">
+                <span className="inline-flex items-center justify-center w-6 h-6 rounded bg-gray-900 text-amber-400 text-xs font-mono font-bold">
+                  {isLan ? 'LAN' : 'CLI'}
+                </span>
+                <h3 className="font-bold text-gray-900 text-sm md:text-base">
+                  {endpoint.label}
+                </h3>
+              </div>
+              <p className="text-xs text-gray-500 mt-0.5">{endpoint.subtitle}</p>
+            </div>
+            {renderConnectionBadge(endpoint.connectionState)}
+          </div>
+
+          {/* LNA Metadata Badges */}
+          <div className="flex flex-wrap items-center gap-2 my-3">
+            {renderPermissionBadge(endpoint.permissionName, endpoint.permissionState)}
+            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-mono bg-gray-200/80 text-gray-800">
+              targetAddressSpace: &quot;{endpoint.addressSpace}&quot;
+            </span>
+          </div>
+
+          {/* Preset Selector */}
+          <div className="mb-2">
+            <label className="block text-[11px] font-semibold uppercase tracking-wider text-gray-500 mb-1">
