+            </label>
+            <div className="flex flex-wrap gap-1.5">
+              {presets.map((preset) => (
+                <button
+                  key={preset.url}
+                  type="button"
+                  onClick={() =>
+                    setEndpoint((prev) => ({
+                      ...prev,
+                      url: preset.url,
+                    }))
+                  }
+                  className={`text-xs px-2 py-1 rounded border transition-colors cursor-pointer ${
+                    endpoint.url === preset.url
+                      ? 'bg-gray-800 text-white border-gray-800'
+                      : 'bg-white text-gray-700 border-gray-300 hover:border-amber-400'
+                  }`}
+                >
+                  {preset.label}
+                </button>
+              ))}
+            </div>
+          </div>
+
+          {/* Endpoint Input + Connect Button */}
+          <div className="mt-3">
+            <label
+              htmlFor={`input-${endpoint.id}`}
+              className="block text-xs font-semibold text-gray-700 mb-1"
+            >
+              {isLan ? 'LAN Hardware Endpoint URL' : 'Loopback Companion CLI URL'}
+            </label>
+            <div className="flex flex-col sm:flex-row gap-2">
+              <input
+                id={`input-${endpoint.id}`}
+                type="url"
+                value={endpoint.url}
+                onChange={(e) =>
+                  setEndpoint((prev) => ({
+                    ...prev,
+                    url: e.target.value,
+                  }))
+                }
+                placeholder={
+                  isLan
+                    ? 'http://192.168.1.100:8080/diagnostics'
+                    : 'http://127.0.0.1:9229/status'
+                }
+                className="flex-1 px-3 py-1.5 text-sm font-mono bg-white border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-400"
+              />
+              <button
+                type="button"
+                onClick={() => connectToEndpoint(endpoint.id)}
+                disabled={endpoint.connectionState === 'connecting'}
+                data-testid={`connect-btn-${endpoint.id}`}
+                className="bg-gray-900 hover:bg-gray-800 disabled:bg-gray-400 text-white text-xs font-semibold px-4 py-2 rounded transition-colors whitespace-nowrap cursor-pointer"
+              >
+                {endpoint.connectionState === 'connecting'
+                  ? 'Connecting...'
+                  : isLan
