+                  : 'Connect Local CLI'}
+              </button>
+            </div>
+          </div>
+
+          {/* Permission State Hint */}
+          {endpoint.permissionState === 'prompt' && (
+            <p className="mt-2 text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2.5 py-1.5">
+              Connecting will request the granular{' '}
+              <code className="font-mono font-bold">{endpoint.permissionName}</code>{' '}
+              browser permission with{' '}
