+        </div>
+      </div>
+    );
+  };
+
+  const widgetContent = (
+    <section
+      aria-label="Developer Diagnostics Connection Widget"
+      data-testid="developer-diagnostics-widget"
+      className="bg-white border border-gray-300 rounded-lg shadow-xs overflow-hidden"
+    >
+      {/* Top Banner */}
+      <div className="bg-gray-900 text-white px-4 py-3 flex flex-wrap items-center justify-between gap-3">
+        <div className="flex items-center gap-2.5">
+          <span className="inline-flex items-center justify-center w-7 h-7 rounded bg-amber-400 text-gray-900 font-bold text-xs font-mono">
+            LNA
+          </span>
+          <div>
+            <div className="flex items-center gap-2">
+              <h2 className="text-sm md:text-base font-bold tracking-tight">
+                Developer Diagnostics Bridge
+              </h2>
+              <span className="text-[10px] font-mono uppercase tracking-wider px-2 py-0.5 rounded bg-gray-800 text-amber-400 border border-gray-700">
+                Local Network Access
+              </span>
+            </div>
+            <p className="text-xs text-gray-300">
+              Connect directly from your browser to a private Wi-Fi LAN hardware test device (
+              <code className="font-mono text-amber-300">192.168.1.x</code>) and your local
+              companion CLI (<code className="font-mono text-amber-300">127.0.0.1</code>).
