+        </div>
+
+        <div className="flex items-center gap-2">
+          <span
+            className={`text-xs px-2.5 py-1 rounded font-medium border ${
+              isSecureContextState
+                ? 'bg-emerald-950/80 text-emerald-300 border-emerald-700'
+                : 'bg-red-950/80 text-red-300 border-red-700'
+            }`}
+          >
+            {isSecureContextState ? 'Secure Context (HTTPS / Local)' : 'Insecure Context (HTTP)'}
+          </span>
+
+          <button
+            type="button"
+            onClick={connectBoth}
+            data-testid="connect-both-btn"
+            className="bg-amber-400 hover:bg-amber-300 text-gray-900 text-xs font-bold px-3 py-1.5 rounded transition-colors cursor-pointer"
+          >
+            Ping Both Endpoints
+          </button>
+
+          <button
+            type="button"
+            onClick={() => setShowReference((prev) => !prev)}
+            className="bg-gray-800 hover:bg-gray-700 text-gray-200 text-xs font-medium px-2.5 py-1.5 rounded border border-gray-700 transition-colors cursor-pointer"
+          >
+            {showReference ? 'Hide LNA Info' : 'LNA Spec & CORS Info'}
+          </button>
+
+          {mode === 'flyout' && onClose && (
+            <button
+              type="button"
+              onClick={onClose}
+              aria-label="Close Diagnostics Widget"
+              className="text-gray-400 hover:text-white p-1 rounded cursor-pointer"
+            >
+              <svg
+                xmlns="http://www.w3.org/2000/svg"
+                className="h-5 w-5"
+                fill="none"
+                viewBox="0 0 24 24"
+                stroke="currentColor"
+                strokeWidth={2}
+              >
+                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+              </svg>
+            </button>
+          )}
+        </div>
+      </div>
+
+      {!isSecureContextState && (
+        <div className="bg-red-50 border-b border-red-200 px-4 py-2 text-xs text-red-800">
+          <strong>Secure Context Required:</strong> Chrome Local Network Access blocks requests to{' '}
+          <code className="font-mono">local</code> and <code className="font-mono">loopback</code>{' '}
+          address spaces from non-secure (<code className="font-mono">http://</code>) public origins.
+          Serve this application over <code className="font-mono">https://</code>.
+        </div>
+      )}
+
+      {/* Dual Connection Cards: Private Wi-Fi LAN (local) & Local Companion CLI (loopback) */}
+      <div className="p-4 grid grid-cols-1 lg:grid-cols-2 gap-4">
+        {renderEndpointCard(lanEndpoint, setLanEndpoint, LAN_PRESETS)}
+        {renderEndpointCard(cliEndpoint, setCliEndpoint, LOOPBACK_PRESETS)}
+      </div>
+
+      {/* Collapsible LNA Specification & Companion Setup Reference */}
+      {showReference && (
+        <div className="px-4 pb-4">
+          <div className="bg-gray-900 text-gray-200 rounded-lg p-4 text-xs space-y-3 font-sans">
+            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-gray-700 pb-2">
