+                />
+                <button
+                  type="button"
+                  onClick={refreshPermissions}
+                  className="bg-gray-800 hover:bg-gray-700 text-gray-200 px-2 py-0.5 rounded border border-gray-700 cursor-pointer"
+                >
+                  Re-query Permissions
+                </button>
+              </div>
+            </div>
+
+            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 text-[11px]">
+              <div className="bg-gray-800/80 p-3 rounded border border-gray-700">
+                <div className="font-bold text-white mb-1">1. Granular Permissions</div>
+                <p className="text-gray-300">
+                  Chrome splits Local Network Access into two separate permissions queried via{' '}
+                  <code className="text-amber-300">navigator.permissions.query()</code>:
+                </p>
+                <ul className="list-disc list-inside mt-1 text-gray-300 space-y-0.5 font-mono">
+                  <li>&quot;local-network&quot; (192.168.1.x)</li>
+                  <li>&quot;loopback-network&quot; (127.0.0.1)</li>
+                </ul>
+              </div>
+
+              <div className="bg-gray-800/80 p-3 rounded border border-gray-700">
+                <div className="font-bold text-white mb-1">2. Explicit targetAddressSpace</div>
+                <p className="text-gray-300">
+                  Passing <code className="text-amber-300">targetAddressSpace: &apos;local&apos;</code>{' '}
+                  or <code className="text-amber-300">&apos;loopback&apos;</code> in{' '}
+                  <code className="text-amber-300">fetch()</code> exempts private HTTP endpoints from
+                  Mixed Content blocking and verifies DNS resolution matches the expected space.
+                </p>
+              </div>
+
+              <div className="bg-gray-800/80 p-3 rounded border border-gray-700">
+                <div className="font-bold text-white mb-1">3. Permissions-Policy &amp; CORS</div>
+                <p className="text-gray-300">
+                  Responses send{' '}
+                  <code className="text-amber-300">
+                    Permissions-Policy: local-network=(self), loopback-network=(self)
+                  </code>
+                  . Target devices must return{' '}
+                  <code className="text-amber-300">Access-Control-Allow-Origin</code> headers.
+                </p>
+              </div>
+            </div>
+          </div>
+        </div>
+      )}
+
+      {/* Diagnostics Activity Log */}
+      {logs.length > 0 && (
+        <div className="border-t border-gray-200 bg-gray-50 px-4 py-2.5">
+          <div className="flex items-center justify-between mb-1.5">
+            <span className="text-[11px] font-bold uppercase tracking-wider text-gray-500">
+              Connection Diagnostics Log
+            </span>
+            <button
+              type="button"
+              onClick={() => setLogs([])}
+              className="text-[11px] text-gray-500 hover:text-gray-800 cursor-pointer"
+            >
+              Clear Log
+            </button>
+          </div>
+          <ul className="space-y-1 max-h-28 overflow-y-auto font-mono text-[11px]">
+            {logs.map((entry) => (
+              <li
+                key={entry.id}
+                className="flex flex-wrap items-baseline gap-x-2 text-gray-700"
+              >
+                <span className="text-gray-400">[{entry.timestamp}]</span>
+                <span
+                  className={`font-bold ${
+                    entry.level === 'success'
+                      ? 'text-emerald-700'
+                      : entry.level === 'error'
+                      ? 'text-red-700'
+                      : entry.level === 'warning'
+                      ? 'text-amber-700'
+                      : 'text-blue-700'
+                  }`}
+                >
+                  [{entry.target === 'lan-device' ? 'LAN' : 'CLI'}]
+                </span>
+                <span>{entry.message}</span>
+              </li>
+            ))}
+          </ul>
+        </div>
+      )}
+    </section>
+  );
+
+  if (mode === 'flyout') {
+    return (
+      <div
+        className="fixed inset-0 bg-black/40 backdrop-blur-xs z-[99999] flex justify-center items-start p-4 pt-[10vh] overflow-y-auto"
+        onClick={onClose}
+      >
+        <div
+          className="w-full max-w-4xl relative"
+          onClick={(e) => e.stopPropagation()}
+        >
+          {widgetContent}
+        </div>
+      </div>
+    );
+  }
+
+  return widgetContent;
+}
