+      const overlayRoast = document.getElementById('overlay-drink-roast');
+      const overlayNotes = document.getElementById('overlay-drink-notes');
+      const overlayNutrition = document.getElementById('overlay-drink-nutrition');
+      const overlayImage = document.getElementById('overlay-drink-image');
+      const overlayOrderLink = document.getElementById('overlay-order-link');
+
+      let lastFocusedTrigger = null;
+      let closeTimer = null;
+
+      function populateDrinkOverlay(drinkId, fallbackCard) {
+        const details = DRINK_DETAILS[drinkId] || null;
+        if (details) {
+          if (overlayTitle) overlayTitle.textContent = details.title;
+          if (overlayBadge) overlayBadge.textContent = details.badge;
+          if (overlayPrice) overlayPrice.textContent = details.price;
+          if (overlayDescription) overlayDescription.textContent = details.description;
+          if (overlayRoast) overlayRoast.textContent = details.roast;
+          if (overlayNotes) overlayNotes.textContent = details.notes;
+          if (overlayNutrition) overlayNutrition.textContent = details.nutrition;
