+      function handleSwipeStart(x, y) {
+        if (!isOpen) return;
+        startX = x;
+        startY = y;
+        currentX = x;
+        isDragging = true;
+        drawer.classList.add('dragging');
+      }
+
+      function handleSwipeMove(x, y) {
+        if (!isDragging || startX === null) return;
+        currentX = x;
+        const deltaX = currentX - startX;
+        const deltaY = Math.abs(y - startY);
+
+        // Ignore predominantly vertical scrolling unless horizontal movement is significant
+        if (deltaY > Math.abs(deltaX) && Math.abs(deltaX) < 15) {
+          return;
+        }
