+        // Follow finger when swiping right (towards the right off-screen edge)
+        if (deltaX > 0) {
+          drawer.style.transform = `translateX(${deltaX}px)`;
+        } else {
+          drawer.style.transform = 'translateX(0px)';
+        }
+      }
+
+      function handleSwipeEnd(endX) {
+        if (!isDragging || startX === null) return;
+        const finalX = typeof endX === 'number' ? endX : currentX;
+        const deltaX = finalX - startX;
