+/**
+ * Deletes a credential on the server and immediately synchronizes remaining credential IDs
+ * with the browser authenticator via PublicKeyCredential.signalAllAcceptedCredentials().
+ */
+export async function performDelete(credentialId) {
+  const targetCred = activeCredentials.find(c => c.id === credentialId);
+  const deletedLabel = targetCred ? targetCred.name : 'passkey';
