+/**
+ * Registers a new passkey using WebAuthn navigator.credentials.create().
+ * Omits authenticatorAttachment when called from the management panel so security keys work too.
+ */
+export async function registerPasskey(isPromotion = false) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    announceStatus('Passkeys are not supported in this browser.');
+    return;
+  }
+
+  let capabilities;
+  try {
+    capabilities = await PublicKeyCredential.getClientCapabilities();
+  } catch {
+    capabilities = {};
+  }
+
+  if (!capabilities.passkeyPlatformAuthenticator) {
+    announceStatus('Platform passkey authenticator is not available on this device.');
+    return;
+  }
+
+  const creationOptionsJSON = await optionsFetch({ promotion: isPromotion });
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(creationOptionsJSON);
