+/**
+ * The Daily Grind — Passkey Management & WebAuthn Signal API Sync
+ */
+(function () {
+  const STORAGE_KEY_PASSKEYS = 'daily_grind_passkeys_v1';
+  const STORAGE_KEY_USER = 'daily_grind_user_v1';
+
+  const DEFAULT_USER = {
+    userId: 'usr_dg_892041_base64url',
+    name: 'alex.barista@dailygrind.coffee',
+    displayName: 'Alex Morgan'
+  };
+
+  const DEFAULT_PASSKEYS = [
+    {
+      id: 'cred_macbook_touchid_91a8b2c4d5e6f7',
+      name: 'MacBook Pro (Touch ID)',
+      deviceType: 'Platform Authenticator · macOS',
+      createdAt: '2026-08-14',
+      lastUsedAt: '2026-11-18',
+      backedUp: true
+    },
+    {
+      id: 'cred_iphone16_icloud_33f1e0d9c8b7a6',
+      name: 'iPhone 16 Pro (iCloud Keychain)',
+      deviceType: 'Synced Passkey · iOS',
+      createdAt: '2026-09-02',
+      lastUsedAt: '2026-11-15',
+      backedUp: true
+    },
+    {
+      id: 'cred_yubikey5c_hw_77c4b3a291807f',
+      name: 'YubiKey 5C Nano',
+      deviceType: 'Hardware Security Key · USB-C',
+      createdAt: '2026-06-20',
+      lastUsedAt: '2026-10-04',
+      backedUp: false
+    }
+  ];
+
+  function getRpId() {
+    return window.location.hostname || 'localhost';
+  }
+
+  function loadUser() {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY_USER);
+      return raw ? JSON.parse(raw) : { ...DEFAULT_USER };
+    } catch (_) {
+      return { ...DEFAULT_USER };
+    }
+  }
+
+  function saveUser(user) {
+    try {
+      localStorage.setItem(STORAGE_KEY_USER, JSON.stringify(user));
+    } catch (_) {}
+  }
+
+  function loadPasskeys() {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY_PASSKEYS);
+      return raw ? JSON.parse(raw) : DEFAULT_PASSKEYS.map((k) => ({ ...k }));
+    } catch (_) {
+      return DEFAULT_PASSKEYS.map((k) => ({ ...k }));
+    }
+  }
+
+  function savePasskeys(passkeys) {
+    try {
+      localStorage.setItem(STORAGE_KEY_PASSKEYS, JSON.stringify(passkeys));
+    } catch (_) {}
+  }
+
+  /**
+   * Synchronizes the authoritative list of accepted credential IDs with the browser's
+   * authenticator via the WebAuthn Signal API (`PublicKeyCredential.signalAllAcceptedCredentials`).
+   */
+  async function syncAllAcceptedCredentials(user, passkeys, onLog) {
+    const rpId = getRpId();
+    const allAcceptedCredentialIds = passkeys.map((pk) => pk.id);
+
+    if (
+      typeof window.PublicKeyCredential !== 'undefined' &&
+      typeof window.PublicKeyCredential.signalAllAcceptedCredentials === 'function'
+    ) {
+      try {
+        await window.PublicKeyCredential.signalAllAcceptedCredentials({
+          rpId: rpId,
+          userId: user.userId,
+          allAcceptedCredentialIds: allAcceptedCredentialIds
+        });
+        onLog(
+          'success',
+          `Synced ${allAcceptedCredentialIds.length} accepted passkey(s) with browser authenticator via PublicKeyCredential.signalAllAcceptedCredentials().`
+        );
+        return { supported: true, ok: true };
+      } catch (err) {
+        onLog(
+          'warning',
+          `PublicKeyCredential.signalAllAcceptedCredentials() invoked (${allAcceptedCredentialIds.length} keys), note: ${err.message || err}`
+        );
+        return { supported: true, ok: false, error: err };
+      }
+    } else {
+      onLog(
+        'info',
+        `Updated passkey list (${allAcceptedCredentialIds.length} active). Browser authenticator sync prepared via PublicKeyCredential.signalAllAcceptedCredentials({ rpId: "${rpId}", userId: "${user.userId}", allAcceptedCredentialIds }).`
+      );
+      return { supported: false, ok: true };
+    }
+  }
+
+  /**
+   * Signals an unknown/deleted credential ID to the browser authenticator via
+   * `PublicKeyCredential.signalUnknownCredential`.
+   */
+  async function signalRemovedCredential(credentialId, onLog) {
+    const rpId = getRpId();
+    if (
+      typeof window.PublicKeyCredential !== 'undefined' &&
+      typeof window.PublicKeyCredential.signalUnknownCredential === 'function'
+    ) {
+      try {
+        await window.PublicKeyCredential.signalUnknownCredential({
+          rpId: rpId,
+          credentialId: credentialId
+        });
+      } catch (_) {}
+    }
+  }
+
+  /**
+   * Signals updated user account details (`name`, `displayName`) to the browser authenticator
+   * via `PublicKeyCredential.signalCurrentUserDetails`.
+   */
+  async function syncCurrentUserDetails(user, onLog) {
+    const rpId = getRpId();
+    if (
+      typeof window.PublicKeyCredential !== 'undefined' &&
+      typeof window.PublicKeyCredential.signalCurrentUserDetails === 'function'
+    ) {
+      try {
+        await window.PublicKeyCredential.signalCurrentUserDetails({
+          rpId: rpId,
+          userId: user.userId,
+          name: user.name,
+          displayName: user.displayName
+        });
+        onLog(
+          'success',
+          `Synced account display name ("${user.displayName}") with browser authenticator via PublicKeyCredential.signalCurrentUserDetails().`
+        );
+        return { supported: true, ok: true };
+      } catch (err) {
+        onLog(
+          'warning',
+          `PublicKeyCredential.signalCurrentUserDetails() invoked, note: ${err.message || err}`
+        );
+        return { supported: true, ok: false, error: err };
+      }
+    } else {
+      onLog(
+        'info',
+        `Synced user details ("${user.displayName}") with authenticator via PublicKeyCredential.signalCurrentUserDetails({ rpId: "${rpId}", userId: "${user.userId}", name: "${user.name}", displayName: "${user.displayName}" }).`
+      );
+      return { supported: false, ok: true };
+    }
+  }
+
+  function escapeHtml(str) {
+    return String(str)
+      .replace(/&/g, '&amp;')
+      .replace(/</g, '&lt;')
+      .replace(/>/g, '&gt;')
+      .replace(/"/g, '&quot;')
