+               <p style="font-weight: 600; margin-bottom: 6px;">No passkeys registered</p>
+               <p style="font-size: 0.9rem;">Register a new passkey to sign in faster and more securely without a password.</p>
+             </div>`
+          : passkeys
+              .map((pk) => {
+                const isEditing = editingId === pk.id;
+                return `
+                  <div class="pk-item" data-passkey-id="${escapeHtml(pk.id)}" style="display: flex; justify-content: space-between; align-items: center; padding: 16px; border: 1px solid var(--secondary); border-radius: 8px; background: #fff; margin-bottom: 12px; flex-wrap: wrap; gap: 12px;">
+                    <div style="flex: 1; min-width: 240px;">
+                      ${
+                        isEditing
+                          ? `<form class="pk-rename-form" data-id="${escapeHtml(pk.id)}" style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap;">
+                               <label for="rename-input-${escapeHtml(pk.id)}" style="position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0,0,0,0);">Passkey Name</label>
+                               <input
+                                 id="rename-input-${escapeHtml(pk.id)}"
