+                                 class="pk-rename-input"
+                                 value="${escapeHtml(pk.name)}"
+                                 required
+                                 maxlength="60"
+                                 style="padding: 7px 10px; border: 1px solid var(--primary); border-radius: 4px; font-size: 0.95rem; flex: 1; min-width: 180px;"
+                               />
+                               <button type="submit" class="pk-save-btn" style="background: var(--primary); color: #fff; border: none; padding: 7px 14px; border-radius: 4px; cursor: pointer; font-weight: 600;">Save</button>
+                               <button type="button" class="pk-cancel-btn" data-id="${escapeHtml(pk.id)}" style="background: transparent; color: var(--text); border: 1px solid #bbb; padding: 7px 12px; border-radius: 4px; cursor: pointer;">Cancel</button>
+                             </form>`
+                          : `<div style="display: flex; align-items: center; gap: 10px; flex-wrap: wrap;">
+                               <strong class="pk-name" style="font-size: 1.05rem; color: var(--primary);">${escapeHtml(pk.name)}</strong>
+                               <span style="font-size: 0.75rem; background: ${pk.backedUp ? '#e8f5e9' : '#fff3e0'}; color: ${pk.backedUp ? '#2e7d32' : '#e65100'}; padding: 2px 8px; border-radius: 12px; font-weight: 600;">
+                                 ${pk.backedUp ? 'Synced' : 'Hardware-bound'}
+                               </span>
+                             </div>`
+                      }
+                      <div style="font-size: 0.85rem; color: #666; margin-top: 6px;">
+                        <span>${escapeHtml(pk.deviceType)}</span> &bull;
+                        <span>Added ${escapeHtml(pk.createdAt)}</span> &bull;
+                        <span>Last used ${escapeHtml(pk.lastUsedAt)}</span>
+                      </div>
