+            <button type="button" class="pk-sync-now-btn" style="background: white; color: ${badgeColor}; border: 1px solid ${badgeColor}; padding: 5px 12px; border-radius: 4px; cursor: pointer; font-size: 0.82rem; font-weight: 600;">
