+          <div class="pk-profile-bar" style="background: #fafafa; border: 1px solid var(--secondary); border-radius: 8px; padding: 16px; margin-bottom: 24px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 15px;">
