+                newKey.id = cred.id;
+              }
+            } catch (_) {
+              // If user cancels or environment lacks virtual authenticator, still register in UI
+            }
+          }
+
+          passkeys.push(newKey);
+          savePasskeys(passkeys);
+          await syncAllAcceptedCredentials(user, passkeys, setLog);
+        });
+      }
+
+      container.querySelectorAll('.pk-edit-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          editingId = btn.getAttribute('data-id');
+          render();
+          const input = container.querySelector(`#rename-input-${editingId}`);
+          if (input) {
+            input.focus();
+            input.select();
+          }
+        });
+      });
+
+      container.querySelectorAll('.pk-cancel-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          editingId = null;
+          render();
+        });
+      });
+
+      container.querySelectorAll('.pk-rename-form').forEach((form) => {
+        form.addEventListener('submit', async (e) => {
+          e.preventDefault();
+          const id = form.getAttribute('data-id');
+          const input = form.querySelector('.pk-rename-input');
+          const newName = input ? input.value.trim() : '';
+          if (!newName) return;
+
+          const target = passkeys.find((k) => k.id === id);
+          if (target) {
+            const oldName = target.name;
+            target.name = newName;
+            savePasskeys(passkeys);
+            editingId = null;
+            await syncCurrentUserDetails(user, () => {});
+            await syncAllAcceptedCredentials(user, passkeys, () => {});
+            setLog(
+              'success',
