+    render();
+    // Perform initial sync on load so the browser authenticator is immediately consistent
+    syncAllAcceptedCredentials(user, passkeys, setLog);
+  }
+
+  document.addEventListener('DOMContentLoaded', () => {
+    mountPasskeyManager(document.getElementById('account-passkeys-root'));
+    mountPasskeyManager(document.getElementById('home-passkeys-root'));
