+import React, { useState, useEffect, useCallback } from 'react';
+import aaguidsData from '../utils/aaguids.json';
+import type { StoredPasskeyCredential, AaguidEntry } from '../utils/passkey-db';
+
+const aaguids = aaguidsData as Record<string, AaguidEntry>;
+
+const FALLBACK_KEY_ICON_DATA_URI =
+  'data:image/svg+xml;base64,' +
+  '';
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+function getProviderMetaFromAaguid(aaguid: string): {
+  providerName: string;
+  providerIcon?: string;
+} {
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      providerName: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const entry = aaguids[aaguid.toLowerCase()];
+  return {
+    providerName: entry?.name || 'Unknown passkey provider',
+    providerIcon: entry?.icon_light,
+  };
+}
+
+function formatEpochDate(epochMs?: number): string {
+  if (!epochMs) return 'Never used';
+  return new Date(epochMs).toLocaleDateString('en-US', {
+    year: 'numeric',
+    month: 'short',
+    day: 'numeric',
+  });
+}
+
+async function syncAcceptedCredentials(
+  rpId: string,
+  userId: string,
+  currentCredentialsList: StoredPasskeyCredential[]
+) {
+  const pkc =
+    typeof window !== 'undefined' ? (window.PublicKeyCredential as any) : undefined;
+  if (!pkc || typeof pkc.signalAllAcceptedCredentials !== 'function') {
+    return;
+  }
+
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  if (
+    !rpId ||
+    !isValidBase64Url(userId) ||
+    !credentialIds.every(isValidBase64Url)
+  ) {
+    console.warn(
+      'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.'
+    );
+    return;
+  }
+
+  try {
+    await pkc.signalAllAcceptedCredentials({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    // Use console.warn instead of console.error so passive sync failures do not fail Lighthouse errors-in-console
+    console.warn('SignalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+interface PasskeyManagementProps {
+  initialRpId?: string;
+  initialUserId?: string;
+  initialUser?: {
+    name: string;
+    displayName: string;
+    subscriptionTier?: string;
+  };
+  initialCredentials?: StoredPasskeyCredential[];
+}
+
+export default function PasskeyManagement({
+  initialRpId = '',
+  initialUserId = '',
+  initialUser = {
+    name: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    subscriptionTier: 'Digital All-Access Subscriber',
+  },
+  initialCredentials = [],
+}: PasskeyManagementProps) {
+  const baseUrl = import.meta.env.BASE_URL || '/';
+
+  const [rpId, setRpId] = useState<string>(initialRpId);
+  const [userId, setUserId] = useState<string>(initialUserId);
+  const [credentials, setCredentials] =
+    useState<StoredPasskeyCredential[]>(initialCredentials);
+
+  // User profile state for account username / displayName updates
+  const [accountName, setAccountName] = useState<string>(initialUser.name);
+  const [accountDisplayName, setAccountDisplayName] = useState<string>(
+    initialUser.displayName
+  );
+  const [subscriptionTier, setSubscriptionTier] = useState<string>(
+    initialUser.subscriptionTier || 'Digital All-Access Subscriber'
+  );
+  const [isUpdatingUser, setIsUpdatingUser] = useState<boolean>(false);
+
+  // Per-passkey rename state
+  const [editingCredentialId, setEditingCredentialId] = useState<string | null>(
+    null
+  );
+  const [editingNameValue, setEditingNameValue] = useState<string>('');
+  const [pendingActionId, setPendingActionId] = useState<string | null>(null);
+
+  // Passkey creation capability state
+  const [isPasskeySupported, setIsPasskeySupported] = useState<boolean>(false);
+  const [capabilityChecked, setCapabilityChecked] = useState<boolean>(false);
+  const [isCreatingPasskey, setIsCreatingPasskey] = useState<boolean>(false);
+
+  // Status banner messages
+  const [statusMessage, setStatusMessage] = useState<{
+    type: 'success' | 'error' | 'info';
+    text: string;
+  } | null>(null);
+
+  const loadManagementPanel = useCallback(async () => {
+    try {
+      const response = await fetch(`${baseUrl}api/credentials`);
+      if (!response.ok) return;
+      const data = await response.json();
+      setRpId(data.rpId);
+      setUserId(data.userId);
+      setCredentials(data.credentials || []);
+      if (data.user) {
+        setAccountName(data.user.name);
+        setAccountDisplayName(data.user.displayName);
+        if (data.user.subscriptionTier) {
+          setSubscriptionTier(data.user.subscriptionTier);
+        }
+      }
+      // Sync accepted credentials on initial load using server-provided rpId and userId
+      await syncAcceptedCredentials(
+        data.rpId,
+        data.userId,
+        data.credentials || []
+      );
+    } catch (e) {
+      console.warn('Could not refresh passkey credentials list:', e);
+    }
+  }, [baseUrl]);
+
+  useEffect(() => {
+    let mounted = true;
+
+    async function init() {
+      // Load webauthn-polyfills on client for getClientCapabilities & JSON helpers
+      try {
+        await import('webauthn-polyfills');
+      } catch (e) {
+        console.warn('webauthn-polyfills load warning:', e);
+      }
+
+      // Check passkey platform authenticator & conditionalGet capabilities
+      let supported = false;
+      const pkc =
+        typeof window !== 'undefined'
+          ? (window.PublicKeyCredential as any)
+          : undefined;
+      if (pkc && typeof pkc.getClientCapabilities === 'function') {
+        try {
+          const capabilities = await pkc.getClientCapabilities();
+          supported = Boolean(
+            capabilities?.passkeyPlatformAuthenticator &&
+              capabilities?.conditionalGet !== false
+          );
+        } catch {
+          supported = false;
+        }
+      }
+
+      if (mounted) {
+        setIsPasskeySupported(supported);
+        setCapabilityChecked(true);
+      }
+
+      // Load credentials and invoke signalAllAcceptedCredentials on mount
+      await loadManagementPanel();
+    }
+
+    init();
+
+    return () => {
+      mounted = false;
+    };
+  }, [loadManagementPanel]);
+
+  const startCredentialRename = (cred: StoredPasskeyCredential) => {
