+++ b/src/pages/api/register/options.ts
@@ -0,0 +1,47 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { db, getRpId } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ request, url }) => {
+  const user = db.getCurrentUser();
+  const rpId = getRpId(url);
+  const existingCredentials = db.findCredentialsByUserId(user.passkeyUserId);
+
+  let isPromotionFlow = false;
+  try {
+    const body = await request.json();
+    isPromotionFlow = Boolean(body?.promotion);
+  } catch {
+    isPromotionFlow = false;
+  }
+
+  const options = await generateRegistrationOptions({
+    rpName: 'The DevTools Times',
+    rpID: rpId,
+    userID: Buffer.from(user.passkeyUserId, 'base64url'),
+    userName: user.name,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    supportedAlgorithmIDs: [-7, -257],
+    excludeCredentials: existingCredentials.map((cred) => ({
+      id: cred.id,
+      transports: cred.transports as AuthenticatorTransport[],
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow ? { authenticatorAttachment: 'platform' } : {}),
+    },
+  });
+
+  // Ensure user.id matches our unpadded Base64URL passkeyUserId
+  options.user.id = user.passkeyUserId;
+
+  db.setChallenge(user.id, options.challenge);
+
+  return new Response(JSON.stringify(options), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
diff --git a/src/pages/api/register/verify.ts b/src/pages/api/register/verify.ts
new file mode 100644
index 0000000..c04380f
--- /dev/null
+++ b/src/pages/api/register/verify.ts
@@ -0,0 +1,108 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import {
+  db,
+  getRpId,
+  resolveAaguidProvider,
+  toBase64Url,
+  type StoredPasskeyCredential,
+} from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ request, url }) => {
+  const user = db.getCurrentUser();
+  const rpId = getRpId(url);
+  const expectedChallenge = db.getChallenge(user.id);
+
+  if (!expectedChallenge) {
+    return new Response(
+      JSON.stringify({ error: 'No active registration challenge found for session.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  let body: any;
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON payload.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const expectedOrigin = request.headers.get('origin') || url.origin;
+
+  try {
+    const verification = await verifyRegistrationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin,
+      expectedRPID: rpId,
+      requireUserVerification: false, // Relaxed when creation options specify userVerification: 'preferred'
+    });
+
+    if (!verification.verified || !verification.registrationInfo) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey registration verification failed.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const { registrationInfo } = verification;
+    const {
+      credential,
+      credentialDeviceType,
+      credentialBackedUp,
+      aaguid,
+    } = registrationInfo;
+
+    const providerMeta =
+      aaguid === '00000000-0000-0000-0000-000000000000'
+        ? { name: 'Unknown passkey provider', providerIcon: undefined }
+        : resolveAaguidProvider(aaguid);
+
+    const newCred: StoredPasskeyCredential = {
+      id: credential.id,
+      passkeyUserId: user.passkeyUserId,
+      credentialPublicKey: toBase64Url(credential.publicKey),
+      credentialType: 'public-key',
+      credentialDeviceType,
+      credentialBackedUp,
+      aaguid,
+      providerIcon: providerMeta.providerIcon,
+      name: providerMeta.name,
+      transports: credential.transports || body?.response?.transports || ['internal'],
+      registeredAt: Date.now(),
+      counter: credential.counter,
+    };
+
+    db.saveCredential(newCred);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        credential: newCred,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({
+        error: err?.message || 'Verification failed.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
