+++ b/src/utils/passkey-db.ts
@@ -0,0 +1,238 @@
+import aaguidsData from './aaguids.json';
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+export interface UserProfile {
+  id: string;
+  passkeyUserId: string; // Valid unpadded Base64URL string
+  name: string; // Username / email
+  displayName: string; // User display name
+  subscriptionTier: string;
+}
+
+export interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids = aaguidsData as Record<string, AaguidEntry>;
+
+export function resolveAaguidProvider(aaguid: string): { name: string; providerIcon?: string } {
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      name: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const entry = aaguids[aaguid.toLowerCase()];
+  return {
+    name: entry?.name || 'Unknown passkey provider',
+    providerIcon: entry?.icon_light,
+  };
+}
+
+export function getRpId(requestUrl?: URL): string {
+  if (process.env.WEBAUTHN_RP_ID) {
+    return process.env.WEBAUTHN_RP_ID;
+  }
+  if (requestUrl?.hostname) {
+    return requestUrl.hostname;
+  }
+  return 'localhost';
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+// Encode arbitrary string to unpadded Base64URL
+export function toBase64Url(input: string | Uint8Array): string {
+  return Buffer.from(input).toString('base64url');
+}
+
+const DEFAULT_USER_ID = toBase64Url('devtools-reader-alex-rivera-01');
+
+interface PasskeyStoreState {
+  users: Map<string, UserProfile>;
+  credentials: Map<string, StoredPasskeyCredential>;
+  challenges: Map<string, string>;
+  activeUserId: string;
+}
+
+const globalStoreKey = '__devtools_times_passkey_store__';
+
+function createInitialStore(): PasskeyStoreState {
+  const users = new Map<string, UserProfile>();
+  const credentials = new Map<string, StoredPasskeyCredential>();
+  const challenges = new Map<string, string>();
+
+  const defaultUser: UserProfile = {
+    id: DEFAULT_USER_ID,
+    passkeyUserId: DEFAULT_USER_ID,
+    name: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    subscriptionTier: 'Digital All-Access Subscriber',
+  };
+  users.set(defaultUser.id, defaultUser);
+
+  const now = Date.now();
+  const gpmMeta = resolveAaguidProvider('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+  const appleMeta = resolveAaguidProvider('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+  const onePassMeta = resolveAaguidProvider('bada5566-a7aa-401f-bd96-45619a55120d');
+
+  const seedCreds: StoredPasskeyCredential[] = [
+    {
+      id: toBase64Url('cred-google-password-manager-01'),
+      passkeyUserId: defaultUser.passkeyUserId,
+      credentialPublicKey: toBase64Url('mock-pubkey-gpm-01-bytes-placeholder'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      providerIcon: gpmMeta.providerIcon,
+      name: gpmMeta.name,
+      transports: ['internal', 'hybrid'],
+      registeredAt: now - 1000 * 60 * 60 * 24 * 45, // 45 days ago
+      lastUsedAt: now - 1000 * 60 * 60 * 3, // 3 hours ago
+      counter: 14,
+    },
+    {
+      id: toBase64Url('cred-icloud-keychain-macbook-02'),
+      passkeyUserId: defaultUser.passkeyUserId,
+      credentialPublicKey: toBase64Url('mock-pubkey-apple-02-bytes-placeholder'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      providerIcon: appleMeta.providerIcon,
+      name: appleMeta.name,
+      transports: ['internal', 'hybrid'],
+      registeredAt: now - 1000 * 60 * 60 * 24 * 18, // 18 days ago
+      lastUsedAt: now - 1000 * 60 * 60 * 24 * 2, // 2 days ago
+      counter: 5,
+    },
+    {
+      id: toBase64Url('cred-1password-work-vault-03'),
+      passkeyUserId: defaultUser.passkeyUserId,
+      credentialPublicKey: toBase64Url('mock-pubkey-1pass-03-bytes-placeholder'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+      providerIcon: onePassMeta.providerIcon,
+      name: onePassMeta.name,
+      transports: ['internal'],
+      registeredAt: now - 1000 * 60 * 60 * 24 * 90, // 90 days ago
+      counter: 1,
+    },
+  ];
+
+  for (const cred of seedCreds) {
+    credentials.set(cred.id, cred);
+  }
+
+  return {
+    users,
+    credentials,
+    challenges,
+    activeUserId: defaultUser.id,
+  };
+}
+
+function getStore(): PasskeyStoreState {
+  const g = globalThis as unknown as Record<string, PasskeyStoreState | undefined>;
+  if (!g[globalStoreKey]) {
+    g[globalStoreKey] = createInitialStore();
+  }
+  return g[globalStoreKey]!;
+}
+
+export const db = {
+  getCurrentUser(): UserProfile {
+    const store = getStore();
+    return store.users.get(store.activeUserId)!;
+  },
+
+  updateUser(
+    userId: string,
+    updates: { name?: string; displayName?: string }
+  ): UserProfile {
+    const store = getStore();
+    const existing = store.users.get(userId) || store.users.get(store.activeUserId)!;
+    const updated: UserProfile = {
+      ...existing,
+      ...(typeof updates.name === 'string' && updates.name.trim()
+        ? { name: updates.name.trim() }
+        : {}),
+      ...(typeof updates.displayName === 'string' && updates.displayName.trim()
+        ? { displayName: updates.displayName.trim() }
+        : {}),
+    };
+    store.users.set(updated.id, updated);
+    return updated;
+  },
+
+  findCredentialsByUserId(passkeyUserId: string): StoredPasskeyCredential[] {
+    const store = getStore();
+    const list: StoredPasskeyCredential[] = [];
+    for (const cred of store.credentials.values()) {
+      if (cred.passkeyUserId === passkeyUserId) {
+        // Hydrate provider icon and fallback name via AAGUID lookup if not already set
+        const provider = resolveAaguidProvider(cred.aaguid);
+        list.push({
+          ...cred,
+          name: cred.name || provider.name,
+          providerIcon: cred.providerIcon ?? provider.providerIcon,
+        });
+      }
+    }
+    return list.sort((a, b) => b.registeredAt - a.registeredAt);
+  },
+
+  findCredentialById(id: string): StoredPasskeyCredential | undefined {
+    const store = getStore();
+    return store.credentials.get(id);
+  },
+
+  saveCredential(cred: StoredPasskeyCredential): StoredPasskeyCredential {
+    const store = getStore();
+    store.credentials.set(cred.id, cred);
+    return cred;
+  },
+
+  deleteCredential(id: string): boolean {
+    const store = getStore();
+    return store.credentials.delete(id);
+  },
+
+  setChallenge(userId: string, challenge: string): void {
+    const store = getStore();
+    store.challenges.set(userId, challenge);
+  },
+
+  getChallenge(userId: string): string | undefined {
+    const store = getStore();
+    return store.challenges.get(userId);
+  },
+};

