+import React, { useState, useEffect } from 'react';
+import {
+  UserCircleIcon,
+  ShieldCheckIcon,
+  NewspaperIcon,
+  CheckCircleIcon,
+} from '@heroicons/react/24/outline';
+import PasskeyManagementSection from './PasskeyManagementSection';
+
+export default function AccountSettings() {
+  const [displayName, setDisplayName] = useState('Alex Rivera');
+  const [email, setEmail] = useState('alex.rivera@devtoolstimes.com');
+  const [subscriptionTier] = useState('All-Access Digital Subscriber');
+  const [profileSaved, setProfileSaved] = useState(false);
+
+  useEffect(() => {
+    if (typeof window !== 'undefined') {
+      const storedUser = localStorage.getItem('devtools_times_user');
+      if (storedUser) {
+        try {
+          const parsed = JSON.parse(storedUser);
+          if (parsed.displayName) setDisplayName(parsed.displayName);
+          if (parsed.email) setEmail(parsed.email);
+        } catch {
+          // Use defaults
+        }
+      }
+    }
+  }, []);
+
+  const handleSaveProfile = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (typeof window !== 'undefined') {
+      localStorage.setItem(
+        'devtools_times_user',
+        JSON.stringify({ displayName, email })
+      );
+
+      // Keep browser authenticator user details in sync when reader updates their profile name
+      if (
+        typeof window.PublicKeyCredential !== 'undefined' &&
+        typeof PublicKeyCredential.signalCurrentUserDetails === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalCurrentUserDetails({
+            rpId: window.location.hostname || 'localhost',
+            userId: 'dXNlcl9kZXZ0b29sc19yZWFkZXJfMDE',
+            name: email,
+            displayName,
+          });
+        } catch {
+          // Ignore authenticator errors in unsupported environments
+        }
+      }
+    }
+    setProfileSaved(true);
+    setTimeout(() => setProfileSaved(false), 3500);
+  };
+
+  return (
+    <div className="max-w-4xl mx-auto py-8 px-4 sm:px-6 lg:px-8 space-y-8">
+      {/* Page Header */}
+      <div className="border-b border-gray-300 pb-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
+        <div>
+          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">
+            Subscriber Account
+          </p>
+          <h1 className="text-3xl font-bold text-gray-900 mt-1">
+            Account Settings
+          </h1>
+          <p className="text-sm text-gray-600 mt-1">
+            Manage your reader profile, passkey authentication, and security preferences for The DevTools Times.
