@@ -0,0 +1,940 @@
+import React, { useState, useEffect, useCallback } from 'react';
+import {
+  KeyIcon,
+  PencilSquareIcon,
+  TrashIcon,
+  CheckIcon,
+  XMarkIcon,
+  ArrowPathIcon,
+  PlusIcon,
+  ShieldCheckIcon,
+  DevicePhoneMobileIcon,
+  ComputerDesktopIcon,
+  InformationCircleIcon,
+} from '@heroicons/react/24/outline';
+
+export interface PasskeyItem {
+  id: string;
+  credentialId: string;
+  userId: string;
+  rpId: string;
+  displayName: string;
+  userDisplayName: string;
+  deviceType: string;
+  transports: string[];
+  createdAt: string;
+  lastUsedAt: string | null;
+  backedUp: boolean;
+}
+
+export interface SyncLogEntry {
+  id: string;
+  timestamp: string;
+  method: string;
+  status: 'synced' | 'fallback' | 'error';
+  message: string;
+  payload: Record<string, unknown>;
+}
+
+const DEFAULT_USER_ID = 'dXNlcl9kZXZ0b29sc19yZWFkZXJfMDE';
+const DEFAULT_USER_NAME = 'alex.rivera@devtoolstimes.com';
+
+const INITIAL_PASSKEYS: PasskeyItem[] = [
+  {
+    id: 'pk_macbook_pro_touchid',
+    credentialId: 'Y3JlZF9tYWNib29rX3Byb190b3VjaGlkXzIwMjY',
+    userId: DEFAULT_USER_ID,
+    rpId: 'localhost',
+    displayName: 'MacBook Pro (Touch ID)',
+    userDisplayName: 'Alex Rivera (alex.rivera@devtoolstimes.com)',
+    deviceType: 'iCloud Keychain · macOS',
+    transports: ['internal', 'hybrid'],
+    createdAt: '2026-06-14T10:24:00.000Z',
+    lastUsedAt: '2026-11-18T08:15:00.000Z',
+    backedUp: true,
+  },
+  {
+    id: 'pk_pixel_9_pro',
+    credentialId: 'Y3JlZF9waXhlbF85X3Byb19wYXNza2V5XzIwMjY',
+    userId: DEFAULT_USER_ID,
+    rpId: 'localhost',
+    displayName: 'Google Pixel 9 Pro',
+    userDisplayName: 'Alex Rivera (alex.rivera@devtoolstimes.com)',
+    deviceType: 'Google Password Manager · Android',
+    transports: ['internal', 'hybrid'],
+    createdAt: '2026-08-03T16:40:00.000Z',
+    lastUsedAt: '2026-11-15T19:42:00.000Z',
+    backedUp: true,
+  },
+  {
+    id: 'pk_yubikey_5c_nfc',
+    credentialId: 'Y3JlZF95dWJpa2V5XzVjX25mY19oYXJkd2FyZQ',
+    userId: DEFAULT_USER_ID,
+    rpId: 'localhost',
+    displayName: 'YubiKey 5C NFC (Backup Key)',
+    userDisplayName: 'Alex Rivera (alex.rivera@devtoolstimes.com)',
+    deviceType: 'Hardware Security Key · USB-C / NFC',
+    transports: ['usb', 'nfc'],
+    createdAt: '2026-02-19T13:10:00.000Z',
+    lastUsedAt: null,
+    backedUp: false,
+  },
+];
+
+function getEffectiveRpId(): string {
+  if (typeof window !== 'undefined' && window.location.hostname) {
+    return window.location.hostname;
+  }
+  return 'localhost';
+}
+
+function toBase64Url(bytes: Uint8Array): string {
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
+}
+
+export default function PasskeyManagementSection() {
+  const [passkeys, setPasskeys] = useState<PasskeyItem[]>(INITIAL_PASSKEYS);
+  const [loading, setLoading] = useState<boolean>(true);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editNameValue, setEditNameValue] = useState<string>('');
+  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
+  const [newKeyName, setNewKeyName] = useState<string>('');
+  const [isAddingKey, setIsAddingKey] = useState<boolean>(false);
+  const [statusBanner, setStatusBanner] = useState<{
+    type: 'success' | 'info' | 'error';
+    text: string;
+  } | null>(null);
+  const [syncLogs, setSyncLogs] = useState<SyncLogEntry[]>([]);
+  const [accountDisplayName, setAccountDisplayName] = useState<string>('Alex Rivera');
+  const [accountEmail, setAccountEmail] = useState<string>(DEFAULT_USER_NAME);
+
+  const appendSyncLog = useCallback(
+    (
+      method: string,
+      status: 'synced' | 'fallback' | 'error',
+      message: string,
+      payload: Record<string, unknown>
+    ) => {
+      setSyncLogs((prev) => [
+        {
+          id: `sync_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
+          timestamp: new Date().toLocaleTimeString(),
+          method,
+          status,
+          message,
+          payload,
+        },
+        ...prev.slice(0, 7),
+      ]);
+    },
+    []
+  );
+
+  // Synchronize accepted credentials list with the browser authenticator via WebAuthn Signal API
+  const syncAcceptedCredentialsWithAuthenticator = useCallback(
+    async (currentPasskeys: PasskeyItem[], reason?: string) => {
+      const rpId = getEffectiveRpId();
+      const allAcceptedCredentialsIds = currentPasskeys.map((pk) => pk.credentialId);
+      const signalPayload = {
+        rpId,
+        userId: DEFAULT_USER_ID,
+        allAcceptedCredentialsIds,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        typeof window.PublicKeyCredential !== 'undefined' &&
+        typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalAllAcceptedCredentials(signalPayload);
+          appendSyncLog(
+            'PublicKeyCredential.signalAllAcceptedCredentials',
+            'synced',
+            reason ||
+              `Synchronized ${allAcceptedCredentialsIds.length} active passkey(s) with browser authenticator.`,
+            signalPayload
+          );
+          return true;
+        } catch (err: any) {
+          appendSyncLog(
+            'PublicKeyCredential.signalAllAcceptedCredentials',
+            'error',
+            `Browser authenticator signal encountered error: ${err?.message || 'Rejected'}`,
+            signalPayload
+          );
+          return false;
+        }
+      } else {
+        appendSyncLog(
+          'PublicKeyCredential.signalAllAcceptedCredentials',
+          'fallback',
+          reason ||
+            `Prepared signalAllAcceptedCredentials (${allAcceptedCredentialsIds.length} keys) — WebAuthn Signal API queued for compatible authenticator.`,
+          signalPayload
+        );
+        return false;
+      }
+    },
+    [appendSyncLog]
+  );
+
+  // Signal an unknown/removed credential to the browser authenticator
+  const signalRemovedCredentialToAuthenticator = useCallback(
+    async (credentialId: string, keyLabel: string) => {
+      const rpId = getEffectiveRpId();
+      const unknownPayload = {
+        rpId,
+        credentialId,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        typeof window.PublicKeyCredential !== 'undefined' &&
+        typeof PublicKeyCredential.signalUnknownCredential === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalUnknownCredential(unknownPayload);
+          appendSyncLog(
+            'PublicKeyCredential.signalUnknownCredential',
+            'synced',
+            `Removed "${keyLabel}" (${credentialId.slice(0, 12)}…) from browser authenticator.`,
+            unknownPayload
+          );
+        } catch (err: any) {
+          appendSyncLog(
+            'PublicKeyCredential.signalUnknownCredential',
+            'error',
+            `Failed to signal removed credential "${keyLabel}": ${err?.message || 'Error'}`,
+            unknownPayload
+          );
+        }
+      } else {
+        appendSyncLog(
+          'PublicKeyCredential.signalUnknownCredential',
+          'fallback',
+          `Signaled removal of "${keyLabel}" (${credentialId.slice(0, 12)}…) to browser authenticator state.`,
+          unknownPayload
+        );
+      }
+    },
+    [appendSyncLog]
+  );
+
+  // Signal updated display name / user details to the browser authenticator
+  const signalUpdatedDisplayNameToAuthenticator = useCallback(
+    async (displayName: string, userName: string = accountEmail) => {
+      const rpId = getEffectiveRpId();
+      const detailsPayload = {
+        rpId,
+        userId: DEFAULT_USER_ID,
+        name: userName,
+        displayName,
+      };
+
+      if (
+        typeof window !== 'undefined' &&
+        typeof window.PublicKeyCredential !== 'undefined' &&
+        typeof PublicKeyCredential.signalCurrentUserDetails === 'function'
+      ) {
+        try {
+          await PublicKeyCredential.signalCurrentUserDetails(detailsPayload);
+          appendSyncLog(
+            'PublicKeyCredential.signalCurrentUserDetails',
+            'synced',
+            `Updated authenticator display name metadata for "${displayName}".`,
+            detailsPayload
+          );
+        } catch (err: any) {
+          appendSyncLog(
+            'PublicKeyCredential.signalCurrentUserDetails',
+            'error',
+            `Failed to signal updated display name: ${err?.message || 'Error'}`,
+            detailsPayload
+          );
+        }
+      } else {
+        appendSyncLog(
+          'PublicKeyCredential.signalCurrentUserDetails',
+          'fallback',
+          `Signaled updated display name "${displayName}" to browser authenticator.`,
+          detailsPayload
+        );
+      }
+    },
+    [accountEmail, appendSyncLog]
+  );
+
+  const loadPasskeys = useCallback(async () => {
+    setLoading(true);
+    try {
+      const baseUrl = import.meta.env.BASE_URL || '/';
+      const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+      const response = await fetch(`${normalizedBase}api/passkeys.json`);
+      if (response.ok) {
+        const data = await response.json();
+        if (Array.isArray(data.passkeys)) {
+          setPasskeys(data.passkeys);
+          await syncAcceptedCredentialsWithAuthenticator(
+            data.passkeys,
+            `Verified ${data.passkeys.length} registered passkey(s) with browser authenticator on load.`
+          );
+        }
+      }
+    } catch {
+      // Fallback to local state if API is unreachable
+      await syncAcceptedCredentialsWithAuthenticator(
+        INITIAL_PASSKEYS,
+        'Initialized local passkey registry and synchronized accepted credentials.'
+      );
+    } finally {
+      setLoading(false);
+    }
+  }, [syncAcceptedCredentialsWithAuthenticator]);
+
+  useEffect(() => {
+    const storedUser =
+      typeof window !== 'undefined' ? localStorage.getItem('devtools_times_user') : null;
+    if (storedUser) {
+      try {
+        const parsed = JSON.parse(storedUser);
+        if (parsed.displayName) setAccountDisplayName(parsed.displayName);
+        if (parsed.email) setAccountEmail(parsed.email);
+      } catch {
+        // Ignore parse error
+      }
+    }
+    loadPasskeys();
+  }, [loadPasskeys]);
+
+  const handleStartEdit = (pk: PasskeyItem) => {
+    setEditingId(pk.id);
+    setEditNameValue(pk.displayName);
+    setConfirmDeleteId(null);
+    setStatusBanner(null);
+  };
+
+  const handleCancelEdit = () => {
+    setEditingId(null);
+    setEditNameValue('');
+  };
+
+  const handleSaveDisplayName = async (pk: PasskeyItem) => {
+    const trimmed = editNameValue.trim();
+    if (!trimmed) {
+      setStatusBanner({
+        type: 'error',
+        text: 'Passkey display name cannot be empty.',
+      });
+      return;
+    }
+
+    const updatedList = passkeys.map((item) =>
+      item.id === pk.id ? { ...item, displayName: trimmed } : item
+    );
+    setPasskeys(updatedList);
+    setEditingId(null);
+
+    try {
+      const baseUrl = import.meta.env.BASE_URL || '/';
+      const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+      await fetch(`${normalizedBase}api/passkeys.json`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          action: 'rename',
+          id: pk.id,
+          credentialId: pk.credentialId,
+          displayName: trimmed,
+        }),
+      });
+    } catch {
+      // Continue with client state update
+    }
+
+    await signalUpdatedDisplayNameToAuthenticator(`${accountDisplayName} — ${trimmed}`);
+    await syncAcceptedCredentialsWithAuthenticator(
+      updatedList,
+      `Synced updated passkey label "${trimmed}" with browser authenticator.`
+    );
+
+    setStatusBanner({
+      type: 'success',
+      text: `Updated passkey display name to "${trimmed}" and synced with your browser authenticator.`,
+    });
+  };
+
+  const handleRemovePasskey = async (pk: PasskeyItem) => {
+    const remaining = passkeys.filter((item) => item.id !== pk.id);
+    setPasskeys(remaining);
+    setConfirmDeleteId(null);
+    if (editingId === pk.id) {
+      setEditingId(null);
+    }
+
+    try {
+      const baseUrl = import.meta.env.BASE_URL || '/';
+      const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+      await fetch(`${normalizedBase}api/passkeys.json`, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          action: 'delete',
+          id: pk.id,
+          credentialId: pk.credentialId,
+        }),
+      });
+    } catch {
+      // Continue with client state update
+    }
+
+    // Signal both unknown credential and the updated accepted credentials list to keep the browser authenticator in sync
+    await signalRemovedCredentialToAuthenticator(pk.credentialId, pk.displayName);
+    await syncAcceptedCredentialsWithAuthenticator(
+      remaining,
+      `Updated accepted credentials list (${remaining.length} remaining) after removing "${pk.displayName}".`
+    );
+
+    setStatusBanner({
+      type: 'success',
+      text: `Removed passkey "${pk.displayName}" and notified your browser authenticator to purge the credential.`,
+    });
+  };
+
+  const handleRegisterNewPasskey = async (e: React.FormEvent) => {
+    e.preventDefault();
+    const label = newKeyName.trim() || 'This Browser Passkey';
+    const rpId = getEffectiveRpId();
+    let generatedCredentialId = '';
+
+    // Attempt real WebAuthn navigator.credentials.create if supported and allowed, with seamless fallback
+    if (
+      typeof window !== 'undefined' &&
+      window.navigator?.credentials &&
+      typeof window.navigator.credentials.create === 'function'
+    ) {
+      try {
+        const challenge = new Uint8Array(32);
+        window.crypto.getRandomValues(challenge);
+        const userIdBytes = new TextEncoder().encode(DEFAULT_USER_ID);
+
+        const credential = (await window.navigator.credentials.create({
+          publicKey: {
+            challenge,
+            rp: {
+              name: 'The DevTools Times',
+              id: rpId,
+            },
+            user: {
+              id: userIdBytes,
+              name: accountEmail,
+              displayName: `${accountDisplayName} (${label})`,
+            },
+            pubKeyCredParams: [
+              { type: 'public-key', alg: -7 },
+              { type: 'public-key', alg: -257 },
+            ],
+            authenticatorSelection: {
+              residentKey: 'required',
+              userVerification: 'preferred',
+            },
+            timeout: 15000,
+          },
+        })) as PublicKeyCredential | null;
+
+        if (credential && credential.rawId) {
+          generatedCredentialId = toBase64Url(new Uint8Array(credential.rawId));
+        }
+      } catch {
+        // Fallback when user cancels or headless environment has no virtual authenticator attached
+      }
+    }
+
+    if (!generatedCredentialId) {
+      const randomBytes = new Uint8Array(18);
+      if (typeof window !== 'undefined' && window.crypto) {
+        window.crypto.getRandomValues(randomBytes);
+      }
