+import type { APIRoute } from 'astro';
+import crypto from 'node:crypto';
+import {
+  createOrUpdateUser,
+  generateChallenge,
+  getSessionFromRequest,
+  getUserByUsername,
+  saveChallenge,
+} from '../../../utils/passkeyStore';
+
+export const POST: APIRoute = async ({ request, url }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const sessionCtx = getSessionFromRequest(request);
+
+    const username = (body.username || sessionCtx?.user.username || '').trim();
+    const displayName = (body.displayName || sessionCtx?.user.displayName || username).trim();
+    const email = (body.email || sessionCtx?.user.email || '').trim();
+    const authenticatorAttachment = body.authenticatorAttachment as AuthenticatorAttachment | undefined;
+
+    if (!username) {
+      return new Response(JSON.stringify({ error: 'Username is required to register a passkey.' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    let user = sessionCtx?.user || getUserByUsername(username);
+    if (!user) {
+      user = createOrUpdateUser({
+        username,
+        displayName: displayName || username,
+        email: email || undefined,
+        password: body.password || undefined,
+      });
+    }
+
+    const challenge = generateChallenge();
+    const challengeId = crypto.randomBytes(16).toString('base64url');
+    saveChallenge(challengeId, challenge, { userId: user.id, username: user.username });
+
+    const rpId = body.rpId || url.hostname || 'localhost';
+
+    const excludeCredentials = user.passkeys.map((pk) => ({
+      id: pk.id,
+      type: 'public-key' as const,
+      transports: pk.transports || ['internal', 'hybrid', 'usb', 'ble', 'nfc'],
+    }));
+
+    const options = {
+      challenge,
+      rp: {
+        name: 'The DevTools Times',
+        id: rpId,
+      },
+      user: {
+        id: user.id,
+        name: user.username,
+        displayName: user.displayName || user.username,
+      },
+      pubKeyCredParams: [
+        { alg: -7, type: 'public-key' },   // ES256
+        { alg: -257, type: 'public-key' }, // RS256
+        { alg: -8, type: 'public-key' },   // EdDSA
+      ],
+      timeout: 60000,
+      attestation: 'none',
+      excludeCredentials,
+      authenticatorSelection: {
+        residentKey: 'preferred',
+        requireResidentKey: false,
+        userVerification: 'preferred',
+        ...(authenticatorAttachment ? { authenticatorAttachment } : {}),
+      },
+    };
+
+    return new Response(
+      JSON.stringify({
+        challengeId,
+        options,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate registration options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
