@@ -0,0 +1,160 @@
+import type { APIRoute } from 'astro';
+import {
+  consumeChallenge,
+  createOrUpdateUser,
+  createSession,
+  getSessionFromRequest,
+  getUserById,
+  getUserByUsername,
+  parseAuthenticatorData,
+  sanitizeUser,
+  type PasskeyCredential,
+} from '../../../utils/passkeyStore';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { challengeId, credential, passkeyName, username, displayName, email, password } = body;
+
+    if (!credential || !credential.id || !credential.response) {
+      return new Response(JSON.stringify({ error: 'Invalid WebAuthn credential payload' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const challengeEntry = challengeId ? consumeChallenge(challengeId) : null;
+    if (challengeId && !challengeEntry) {
+      return new Response(JSON.stringify({ error: 'Registration challenge expired or invalid. Please try again.' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    // Parse clientDataJSON if present
+    let clientData: any = null;
+    if (credential.response.clientDataJSON) {
+      const raw = Buffer.from(credential.response.clientDataJSON, 'base64url').toString('utf8');
+      clientData = JSON.parse(raw);
+      if (challengeEntry && clientData.challenge !== challengeEntry.challenge) {
+        return new Response(JSON.stringify({ error: 'Challenge verification failed' }), {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+    }
+
+    // Parse authenticatorData if provided
+    let parsedAuth: ReturnType<typeof parseAuthenticatorData> | null = null;
+    if (credential.response.authenticatorData) {
+      try {
+        const authDataBuf = Buffer.from(credential.response.authenticatorData, 'base64url');
+        parsedAuth = parseAuthenticatorData(authDataBuf);
+      } catch {
+        // Fallback if authenticatorData isn't directly sent
+      }
+    }
+
+    const sessionCtx = getSessionFromRequest(request);
+    let user =
+      sessionCtx?.user ||
+      (challengeEntry?.userId ? getUserById(challengeEntry.userId) : undefined) ||
+      (username ? getUserByUsername(username) : undefined);
+
+    if (!user) {
+      user = createOrUpdateUser({
+        username: username || challengeEntry?.username || 'reader',
+        displayName: displayName || username || 'DevTools Times Reader',
+        email,
+        password,
+      });
+    } else if (password || displayName || email) {
+      createOrUpdateUser({
+        username: user.username,
+        displayName,
+        email,
+        password,
+      });
+    }
+
+    const existingIdx = user.passkeys.findIndex((p) => p.id === credential.id);
+    const transports: string[] = credential.response.transports || ['internal', 'hybrid'];
+    const defaultName =
+      passkeyName?.trim() ||
+      inferPasskeyName(request.headers.get('user-agent') || '', transports, user.passkeys.length + 1);
+
+    const newPasskey: PasskeyCredential = {
+      id: credential.id,
+      publicKey: credential.response.publicKey || credential.response.attestationObject || '',
+      publicKeySpki: credential.response.publicKey || undefined,
+      algorithm: credential.response.publicKeyAlgorithm || -7,
+      counter: parsedAuth?.counter ?? 0,
+      transports,
+      name: defaultName,
+      createdAt: new Date().toISOString(),
+      lastUsedAt: new Date().toISOString(),
+      deviceType: parsedAuth?.backupEligible ? 'multiDevice' : 'singleDevice',
+      backedUp: parsedAuth?.backupState ?? true,
+      aaguid: parsedAuth?.aaguid || '00000000-0000-0000-0000-000000000000',
+    };
+
+    if (existingIdx >= 0) {
+      user.passkeys[existingIdx] = newPasskey;
+    } else {
+      user.passkeys.push(newPasskey);
+    }
+
+    const { token, session } = sessionCtx
+      ? { token: sessionCtx.token, session: sessionCtx.session }
+      : createSession(user, 'passkey', newPasskey.id);
+
+    session.lastReauthAt = Date.now();
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        token,
+        user: sanitizeUser(user),
+        passkey: {
+          id: newPasskey.id,
+          name: newPasskey.name,
+          createdAt: newPasskey.createdAt,
+          lastUsedAt: newPasskey.lastUsedAt,
+          transports: newPasskey.transports,
+          deviceType: newPasskey.deviceType,
+          backedUp: newPasskey.backedUp,
+          aaguid: newPasskey.aaguid,
+        },
+        session: {
+          authMethod: session.authMethod,
+          authenticatedAt: session.authenticatedAt,
+          lastReauthAt: session.lastReauthAt,
+        },
+      }),
+      {
+        status: 200,
+        headers: {
+          'Content-Type': 'application/json',
+          'Set-Cookie': `dtt_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400`,
+        },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to verify passkey registration' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
+
+function inferPasskeyName(ua: string, transports: string[], index: number): string {
+  if (transports.includes('usb') || transports.includes('nfc')) {
+    return `Security Key #${index}`;
+  }
+  if (/Macintosh|Mac OS X/i.test(ua)) return 'iCloud Keychain / Mac Passkey';
+  if (/iPhone|iPad/i.test(ua)) return 'iPhone / iPad Passkey';
+  if (/Android/i.test(ua)) return 'Google Password Manager (Android)';
+  if (/Windows/i.test(ua)) return 'Windows Hello Passkey';
+  if (/Linux/i.test(ua)) return `Chrome Profile Passkey #${index}`;
+  return `Passkey #${index}`;
+}
diff --git a/src/pages/api/auth/passkeys.ts b/src/pages/api/auth/passkeys.ts
new file mode 100644
index 0000000..3fda01e
--- /dev/null
+++ b/src/pages/api/auth/passkeys.ts
@@ -0,0 +1,121 @@
+import type { APIRoute } from 'astro';
+import {
+  getSessionFromRequest,
+  getUserByUsername,
+  sanitizeUser,
+} from '../../utils/passkeyStore';
+
+export const GET: APIRoute = async ({ request, url }) => {
+  const sessionCtx = getSessionFromRequest(request);
+  const usernameParam = url.searchParams.get('username');
+  const user = sessionCtx?.user || (usernameParam ? getUserByUsername(usernameParam) : undefined);
+
+  if (!user) {
+    return new Response(JSON.stringify({ passkeys: [] }), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  return new Response(
+    JSON.stringify({
+      user: sanitizeUser(user),
+      passkeys: sanitizeUser(user).passkeys,
+    }),
+    { status: 200, headers: { 'Content-Type': 'application/json' } }
+  );
+};
+
+export const PATCH: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { credentialId, name, username } = body;
+
+    if (!credentialId || !name || !name.trim()) {
+      return new Response(JSON.stringify({ error: 'Credential ID and new name are required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const sessionCtx = getSessionFromRequest(request);
+    const user = sessionCtx?.user || (username ? getUserByUsername(username) : undefined);
+    if (!user) {
+      return new Response(JSON.stringify({ error: 'Authentication required' }), {
+        status: 401,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const pk = user.passkeys.find((p) => p.id === credentialId);
+    if (!pk) {
+      return new Response(JSON.stringify({ error: 'Passkey not found' }), {
+        status: 404,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    pk.name = name.trim();
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        user: sanitizeUser(user),
+        passkeys: sanitizeUser(user).passkeys,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to update passkey' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
+
+export const DELETE: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { credentialId, username } = body;
+
+    if (!credentialId) {
+      return new Response(JSON.stringify({ error: 'Credential ID is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const sessionCtx = getSessionFromRequest(request);
+    const user = sessionCtx?.user || (username ? getUserByUsername(username) : undefined);
+    if (!user) {
+      return new Response(JSON.stringify({ error: 'Authentication required' }), {
+        status: 401,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const initialLen = user.passkeys.length;
+    user.passkeys = user.passkeys.filter((p) => p.id !== credentialId);
+
+    if (user.passkeys.length === initialLen) {
+      return new Response(JSON.stringify({ error: 'Passkey not found' }), {
+        status: 404,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        user: sanitizeUser(user),
+        passkeys: sanitizeUser(user).passkeys,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to delete passkey' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/pages/api/auth/session.ts b/src/pages/api/auth/session.ts
new file mode 100644
index 0000000..3bb14c5
--- /dev/null
+++ b/src/pages/api/auth/session.ts
@@ -0,0 +1,173 @@
+import type { APIRoute } from 'astro';
+import {
+  createOrUpdateUser,
+  createSession,
+  getSessionFromRequest,
+  getUserByUsername,
+  hashPassword,
+  sanitizeUser,
+  sessionsStore,
+} from '../../utils/passkeyStore';
+
+export const GET: APIRoute = async ({ request }) => {
+  const sessionCtx = getSessionFromRequest(request);
+  if (!sessionCtx) {
+    return new Response(
+      JSON.stringify({ authenticated: false, user: null, session: null }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+
+  return new Response(
+    JSON.stringify({
+      authenticated: true,
+      user: sanitizeUser(sessionCtx.user),
+      session: {
+        authMethod: sessionCtx.session.authMethod,
+        authenticatedAt: sessionCtx.session.authenticatedAt,
+        lastReauthAt: sessionCtx.session.lastReauthAt,
+        credentialId: sessionCtx.session.credentialId,
+      },
+    }),
+    { status: 200, headers: { 'Content-Type': 'application/json' } }
+  );
+};
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const { action, username, password, displayName, email } = body;
+
+    if (action === 'logout') {
+      const sessionCtx = getSessionFromRequest(request);
+      if (sessionCtx) {
+        sessionsStore.delete(sessionCtx.token);
+      }
+      return new Response(JSON.stringify({ success: true }), {
+        status: 200,
+        headers: {
+          'Content-Type': 'application/json',
+          'Set-Cookie': 'dtt_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0',
+        },
+      });
+    }
+
+    if (action === 'reauth-password') {
+      const sessionCtx = getSessionFromRequest(request);
+      const user = sessionCtx?.user || (username ? getUserByUsername(username) : undefined);
+      if (!user) {
+        return new Response(JSON.stringify({ error: 'Not signed in' }), {
+          status: 401,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+      if (user.passwordHash && password && hashPassword(password) !== user.passwordHash) {
+        return new Response(JSON.stringify({ error: 'Incorrect password for reauthentication' }), {
+          status: 401,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+      if (sessionCtx) {
+        sessionCtx.session.lastReauthAt = Date.now();
+      }
+      return new Response(
+        JSON.stringify({
+          verified: true,
+          reauthenticated: true,
+          user: sanitizeUser(user),
+          session: sessionCtx?.session,
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (action === 'update-profile') {
+      const sessionCtx = getSessionFromRequest(request);
+      const user = sessionCtx?.user || (username ? getUserByUsername(username) : undefined);
+      if (!user) {
+        return new Response(JSON.stringify({ error: 'Not signed in' }), {
+          status: 401,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+      if (displayName !== undefined) user.displayName = displayName.trim();
+      if (email !== undefined) user.email = email.trim();
+      if (password) user.passwordHash = hashPassword(password);
+
+      return new Response(
+        JSON.stringify({
+          success: true,
+          user: sanitizeUser(user),
+        }),
+        { status: 200, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (!username) {
+      return new Response(JSON.stringify({ error: 'Username is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    if (action === 'register') {
+      if (password && (password.length < 8 || !/\d/.test(password))) {
+        return new Response(
+          JSON.stringify({ error: 'Password must be at least 8 characters and contain a number.' }),
+          { status: 400, headers: { 'Content-Type': 'application/json' } }
+        );
+      }
+      const user = createOrUpdateUser({ username, displayName, email, password });
+      const { token, session } = createSession(user, 'password');
+      return new Response(
+        JSON.stringify({
+          success: true,
+          token,
+          user: sanitizeUser(user),
+          session,
+        }),
+        {
+          status: 200,
+          headers: {
+            'Content-Type': 'application/json',
+            'Set-Cookie': `dtt_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400`,
+          },
+        }
+      );
+    }
+
+    // Default: password login
+    let user = getUserByUsername(username);
+    if (!user) {
+      // Create account on the fly if logging in after external CDN login or demo
+      user = createOrUpdateUser({ username, password });
+    } else if (user.passwordHash && password && user.passwordHash !== hashPassword(password)) {
+      return new Response(
+        JSON.stringify({ error: 'Invalid username or password (APP_ERR_2001)' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const { token, session } = createSession(user, 'password');
+    return new Response(
+      JSON.stringify({
+        success: true,
+        token,
+        user: sanitizeUser(user),
+        session,
+      }),
+      {
+        status: 200,
+        headers: {
+          'Content-Type': 'application/json',
+          'Set-Cookie': `dtt_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400`,
+        },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Session operation failed' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/utils/passkeyStore.ts b/src/utils/passkeyStore.ts
new file mode 100644
index 0000000..d1fed83
--- /dev/null
+++ b/src/utils/passkeyStore.ts
@@ -0,0 +1,344 @@
+import crypto from 'node:crypto';
+
+export interface PasskeyCredential {
+  id: string; // base64url encoded credential ID
+  publicKey: string; // SPKI PEM or base64url or JWK or COSE
+  publicKeySpki?: string; // base64 encoded SPKI public key (if client sends it via getPublicKey()) or parsed from attestationObject
+  algorithm: number; // COSE algorithm (-7 for ES256, -257 for RS256, -8 for EdDSA)
+  counter: number;
+  transports?: string[];
+  name: string;
+  createdAt: string;
+  lastUsedAt?: string;
+  deviceType?: 'singleDevice' | 'multiDevice';
+  backedUp?: boolean;
+  aaguid?: string;
+}
+
+export interface UserAccount {
+  id: string; // base64url user handle
+  username: string;
+  displayName: string;
+  email: string;
+  passwordHash?: string;
+  createdAt: string;
+  passkeys: PasskeyCredential[];
+}
+
+export interface SessionData {
+  userId: string;
+  username: string;
+  authMethod: 'passkey' | 'password';
+  credentialId?: string;
+  authenticatedAt: number;
+  lastReauthAt: number;
+}
+
+// Global in-memory store (persists across requests in Node server)
+const globalStore = globalThis as unknown as {
+  __dtt_users?: Map<string, UserAccount>;
+  __dtt_challenges?: Map<string, { challenge: string; userId?: string; username?: string; expiresAt: number }>;
+  __dtt_sessions?: Map<string, SessionData>;
+};
+
+if (!globalStore.__dtt_users) {
+  globalStore.__dtt_users = new Map<string, UserAccount>();
+  // Pre-seed a demo account so testing sign-in / account management works immediately if needed
+  const demoUserId = Buffer.from('user-alex-rivera-01').toString('base64url');
+  globalStore.__dtt_users.set('alex.rivera', {
+    id: demoUserId,
+    username: 'alex.rivera',
+    displayName: 'Alex Rivera',
+    email: 'alex.rivera@devtoolstimes.com',
+    passwordHash: hashPassword('devtools123'),
+    createdAt: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30).toISOString(),
+    passkeys: [
+      {
+        id: Buffer.from('demo-passkey-macbook-pro-touchid').toString('base64url'),
+        publicKey: '',
+        algorithm: -7,
+        counter: 12,
+        transports: ['internal', 'hybrid'],
+        name: 'MacBook Pro (Chrome)',
+        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 24 * 14).toISOString(),
+        lastUsedAt: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(),
+        deviceType: 'multiDevice',
+        backedUp: true,
+        aaguid: 'adce0002-35bc-c60a-648b-0b25f1f05503',
+      },
+      {
+        id: Buffer.from('demo-passkey-yubikey-5-nfc').toString('base64url'),
+        publicKey: '',
+        algorithm: -7,
+        counter: 3,
+        transports: ['usb', 'nfc'],
+        name: 'YubiKey 5 NFC',
+        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7).toISOString(),
+        lastUsedAt: new Date(Date.now() - 1000 * 60 * 60 * 24 * 3).toISOString(),
+        deviceType: 'singleDevice',
+        backedUp: false,
+        aaguid: '2fc0579f-8113-47ea-b116-bb5a8db9202a',
+      }
+    ],
+  });
+}
+
+if (!globalStore.__dtt_challenges) {
+  globalStore.__dtt_challenges = new Map();
+}
+
+if (!globalStore.__dtt_sessions) {
+  globalStore.__dtt_sessions = new Map();
+}
+
+export const usersStore = globalStore.__dtt_users;
+export const challengesStore = globalStore.__dtt_challenges;
+export const sessionsStore = globalStore.__dtt_sessions;
+
+export function hashPassword(password: string): string {
+  return crypto.createHash('sha256').update(password + '_dtt_salt').digest('hex');
+}
+
+export function generateChallenge(): string {
+  return crypto.randomBytes(32).toString('base64url');
+}
+
+export function saveChallenge(challengeId: string, challenge: string, meta?: { userId?: string; username?: string }) {
+  challengesStore.set(challengeId, {
+    challenge,
+    userId: meta?.userId,
+    username: meta?.username,
+    expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes
+  });
+}
+
+export function consumeChallenge(challengeId: string) {
+  const entry = challengesStore.get(challengeId);
+  if (!entry) return null;
+  challengesStore.delete(challengeId);
+  if (Date.now() > entry.expiresAt) return null;
+  return entry;
+}
+
+export function getUserByUsername(username: string): UserAccount | undefined {
+  const normalized = username.trim().toLowerCase();
+  for (const user of usersStore.values()) {
+    if (user.username.toLowerCase() === normalized || user.email.toLowerCase() === normalized) {
+      return user;
+    }
+  }
+  return undefined;
+}
+
+export function getUserById(userId: string): UserAccount | undefined {
+  for (const user of usersStore.values()) {
+    if (user.id === userId) {
+      return user;
+    }
+  }
+  return undefined;
+}
+
+export function getUserByCredentialId(credentialId: string): { user: UserAccount; passkey: PasskeyCredential } | undefined {
+  for (const user of usersStore.values()) {
+    const pk = user.passkeys.find((p) => p.id === credentialId);
+    if (pk) {
+      return { user, passkey: pk };
+    }
+  }
+  return undefined;
+}
+
+export function createOrUpdateUser(params: {
+  username: string;
+  displayName?: string;
+  email?: string;
+  password?: string;
+}): UserAccount {
+  const normalized = params.username.trim().toLowerCase();
+  let existing = getUserByUsername(normalized);
+  if (existing) {
+    if (params.displayName) existing.displayName = params.displayName;
+    if (params.email) existing.email = params.email;
+    if (params.password) existing.passwordHash = hashPassword(params.password);
+    return existing;
+  }
+
+  const newUser: UserAccount = {
+    id: crypto.randomBytes(16).toString('base64url'),
+    username: params.username.trim(),
+    displayName: params.displayName?.trim() || params.username.trim(),
+    email: params.email?.trim() || (params.username.includes('@') ? params.username.trim() : `${normalized}@devtoolstimes.com`),
+    passwordHash: params.password ? hashPassword(params.password) : undefined,
+    createdAt: new Date().toISOString(),
+    passkeys: [],
+  };
+  usersStore.set(normalized, newUser);
+  return newUser;
+}
+
+export function createSession(user: UserAccount, authMethod: 'passkey' | 'password', credentialId?: string): { token: string; session: SessionData } {
+  const token = crypto.randomBytes(24).toString('base64url');
+  const now = Date.now();
+  const session: SessionData = {
+    userId: user.id,
+    username: user.username,
+    authMethod,
+    credentialId,
+    authenticatedAt: now,
+    lastReauthAt: now,
+  };
+  sessionsStore.set(token, session);
+  return { token, session };
+}
+
+export function getSessionFromRequest(request: Request): { token: string; session: SessionData; user: UserAccount } | null {
+  const authHeader = request.headers.get('authorization');
+  let token = '';
+  if (authHeader && authHeader.startsWith('Bearer ')) {
+    token = authHeader.slice(7).trim();
+  }
+  if (!token) {
+    const cookieHeader = request.headers.get('cookie') || '';
+    const match = cookieHeader.match(/(?:^|;\s*)dtt_session=([^;]+)/);
+    if (match) {
+      token = decodeURIComponent(match[1]);
+    }
+  }
+  if (!token) return null;
+
+  const session = sessionsStore.get(token);
+  if (!session) return null;
+  const user = getUserById(session.userId);
+  if (!user) return null;
+
+  return { token, session, user };
+}
+
+/**
+ * Parses authenticatorData buffer from WebAuthn response
+ */
+export function parseAuthenticatorData(authDataBuffer: Buffer) {
+  if (authDataBuffer.length < 37) {
+    throw new Error('Authenticator data too short');
+  }
+  const rpIdHash = authDataBuffer.subarray(0, 32);
+  const flags = authDataBuffer[32];
+  const userPresent = (flags & 0x01) !== 0;
+  const userVerified = (flags & 0x04) !== 0;
+  const backupEligible = (flags & 0x08) !== 0;
+  const backupState = (flags & 0x10) !== 0;
+  const attestedCredentialDataIncluded = (flags & 0x40) !== 0;
+  const extensionDataIncluded = (flags & 0x80) !== 0;
+  const counter = authDataBuffer.readUInt32BE(33);
+
+  let aaguid = '00000000-0000-0000-0000-000000000000';
+  let credentialId: Buffer | undefined;
+
+  if (attestedCredentialDataIncluded && authDataBuffer.length >= 55) {
+    const aaguidHex = authDataBuffer.subarray(37, 53).toString('hex');
+    aaguid = `${aaguidHex.slice(0, 8)}-${aaguidHex.slice(8, 12)}-${aaguidHex.slice(12, 16)}-${aaguidHex.slice(16, 20)}-${aaguidHex.slice(20)}`;
+    const credIdLen = authDataBuffer.readUInt16BE(53);
+    if (authDataBuffer.length >= 55 + credIdLen) {
+      credentialId = authDataBuffer.subarray(55, 55 + credIdLen);
+    }
+  }
+
+  return {
+    rpIdHash,
+    flags,
+    userPresent,
+    userVerified,
+    backupEligible,
+    backupState,
+    attestedCredentialDataIncluded,
+    extensionDataIncluded,
+    counter,
+    aaguid,
+    credentialId,
+  };
+}
+
+/**
+ * Verify clientDataJSON and cryptographic signature (if publicKeySpki is available)
+ */
+export function verifyWebAuthnSignature(params: {
+  clientDataJSONBase64Url: string;
+  authenticatorDataBase64Url: string;
+  signatureBase64Url: string;
+  expectedChallenge: string;
+  expectedType: 'webauthn.create' | 'webauthn.get';
+  publicKeySpkiBase64Url?: string;
+  algorithm?: number;
+}): { verified: boolean; parsedAuthData: ReturnType<typeof parseAuthenticatorData>; clientData: any } {
+  const clientDataRaw = Buffer.from(params.clientDataJSONBase64Url, 'base64url');
+  const clientData = JSON.parse(clientDataRaw.toString('utf8'));
+
+  if (clientData.type !== params.expectedType) {
+    throw new Error(`Unexpected WebAuthn type: ${clientData.type}`);
+  }
+
+  if (clientData.challenge !== params.expectedChallenge) {
+    throw new Error('Challenge mismatch');
+  }
+
+  const authDataBuffer = Buffer.from(params.authenticatorDataBase64Url, 'base64url');
+  const parsedAuthData = parseAuthenticatorData(authDataBuffer);
+
+  if (!parsedAuthData.userPresent) {
+    throw new Error('User presence flag not set');
+  }
+
+  // If this is an assertion (webauthn.get) and we have the SPKI public key stored from registration, verify cryptographic signature
+  if (params.expectedType === 'webauthn.get' && params.publicKeySpkiBase64Url && params.signatureBase64Url) {
+    const clientDataHash = crypto.createHash('sha256').update(clientDataRaw).digest();
+    const signedData = Buffer.concat([authDataBuffer, clientDataHash]);
+    const signatureBuffer = Buffer.from(params.signatureBase64Url, 'base64url');
+    const spkiDer = Buffer.from(params.publicKeySpkiBase64Url, 'base64url');
+
+    const publicKeyObj = crypto.createPublicKey({
+      key: spkiDer,
+      format: 'der',
+      type: 'spki',
+    });
+
+    const isOk = crypto.verify(
+      params.algorithm === -8 ? null : 'sha256',
+      signedData,
+      publicKeyObj,
+      signatureBuffer
+    );
+
+    if (!isOk) {
+      throw new Error('Invalid passkey cryptographic signature');
+    }
+  }
+
+  return {
+    verified: true,
+    parsedAuthData,
+    clientData,
+  };
+}
+
+export function sanitizeUser(user: UserAccount) {
+  return {
+    id: user.id,
+    username: user.username,
+    displayName: user.displayName,
+    email: user.email,
+    hasPassword: Boolean(user.passwordHash),
+    createdAt: user.createdAt,
+    passkeys: user.passkeys.map((pk) => ({
