@@ -0,0 +1,427 @@
+export interface PasskeyItem {
+  id: string;
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  transports: string[];
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  aaguid?: string;
+  algorithm?: number;
+}
+
+export interface ClientUser {
+  id: string;
+  username: string;
+  displayName: string;
+  email: string;
+  hasPassword?: boolean;
+  createdAt: string;
+  passkeys: PasskeyItem[];
+}
+
+export interface ClientSession {
+  authMethod: 'passkey' | 'password';
+  authenticatedAt: number;
+  lastReauthAt: number;
+  credentialId?: string;
+}
+
+const STORAGE_USER_KEY = 'dtt_auth_user';
+const STORAGE_TOKEN_KEY = 'dtt_auth_token';
+const STORAGE_SESSION_KEY = 'dtt_auth_session';
+
+export function base64UrlToUint8Array(base64Url: string): Uint8Array {
+  const padding = '='.repeat((4 - (base64Url.length % 4)) % 4);
+  const base64 = (base64Url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = window.atob(base64);
+  const outputArray = new Uint8Array(rawData.length);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray;
+}
+
+export function bufferToBase64Url(buffer: ArrayBuffer | Uint8Array): string {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return window
+    .btoa(binary)
+    .replace(/\+/g, '-')
+    .replace(/\//g, '_')
+    .replace(/=+$/, '');
+}
+
+export async function checkWebAuthnCapabilities() {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) {
+    return {
+      supported: false,
+      platformAuthenticator: false,
+      conditionalMediation: false,
+    };
+  }
+
+  let platformAuthenticator = false;
+  let conditionalMediation = false;
+
+  try {
+    if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
+      platformAuthenticator = await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+    }
+  } catch {
+    platformAuthenticator = false;
+  }
+
+  try {
+    if (typeof PublicKeyCredential.isConditionalMediationAvailable === 'function') {
+      conditionalMediation = await PublicKeyCredential.isConditionalMediationAvailable();
+    }
+  } catch {
+    conditionalMediation = false;
+  }
+
+  return {
+    supported: true,
+    platformAuthenticator,
+    conditionalMediation,
+  };
+}
+
+export function getStoredAuth(): {
+  token: string | null;
+  user: ClientUser | null;
+  session: ClientSession | null;
+} {
+  if (typeof window === 'undefined') {
+    return { token: null, user: null, session: null };
+  }
+  try {
+    const token = localStorage.getItem(STORAGE_TOKEN_KEY);
+    const userRaw = localStorage.getItem(STORAGE_USER_KEY);
+    const sessionRaw = localStorage.getItem(STORAGE_SESSION_KEY);
+    return {
+      token,
+      user: userRaw ? JSON.parse(userRaw) : null,
+      session: sessionRaw ? JSON.parse(sessionRaw) : null,
+    };
+  } catch {
+    return { token: null, user: null, session: null };
+  }
+}
+
+export function setStoredAuth(data: {
+  token?: string | null;
+  user?: ClientUser | null;
+  session?: ClientSession | null;
+}) {
+  if (typeof window === 'undefined') return;
+  try {
+    if (data.token !== undefined) {
+      if (data.token) localStorage.setItem(STORAGE_TOKEN_KEY, data.token);
+      else localStorage.removeItem(STORAGE_TOKEN_KEY);
+    }
+    if (data.user !== undefined) {
+      if (data.user) localStorage.setItem(STORAGE_USER_KEY, JSON.stringify(data.user));
+      else localStorage.removeItem(STORAGE_USER_KEY);
+    }
+    if (data.session !== undefined) {
+      if (data.session) localStorage.setItem(STORAGE_SESSION_KEY, JSON.stringify(data.session));
+      else localStorage.removeItem(STORAGE_SESSION_KEY);
+    }
+    window.dispatchEvent(new CustomEvent('dtt-auth-changed', { detail: getStoredAuth() }));
+  } catch {
+    // ignore storage errors
+  }
+}
+
+export function clearStoredAuth() {
+  setStoredAuth({ token: null, user: null, session: null });
+}
+
+function getApiBase(): string {
+  const base = import.meta.env.BASE_URL || '/';
+  return base.endsWith('/') ? base : `${base}/`;
+}
+
+export function getAuthHeaders(): Record<string, string> {
+  const { token } = getStoredAuth();
+  const headers: Record<string, string> = {
+    'Content-Type': 'application/json',
+  };
+  if (token) {
+    headers['Authorization'] = `Bearer ${token}`;
+  }
+  return headers;
+}
+
+/**
+ * Register a new Passkey using navigator.credentials.create()
+ */
+export async function registerPasskeyClient(params: {
+  username: string;
+  displayName?: string;
+  email?: string;
+  password?: string;
+  passkeyName?: string;
+  authenticatorAttachment?: AuthenticatorAttachment;
+}) {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) {
+    throw new Error('Passkeys (WebAuthn) are not supported in this browser.');
+  }
+
+  const apiBase = getApiBase();
+  const optionsRes = await fetch(`${apiBase}api/auth/passkey/register-options`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      username: params.username,
+      displayName: params.displayName,
+      email: params.email,
+      password: params.password,
+      authenticatorAttachment: params.authenticatorAttachment,
+      rpId: window.location.hostname,
+    }),
+  });
+
+  const optionsData = await optionsRes.json();
+  if (!optionsRes.ok) {
+    throw new Error(optionsData.error || 'Could not start passkey registration.');
+  }
+
+  const { challengeId, options } = optionsData;
+
+  const publicKeyOptions: PublicKeyCredentialCreationOptions = {
+    ...options,
+    challenge: base64UrlToUint8Array(options.challenge) as BufferSource,
+    user: {
+      ...options.user,
+      id: base64UrlToUint8Array(options.user.id) as BufferSource,
+    },
+    excludeCredentials: (options.excludeCredentials || []).map((cred: any) => ({
+      ...cred,
+      id: base64UrlToUint8Array(cred.id) as BufferSource,
+    })),
+  };
+
+  let credential: PublicKeyCredential | null = null;
+  try {
+    credential = (await navigator.credentials.create({
+      publicKey: publicKeyOptions,
+    })) as PublicKeyCredential | null;
+  } catch (err: any) {
+    if (err?.name === 'InvalidStateError') {
+      throw new Error('A passkey is already registered on this device or authenticator for this account.');
+    }
+    if (err?.name === 'NotAllowedError') {
+      throw new Error('Passkey registration was cancelled or timed out.');
+    }
+    throw new Error(err?.message || 'Passkey creation failed.');
+  }
+
+  if (!credential) {
+    throw new Error('No passkey credential was returned by the authenticator.');
+  }
+
+  const response = credential.response as AuthenticatorAttestationResponse;
+
+  const transports =
+    typeof response.getTransports === 'function' ? response.getTransports() : ['internal', 'hybrid'];
+
+  const publicKeyBuffer =
+    typeof response.getPublicKey === 'function' ? response.getPublicKey() : null;
+
+  const publicKeyAlgorithm =
+    typeof response.getPublicKeyAlgorithm === 'function' ? response.getPublicKeyAlgorithm() : -7;
+
+  const authenticatorDataBuffer =
+    typeof response.getAuthenticatorData === 'function' ? response.getAuthenticatorData() : null;
+
+  const serializedCredential = {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    authenticatorAttachment: (credential as any).authenticatorAttachment || null,
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      attestationObject: bufferToBase64Url(response.attestationObject),
+      transports,
+      publicKey: publicKeyBuffer ? bufferToBase64Url(publicKeyBuffer) : null,
+      publicKeyAlgorithm,
+      authenticatorData: authenticatorDataBuffer ? bufferToBase64Url(authenticatorDataBuffer) : null,
+    },
+  };
+
+  const verifyRes = await fetch(`${apiBase}api/auth/passkey/register-verify`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      challengeId,
+      credential: serializedCredential,
+      passkeyName: params.passkeyName,
+      username: params.username,
+      displayName: params.displayName,
+      email: params.email,
+      password: params.password,
+    }),
+  });
+
+  const verifyData = await verifyRes.json();
+  if (!verifyRes.ok) {
+    throw new Error(verifyData.error || 'Failed to verify registered passkey.');
+  }
+
+  setStoredAuth({
+    token: verifyData.token,
+    user: verifyData.user,
+    session: verifyData.session,
+  });
+
+  return verifyData;
+}
+
+/**
+ * Authenticate or Reauthenticate with a Passkey using navigator.credentials.get()
+ */
+export async function authenticateWithPasskeyClient(params?: {
+  username?: string;
+  reauth?: boolean;
+  mediation?: CredentialMediationRequirement;
+  signal?: AbortSignal;
+}) {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) {
+    throw new Error('Passkeys (WebAuthn) are not supported in this browser.');
+  }
+
+  const apiBase = getApiBase();
+  const optionsRes = await fetch(`${apiBase}api/auth/passkey/authenticate-options`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      username: params?.username,
+      reauth: params?.reauth,
+      rpId: window.location.hostname,
+    }),
+  });
+
+  const optionsData = await optionsRes.json();
+  if (!optionsRes.ok) {
+    throw new Error(optionsData.error || 'Could not start passkey authentication.');
+  }
+
+  const { challengeId, options } = optionsData;
+
+  const publicKeyOptions: PublicKeyCredentialRequestOptions = {
+    challenge: base64UrlToUint8Array(options.challenge) as BufferSource,
+    rpId: options.rpId,
+    timeout: options.timeout || 60000,
+    userVerification: options.userVerification || 'preferred',
+    allowCredentials: (options.allowCredentials || []).map((cred: any) => ({
+      ...cred,
+      id: base64UrlToUint8Array(cred.id) as BufferSource,
+    })),
+  };
+
+  let credential: PublicKeyCredential | null = null;
+  try {
+    credential = (await navigator.credentials.get({
+      publicKey: publicKeyOptions,
+      mediation: params?.mediation,
+      signal: params?.signal,
+    })) as PublicKeyCredential | null;
+  } catch (err: any) {
+    if (err?.name === 'AbortError') {
+      throw err;
+    }
+    if (err?.name === 'NotAllowedError') {
+      throw new Error('Passkey authentication was cancelled or not allowed.');
+    }
+    throw new Error(err?.message || 'Passkey authentication failed.');
+  }
+
+  if (!credential) {
+    throw new Error('No passkey assertion was returned.');
+  }
+
+  const response = credential.response as AuthenticatorAssertionResponse;
+
+  const serializedCredential = {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    authenticatorAttachment: (credential as any).authenticatorAttachment || null,
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      authenticatorData: bufferToBase64Url(response.authenticatorData),
+      signature: bufferToBase64Url(response.signature),
+      userHandle: response.userHandle ? bufferToBase64Url(response.userHandle) : null,
+    },
+  };
+
+  const verifyRes = await fetch(`${apiBase}api/auth/passkey/authenticate-verify`, {
+    method: 'POST',
+    headers: getAuthHeaders(),
+    body: JSON.stringify({
+      challengeId,
+      credential: serializedCredential,
+      username: params?.username,
+      reauth: params?.reauth,
+    }),
+  });
+
+  const verifyData = await verifyRes.json();
+  if (!verifyRes.ok) {
+    throw new Error(verifyData.error || 'Passkey verification failed.');
+  }
+
+  setStoredAuth({
+    token: verifyData.token,
+    user: verifyData.user,
+    session: verifyData.session,
+  });
+
+  return verifyData;
+}
+
+export async function fetchCurrentSession() {
+  const apiBase = getApiBase();
+  const stored = getStoredAuth();
+  try {
+    const res = await fetch(`${apiBase}api/auth/session`, {
+      headers: getAuthHeaders(),
+    });
+    if (res.ok) {
+      const data = await res.json();
+      if (data.authenticated && data.user) {
+        setStoredAuth({
+          user: data.user,
+          session: data.session,
+        });
+        return { authenticated: true, user: data.user as ClientUser, session: data.session as ClientSession };
+      }
+    }
+  } catch {
+    // Fallback to localStorage if offline
+  }
+
+  if (stored.user) {
+    return { authenticated: true, user: stored.user, session: stored.session };
+  }
+  return { authenticated: false, user: null, session: null };
+}
+
+export async function logoutClient() {
+  const apiBase = getApiBase();
+  try {
+    await fetch(`${apiBase}api/auth/session`, {
+      method: 'POST',
+      headers: getAuthHeaders(),
+      body: JSON.stringify({ action: 'logout' }),
+    });
+  } catch {
+    // ignore
+  }
+  clearStoredAuth();
+}

