+// --- 7. Data Rights and User Control (Access, Correction, Erasure) ---
+function initDataRightsControls() {
+  const accessBtn = document.getElementById('btn-access-data');
+  const correctBtn = document.getElementById('btn-correct-data');
+  const deleteBtn = document.getElementById('btn-delete-data');
+  const outputEl = document.getElementById('data-rights-output');
+
+  if (accessBtn && outputEl) {
+    accessBtn.addEventListener('click', () => {
+      const snapshot = JSON.stringify(ephemeralProfileState, null, 2);
+      outputEl.textContent = `Current Minimized Data Record (In-Memory Only, Zero localStorage PII):\n${snapshot}`;
+      safeLog('data_rights_access', 'User exported personal data record');
+    });
+  }
