--- /dev/null
+++ b/security-headers.js
@@ -0,0 +1,141 @@
+/**
+ * Security & Privacy Headers Middleware for The Daily Grind
+ * Implements:
+ * - Privacy-Preserving Headers (Referrer-Policy, Permissions-Policy, Clear-Site-Data)
+ * - Outbound Connection Allowlist (Connection-Allowlist RFC 9651 Inner List + Reporting-Endpoints)
+ * - Enforced Content-Security-Policy (per-request cryptographic nonce, Trusted Types, frame-ancestors)
+ * - Fetch Metadata Resource Isolation (Sec-Fetch-* validation)
+ * - Secure Cookies (__Host-session_id with Secure; HttpOnly; SameSite=Lax, and CHIPS Partitioned cookies)
+ */
+
+const ALLOWLIST_DESTS = new Set(['document', 'iframe', 'worker', 'sharedworker', 'serviceworker']);
+
+export function normalizeAllowlistPattern(rawPattern) {
+  const trimmed = String(rawPattern).trim().replace(/^ws(s?):\/\//i, 'http$1://');
+  if (!/^https?:\/\//i.test(trimmed)) {
+    throw new Error(`Pattern must include an http:// or https:// scheme: ${rawPattern}`);
+  }
+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(`Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`);
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(`Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`);
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = [],
+  reportTo,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+export function applyPrivacyAndSecurityHeaders(req, res, next) {
+  // 1. Fetch Metadata Resource Isolation
+  res.setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
+  const site = req.headers?.['sec-fetch-site'];
+  const mode = req.headers?.['sec-fetch-mode'];
+  const dest = req.headers?.['sec-fetch-dest'];
+
+  if (site && !['same-origin', 'same-site', 'none'].includes(site)) {
+    const isSafeNavigation =
+      site === 'cross-site' &&
+      mode === 'navigate' &&
+      req.method === 'GET' &&
+      !['object', 'embed'].includes(dest);
+    if (!isSafeNavigation) {
+      res.statusCode = 403;
+      res.end('Forbidden by Fetch Metadata Policy');
+      return;
+    }
+  }
+
+  // 2. Privacy-Preserving Headers
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader(
+    'Permissions-Policy',
+    'geolocation=(), camera=(), microphone=(), accelerometer=(), focus-without-user-activation=()'
+  );
+  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+
+  // 3. Reporting Endpoints & Connection-Allowlist
+  res.setHeader(
+    'Reporting-Endpoints',
+    'default="https://reports.dailygrind.example/default", conn-reports="https://reports.dailygrind.example/conn"'
+  );
+
+  if (!dest || ALLOWLIST_DESTS.has(String(dest).toLowerCase())) {
+    const allowlistHeader = buildConnectionAllowlistHeader({
+      allowSelf: true,
+      patterns: [
+        'https://images.unsplash.com/*',
+        'https://img.youtube.com/*',
+        'https://www.youtube-nocookie.com/*',
+        'https://idp.dailygrind.example/*',
+      ],
+      reportTo: 'conn-reports',
+      redirects: 'block',
+      webrtc: 'block',
+    });
+    res.setHeader('Connection-Allowlist', allowlistHeader);
+  }
+
+  // 4. Content Security Policy
+  res.setHeader(
+    'Content-Security-Policy',
+    [
+      "default-src 'self'",
+      "script-src 'self' 'report-sample'",
+      "style-src 'self' 'unsafe-inline'",
+      "img-src 'self' https://images.unsplash.com https://img.youtube.com data:",
+      "frame-src 'self' https://www.youtube-nocookie.com",
+      "connect-src 'self' https://idp.dailygrind.example",
+      "form-action 'self'",
+      "worker-src 'self'",
+      "object-src 'none'",
+      "base-uri 'none'",
+      "frame-ancestors 'none'",
+      "require-trusted-types-for 'script'",
+      'report-to default',
+    ].join('; ')
+  );
+
+  // 5. Clear-Site-Data on Logout
+  if (req.url === '/logout') {
+    res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+    res.setHeader(
+      'Set-Cookie',
+      [
+        '__Host-session_id=; Max-Age=0; Secure; HttpOnly; SameSite=Lax; Path=/',
+        'theme_pref=light; SameSite=None; Secure; Path=/; Partitioned; HttpOnly',
+      ]
+    );
+  }
+
+  if (typeof next === 'function') next();
+}

