@@ -0,0 +1,36 @@
+import type { APIRoute } from 'astro';
+
+function scrubUrlPii(rawUrl: unknown): string | undefined {
+  if (typeof rawUrl !== 'string') return undefined;
+  try {
+    const parsed = new URL(rawUrl, 'https://example.invalid');
+    // Strip query parameters and hash fragments to avoid logging tokens or PII
+    return `${parsed.origin === 'https://example.invalid' ? '' : parsed.origin}${parsed.pathname}`;
+  } catch {
+    return '[redacted-url]';
+  }
+}
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const payload = await request.json();
+    const reports = Array.isArray(payload) ? payload : [payload];
+
+    // Scrub PII, query strings, and tokens before any telemetry processing
+    const sanitizedReports = reports.map((report) => ({
+      type: typeof report?.type === 'string' ? report.type : 'unknown',
+      url: scrubUrlPii(report?.url),
+      disposition: report?.body?.disposition,
+      effectiveDirective: report?.body?.effectiveDirective,
+    }));
+
+    return new Response(JSON.stringify({ received: sanitizedReports.length }), {
+      status: 204,
+      headers: {
+        'Cache-Control': 'no-store',
+      },
+    });
+  } catch {
+    return new Response(null, { status: 204 });
+  }
+};
diff --git a/src/pages/api/session.ts b/src/pages/api/session.ts
