--- /dev/null
+++ b/src/pages/api/session.ts
@@ -0,0 +1,67 @@
+import type { APIRoute } from 'astro';
+
+export const POST: APIRoute = async ({ request, cookies, session }) => {
+  try {
+    const body = await request.json();
+    const username = typeof body?.username === 'string' ? body.username.trim() : '';
+
+    if (!username) {
+      return new Response(JSON.stringify({ error: 'Invalid session request' }), {
+        status: 400,
+        headers: {
+          'Content-Type': 'application/json',
+          'Cache-Control': 'no-store',
+        },
+      });
+    }
+
+    // Store minimal non-sensitive session state server-side and issue an HttpOnly cookie
+    // rather than storing authentication tokens in client-accessible localStorage.
+    if (session) {
+      await session.set('user', { username, authenticatedAt: new Date().toISOString() });
+    }
+
+    cookies.set('__Host-devtools_times_session', 'authenticated', {
+      path: '/',
+      httpOnly: true,
+      secure: true,
+      sameSite: 'lax',
+      maxAge: 60 * 60 * 24, // 24 hours (data minimization via bounded retention)
+    });
+
+    return new Response(JSON.stringify({ authenticated: true, username }), {
+      status: 200,
+      headers: {
+        'Content-Type': 'application/json',
+        'Cache-Control': 'no-store',
+      },
+    });
+  } catch {
+    return new Response(JSON.stringify({ error: 'Failed to establish session' }), {
+      status: 400,
+      headers: {
+        'Content-Type': 'application/json',
+        'Cache-Control': 'no-store',
+      },
+    });
+  }
+};
+
+export const GET: APIRoute = async ({ session }) => {
+  const user = (await session?.get('user')) || null;
+  const readingList = (await session?.get('readingList')) || [];
+
+  return new Response(
+    JSON.stringify({
+      user,
+      readingList,
+    }),
+    {
+      status: 200,
+      headers: {
+        'Content-Type': 'application/json',
+        'Cache-Control': 'no-store',
+      },
+    },
+  );
+};
