+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(`Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`);
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(`Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`);
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+// Build an RFC 9651 Inner List value for Connection-Allowlist or Connection-Allowlist-Report-Only.
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = DEFAULT_ALLOWED_PATTERNS,
+  reportTo,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+// Build companion Content-Security-Policy fallback header for browsers without Connection-Allowlist.
+export function buildContentSecurityPolicyHeader({
+  styleHash,
+  scriptHash,
+  reportTo = 'conn-reports',
+} = {}) {
+  const styleTokens = ["'self'", ...(styleHash ? [`'${styleHash}'`] : ["'unsafe-inline'"])];
+  const scriptTokens = ["'self'", ...(scriptHash ? [`'${scriptHash}'`] : [])];
+  const directives = [
+    "default-src 'self'",
+    "connect-src 'self'",
+    `img-src 'self' ${UNSPLASH_ORIGIN} data: blob:`,
+    `style-src ${styleTokens.join(' ')}`,
+    `script-src ${scriptTokens.join(' ')}`,
+    "form-action 'self'",
+    "worker-src 'self'",
+    "frame-ancestors 'none'",
+    "object-src 'none'",
+    "base-uri 'self'",
+  ];
+  if (reportTo) {
+    directives.push(`report-to ${reportTo}`);
+  }
+  return directives.join('; ');
+}
+
+// Server or middleware helper applying Connection-Allowlist, Reporting-Endpoints,
+// and fallback Content-Security-Policy headers on document and worker responses.
+export function setConnectionAllowlistHeaders(res, options = {}) {
+  const {
+    secFetchDest = 'document',
+    patterns = DEFAULT_ALLOWED_PATTERNS,
+    reportOnlyPatterns,
+    reportEndpointName = 'conn-reports',
+    reportEndpointUrl = '/api/security-reports',
+    redirects = 'block',
+    webrtc = 'block',
+    reportOnly = false,
+    styleHash,
+    scriptHash,
+  } = options;
+
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function' ? res.setHeader(name, value) : res.headers.set(name, value);
+
+  if (typeof res.appendHeader === 'function') {
+    res.appendHeader('Vary', 'Sec-Fetch-Dest');
+  } else if (typeof res.headers?.append === 'function') {
+    res.headers.append('Vary', 'Sec-Fetch-Dest');
+  } else {
+    setHeader('Vary', 'Sec-Fetch-Dest');
+  }
+
+  setHeader('X-Content-Type-Options', 'nosniff');
+  setHeader('X-Frame-Options', 'DENY');
+  setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  setHeader(
+    'Permissions-Policy',
+    'camera=(), geolocation=(), microphone=(), focus-without-user-activation=()',
+  );
+  setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+
+  if (secFetchDest && !ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())) return;
+
+  setHeader('Reporting-Endpoints', `${reportEndpointName}="${reportEndpointUrl}"`);
+  setHeader(
+    reportOnly ? 'Connection-Allowlist-Report-Only' : 'Connection-Allowlist',
+    buildConnectionAllowlistHeader({
+      allowSelf: true,
+      patterns,
+      reportTo: reportEndpointName,
+      redirects,
+      webrtc,
+    }),
+  );
+
+  if (!reportOnly && Array.isArray(reportOnlyPatterns)) {
+    setHeader(
+      'Connection-Allowlist-Report-Only',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: reportOnlyPatterns,
+        reportTo: reportEndpointName,
+        redirects,
+        webrtc,
+      }),
+    );
+  }
+
+  setHeader(
+    'Content-Security-Policy',
+    buildContentSecurityPolicyHeader({
+      styleHash,
+      scriptHash,
+      reportTo: reportEndpointName,
+    }),
+  );
+}
+
+// Inline hashes for index.html <style> and <script> blocks so CSP avoids 'unsafe-inline'.
+export const INDEX_STYLE_HASH = 'sha256-X1+4wsRDO+YaiyQ29fsrHD2iMHuVU4deq/K+NQZONV8=';
+export const INDEX_SCRIPT_HASH = 'sha256-MC6OTvgMSKwI7i0iUcbBqFhkbDEUAT8eqV3YEiukfDo=';
+
+const subscribers = new Set();
+
+function readRequestBody(req, maxBytes = 64 * 1024) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let total = 0;
+    req.on('data', (chunk) => {
+      total += chunk.length;
+      if (total > maxBytes) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function parseEmailFromBody(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  if (contentType.includes('application/json')) {
+    try {
+      const parsed = JSON.parse(rawBody);
+      return typeof parsed?.email === 'string' ? parsed.email.trim() : '';
+    } catch {
+      return '';
+    }
+  }
+  const params = new URLSearchParams(rawBody);
+  return (params.get('email') || '').trim();
+}
+
+function isValidEmail(email) {
+  return typeof email === 'string' && email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+}
+
+export function createServer() {
+  return http.createServer(async (req, res) => {
+    const host = req.headers.host || `localhost:${process.env.PORT || 11222}`;
+    const proto = req.headers['x-forwarded-proto'] === 'https' ? 'https' : 'http';
+    const baseUrl = `${proto}://${host}`;
+    const url = new URL(req.url || '/', baseUrl);
+    const reportEndpointUrl = `${baseUrl}/api/security-reports`;
+    const secFetchDest = req.headers['sec-fetch-dest'] || 'document';
+
+    if (req.method === 'POST' && url.pathname === '/api/security-reports') {
+      try {
+        await readRequestBody(req);
+      } catch {
+        // Ignore malformed report bodies
+      }
+      res.statusCode = 204;
+      res.end();
+      return;
+    }
+
+    if (
+      req.method === 'POST' &&
+      (url.pathname === '/api/newsletter' || url.pathname === '/newsletter')
+    ) {
+      setConnectionAllowlistHeaders(res, {
+        secFetchDest: req.headers['sec-fetch-dest'] || 'empty',
+        reportEndpointUrl,
+      });
+
+      try {
+        const rawBody = await readRequestBody(req);
+        const email = parseEmailFromBody(rawBody, req.headers['content-type'] || '');
+
+        if (!isValidEmail(email)) {
+          res.statusCode = 400;
+          res.setHeader('Content-Type', 'application/json; charset=utf-8');
+          res.end(
+            JSON.stringify({
+              ok: false,
+              error: 'Enter an email address in the format you@example.com.',
+            }),
+          );
+          return;
+        }
+
+        subscribers.add(email.toLowerCase());
+        res.statusCode = 200;
+        res.setHeader('Content-Type', 'application/json; charset=utf-8');
+        res.end(
+          JSON.stringify({
+            ok: true,
+            email,
+            message: `Thanks for subscribing! We'll send fresh roast updates to ${email}.`,
+          }),
+        );
+      } catch {
+        res.statusCode = 400;
+        res.setHeader('Content-Type', 'application/json; charset=utf-8');
+        res.end(
+          JSON.stringify({
+            ok: false,
+            error: 'We could not process your signup request. Please try again.',
+          }),
+        );
+      }
+      return;
+    }
+
+    if (req.method === 'GET' && url.pathname === '/logout') {
+      setConnectionAllowlistHeaders(res, {
+        secFetchDest,
+        reportEndpointUrl,
+      });
+      res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+      res.statusCode = 200;
+      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+      res.end('Logged out.');
+      return;
+    }
+
+    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+      try {
+        const htmlPath = path.join(__dirname, 'index.html');
+        const html = await fs.readFile(htmlPath, 'utf8');
+        setConnectionAllowlistHeaders(res, {
+          secFetchDest,
+          reportEndpointUrl,
+          styleHash: INDEX_STYLE_HASH,
+          scriptHash: INDEX_SCRIPT_HASH,
+        });
+        res.statusCode = 200;
+        res.setHeader('Content-Type', 'text/html; charset=utf-8');
+        res.end(html);
+      } catch {
+        res.statusCode = 500;
+        res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+        res.end('Internal Server Error');
+      }
+      return;
+    }
+
+    res.statusCode = 404;
+    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+    res.end('Not Found');
+  });
+}
+
+const isMain = process.argv[1] && path.resolve(process.argv[1]) === __filename;
+if (isMain) {
+  const port = Number(process.env.PORT) || 11222;
+  const server = createServer();
+  server.listen(port, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${port}`);
+  });
+}

