+(function () {
+  const DEFAULT_ERROR_MSG =
+    'Error: Your request could not go through. Unable to complete the request because the connection failed or was blocked.';
+  const CSP_ERROR_MSG =
+    'Error: Your request could not go through. Requests to unauthorized external hosts are blocked to protect your data.';
+  const DEFAULT_SUCCESS_MSG =
+    'Thank you for subscribing! Your email has been registered with The Daily Grind newsletter.';
+
+  let failedDuringCurrentSubmit = false;
+  let pendingMessage = null;
+
+  function renderMessage(text, type) {
+    const msgEl = document.getElementById('newsletter-message');
+    if (!msgEl) {
+      pendingMessage = { text, type };
+      return;
+    }
+
+    msgEl.textContent = text;
+    msgEl.hidden = false;
+    msgEl.removeAttribute('hidden');
+    msgEl.style.display = 'block';
+    msgEl.dataset.status = type;
+
+    if (type === 'error') {
+      msgEl.className = 'newsletter-message status-message error error-message';
+      msgEl.setAttribute('role', 'alert');
+    } else {
+      msgEl.className = 'newsletter-message status-message success success-message';
+      msgEl.setAttribute('role', 'status');
+    }
+  }
+
+  function handleBlockedOrFailedRequest(customMessage) {
+    failedDuringCurrentSubmit = true;
+    renderMessage(customMessage || DEFAULT_ERROR_MSG, 'error');
+  }
+
+  // Listen for Content Security Policy violations (e.g. injected script trying to exfiltrate data)
+  function onSecurityPolicyViolation(event) {
+    const blocked = event && event.blockedURI ? ` (${event.blockedURI})` : '';
+    handleBlockedOrFailedRequest(
+      `Error: Your request${blocked} could not go through. Connections outside our server are blocked to protect customer data.`
+    );
+  }
+
+  window.addEventListener('securitypolicyviolation', onSecurityPolicyViolation);
+  document.addEventListener('securitypolicyviolation', onSecurityPolicyViolation);
+
+  // Monitor fetch calls so any failed or blocked request informs the customer
+  if (typeof window.fetch === 'function') {
+    const originalFetch = window.fetch;
+    window.fetch = function (...args) {
+      return originalFetch.apply(this, args).then(
+        (response) => {
+          if (!response.ok) {
+            handleBlockedOrFailedRequest(DEFAULT_ERROR_MSG);
+          }
+          return response;
+        },
+        (error) => {
+          handleBlockedOrFailedRequest(DEFAULT_ERROR_MSG);
+          throw error;
+        }
+      );
+    };
+  }
+
+  // Monitor XMLHttpRequest calls
+  if (typeof window.XMLHttpRequest === 'function') {
+    const originalSend = window.XMLHttpRequest.prototype.send;
+    window.XMLHttpRequest.prototype.send = function (...args) {
+      this.addEventListener('error', () => {
+        handleBlockedOrFailedRequest(DEFAULT_ERROR_MSG);
+      });
+      try {
+        return originalSend.apply(this, args);
+      } catch (err) {
+        handleBlockedOrFailedRequest(DEFAULT_ERROR_MSG);
+        throw err;
+      }
+    };
+  }
+
+  // Monitor navigator.sendBeacon
+  if (typeof navigator !== 'undefined' && typeof navigator.sendBeacon === 'function') {
+    const originalBeacon = navigator.sendBeacon.bind(navigator);
+    navigator.sendBeacon = function (...args) {
+      try {
+        const queued = originalBeacon(...args);
+        if (!queued) {
+          handleBlockedOrFailedRequest(CSP_ERROR_MSG);
+        }
+        return queued;
+      } catch (err) {
+        handleBlockedOrFailedRequest(CSP_ERROR_MSG);
+        throw err;
+      }
+    };
+  }
+
+  function initNewsletterForm() {
+    if (pendingMessage) {
+      renderMessage(pendingMessage.text, pendingMessage.type);
+      pendingMessage = null;
+    }
+
+    const form = document.getElementById('newsletter-form') || document.querySelector('form');
+    if (!form) return;
+
+    form.addEventListener(
+      'submit',
+      () => {
+        failedDuringCurrentSubmit = false;
+      },
+      true
+    );
+
+    form.addEventListener('submit', async (event) => {
+      event.preventDefault();
+
+      const emailInput =
+        document.getElementById('newsletter-email') ||
+        form.querySelector('input[type="email"], input[name="email"]');
+      const submitBtn =
+        document.getElementById('newsletter-submit') ||
+        form.querySelector('button[type="submit"], input[type="submit"]');
+
+      const email = emailInput ? emailInput.value.trim() : '';
+      if (!email) {
+        handleBlockedOrFailedRequest(
+          'Error: Your request could not go through. Please enter your email address.'
+        );
+        return;
+      }
