+      const actionAttr = form.getAttribute('action') || '/api/newsletter';
+      const targetUrl = form.dataset.endpoint || actionAttr;
+
+      if (submitBtn) submitBtn.disabled = true;
+
+      try {
+        const response = await window.fetch(targetUrl, {
+          method: 'POST',
+          headers: {
+            'Content-Type': 'application/json',
+            Accept: 'application/json'
+          },
+          body: JSON.stringify({ email })
+        });
+
+        let payload = null;
+        try {
+          payload = await response.json();
+        } catch (_) {
+          // ignore non-JSON body
+        }
+
+        if (!response.ok) {
+          handleBlockedOrFailedRequest(
+            (payload && (payload.error || payload.message)) || DEFAULT_ERROR_MSG
+          );
+          return;
+        }
+
+        if (!failedDuringCurrentSubmit) {
+          renderMessage(
+            (payload && payload.message) || DEFAULT_SUCCESS_MSG,
+            'success'
+          );
+          if (emailInput) emailInput.value = '';
+        }
+      } catch (err) {
+        handleBlockedOrFailedRequest(DEFAULT_ERROR_MSG);
+      } finally {
+        if (submitBtn) submitBtn.disabled = false;
+      }
+    });
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initNewsletterForm);
+  } else {
+    initNewsletterForm();
+  }
+})();
