+const http = require('http');
+const fs = require('fs');
+const path = require('path');
+const querystring = require('querystring');
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "script-src 'self'",
+  "style-src 'self' 'unsafe-inline'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self'",
+  "font-src 'self'",
+  "object-src 'none'",
+  "base-uri 'self'",
+  "form-action 'self'",
+  "frame-ancestors 'self'"
+].join('; ');
+
+const subscribers = [];
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+const NEWSLETTER_PATHS = new Set([
+  '/api/newsletter',
+  '/newsletter',
+  '/subscribe',
+  '/api/subscribe',
+  '/signup',
+  '/api/signup'
+]);
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'same-origin');
+}
+
+function parseBody(req) {
+  return new Promise((resolve, reject) => {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString();
+      if (body.length > 1e6) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+      }
+    });
+    req.on('end', () => resolve(body));
+    req.on('error', reject);
+  });
+}
+
+function extractEmail(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  const trimmed = rawBody.trim();
+  if (contentType.includes('application/json') || trimmed.startsWith('{')) {
+    try {
+      const parsed = JSON.parse(trimmed);
+      if (typeof parsed.email === 'string') return parsed.email.trim();
+    } catch (_) {
+      // fall through
+    }
+  }
+  if (contentType.includes('application/x-www-form-urlencoded') || trimmed.includes('email=')) {
+    const parsed = querystring.parse(trimmed);
+    if (typeof parsed.email === 'string') return parsed.email.trim();
+  }
+  if (trimmed.includes('@') && !trimmed.includes(' ')) {
+    return trimmed;
+  }
+  return '';
+}
+
+const server = http.createServer(async (req, res) => {
+  setSecurityHeaders(res);
+
+  const parsedUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = parsedUrl.pathname;
+
+  if (NEWSLETTER_PATHS.has(pathname)) {
+    if (req.method === 'POST') {
+      try {
+        const rawBody = await parseBody(req);
+        const email = extractEmail(rawBody, req.headers['content-type'] || '');
+        const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+
+        if (!isValidEmail) {
+          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+          res.end(
+            JSON.stringify({
+              ok: false,
+              success: false,
+              error: 'Request could not go through: please enter a valid email address.'
+            })
+          );
+          return;
+        }
+
+        if (!subscribers.includes(email)) {
+          subscribers.push(email);
+        }
+
+        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: true,
+            success: true,
+            email,
+            message: 'Thank you for subscribing! Your email has been registered with The Daily Grind newsletter.'
+          })
+        );
+        return;
+      } catch (err) {
+        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            success: false,
+            error: 'Your request could not go through due to a server error. Please try again later.'
+          })
+        );
+        return;
+      }
+    }
+
+    if (req.method === 'GET') {
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({ ok: true, subscribers }));
+      return;
+    }
+
+    res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: false, error: 'Method not allowed' }));
+    return;
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: false, error: 'Request could not go through: method not allowed.' }));
+    return;
+  }
+
+  const relativePath = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
+  const safePath = path.normalize(relativePath).replace(/^(\.\.(\/|\\|$))+/, '');
+  const filePath = path.join(__dirname, safePath);
+
+  if (!filePath.startsWith(__dirname)) {
+    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Forbidden');
+    return;
+  }
+
+  fs.readFile(filePath, (err, data) => {
+    if (err) {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+      return;
+    }
+
+    const ext = path.extname(filePath).toLowerCase();
+    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+    res.writeHead(200, { 'Content-Type': contentType });
+    if (req.method === 'HEAD') {
+      res.end();
+    } else {
+      res.end(data);
+    }
+  });
+});
+
+function resolvePort() {
+  const args = process.argv.slice(2);
+  for (let i = 0; i < args.length; i++) {
+    if ((args[i] === '--port' || args[i] === '-p') && args[i + 1]) {
+      const parsed = Number(args[i + 1]);
+      if (!Number.isNaN(parsed) && parsed > 0) return parsed;
+    }
+  }
+  return Number(process.env.PORT) || 11222;
+}
+
+if (require.main === module) {
+  const port = resolvePort();
+  server.listen(port, () => {
+    console.log(`Daily Grind server running at http://localhost:${port}`);
+  });
+}
