+        if (action === 'move-item-up' || action === 'move-item-down') {
+          const itemEl = btn.closest('.customization-item');
+          const listEl = itemEl?.closest('.customizations-list');
+          if (!itemEl || !listEl) return;
+
+          const items = Array.from(listEl.children);
+          const idx = items.indexOf(itemEl);
+          const targetIdx = action === 'move-item-up' ? idx - 1 : idx + 1;
+          if (targetIdx < 0 || targetIdx >= items.length) return;
+
+          const newOrder = items.slice();
+          newOrder.splice(idx, 1);
+          newOrder.splice(targetIdx, 0, itemEl);
