+        if (action === 'remove-item') {
+          const itemEl = btn.closest('.customization-item');
+          if (!itemEl) return;
+
+          const itemLabel = itemEl.querySelector('.item-label')?.textContent?.trim() || 'Item';
+          const hadFocus = itemEl.contains(document.activeElement);
+          const nextFocusTarget =
+            itemEl.nextElementSibling?.querySelector('button[data-action="remove-item"]') ??
+            itemEl.previousElementSibling?.querySelector('button[data-action="remove-item"]') ??
+            cardEl.querySelector('button[data-action="add-item"]') ??
