+              grid.append(emptyDiv);
+            }
+            if (hadFocus) {
+              nextFocusTarget?.focus();
+            }
+          });
+          announce(`Removed ${ drinkName } from Seasonal Favorites`);
+        }
+      });
+    })();
+  </script>
