+  <script>
+    let currentScrollId = 0;
+    const sections = document.querySelectorAll('main section[id]');
+    const navLinks = document.querySelectorAll('nav a[href^="#"], nav a[data-scroll-target]');
+
+    function getTargetElement(trigger) {
+      const dataTarget = trigger.dataset.scrollTarget;
+      if (dataTarget) {
+        const id = dataTarget.startsWith('#') ? dataTarget.slice(1) : dataTarget;
+        return document.getElementById(id);
+      }
+      const href = trigger.getAttribute('href');
+      if (href && href.startsWith('#') && href.length > 1) {
+        return document.getElementById(href.slice(1));
+      }
+      return null;
+    }
+
+    async function scrollToAndHighlight(targetElement, triggerLink) {
+      const scrollId = ++currentScrollId;
+
+      sections.forEach((section) => section.classList.remove('highlight'));
+      navLinks.forEach((link) => link.classList.remove('active'));
+
+      await targetElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
+
+      // Abort follow-up effect if another scroll was triggered while awaiting
+      if (scrollId !== currentScrollId) return;
+
+      targetElement.classList.add('highlight');
+      if (triggerLink) {
+        triggerLink.classList.add('active');
+      }
+      targetElement.focus({ preventScroll: true });
+    }
+
+    document.querySelectorAll('a[href^="#"], [data-scroll-target]').forEach((link) => {
+      link.addEventListener('click', async (event) => {
+        const targetElement = getTargetElement(link);
+        if (!targetElement) return;
+
+        event.preventDefault();
+        await scrollToAndHighlight(targetElement, link.closest('nav a'));
+      });
+    });
+  </script>
+
