+        const badgeAttr = this.getAttribute('badge');
+        if (badgeAttr && badgeAttr !== 'true') return badgeAttr;
+        const limitedAttr = this.getAttribute('limited');
+        if (limitedAttr && limitedAttr !== 'true') return limitedAttr;
+        return 'Limited';
+      }
+
+      set badge(value) {
+        if (value && value !== 'false') {
+          this.setAttribute('badge', value === true ? 'Limited' : String(value));
+        } else {
+          this.removeAttribute('badge');
+          this.removeAttribute('limited');
+        }
+      }
+
+      _updateBadge() {
+        if (!this._badgeEl || !this._badgeSlot) return;
+        const assigned = this._badgeSlot
+          .assignedNodes({ flatten: false })
+          .filter((n) => n.textContent.trim().length > 0);
+
+        if (assigned.length > 0) {
+          this._badgeEl.hidden = false;
+        } else if (this.limited) {
+          this._badgeSlot.textContent = this.badge || 'Limited';
+          this._badgeEl.hidden = false;
+        } else {
+          this._badgeSlot.textContent = '';
+          this._badgeEl.hidden = true;
+        }
+      }
+
+      _render() {
+        if (this._titleSlot && this._titleSlot.assignedNodes().length === 0) {
+          this._titleSlot.textContent = this.title;
+        }
+        if (this._descriptionSlot && this._descriptionSlot.assignedNodes().length === 0) {
+          this._descriptionSlot.textContent = this.description;
+        }
+        if (this._actionLink) {
+          this._actionLink.setAttribute('href', this.href);
+        }
+        if (this._actionSlot && this._actionSlot.assignedNodes().length === 0) {
+          this._actionSlot.textContent = this.actionText;
+        }
+        this._updateBadge();
+      }
