+          ratio: 'Ratio: 1:16'
+        },
+        {
+          name: 'Bold',
+          title: 'Medium-Dark Roast \u2022 Rich & Full-Bodied',
+          desc: 'Deep cocoa and roasted hazelnut flavors with a velvety mouthfeel and lingering spice finish. Great for drip or French press.',
