+          desc: 'Commanding dark chocolate richness, caramelized sugar, and bold smokey crema. Built for espresso lovers and strong wake-up calls.',
+          grind: 'Grind: Fine',
+          ratio: 'Ratio: 1:13'
+        }
+      ];
+
+      const slider = document.getElementById('brew-strength-slider');
+      const wrapper = document.getElementById('brew-slider-wrapper');
+      const fill = document.getElementById('brew-slider-fill');
+      const valueOutput = document.getElementById('brew-strength-value');
