+
+      function updateBrewStrength(rawIndex) {
+        const min = Number(slider.min) || 0;
+        const max = Number(slider.max) || 3;
+        const index = Math.max(min, Math.min(max, Number(rawIndex)));
+        const strength = strengths[index] || strengths[1];
+        const percentage = ((index - min) / (max - min)) * 100;
+        const pctString = percentage.toFixed(4) + '%';
+
+        slider.value = String(index);
+        slider.setAttribute('aria-valuenow', String(index));
+        slider.setAttribute('aria-valuetext', strength.name);
+        slider.style.setProperty('--fill-progress', pctString);
+
+        if (wrapper) {
+          wrapper.style.setProperty('--fill-progress', pctString);
+        }
+        if (fill) {
+          fill.style.width = pctString;
+        }
+        if (valueOutput) {
+          valueOutput.textContent = strength.name;
+        }
+        if (profileTitle) {
+          profileTitle.textContent = strength.title;
+        }
+        if (profileDesc) {
+          profileDesc.textContent = strength.desc;
+        }
+        if (profileGrind) {
