+import type { APIRoute } from 'astro';
+import { extractHostDomain, formatOriginBoundSms, generateSixDigitOtp } from '../../utils/smsOtp';
+
+async function parseRequestBody(request: Request): Promise<Record<string, string>> {
+  const contentType = request.headers.get('content-type') || '';
+  if (contentType.includes('application/json')) {
+    const json = await request.json().catch(() => ({}));
+    return typeof json === 'object' && json !== null ? json : {};
+  }
+  const formData = await request.formData().catch(() => null);
+  if (formData) {
+    const result: Record<string, string> = {};
+    for (const [key, value] of formData.entries()) {
+      if (typeof value === 'string') {
+        result[key] = value;
+      }
+    }
+    return result;
+  }
+  return {};
+}
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await parseRequestBody(request);
+  const phone = (body.phone || '').trim();
+  const username = (body.username || '').trim();
+
+  if (!phone) {
+    return new Response(
+      JSON.stringify({ error: 'Please enter a valid phone number to receive an SMS verification code.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const otpCode = generateSixDigitOtp();
+  const hostDomain = extractHostDomain(request.headers.get('host') || request.url);
+  const smsMessage = formatOriginBoundSms(hostDomain, otpCode);
+
+  if (session) {
+    await session.set('pendingOtp', {
+      phone,
+      username,
+      code: otpCode,
+      expiresAt: Date.now() + 5 * 60 * 1000,
+    });
