+import type { APIRoute } from 'astro';
+
+interface PendingOtpSession {
+  phone: string;
+  username?: string;
+  code: string;
+  expiresAt: number;
+}
+
+async function parseRequestBody(request: Request): Promise<Record<string, string>> {
+  const contentType = request.headers.get('content-type') || '';
+  if (contentType.includes('application/json')) {
+    const json = await request.json().catch(() => ({}));
+    return typeof json === 'object' && json !== null ? json : {};
+  }
+  const formData = await request.formData().catch(() => null);
+  if (formData) {
+    const result: Record<string, string> = {};
+    for (const [key, value] of formData.entries()) {
+      if (typeof value === 'string') {
+        result[key] = value;
+      }
+    }
+    return result;
+  }
+  return {};
+}
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await parseRequestBody(request);
+  const otp = (body.otp || '').trim();
+  const phone = (body.phone || '').trim();
+
+  if (!/^\d{6}$/.test(otp)) {
+    return new Response(
+      JSON.stringify({ error: 'Please enter the 6-digit numeric verification code sent to your phone.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const pendingOtp = (await session?.get('pendingOtp')) as PendingOtpSession | undefined;
+
+  if (pendingOtp) {
+    if (Date.now() > pendingOtp.expiresAt) {
+      return new Response(
+        JSON.stringify({ error: 'Your verification code has expired. Please request a new code.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (pendingOtp.code !== otp) {
+      return new Response(
+        JSON.stringify({ error: 'The verification code you entered does not match. Please try again.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    await session?.set('pendingOtp', undefined);
+  }
+
+  return new Response(
+    JSON.stringify({
+      ok: true,
+      verified: true,
+      phone,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
