+/**
+ * Formats an origin-bound SMS OTP message adhering to the WebOTP and origin-bound autofill specification.
+ *
+ * Rules enforced:
+ * 1. Human-readable sentence containing the verification code comes first.
+ * 2. `@<domain> #<otp>` is placed on the very last line, with `@` as the first character and no trailing text.
+ * 3. Only the host domain is used (no scheme, port, or path).
+ * 4. `@<domain>` and `#<otp>` are separated by a single space, with no internal whitespace.
+ */
+export function extractHostDomain(input: string): string {
+  const trimmed = input.trim();
+  if (!trimmed) return 'localhost';
+
+  try {
+    if (/^[a-zA-Z][a-zA-Z\d+\-.]*:\/\//.test(trimmed)) {
+      return new URL(trimmed).hostname || 'localhost';
+    }
+    return new URL(`https://${trimmed}`).hostname || 'localhost';
+  } catch {
+    return trimmed
+      .replace(/^[a-zA-Z][a-zA-Z\d+\-.]*:\/\//, '')
+      .split('/')[0]
+      .split('?')[0]
+      .split('#')[0]
+      .split(':')[0]
+      .replace(/\s+/g, '') || 'localhost';
+  }
+}
+
+export function formatOriginBoundSms(
+  domainOrUrl: string,
+  otpCode: string,
+  iframeDomainOrUrl?: string
+): string {
+  const hostDomain = extractHostDomain(domainOrUrl);
+  const cleanOtp = otpCode.replace(/\s+/g, '');
+
+  const lastLine = iframeDomainOrUrl
+    ? `@${hostDomain} #${cleanOtp} @${extractHostDomain(iframeDomainOrUrl)}`
+    : `@${hostDomain} #${cleanOtp}`;
+
+  return `Your verification code is ${cleanOtp}.\n\n${lastLine}`;
+}
+
+export function generateSixDigitOtp(): string {
+  return String(Math.floor(Math.random() * 1_000_000)).padStart(6, '0');
+}

