+        detailTitle.textContent = item.title;
+        detailSummary.textContent = item.shortSummary;
+        detailDeepLinkDisplay.textContent = item.canonicalPath;
+        detailHeroBanner.style.backgroundImage =
+          `linear-gradient(to top, rgba(28, 16, 12, 0.88) 0%, rgba(28, 16, 12, 0.35) 60%, rgba(28, 16, 12, 0.45) 100%), url('${item.heroImage}')`;
+
+        updateOrderPriceDisplay();
+        detailStory.textContent = item.story;
+
+        // Render Tasting Notes
+        detailTastingGrid.innerHTML = item.tastingNotes
+          .map(
+            (n) => `
+            <div class="tasting-stat">
+              <div class="tasting-stat-label">${n.label}</div>
+              <div class="tasting-stat-value">${n.value}</div>
+            </div>
+          `
+          )
+          .join('');
+
+        // Render Barista Specs
+        detailSpecsList.innerHTML = item.specs
+          .map((s) => `<li><span>${s.label}</span><span>${s.value}</span></li>`)
+          .join('');
+
+        // Render Nutrition
+        detailNutritionList.innerHTML = item.nutrition
+          .map((n) => `<li><span>${n.label}</span><span>${n.value}</span></li>`)
+          .join('');
+
+        // Render Sibling Seasonal Favorites for quick switching
+        detailSiblingNav.innerHTML = Object.keys(SEASONAL_ITEMS)
+          .filter((k) => k !== itemKey)
+          .map((k) => {
+            const sib = SEASONAL_ITEMS[k];
+            return `
+              <a href="${sib.canonicalPath}" class="sibling-card" data-drill-link="${sib.slug}">
+                <img src="${sib.thumbImage}" alt="${sib.title}">
+                <div class="sibling-card-info">
+                  <strong>${sib.title}</strong>
+                  <span>${formatCurrency(sib.basePrice)} &bull; View Details &rarr;</span>
+                </div>
+              </a>
+            `;
+          })
+          .join('');
+
+        document.title = `${item.title} | Seasonal Favorites | The Daily Grind`;
+      }
+
+      /**
+       * Apply stack visual state (root vs detail level)
+       */
+      function applyStackState(route, options = {}) {
+        const { resetScroll = true } = options;
+
+        // Clear any leftover inline gesture transforms
+        detailScreen.style.transform = '';
+        rootScreen.style.transform = '';
+        rootScreen.style.filter = '';
+        backdrop.style.opacity = '';
+        detailScreen.classList.remove('is-dragging');
+        rootScreen.classList.remove('is-dragging');
+        backdrop.classList.remove('is-dragging');
+
+        if (route.view === 'detail' && route.itemKey && SEASONAL_ITEMS[route.itemKey]) {
+          renderDetailView(route.itemKey);
+          detailScreen.classList.add('is-visible');
+          viewport.classList.add('has-detail');
+          viewport.setAttribute('data-stack-depth', '1');
+          detailScreen.setAttribute('aria-hidden', 'false');
+          rootScreen.setAttribute('aria-hidden', 'true');
+          if (resetScroll) {
+            detailScrollBody.scrollTop = 0;
+          }
+        } else {
+          activeItemKey = null;
+          viewport.classList.remove('has-detail');
+          viewport.setAttribute('data-stack-depth', '0');
+          detailScreen.setAttribute('aria-hidden', 'true');
+          rootScreen.setAttribute('aria-hidden', 'false');
+          document.title = 'The Daily Grind | Artisanal Coffee';
+        }
+      }
+
+      /**
+       * Navigate into a detail screen (push onto navigation stack & browser history)
+       */
+      function pushDetailScreen(itemSlug, options = {}) {
+        const resolvedKey = ALIAS_TO_KEY[(itemSlug || '').toLowerCase()];
+        if (!resolvedKey) return;
+
+        const item = SEASONAL_ITEMS[resolvedKey];
+        const currentRoute = resolveRouteFromLocation(window.location);
+
+        if (currentRoute.view === 'detail' && currentRoute.itemKey === resolvedKey) {
+          applyStackState({ view: 'detail', itemKey: resolvedKey }, { resetScroll: false });
+          return;
+        }
+
+        const statePayload = {
+          stackView: 'detail',
+          itemKey: resolvedKey,
+          fromInternalRoot: currentRoute.view === 'root' || hasInternalHistoryEntry
+        };
+
+        if (!options.skipHistory) {
+          try {
+            window.history.pushState(statePayload, '', item.canonicalPath);
+            hasInternalHistoryEntry = true;
+          } catch (err) {
+            window.location.hash = '#' + item.canonicalPath;
+          }
+        }
+
+        applyStackState({ view: 'detail', itemKey: resolvedKey }, { resetScroll: true });
+      }
+
+      /**
+       * Pop the current detail screen and return to the root homepage in sync with browser history.
+       * If the user landed directly via a deep link with no prior history entry in this session,
+       * we cleanly push/replace '/' so they always return to the root homepage stack level.
+       */
+      function popToRootScreen() {
+        const currentRoute = resolveRouteFromLocation(window.location);
+        if (currentRoute.view === 'root') return;
+
+        if (hasInternalHistoryEntry || (window.history.state && window.history.state.fromInternalRoot)) {
+          hasInternalHistoryEntry = false;
+          window.history.back();
+        } else {
+          try {
+            window.history.pushState({ stackView: 'root' }, '', '/');
+          } catch (err) {
+            window.location.hash = '';
+          }
+          applyStackState({ view: 'root', itemKey: null }, { resetScroll: false });
+        }
+      }
+
+      // Listen for Browser Back / Forward buttons (popstate) and hashchange
+      window.addEventListener('popstate', () => {
+        const route = resolveRouteFromLocation(window.location);
+        applyStackState(route, { resetScroll: false });
+      });
+
+      window.addEventListener('hashchange', () => {
+        const route = resolveRouteFromLocation(window.location);
+        applyStackState(route, { resetScroll: false });
+      });
+
+      // Delegated Click Handling for Drill-Down Cards, Links, and Back Navigation
+      document.addEventListener('click', (e) => {
+        // 1. Check for explicit drill link or card click
+        const drillLink = e.target.closest('[data-drill-link]');
+        if (drillLink) {
+          if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
+          e.preventDefault();
+          const slug = drillLink.getAttribute('data-drill-link');
+          pushDetailScreen(slug);
+          return;
+        }
+
+        const card = e.target.closest('.card[data-item-slug]');
+        if (card) {
+          e.preventDefault();
+          const slug = card.getAttribute('data-item-slug');
+          pushDetailScreen(slug);
+          return;
+        }
+
+        // 2. Check for root navigation links (Back button, Breadcrumb Home, Logo)
+        const rootNavTrigger = e.target.closest('[data-nav-root], #stackBackBtn');
+        if (rootNavTrigger) {
+          if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
+          e.preventDefault();
+          popToRootScreen();
+          return;
+        }
+
+        // 3. Smooth scroll to Seasonal Favorites when on root screen
+        const scrollSeasonal = e.target.closest('[data-scroll-seasonal]');
+        if (scrollSeasonal) {
+          e.preventDefault();
+          const targetSection = document.getElementById('seasonal-favorites');
+          if (targetSection) {
+            targetSection.scrollIntoView({ behavior: 'smooth' });
+          }
+        }
+      });
+
+      // Keyboard accessibility: Enter/Space on cards, Escape to pop detail view
+      document.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape' && viewport.classList.contains('has-detail')) {
+          e.preventDefault();
+          popToRootScreen();
+          return;
+        }
+
+        if (e.key === 'Enter' || e.key === ' ') {
+          const focusedCard = document.activeElement && document.activeElement.closest('.card[data-item-slug]');
+          if (focusedCard && document.activeElement === focusedCard) {
+            e.preventDefault();
+            pushDetailScreen(focusedCard.getAttribute('data-item-slug'));
+          }
+        }
+      });
+
+      // Clicking the dimmed backdrop also pops back to root
+      backdrop.addEventListener('click', () => {
+        if (viewport.classList.contains('has-detail')) {
+          popToRootScreen();
+        }
+      });
+
+      // Size Selector interactivity inside Detail View
+      sizeSelector.addEventListener('click', (e) => {
+        const option = e.target.closest('.size-option');
+        if (!option) return;
+        sizeSelector.querySelectorAll('.size-option').forEach((btn) => btn.classList.remove('active'));
+        option.classList.add('active');
+        selectedPriceDelta = parseFloat(option.getAttribute('data-price-delta') || '0');
+        updateOrderPriceDisplay();
+      });
+
+      // Add to Order Feedback Toast
+      addToOrderBtn.addEventListener('click', () => {
+        if (!activeItemKey) return;
+        const item = SEASONAL_ITEMS[activeItemKey];
+        const activeSizeBtn = sizeSelector.querySelector('.size-option.active');
+        const sizeLabel = activeSizeBtn ? activeSizeBtn.getAttribute('data-size') : 'Medium (16 oz)';
+        orderToast.textContent = `Added ${sizeLabel} ${item.title} (${orderBtnPrice.textContent}) to your active bag!`;
+        orderToast.classList.add('visible');
+      });
+
+      // Copy Deep Link button
+      copyDeepLinkBtn.addEventListener('click', () => {
+        const url = window.location.href;
+        if (navigator.clipboard && navigator.clipboard.writeText) {
+          navigator.clipboard.writeText(url).catch(() => {});
+        }
+        const origText = copyDeepLinkBtn.textContent;
+        copyDeepLinkBtn.textContent = 'Link Copied!';
+        setTimeout(() => {
+          copyDeepLinkBtn.textContent = origText;
+        }, 1600);
+      });
+
+      /**
+       * Interactive Swipe-Back Gesture Handler (Touch + Pointer/Mouse Drag)
+       * Users can swipe right from the left edge (or swipe horizontally across the detail screen)
+       * to interactively drag the detail view off the stack and return to the root screen.
+       */
+      let swipeState = {
+        active: false,
+        dragging: false,
+        startX: 0,
+        startY: 0,
+        currentX: 0,
+        startTime: 0,
+        startedFromEdge: false
+      };
+
+      function beginSwipeCandidate(clientX, clientY, isEdgeTarget) {
+        if (!viewport.classList.contains('has-detail')) return;
+        const edgeThreshold = 64; // px from left edge for anywhere start, or explicit edge zone
+        swipeState.active = true;
+        swipeState.dragging = false;
+        swipeState.startX = clientX;
+        swipeState.startY = clientY;
+        swipeState.currentX = clientX;
+        swipeState.startTime = performance.now();
+        swipeState.startedFromEdge = isEdgeTarget || clientX <= edgeThreshold;
+      }
+
+      function updateSwipeMove(clientX, clientY, eventToPrevent) {
+        if (!swipeState.active) return;
+
+        const deltaX = clientX - swipeState.startX;
+        const deltaY = clientY - swipeState.startY;
+
+        if (!swipeState.dragging) {
+          // Determine if horizontal right-swipe intent is stronger than vertical scroll
+          if (deltaX < 8) return;
+          if (Math.abs(deltaY) > Math.abs(deltaX) * 0.85) {
+            // User is scrolling vertically; cancel swipe candidate
+            swipeState.active = false;
+            return;
+          }
+          // Allow full-screen horizontal swipe on touch or edge-initiated drag on mouse
+          swipeState.dragging = true;
+          detailScreen.classList.add('is-dragging');
+          rootScreen.classList.add('is-dragging');
+          backdrop.classList.add('is-dragging');
+        }
+
+        if (swipeState.dragging) {
+          if (eventToPrevent && eventToPrevent.cancelable) {
+            eventToPrevent.preventDefault();
+          }
+          swipeState.currentX = Math.max(0, deltaX);
+          const width = window.innerWidth || 1;
+          const progress = Math.min(1, swipeState.currentX / width);
+
+          // Live interactive stack parallax transforms
+          detailScreen.style.transform = `translate3d(${swipeState.currentX}px, 0, 0)`;
+          const rootOffset = -26 * (1 - progress);
+          const rootScale = 0.96 + 0.04 * progress;
+          const rootBrightness = 0.72 + 0.28 * progress;
+          rootScreen.style.transform = `translate3d(${rootOffset}%, 0, 0) scale(${rootScale})`;
+          rootScreen.style.filter = `brightness(${rootBrightness})`;
+          backdrop.style.opacity = String(1 - progress);
+        }
+      }
+
+      function endSwipeGesture() {
+        if (!swipeState.active) return;
+        const wasDragging = swipeState.dragging;
+        const deltaX = swipeState.currentX - swipeState.startX;
+        const elapsed = Math.max(1, performance.now() - swipeState.startTime);
+        const velocity = deltaX / elapsed; // px per ms
+
+        swipeState.active = false;
+        swipeState.dragging = false;
+
+        if (!wasDragging) return;
+
+        detailScreen.classList.remove('is-dragging');
+        rootScreen.classList.remove('is-dragging');
+        backdrop.classList.remove('is-dragging');
+
+        const width = window.innerWidth || 360;
+        const shouldPop = deltaX > width * 0.24 || (deltaX > 45 && velocity > 0.45);
+
+        if (shouldPop) {
+          popToRootScreen();
+        } else {
+          // Snap back to open detail state
+          detailScreen.style.transform = '';
+          rootScreen.style.transform = '';
+          rootScreen.style.filter = '';
+          backdrop.style.opacity = '';
+        }
+      }
+
+      // Touch Listeners on Detail Screen (supports both left-edge and horizontal right-swipe)
+      detailScreen.addEventListener(
+        'touchstart',
+        (e) => {
+          if (e.touches.length !== 1) return;
+          const touch = e.touches[0];
+          const isEdge = Boolean(e.target.closest('#edgeSwipeZone'));
+          beginSwipeCandidate(touch.clientX, touch.clientY, isEdge);
+        },
+        { passive: true }
+      );
+
+      detailScreen.addEventListener(
+        'touchmove',
+        (e) => {
+          if (!swipeState.active || e.touches.length !== 1) return;
+          const touch = e.touches[0];
+          updateSwipeMove(touch.clientX, touch.clientY, e);
+        },
+        { passive: false }
+      );
+
+      detailScreen.addEventListener('touchend', endSwipeGesture);
+      detailScreen.addEventListener('touchcancel', endSwipeGesture);
+
+      // Pointer / Mouse Drag Listeners for desktop swipe-back from left edge or header/hero
+      detailScreen.addEventListener('mousedown', (e) => {
+        if (e.button !== 0) return;
+        const isEdge = Boolean(e.target.closest('#edgeSwipeZone'));
+        if (!isEdge && e.clientX > 48) return;
+        beginSwipeCandidate(e.clientX, e.clientY, isEdge);
+      });
+
+      window.addEventListener('mousemove', (e) => {
+        if (!swipeState.active) return;
+        updateSwipeMove(e.clientX, e.clientY, e);
+      });
+
+      window.addEventListener('mouseup', endSwipeGesture);
+
+      // Initialize Router on Page Load (handles direct deep links and initial history state)
+      const initialRoute = resolveRouteFromLocation(window.location);
+      try {
+        window.history.replaceState(
+          {
+            stackView: initialRoute.view,
+            itemKey: initialRoute.itemKey,
+            fromInternalRoot: false
+          },
+          '',
+          window.location.pathname + window.location.search + window.location.hash
+        );
+      } catch (err) {
+        // Ignore history.replaceState restrictions in sandboxed environments
+      }
+      applyStackState(initialRoute, { resetScroll: true });
+    })();
+  </script>
+</body>
+
+</html>

