+    (function () {
+      const dateInput = document.getElementById('calendar-date-input');
+
+      function resolveIslamicCalendarId() {
+        const candidates = ['islamic-umalqura', 'islamic-civil', 'islamic-tbla', 'islamic'];
+        if (typeof Temporal !== 'undefined' && Temporal.PlainDate) {
+          for (const cal of candidates) {
+            try {
+              Temporal.PlainDate.from('2026-01-01').withCalendar(cal);
+              return cal;
+            } catch (_) {
+              // try next candidate
+            }
+          }
+        }
+        return 'islamic-umalqura';
+      }
+
+      const islamicCalId = resolveIslamicCalendarId();
+
+      const calendars = [
+        { key: 'islamic', id: islamicCalId, name: 'Islamic Calendar' },
+        { key: 'hebrew', id: 'hebrew', name: 'Hebrew Calendar' },
+        { key: 'japanese', id: 'japanese', name: 'Japanese Calendar' }
+      ];
+
+      function getTodayISO() {
+        if (typeof Temporal !== 'undefined' && Temporal.Now) {
+          return Temporal.Now.plainDateISO().toString();
+        }
+        const now = new Date();
+        const y = now.getFullYear();
+        const m = String(now.getMonth() + 1).padStart(2, '0');
+        const d = String(now.getDate()).padStart(2, '0');
+        return `${y}-${m}-${d}`;
+      }
+
+      function getTemporalStatus(selectedISO, todayISO) {
+        if (typeof Temporal !== 'undefined' && Temporal.PlainDate) {
+          const cmp = Temporal.PlainDate.compare(
+            Temporal.PlainDate.from(selectedISO),
+            Temporal.PlainDate.from(todayISO)
+          );
+          if (cmp < 0) return 'Past';
+          if (cmp > 0) return 'Future';
+          return 'Today';
+        }
+        if (selectedISO < todayISO) return 'Past';
+        if (selectedISO > todayISO) return 'Future';
+        return 'Today';
+      }
+
+      function computeCalendarDetails(isoDateStr, calId) {
+        if (typeof Temporal !== 'undefined' && Temporal.PlainDate) {
+          const plainDate = Temporal.PlainDate.from(isoDateStr);
+          const calDate = plainDate.withCalendar(calId);
+
+          const localizedDate = calDate.toLocaleString('en-US', {
+            calendar: calId,
+            year: 'numeric',
+            month: 'long',
+            day: 'numeric'
+          });
+
+          const year = calDate.year;
+          const month = calDate.month;
+          const monthCode = calDate.monthCode;
+          const monthsInYear = calDate.monthsInYear;
+
+          const monthsBreakdown = [];
+          for (let m = 1; m <= monthsInYear; m++) {
+            const mDate = calDate.with({ month: m, day: 1 });
+            const mName = mDate.toLocaleString('en-US', {
+              calendar: calId,
+              month: 'short'
+            });
+            monthsBreakdown.push({
+              month: m,
+              monthCode: mDate.monthCode,
+              days: mDate.daysInMonth,
+              monthName: mName
+            });
+          }
+
+          return {
+            localizedDate,
