+            month,
+            monthCode,
+            monthsInYear,
+            monthsBreakdown
+          };
+        }
+
+        // Fallback if Temporal is unavailable
+        const [gY, gM, gD] = isoDateStr.split('-').map(Number);
+        const utcDate = new Date(Date.UTC(gY, gM - 1, gD, 12, 0, 0));
+        const localizedDate = new Intl.DateTimeFormat('en-US', {
+          calendar: calId,
+          year: 'numeric',
+          month: 'long',
+          day: 'numeric',
+          timeZone: 'UTC'
