+
+        const parts = new Intl.DateTimeFormat('en-US-u-nu-latn', {
+          calendar: calId,
+          year: 'numeric',
+          month: 'numeric',
+          day: 'numeric',
+          timeZone: 'UTC'
+        }).formatToParts(utcDate);
+
+        const relYearPart = parts.find(p => p.type === 'relatedYear' || p.type === 'year');
+        const monthPart = parts.find(p => p.type === 'month');
+        const year = relYearPart ? parseInt(relYearPart.value, 10) : gY;
+        const month = monthPart ? parseInt(monthPart.value, 10) : gM;
+        const monthCode = `M${String(month).padStart(2, '0')}`;
+
+        return {
+          localizedDate,
+          year,
+          month,
+          monthCode,
+          monthsInYear: 12,
+          monthsBreakdown: Array.from({ length: 12 }, (_, idx) => ({
+            month: idx + 1,
+            monthCode: `M${String(idx + 1).padStart(2, '0')}`,
+            days: 30,
+            monthName: `M${idx + 1}`
+          }))
+        };
+      }
+
+      function renderCalendarCards(isoDateStr) {
+        if (!isoDateStr) return;
+        const todayISO = getTodayISO();
+        const status = getTemporalStatus(isoDateStr, todayISO);
+
+        for (const cal of calendars) {
+          const details = computeCalendarDetails(isoDateStr, cal.id);
+
+          const statusEl = document.getElementById(`${cal.key}-status`);
+          if (statusEl) {
+            statusEl.textContent = status;
+            statusEl.className = `temporal-badge badge-${status.toLowerCase()}`;
+          }
+
+          const dateEl = document.getElementById(`${cal.key}-date`);
+          if (dateEl) {
+            dateEl.textContent = details.localizedDate;
+          }
+
+          const yearEl = document.getElementById(`${cal.key}-year`);
+          if (yearEl) {
+            yearEl.textContent = String(details.year);
+          }
+
+          const monthEl = document.getElementById(`${cal.key}-month`);
+          if (monthEl) {
+            monthEl.textContent = String(details.month);
+          }
+
+          const monthCodeEl = document.getElementById(`${cal.key}-month-code`);
+          if (monthCodeEl) {
+            monthCodeEl.textContent = details.monthCode;
+          }
+
+          const monthsInYearEl = document.getElementById(`${cal.key}-months-in-year`);
+          if (monthsInYearEl) {
+            monthsInYearEl.textContent = String(details.monthsInYear);
+          }
+
+          const breakdownEl = document.getElementById(`${cal.key}-months-breakdown`);
+          if (breakdownEl) {
+            breakdownEl.innerHTML = '';
+            for (const item of details.monthsBreakdown) {
