+              li.className = 'month-item' + (item.monthCode === details.monthCode ? ' active-month' : '');
+              li.setAttribute('data-month-code', item.monthCode);
+              li.setAttribute('data-days', String(item.days));
+              li.innerHTML = `<span class="month-code">${item.monthCode} (${item.monthName})</span><span class="month-days">${item.days} days</span>`;
+              breakdownEl.appendChild(li);
+            }
+          }
+        }
+      }
+
+      const initialDate = getTodayISO();
+      if (dateInput) {
