+    (function () {
+      const menuSection = document.getElementById('coffee-menu');
+      if (!menuSection) return;
+
+      const tabWrapper = document.getElementById('coffee-tab-wrapper');
+      const tabList = document.getElementById('coffee-tablist');
+      const tabs = Array.from(tabList.querySelectorAll('[role="tab"]'));
+      const panels = Array.from(menuSection.querySelectorAll('[role="tabpanel"]'));
+      const prevBtn = document.getElementById('tab-scroll-prev');
+      const nextBtn = document.getElementById('tab-scroll-next');
+
+      function updateScrollAffordances() {
+        if (!tabList || !tabWrapper) return;
+        const maxScrollLeft = tabList.scrollWidth - tabList.clientWidth;
+        const currentScroll = Math.round(tabList.scrollLeft);
+        const canScrollLeft = currentScroll > 4;
+        const canScrollRight = maxScrollLeft - currentScroll > 4;
+
+        tabWrapper.classList.toggle('can-scroll-left', canScrollLeft);
+        tabWrapper.classList.toggle('can-scroll-right', canScrollRight);
+
+        if (prevBtn) prevBtn.disabled = !canScrollLeft;
+        if (nextBtn) nextBtn.disabled = !canScrollRight;
+      }
+
+      function scrollTabIntoCenter(tab) {
+        if (!tabList || !tab) return;
+        const tabRect = tab.getBoundingClientRect();
+        const listRect = tabList.getBoundingClientRect();
+        const tabCenter = tabRect.left + tabRect.width / 2;
+        const listCenter = listRect.left + listRect.width / 2;
+        const delta = tabCenter - listCenter;
+
+        if (Math.abs(delta) > 4) {
+          tabList.scrollBy({
+            left: delta,
+            behavior: 'smooth'
+          });
+        }
+      }
+
+      function activateTab(selectedTab, options = {}) {
+        const { focusTab = false, scrollIntoView = true } = options;
+        const targetPanelId = selectedTab.getAttribute('aria-controls');
+
+        tabs.forEach((tab) => {
+          const isSelected = tab === selectedTab;
+          tab.setAttribute('aria-selected', isSelected ? 'true' : 'false');
+          tab.setAttribute('tabindex', isSelected ? '0' : '-1');
+          tab.classList.toggle('active', isSelected);
+        });
+
+        panels.forEach((panel) => {
+          const isMatch = panel.id === targetPanelId;
+          panel.classList.toggle('is-active', isMatch);
+          if (isMatch) {
+            panel.removeAttribute('hidden');
+          } else {
+            panel.setAttribute('hidden', '');
+          }
+        });
+
+        if (focusTab) {
+          selectedTab.focus({ preventScroll: true });
+        }
+
+        if (scrollIntoView) {
+          scrollTabIntoCenter(selectedTab);
+        }
+      }
+
+      tabs.forEach((tab, index) => {
+        tab.addEventListener('click', () => {
+          activateTab(tab, { focusTab: false, scrollIntoView: true });
+        });
+
+        tab.addEventListener('keydown', (event) => {
+          let nextIndex = null;
+          if (event.key === 'ArrowRight') {
+            nextIndex = (index + 1) % tabs.length;
+          } else if (event.key === 'ArrowLeft') {
+            nextIndex = (index - 1 + tabs.length) % tabs.length;
+          } else if (event.key === 'Home') {
+            nextIndex = 0;
+          } else if (event.key === 'End') {
+            nextIndex = tabs.length - 1;
+          }
+
+          if (nextIndex !== null) {
+            event.preventDefault();
+            activateTab(tabs[nextIndex], { focusTab: true, scrollIntoView: true });
+          }
+        });
+      });
+
+      if (prevBtn) {
+        prevBtn.addEventListener('click', () => {
+          const step = Math.max(tabList.clientWidth * 0.65, 160);
+          tabList.scrollBy({ left: -step, behavior: 'smooth' });
