+  <script type="module">
+    const menuSection = document.getElementById('coffee-menu');
+    const tablist = menuSection.querySelector('[focusgroup~="tablist"]');
+    const tabs = Array.from(tablist.querySelectorAll('button'));
+    const panels = Array.from(menuSection.querySelectorAll('[role="tabpanel"]'));
+
+    function selectTab(selected) {
+      if (!selected) return;
+
+      for (const tab of tabs) {
+        const isSelected = tab === selected;
+        tab.ariaSelected = String(isSelected);
+        tab.toggleAttribute('focusgroupstart', isSelected);
+      }
+
+      for (const panel of panels) {
+        const isSelected = panel.getAttribute('aria-labelledby') === selected.id;
+        if (isSelected) {
+          panel.hidden = false;
+          panel.setAttribute('tabindex', '0');
+        } else {
+          panel.hidden = 'until-found';
+          panel.removeAttribute('tabindex');
+        }
+      }
+
+      selected.scrollIntoView({
+        block: 'nearest',
+        inline: 'nearest',
+        container: 'nearest'
+      });
+    }
+
+    // Selection follows focus (and pointer activation)
+    for (const tab of tabs) {
+      tab.addEventListener('focus', () => selectTab(tab));
+      tab.addEventListener('click', () => selectTab(tab));
+    }
+
+    // Sync tab & panel selection when find-in-page reveals a hidden="until-found" panel
+    menuSection.addEventListener('beforematch', (event) => {
+      const matchedPanel = event.target.closest('[role="tabpanel"]');
+      if (!matchedPanel) return;
+      const associatedTab = document.getElementById(matchedPanel.getAttribute('aria-labelledby'));
+      if (associatedTab) {
+        selectTab(associatedTab);
+      }
+    });
+
+    // Fallback for scroll-driven animation edge fades
+    if (!CSS.supports('animation-timeline', 'scroll()')) {
+      for (const scroller of document.querySelectorAll('.scroller')) {
+        const [first, last] = [scroller.firstElementChild, scroller.lastElementChild];
+        const observer = new IntersectionObserver(entries => {
+          for (const { target, intersectionRatio } of entries) {
+            scroller.classList.toggle(target === first ? 'more-start' : 'more-end', intersectionRatio < 1);
+          }
+        }, { root: scroller, threshold: 1, rootMargin: '1px' });
+
+        if (first) observer.observe(first);
+        if (last) observer.observe(last);
+      }
+    }
+
+    // Load focusgroup polyfill only when native support is missing
+    if (!(Object.hasOwn(HTMLElement.prototype, 'focusGroup'))) {
+      try {
+        const { polyfill } = await import('@microsoft/focusgroup-polyfill');
+        polyfill();
+      } catch {
+        // Ignore if offline or polyfill cannot be fetched
+      }
+    }
+  </script>
