+
+    if (rootRef.current) {
+      const closestScope = rootRef.current.closest<HTMLElement>('[data-translatable-scope]');
+      if (closestScope) {
+        const innerTargets = Array.from(
+          closestScope.querySelectorAll<HTMLElement>('[data-translatable]')
+        );
+        return innerTargets.length > 0 ? innerTargets : [closestScope];
+      }
+    }
+
+    return Array.from(
+      document.querySelectorAll<HTMLElement>('[data-translatable]')
+    );
+  };
+
+  const handleTranslate = async () => {
+    if (!apiSupported) return;
+    if (sourceLanguage === targetLanguage) {
+      handleRestore();
+      return;
+    }
+
+    abortControllerRef.current?.abort();
+    const controller = new AbortController();
+    abortControllerRef.current = controller;
+
+    setErrorMessage(null);
+    setDownloadProgress(null);
+    setTranslatedCount(null);
+
+    try {
+      setStatus(availability === 'downloadable' || availability === 'downloading' ? 'downloading' : 'translating');
+
+      const translator = await createTranslatorWithProgress(
+        sourceLanguage,
+        targetLanguage,
+        (percent) => {
+          setStatus('downloading');
+          setDownloadProgress(percent);
+        },
+        controller.signal
+      );
+
+      setStatus('translating');
+      setDownloadProgress(null);
+
+      const elements = getTargetElements();
+      if (elements.length === 0) {
+        translator.destroy();
+        setStatus('idle');
+        return;
+      }
+
+      setTranslatedCount({ current: 0, total: elements.length });
+
+      for (let i = 0; i < elements.length; i++) {
+        if (controller.signal.aborted) break;
+        await translateElementContent(elements[i], translator, targetLanguage, controller.signal);
+        setTranslatedCount({ current: i + 1, total: elements.length });
+      }
+
+      translator.destroy();
+      setActiveLang(targetLanguage);
+      setStatus('translated');
+      setAvailability('available');
+    } catch (err: any) {
+      if (err?.name === 'AbortError') {
+        setStatus('idle');
+        return;
+      }
+      setStatus('error');
+      setErrorMessage(
+        err?.message || 'Unable to translate content using the on-device Translator API.'
+      );
+    }
+  };
+
+  const handleRestore = () => {
+    abortControllerRef.current?.abort();
+    const elements = getTargetElements();
+    for (const el of elements) {
+      restoreElementContent(el);
+    }
+    setActiveLang(null);
+    setStatus('idle');
+    setErrorMessage(null);
+    setDownloadProgress(null);
+    setTranslatedCount(null);
+  };
+
+  const handleSwapLanguages = () => {
+    setSourceLanguage(targetLanguage);
+    setTargetLanguage(sourceLanguage);
+  };
+
+  const isUnavailable = apiSupported === false || availability === 'unavailable';
+  const isBusy = status === 'downloading' || status === 'translating';
+
+  if (compact && !isExpanded) {
+    return (
+      <div ref={rootRef} data-no-translate="true" translate="no" className="inline-flex items-center">
+        <button
+          type="button"
+          onClick={() => setIsExpanded(true)}
+          className="inline-flex items-center gap-1.5 text-xs font-medium text-gray-600 hover:text-amber-700 bg-gray-50 hover:bg-amber-50 border border-gray-200 rounded px-2 py-1 transition-colors"
+          title="Translate on device"
+        >
+          <LanguageIcon className="w-3.5 h-3.5 text-amber-700" />
+          <span>{activeLang ? `Translated (${activeLang.toUpperCase()})` : 'Translate'}</span>
+        </button>
+      </div>
+    );
+  }
+
+  return (
+    <div
+      ref={rootRef}
+      data-no-translate="true"
+      translate="no"
+      className={`${
+        compact
+          ? 'bg-gray-50 border border-gray-200 rounded-md p-2.5 text-xs my-2'
+          : 'bg-amber-50/40 border border-amber-200/80 rounded-lg p-3.5 text-sm my-3'
+      }`}
+    >
+      <div className="flex flex-wrap items-center justify-between gap-2">
+        <div className="flex items-center gap-1.5 font-semibold text-gray-800">
+          <LanguageIcon className="w-4 h-4 text-amber-700 flex-shrink-0" />
+          <span>{label}</span>
+          {availability === 'downloadable' && apiSupported && (
+            <span className="text-[11px] font-normal bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded">
+              Model download required
+            </span>
+          )}
+          {availability === 'available' && apiSupported && status !== 'translated' && (
+            <span className="text-[11px] font-normal bg-green-100 text-green-800 px-1.5 py-0.5 rounded">
+              Ready on-device
+            </span>
+          )}
+          {status === 'translated' && activeLang && (
+            <span className="inline-flex items-center gap-1 text-[11px] font-normal bg-green-100 text-green-800 px-1.5 py-0.5 rounded">
+              <CheckCircleIcon className="w-3.5 h-3.5" />
+              Translated to {SUPPORTED_LANGUAGES.find((l) => l.code === activeLang)?.name || activeLang}
+            </span>
+          )}
+        </div>
+
+        <div className="flex flex-wrap items-center gap-2">
+          <label className="flex items-center gap-1 text-gray-600">
+            <span className="sr-only sm:not-sr-only text-xs">From</span>
+            <select
+              aria-label="Source language"
+              value={sourceLanguage}
+              onChange={(e) => setSourceLanguage(e.target.value)}
+              disabled={!apiSupported || isBusy}
+              className="bg-white border border-gray-300 text-gray-800 rounded px-2 py-1 text-xs focus:ring-2 focus:ring-amber-400 focus:outline-none disabled:opacity-50"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={`src-${lang.code}`} value={lang.code}>
+                  {lang.name}
+                </option>
+              ))}
+            </select>
+          </label>
+
+          <button
+            type="button"
+            onClick={handleSwapLanguages}
+            disabled={!apiSupported || isBusy}
+            title="Swap languages"
+            aria-label="Swap source and target languages"
+            className="p-1 text-gray-500 hover:text-gray-800 disabled:opacity-40 rounded hover:bg-gray-200/60 transition-colors"
+          >
+            ⇄
+          </button>
+
+          <label className="flex items-center gap-1 text-gray-600">
+            <span className="sr-only sm:not-sr-only text-xs">To</span>
+            <select
+              aria-label="Target language"
+              value={targetLanguage}
+              onChange={(e) => setTargetLanguage(e.target.value)}
+              disabled={!apiSupported || isBusy}
+              className="bg-white border border-gray-300 text-gray-800 rounded px-2 py-1 text-xs focus:ring-2 focus:ring-amber-400 focus:outline-none disabled:opacity-50"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={`tgt-${lang.code}`} value={lang.code}>
+                  {lang.name}
+                </option>
+              ))}
+            </select>
+          </label>
+
+          <button
+            type="button"
+            onClick={handleTranslate}
+            disabled={isUnavailable || isBusy || sourceLanguage === targetLanguage}
+            className="inline-flex items-center gap-1.5 bg-gray-900 hover:bg-amber-700 text-white font-semibold text-xs px-3 py-1.5 rounded transition-colors disabled:opacity-40 disabled:pointer-events-none cursor-pointer"
+          >
+            {isBusy && <ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />}
+            <span>
+              {status === 'downloading'
+                ? `Downloading${downloadProgress !== null ? ` ${downloadProgress}%` : '...'}`
+                : status === 'translating'
+                ? translatedCount && translatedCount.total > 1
+                  ? `Translating (${translatedCount.current}/${translatedCount.total})...`
+                  : 'Translating...'
+                : 'Translate'}
+            </span>
+          </button>
+
+          {activeLang && (
+            <button
+              type="button"
+              onClick={handleRestore}
+              className="text-xs font-medium text-gray-700 hover:text-gray-900 underline px-1.5 py-1 cursor-pointer"
+            >
+              Show original
+            </button>
+          )}
+
+          {compact && (
+            <button
+              type="button"
+              onClick={() => setIsExpanded(false)}
+              aria-label="Collapse translation controls"
+              className="text-xs text-gray-400 hover:text-gray-700 px-1"
+            >
+              ✕
+            </button>
+          )}
+        </div>
+      </div>
+
+      {status === 'downloading' && downloadProgress !== null && (
+        <div className="mt-2">
+          <div className="w-full bg-gray-200 rounded-full h-1.5 overflow-hidden">
+            <div
+              className="bg-amber-600 h-1.5 transition-all duration-200"
+              style={{ width: `${Math.max(5, downloadProgress)}%` }}
+            />
+          </div>
+          <p className="text-[11px] text-gray-600 mt-1">
+            Downloading on-device language pack ({downloadProgress}%)...
+          </p>
+        </div>
+      )}
+
+      {apiSupported === false && (
+        <p className="mt-2 flex items-center gap-1.5 text-xs text-amber-800 bg-amber-100/70 px-2.5 py-1.5 rounded">
+          <ExclamationTriangleIcon className="w-4 h-4 flex-shrink-0 text-amber-700" />
+          <span>
+            Client-side translation is currently unsupported in this browser. Use Chrome 138+ or Edge 148+ on desktop for built-in on-device AI translation.
+          </span>
+        </p>
+      )}
+
+      {apiSupported === true && availability === 'unavailable' && sourceLanguage !== targetLanguage && (
+        <p className="mt-2 flex items-center gap-1.5 text-xs text-amber-800 bg-amber-100/70 px-2.5 py-1.5 rounded">
+          <ExclamationTriangleIcon className="w-4 h-4 flex-shrink-0 text-amber-700" />
+          <span>
+            This language pair ({sourceLanguage.toUpperCase()} → {targetLanguage.toUpperCase()}) is unavailable for on-device translation on this device.
+          </span>
+        </p>
+      )}
+
+      {status === 'error' && errorMessage && (
+        <p className="mt-2 flex items-center gap-1.5 text-xs text-red-700 bg-red-50 px-2.5 py-1.5 rounded">
+          <ExclamationTriangleIcon className="w-4 h-4 flex-shrink-0 text-red-600" />
+          <span>{errorMessage}</span>
+        </p>
+      )}
+    </div>
+  );
+}
