+  { code: 'el', name: 'Greek (Ελληνικά)' },
+  { code: 'cs', name: 'Czech (Čeština)' },
+  { code: 'ro', name: 'Romanian (Română)' },
+  { code: 'hu', name: 'Hungarian (Magyar)' },
+  { code: 'uk', name: 'Ukrainian (Українська)' },
+  { code: 'th', name: 'Thai (ไทย)' },
+  { code: 'he', name: 'Hebrew (עברית)' },
+  { code: 'bn', name: 'Bengali (বাংলা)' },
+];
+
+export function isTranslatorSupported(): boolean {
+  return typeof self !== 'undefined' && 'Translator' in self && Boolean(self.Translator);
+}
+
+export async function checkLanguagePairAvailability(
+  sourceLanguage: string,
+  targetLanguage: string
+): Promise<TranslatorAvailability> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    return 'unavailable';
+  }
+  if (sourceLanguage === targetLanguage) {
+    return 'available';
+  }
+  const options: TranslatorCreateCoreOptions = {
+    sourceLanguage,
+    targetLanguage,
+  };
+  try {
+    return await self.Translator.availability(options);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+export async function createTranslatorWithProgress(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onProgress?: (percent: number) => void,
+  signal?: AbortSignal
+): Promise<TranslatorInstance> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    throw new Error('Client-side Translator API is not supported in this browser.');
+  }
+
+  const options: TranslatorCreateCoreOptions = {
+    sourceLanguage,
+    targetLanguage,
+  };
+
+  const availability = await self.Translator.availability(options);
+  if (availability === 'unavailable') {
+    throw new Error(`Translation model for ${sourceLanguage} → ${targetLanguage} is unavailable on this device.`);
+  }
+
+  return await self.Translator.create({
+    ...options,
+    signal,
+    monitor(m) {
+      m.addEventListener('downloadprogress', (e) => {
+        if (onProgress) {
+          onProgress(Math.round(e.loaded * 100));
+        }
+      });
+    },
+  });
+}
+
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'NOSCRIPT', 'SVG', 'IFRAME']);
+
+/**
+ * Collects translatable text nodes inside a container element.
+ */
+export function getTranslatableTextNodes(root: HTMLElement): Text[] {
+  const nodes: Text[] = [];
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const text = node.nodeValue?.trim();
+      if (!text) return NodeFilter.FILTER_REJECT;
+      let parent = node.parentElement;
+      while (parent && parent !== root) {
+        if (
+          SKIP_TAGS.has(parent.tagName) ||
+          parent.hasAttribute('data-no-translate') ||
+          parent.getAttribute('translate') === 'no'
+        ) {
+          return NodeFilter.FILTER_REJECT;
+        }
+        parent = parent.parentElement;
+      }
+      if (
+        root.hasAttribute('data-no-translate') ||
+        root.getAttribute('translate') === 'no'
+      ) {
+        return NodeFilter.FILTER_REJECT;
+      }
+      return NodeFilter.FILTER_ACCEPT;
+    },
+  });
+
+  let current = walker.nextNode();
+  while (current) {
+    nodes.push(current as Text);
+    current = walker.nextNode();
+  }
+  return nodes;
+}
+
+const originalTextStore = new WeakMap<Text, string>();
+const originalLangStore = new WeakMap<HTMLElement, string | null>();
+
+/**
+ * Translates all text nodes inside the given HTML element while preserving original text
+ * so it can be restored or re-translated from the original source text.
+ */
+export async function translateElementContent(
+  element: HTMLElement,
+  translator: TranslatorInstance,
+  targetLanguage: string,
+  signal?: AbortSignal
+): Promise<void> {
+  if (!originalLangStore.has(element)) {
+    originalLangStore.set(element, element.getAttribute('lang'));
+  }
+
+  const textNodes = getTranslatableTextNodes(element);
+  for (const node of textNodes) {
+    if (signal?.aborted) {
+      throw new DOMException('Translation aborted', 'AbortError');
+    }
+    if (!originalTextStore.has(node)) {
+      originalTextStore.set(node, node.nodeValue || '');
+    }
+    const sourceText = originalTextStore.get(node) || '';
+    const trimmed = sourceText.trim();
+    if (!trimmed) continue;
+
+    const leadingWhitespace = sourceText.match(/^\s*/)?.[0] ?? '';
+    const trailingWhitespace = sourceText.match(/\s*$/)?.[0] ?? '';
+
+    const translated = await translator.translate(trimmed, { signal });
+    node.nodeValue = `${leadingWhitespace}${translated}${trailingWhitespace}`;
+  }
+
+  // Mandatory accessibility requirement: apply the lang attribute matching the target BCP 47 language code
+  element.setAttribute('lang', targetLanguage);
+}
+
+/**
+ * Restores an element's original text nodes and lang attribute.
+ */
+export function restoreElementContent(element: HTMLElement): void {
+  const textNodes = getTranslatableTextNodes(element);
+  for (const node of textNodes) {
+    const original = originalTextStore.get(node);
+    if (original !== undefined) {
+      node.nodeValue = original;
+    }
+  }
+  if (originalLangStore.has(element)) {
+    const origLang = originalLangStore.get(element);
+    if (origLang === null || origLang === undefined) {
+      element.removeAttribute('lang');
+    } else {
+      element.setAttribute('lang', origLang);
+    }
+  } else {
+    element.setAttribute('lang', 'en');
+  }
+}

