+              >
+                Reset to Original
+              </button>
+            </div>
+          )}
+
+          {state.error && (
+            <div
+              role="alert"
+              data-testid="translation-error"
+              className="text-red-700 bg-red-50 border border-red-200 rounded px-3 py-1.5"
+            >
+              {state.error}
+            </div>
+          )}
+        </div>
+      )}
+    </section>
+  );
+}
