index 0000000..d11bc9d
--- /dev/null
+++ b/src/components/HeaderTranslationControl.tsx
@@ -0,0 +1,205 @@
+import React, { useState, useEffect } from "react";
+import {
+  SUPPORTED_LANGUAGES,
+  getLanguageShortName,
+  checkTranslationAvailability,
+  getGlobalTranslationState,
+  subscribeTranslationState,
+  setTranslationLanguages,
+  swapTranslationLanguages,
+  translatePageContent,
+  restorePageContent,
+  cancelActiveTranslation,
+  type AvailabilityInfo,
+  type GlobalTranslationState,
+} from "../utils/translator";
+
+export default function HeaderTranslationControl() {
+  const [state, setState] = useState<GlobalTranslationState>(() =>
+    getGlobalTranslationState()
+  );
+  const [availability, setAvailability] = useState<AvailabilityInfo>({
+    status: "available",
+    isNativeSupported: true,
+    message: "Ready",
+  });
+
+  useEffect(() => {
+    const unsubscribe = subscribeTranslationState((nextState) => {
+      setState(nextState);
+    });
+    return unsubscribe;
+  }, []);
+
+  useEffect(() => {
+    let cancelled = false;
+    checkTranslationAvailability(state.sourceLanguage, state.targetLanguage).then(
+      (info) => {
+        if (!cancelled) {
+          setAvailability(info);
+        }
+      }
+    );
+    return () => {
+      cancelled = true;
+    };
+  }, [state.sourceLanguage, state.targetLanguage]);
+
+  const handleSourceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
+    setTranslationLanguages(e.target.value, state.targetLanguage);
+  };
+
+  const handleTargetChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
+    setTranslationLanguages(state.sourceLanguage, e.target.value);
+  };
+
+  const handleTranslate = async () => {
+    await translatePageContent({
+      sourceLanguage: state.sourceLanguage,
+      targetLanguage: state.targetLanguage,
+      scope: "all",
+    });
+  };
+
+  const handleRestore = () => {
+    restorePageContent("all");
+  };
+
+  const hasTranslatedTeasers =
+    Object.keys(state.translatedTeasers).length > 0 || Boolean(state.activeLanguage);
+
+  return (
+    <div
+      role="region"
+      aria-label="On-device page and teaser translation"
+      data-testid="header-translation-control"
+      className="flex flex-wrap items-center gap-1.5 bg-gray-50 border border-gray-200 rounded-md px-2.5 py-1 text-xs"
+    >
+      {/* Icon & Label */}
+      <span
+        className="inline-flex items-center font-semibold text-gray-700 mr-1"
+        title={availability.message}
+      >
+        <svg
+          xmlns="http://www.w3.org/2000/svg"
+          fill="none"
+          viewBox="0 0 24 24"
+          strokeWidth={1.8}
+          stroke="currentColor"
+          className="w-4 h-4 text-amber-700 mr-1"
+        >
+          <path
+            strokeLinecap="round"
+            strokeLinejoin="round"
+            d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+          />
+        </svg>
+        <span className="hidden sm:inline">Translate:</span>
+      </span>
+
+      {/* Source Language */}
+      <select
+        aria-label="Translate from language"
+        data-testid="header-source-language"
+        value={state.sourceLanguage}
+        onChange={handleSourceChange}
+        disabled={state.isTranslating}
+        className="bg-white border border-gray-300 rounded px-1.5 py-0.5 text-xs text-gray-800 focus:outline-none focus:ring-1 focus:ring-amber-400"
+      >
+        <option value="auto">Auto-detect</option>
+        {SUPPORTED_LANGUAGES.map((lang) => (
+          <option key={lang.code} value={lang.code}>
+            {lang.name} ({lang.code.toUpperCase()})
+          </option>
+        ))}
+      </select>
+
+      {/* Swap */}
+      <button
+        type="button"
+        onClick={swapTranslationLanguages}
+        disabled={state.isTranslating}
+        aria-label="Swap translation languages"
+        data-testid="header-swap-languages"
+        title="Swap source and target languages"
+        className="px-1.5 py-0.5 bg-white border border-gray-300 rounded text-gray-600 hover:bg-amber-50 hover:text-amber-800 transition-colors cursor-pointer"
+      >
+        ⇄
+      </button>
+
+      {/* Target Language */}
+      <select
+        aria-label="Translate to language"
+        data-testid="header-target-language"
+        value={state.targetLanguage}
+        onChange={handleTargetChange}
+        disabled={state.isTranslating}
+        className="bg-white border border-gray-300 rounded px-1.5 py-0.5 text-xs text-gray-800 focus:outline-none focus:ring-1 focus:ring-amber-400"
+      >
+        {SUPPORTED_LANGUAGES.map((lang) => (
+          <option key={lang.code} value={lang.code}>
+            {lang.name} ({lang.code.toUpperCase()})
+          </option>
+        ))}
+      </select>
+
+      {/* Translate / Cancel Button */}
+      {state.isTranslating ? (
+        <button
+          type="button"
+          onClick={cancelActiveTranslation}
+          data-testid="header-cancel-btn"
+          className="bg-red-600 text-white font-semibold px-2.5 py-0.5 rounded hover:bg-red-700 transition-colors cursor-pointer"
+        >
+          {state.downloadProgress !== null
+            ? `Model ${state.downloadProgress}%`
+            : `${state.translatedCount}/${state.totalCount}`}
+        </button>
+      ) : (
+        <button
+          type="button"
+          onClick={handleTranslate}
+          disabled={availability.status === "same-language"}
+          data-testid="header-translate-btn"
+          className="bg-amber-700 text-white font-semibold px-2.5 py-0.5 rounded hover:bg-amber-600 transition-colors disabled:opacity-50 cursor-pointer"
+        >
+          Translate
+        </button>
+      )}
+
+      {/* Restore Original Button */}
+      {hasTranslatedTeasers && !state.isTranslating && (
+        <button
+          type="button"
+          onClick={handleRestore}
+          data-testid="header-restore-btn"
+          className="bg-white border border-gray-300 text-gray-700 font-medium px-2 py-0.5 rounded hover:bg-gray-100 transition-colors cursor-pointer"
+        >
+          Original
+        </button>
+      )}
+
+      {/* On-Device Status Indicator */}
+      <span
+        className="hidden md:inline-flex items-center text-[11px] text-gray-500 pl-1"
+        title={availability.message}
+      >
+        <span
+          className={`w-1.5 h-1.5 rounded-full mr-1 ${
+            availability.status === "available"
+              ? "bg-green-500"
+              : availability.status === "downloadable" ||
+                availability.status === "downloading"
+              ? "bg-amber-500"
+              : "bg-blue-500"
+          }`}
+        />
+        {state.activeLanguage
+          ? `${getLanguageShortName(state.activeLanguage)}`
+          : availability.isNativeSupported
+          ? "On-device AI"
+          : "On-device"}
+      </span>
+    </div>
+  );
+}
diff --git a/src/components/TeaserTranslateButton.tsx b/src/components/TeaserTranslateButton.tsx
new file mode 100644
index 0000000..3ae8a21
--- /dev/null
+++ b/src/components/TeaserTranslateButton.tsx
@@ -0,0 +1,136 @@
+import React, { useState, useEffect } from "react";
+import {
+  SUPPORTED_LANGUAGES,
+  getGlobalTranslationState,
+  subscribeTranslationState,
+  translateSingleTeaser,
+  restoreSingleTeaser,
+  type GlobalTranslationState,
+} from "../utils/translator";
+
+interface Props {
+  slug: string;
+  compact?: boolean;
+}
+
+export default function TeaserTranslateButton({ slug, compact = false }: Props) {
+  const [globalState, setGlobalState] = useState<GlobalTranslationState>(() =>
+    getGlobalTranslationState()
+  );
+  const [localTargetLang, setLocalTargetLang] = useState<string>(
+    globalState.targetLanguage || "es"
+  );
+  const [isBusy, setIsBusy] = useState(false);
+
+  useEffect(() => {
+    const unsubscribe = subscribeTranslationState((nextState) => {
+      setGlobalState(nextState);
+      setLocalTargetLang(nextState.targetLanguage);
+    });
+    return unsubscribe;
+  }, []);
+
+  const currentTranslatedLang = globalState.translatedTeasers[slug] || null;
+
+  const handleToggleTranslate = async (e: React.MouseEvent) => {
+    e.preventDefault();
+    e.stopPropagation();
+    if (isBusy) return;
+
+    setIsBusy(true);
+    try {
+      if (currentTranslatedLang && currentTranslatedLang === localTargetLang) {
+        restoreSingleTeaser(slug);
+      } else {
+        await translateSingleTeaser(slug, {
+          sourceLanguage: globalState.sourceLanguage,
+          targetLanguage: localTargetLang,
+        });
+      }
+    } finally {
+      setIsBusy(false);
+    }
+  };
+
+  const handleLanguageSelect = async (
+    e: React.ChangeEvent<HTMLSelectElement>
+  ) => {
+    e.stopPropagation();
+    const nextLang = e.target.value;
+    setLocalTargetLang(nextLang);
+    setIsBusy(true);
+    try {
+      await translateSingleTeaser(slug, {
+        sourceLanguage: globalState.sourceLanguage,
+        targetLanguage: nextLang,
+      });
+    } finally {
+      setIsBusy(false);
+    }
+  };
+
+  const isTranslated = Boolean(currentTranslatedLang);
+
+  return (
+    <div
+      className="inline-flex items-center space-x-1"
+      onClick={(e) => e.stopPropagation()}
+    >
+      {!compact && (
+        <select
+          aria-label={`Select translation language for ${slug}`}
+          value={localTargetLang}
+          onChange={handleLanguageSelect}
+          disabled={isBusy}
+          className="text-[11px] bg-gray-50 border border-gray-200 rounded px-1 py-0.5 text-gray-600 hover:border-amber-300 focus:outline-none focus:ring-1 focus:ring-amber-400"
+        >
+          {SUPPORTED_LANGUAGES.map((lang) => (
+            <option key={lang.code} value={lang.code}>
+              {lang.code.toUpperCase()}
+            </option>
+          ))}
+        </select>
+      )}
+      <button
+        type="button"
+        onClick={handleToggleTranslate}
+        disabled={isBusy}
+        data-testid={`teaser-translate-btn-${slug}`}
+        title={
+          isTranslated
+            ? `Showing ${currentTranslatedLang?.toUpperCase()} translation — click to restore original`
+            : `Translate teaser to ${localTargetLang.toUpperCase()} on-device`
+        }
+        className={`inline-flex items-center space-x-1 px-1.5 py-0.5 rounded text-xs font-medium transition-colors cursor-pointer ${
+          isTranslated
+            ? "bg-amber-100 text-amber-900 border border-amber-300 hover:bg-amber-200"
+            : "text-gray-500 hover:text-amber-700 hover:bg-gray-100"
+        }`}
+      >
+        <svg
+          xmlns="http://www.w3.org/2000/svg"
+          fill="none"
+          viewBox="0 0 24 24"
+          strokeWidth={1.8}
+          stroke="currentColor"
+          className="w-3.5 h-3.5"
+        >
+          <path
+            strokeLinecap="round"
+            strokeLinejoin="round"
+            d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+          />
+        </svg>
+        <span>
+          {isBusy
+            ? "…"
+            : isTranslated
+            ? `${currentTranslatedLang?.toUpperCase()} · Original`
+            : compact
+            ? localTargetLang.toUpperCase()
+            : "Translate"}
+        </span>
+      </button>
+    </div>
+  );
+}
