+function normalizeLookupText(text: string): string {
+  return text.trim().replace(/\s+/g, " ");
+}
+
+/**
+ * Find the English source phrase if the input is already translated in EXACT_PHRASES.
+ */
+function findEnglishFromTranslated(input: string): string | null {
+  const normalized = normalizeLookupText(input);
+  for (const [enText, langMap] of Object.entries(EXACT_PHRASES)) {
+    if (normalizeLookupText(enText).toLowerCase() === normalized.toLowerCase()) {
+      return enText;
+    }
+    for (const translated of Object.values(langMap)) {
+      if (normalizeLookupText(translated).toLowerCase() === normalized.toLowerCase()) {
+        return enText;
+      }
+    }
+  }
+  return null;
+}
+
+export function fallbackTranslateText(
+  text: string,
+  sourceLanguage: string,
+  targetLanguage: string
+): string {
+  const trimmed = text.trim();
+  if (!trimmed) return text;
+
+  const src = sourceLanguage.toLowerCase().split("-")[0];
+  const tgt = targetLanguage.toLowerCase().split("-")[0];
+  if (src === tgt) return text;
+
+  // Strip any existing fallback language tag prefix like "[ES] " if chained
+  const stripped = trimmed.replace(/^\[[A-Z]{2,3}\]\s*/, "");
+
+  // 1. Check exact phrase dictionary (including reverse lookup between non-English languages)
+  const matchedEnglishKey = findEnglishFromTranslated(stripped);
+  if (matchedEnglishKey) {
+    if (tgt === "en") {
+      return matchedEnglishKey;
+    }
+    const targetPhrase = EXACT_PHRASES[matchedEnglishKey]?.[tgt];
+    if (targetPhrase) {
+      return targetPhrase;
+    }
+  }
+
+  // 2. Word-by-word / phrase fallback for supported dictionary languages
+  const dict = WORD_DICTIONARY[tgt];
+  if (dict) {
+    let replacedCount = 0;
+    const translatedWords = stripped.replace(/\b([A-Za-z']+)\b/g, (word) => {
+      const lower = word.toLowerCase();
+      const replacement = dict[lower];
+      if (!replacement) return word;
+      replacedCount++;
+      if (word[0] === word[0].toUpperCase() && word[0] !== word[0].toLowerCase()) {
+        return replacement.charAt(0).toUpperCase() + replacement.slice(1);
+      }
+      return replacement;
+    });
+    if (replacedCount > 0) {
+      return translatedWords;
+    }
+  }
+
+  // 3. If translating back to English from word-dictionary language, attempt reverse word lookup
+  if (tgt === "en" && WORD_DICTIONARY[src]) {
+    const revDict: Record<string, string> = {};
+    for (const [enWord, foreignWord] of Object.entries(WORD_DICTIONARY[src])) {
+      revDict[foreignWord.toLowerCase()] = enWord;
+    }
+    let replacedCount = 0;
+    const reversedWords = stripped.replace(/\b([\p{L}']+)\b/gu, (word) => {
+      const lower = word.toLowerCase();
+      const replacement = revDict[lower];
+      if (!replacement) return word;
+      replacedCount++;
+      if (word[0] === word[0].toUpperCase() && word[0] !== word[0].toLowerCase()) {
+        return replacement.charAt(0).toUpperCase() + replacement.slice(1);
+      }
+      return replacement;
+    });
+    if (replacedCount > 0) {
+      return reversedWords;
+    }
+  }
+
+  // 4. Universal fallback indicator for any remaining arbitrary text/language pair
+  return `[${tgt.toUpperCase()}] ${stripped}`;
+}
