+}
+
+export function isNativeTranslatorSupported(): boolean {
+  if (typeof window === "undefined") return false;
+  return (
+    ("Translator" in window && typeof window.Translator?.create === "function") ||
+    Boolean(window.ai?.translator?.create) ||
+    Boolean(window.translation?.createTranslator)
+  );
+}
+
+export function isNativeLanguageDetectorSupported(): boolean {
+  if (typeof window === "undefined") return false;
+  return (
+    ("LanguageDetector" in window &&
+      typeof window.LanguageDetector?.create === "function") ||
+    Boolean(window.ai?.languageDetector?.create) ||
+    Boolean(window.translation?.createDetector)
+  );
+}
+
+function normalizeAvailabilityStatus(
+  raw: TranslatorAvailability | string | undefined
+): NormalizedAvailability {
+  switch (raw) {
+    case "available":
+    case "readily":
+      return "available";
+    case "downloadable":
+    case "after-download":
+      return "downloadable";
+    case "downloading":
+      return "downloading";
+    case "unavailable":
+    case "no":
+      return "unavailable";
+    default:
+      return "available";
+  }
+}
+
+export async function checkTranslationAvailability(
+  sourceLanguage: string,
+  targetLanguage: string
+): Promise<AvailabilityInfo> {
+  const effectiveSource = sourceLanguage === "auto" ? "en" : sourceLanguage;
+
+  if (effectiveSource === targetLanguage && sourceLanguage !== "auto") {
+    return {
+      status: "same-language",
+      isNativeSupported: isNativeTranslatorSupported(),
+      message: "Source and target languages are the same",
+    };
+  }
+
+  if (typeof window === "undefined") {
+    return {
+      status: "fallback",
+      isNativeSupported: false,
+      message: "Ready",
+    };
+  }
+
+  try {
+    if ("Translator" in window && window.Translator) {
+      if (typeof window.Translator.availability === "function") {
+        const raw = await window.Translator.availability({
+          sourceLanguage: effectiveSource,
+          targetLanguage,
+        });
+        const status = normalizeAvailabilityStatus(raw);
+        return {
+          status,
+          isNativeSupported: true,
+          message: getAvailabilityMessage(status, true),
+        };
+      }
+      return {
+        status: "available",
+        isNativeSupported: true,
+        message: "On-device model ready",
+      };
+    }
+
+    if (window.ai?.translator) {
+      if (typeof window.ai.translator.capabilities === "function") {
+        const caps = await window.ai.translator.capabilities();
+        const raw = caps.languagePairAvailable
+          ? caps.languagePairAvailable(effectiveSource, targetLanguage)
+          : caps.available;
+        const status = normalizeAvailabilityStatus(raw);
+        return {
+          status,
+          isNativeSupported: true,
+          message: getAvailabilityMessage(status, true),
+        };
+      }
+      return {
+        status: "available",
+        isNativeSupported: true,
+        message: "On-device model ready",
+      };
+    }
+
+    if (window.translation?.canTranslate) {
+      const raw = await window.translation.canTranslate({
+        sourceLanguage: effectiveSource,
+        targetLanguage,
+      });
+      const status = normalizeAvailabilityStatus(raw);
+      return {
+        status,
+        isNativeSupported: true,
+        message: getAvailabilityMessage(status, true),
+      };
+    }
+  } catch (err) {
+    console.warn("Translator availability check failed:", err);
+  }
+
+  return {
+    status: "fallback",
+    isNativeSupported: false,
+    message: "Browser Translator API unavailable — on-device fallback ready",
+  };
+}
+
+function getAvailabilityMessage(
+  status: NormalizedAvailability,
+  isNative: boolean
+): string {
+  if (!isNative) {
+    return "Browser Translator API unavailable — on-device fallback ready";
+  }
+  switch (status) {
+    case "available":
+      return "On-device model ready";
+    case "downloadable":
+      return "On-device model download required";
+    case "downloading":
+      return "Downloading on-device language model…";
+    case "unavailable":
+      return "Language pair not available natively (fallback enabled)";
+    case "same-language":
+      return "Select a different target language";
+    default:
+      return "On-device translation ready";
+  }
+}
