+export interface DetectedLanguageInfo {
+  language: string;
+  confidence: number;
+  isNative: boolean;
+}
+
+export async function detectLanguage(
+  sampleText: string
+): Promise<DetectedLanguageInfo> {
+  const cleaned = sampleText.trim().slice(0, 1000);
+  if (!cleaned) {
+    return { language: "en", confidence: 1, isNative: false };
+  }
+
+  if (typeof window !== "undefined") {
+    try {
+      let detector: LanguageDetectorInstance | null = null;
+      if (
+        "LanguageDetector" in window &&
+        typeof window.LanguageDetector?.create === "function"
+      ) {
+        detector = await window.LanguageDetector.create();
+      } else if (typeof window.ai?.languageDetector?.create === "function") {
+        detector = await window.ai.languageDetector.create();
+      } else if (typeof window.translation?.createDetector === "function") {
+        detector = await window.translation.createDetector();
+      }
+
+      if (detector && typeof detector.detect === "function") {
+        const results = await detector.detect(cleaned);
+        if (Array.isArray(results) && results.length > 0) {
+          const top = results[0];
+          const code = top.detectedLanguage?.toLowerCase().split("-")[0];
+          if (code && code !== "und") {
+            return {
+              language: code,
+              confidence: typeof top.confidence === "number" ? top.confidence : 0.95,
+              isNative: true,
+            };
+          }
+        }
+      }
+    } catch (err) {
+      console.warn("Native LanguageDetector failed, using heuristic detection:", err);
+    }
+  }
+
+  return heuristicDetectLanguage(cleaned);
+}
+
+function heuristicDetectLanguage(text: string): DetectedLanguageInfo {
+  if (/[\u3040-\u309f\u30a0-\u30ff]/.test(text)) {
+    return { language: "ja", confidence: 0.94, isNative: false };
+  }
+  if (/[\uac00-\ud7af]/.test(text)) {
+    return { language: "ko", confidence: 0.94, isNative: false };
+  }
+  if (/[\u4e00-\u9fff]/.test(text)) {
+    return { language: "zh", confidence: 0.92, isNative: false };
+  }
+  if (/[\u0400-\u04ff]/.test(text)) {
+    return { language: "ru", confidence: 0.92, isNative: false };
+  }
+  if (/[\u0600-\u06ff]/.test(text)) {
+    return { language: "ar", confidence: 0.92, isNative: false };
+  }
+  if (/[\u0900-\u097f]/.test(text)) {
+    return { language: "hi", confidence: 0.92, isNative: false };
+  }
+
+  const lower = ` ${text.toLowerCase()} `;
+  const scores: Record<string, number> = {
+    en: 0,
+    es: 0,
+    fr: 0,
+    de: 0,
+    it: 0,
+    pt: 0,
+  };
+
+  const markers: Record<string, string[]> = {
+    en: [" the ", " and ", " are ", " with ", " from ", " that ", " this "],
+    es: [" el ", " la ", " los ", " las ", " una ", " para ", " con ", " del ", " que "],
+    fr: [" les ", " des ", " une ", " dans ", " pour ", " avec ", " sur ", " est "],
+    de: [" der ", " die ", " das ", " und ", " für ", " mit ", " von ", " sich "],
+    it: [" gli ", " della ", " nella ", " sono ", " per ", " con ", " una "],
+    pt: [" uma ", " para ", " com ", " dos ", " das ", " pelo ", " mais "],
+  };
+
+  for (const [lang, words] of Object.entries(markers)) {
+    for (const w of words) {
+      if (lower.includes(w)) scores[lang]++;
+    }
+  }
+
+  let bestLang = "en";
+  let bestScore = scores.en;
+  for (const [lang, score] of Object.entries(scores)) {
+    if (score > bestScore) {
+      bestLang = lang;
+      bestScore = score;
+    }
+  }
+
+  return {
+    language: bestLang,
+    confidence: bestScore > 0 ? 0.9 : 0.8,
+    isNative: false,
+  };
+}
+
+// Cache active Translator instances by language pair and constructor reference
+const translatorCache = new Map<string, TranslatorInstance>();
+let lastTranslatorCtor: unknown = null;
+
+async function getNativeTranslator(
+  sourceLanguage: string,
+  targetLanguage: string,
+  options?: {
+    signal?: AbortSignal;
+    onDownloadProgress?: (percent: number) => void;
+  }
+): Promise<TranslatorInstance | null> {
+  if (typeof window === "undefined") return null;
+
+  const currentCtor =
+    window.Translator || window.ai?.translator || window.translation || null;
+  if (!currentCtor) return null;
+
+  if (lastTranslatorCtor !== currentCtor) {
+    translatorCache.clear();
+    lastTranslatorCtor = currentCtor;
+  }
+
+  const cacheKey = `${sourceLanguage}->${targetLanguage}`;
+  const cached = translatorCache.get(cacheKey);
+  if (cached) {
+    return cached;
+  }
+
+  const monitorCallback = (m: EventTarget) => {
+    if (m && typeof m.addEventListener === "function") {
+      m.addEventListener("downloadprogress", (ev: Event) => {
+        const e = ev as ProgressEvent;
+        let percent = 0;
+        if (typeof e.loaded === "number") {
+          if (e.total && e.total > 1) {
+            percent = Math.round((e.loaded / e.total) * 100);
+          } else if (e.loaded <= 1) {
+            percent = Math.round(e.loaded * 100);
+          } else {
+            percent = Math.min(100, Math.round(e.loaded));
+          }
+        }
+        options?.onDownloadProgress?.(percent);
+      });
+    }
+  };
+
+  let instance: TranslatorInstance | null = null;
+  if ("Translator" in window && typeof window.Translator?.create === "function") {
+    instance = await window.Translator.create({
+      sourceLanguage,
+      targetLanguage,
+      signal: options?.signal,
+      monitor: monitorCallback,
+    });
+  } else if (typeof window.ai?.translator?.create === "function") {
+    instance = await window.ai.translator.create({
+      sourceLanguage,
+      targetLanguage,
+      signal: options?.signal,
+      monitor: monitorCallback,
+    });
+  } else if (typeof window.translation?.createTranslator === "function") {
+    instance = await window.translation.createTranslator({
+      sourceLanguage,
+      targetLanguage,
+      signal: options?.signal,
+      monitor: monitorCallback,
+    });
+  }
+
+  if (instance) {
+    translatorCache.set(cacheKey, instance);
+  }
+  return instance;
+}
+
+async function consumeStream(
+  stream: ReadableStream<string>,
+  onPartial?: (partialText: string) => void
+): Promise<string> {
+  let accumulated = "";
+  const anyStream = stream as any;
+  if (typeof anyStream[Symbol.asyncIterator] === "function") {
+    for await (const chunk of anyStream) {
+      accumulated += String(chunk);
+      onPartial?.(accumulated);
+    }
+    return accumulated;
+  }
+  const reader = stream.getReader();
+  try {
+    while (true) {
+      const { done, value } = await reader.read();
+      if (done) break;
+      if (value !== undefined) {
+        accumulated += String(value);
+        onPartial?.(accumulated);
+      }
+    }
+  } finally {
+    reader.releaseLock();
+  }
+  return accumulated;
+}
+
+export interface TranslateSingleOptions {
+  sourceLanguage: string;
+  targetLanguage: string;
+  signal?: AbortSignal;
+  useStreaming?: boolean;
+  onDownloadProgress?: (percent: number) => void;
+  onPartial?: (partialText: string) => void;
+}
+
+export interface TranslateSingleResult {
+  translatedText: string;
+  usedNativeApi: boolean;
+  detectedSourceLanguage: string;
+}
+
+export async function translateSingleText(
+  text: string,
+  options: TranslateSingleOptions
+): Promise<TranslateSingleResult> {
+  const trimmed = text.trim();
+  let sourceLang = options.sourceLanguage;
+  if (sourceLang === "auto") {
+    const detected = await detectLanguage(trimmed);
+    sourceLang = detected.language;
+  }
+
+  const targetLang = options.targetLanguage;
+  if (!trimmed || sourceLang === targetLang) {
+    return {
+      translatedText: text,
+      usedNativeApi: isNativeTranslatorSupported(),
+      detectedSourceLanguage: sourceLang,
+    };
+  }
+
+  if (isNativeTranslatorSupported()) {
+    try {
+      const translator = await getNativeTranslator(sourceLang, targetLang, {
+        signal: options.signal,
+        onDownloadProgress: options.onDownloadProgress,
+      });
+
+      if (translator) {
+        if (
+          options.useStreaming &&
+          typeof translator.translateStreaming === "function"
+        ) {
+          const stream = translator.translateStreaming(trimmed, {
+            signal: options.signal,
+          });
+          const result = await consumeStream(stream, options.onPartial);
+          return {
+            translatedText: result,
+            usedNativeApi: true,
+            detectedSourceLanguage: sourceLang,
+          };
+        }
+
+        if (typeof translator.translate === "function") {
+          const result = await translator.translate(trimmed, {
+            signal: options.signal,
+          });
+          return {
+            translatedText: result,
+            usedNativeApi: true,
+            detectedSourceLanguage: sourceLang,
+          };
+        }
+      }
+    } catch (err: any) {
+      if (options.signal?.aborted || err?.name === "AbortError") {
+        throw err;
+      }
+      console.warn(
+        "Native Translator API call failed, falling back to on-device dictionary:",
+        err
+      );
+    }
+  }
+
+  const fallbackResult = fallbackTranslateText(trimmed, sourceLang, targetLang);
+  return {
+    translatedText: fallbackResult,
+    usedNativeApi: false,
+    detectedSourceLanguage: sourceLang,
+  };
+}
