+
+export function getGlobalTranslationState(): GlobalTranslationState {
+  return { ...globalState, translatedTeasers: { ...globalState.translatedTeasers } };
+}
+
+function updateGlobalState(partial: Partial<GlobalTranslationState>) {
+  globalState = {
+    ...globalState,
+    ...partial,
+  };
+  if (typeof window !== "undefined") {
+    window.dispatchEvent(
+      new CustomEvent(STATE_EVENT_NAME, { detail: getGlobalTranslationState() })
+    );
+  }
+}
+
+export function subscribeTranslationState(
+  listener: (state: GlobalTranslationState) => void
+): () => void {
+  if (typeof window === "undefined") return () => {};
+  const handler = (e: Event) => {
+    const customEvent = e as CustomEvent<GlobalTranslationState>;
+    listener(customEvent.detail);
+  };
+  window.addEventListener(STATE_EVENT_NAME, handler);
+  return () => window.removeEventListener(STATE_EVENT_NAME, handler);
+}
+
+export function setTranslationLanguages(
+  sourceLanguage: string,
+  targetLanguage: string
