+  updateGlobalState({
+    sourceLanguage,
+    targetLanguage,
+    error: null,
+  });
+}
+
+export function setTranslationScope(scope: TranslationScope) {
+  updateGlobalState({ scope });
+}
+
+export function swapTranslationLanguages() {
+  const currentSource =
+    globalState.sourceLanguage === "auto"
+      ? globalState.detectedLanguage?.language || "en"
+      : globalState.sourceLanguage;
+  const currentTarget = globalState.targetLanguage;
+
+  updateGlobalState({
+    sourceLanguage: currentTarget,
+    targetLanguage: currentSource,
+    error: null,
+  });
+}
+
+function preserveOriginalElementContent(el: HTMLElement) {
+  if (el.dataset.originalSaved !== "true") {
+    el.dataset.originalText = el.textContent || "";
+    el.dataset.originalHtml = el.innerHTML;
+    el.dataset.originalLang = el.getAttribute("lang") || "en";
+    el.dataset.originalSaved = "true";
+  }
