+
+function getSourceTextForElement(
+  el: HTMLElement,
+  effectiveSourceLang: string
+): string {
+  preserveOriginalElementContent(el);
+  const currentLang = el.dataset.currentLang || el.dataset.originalLang || "en";
+  // If user is chaining translation from the currently displayed language (e.g. ES -> FR),
+  // translate from the current text; if translating from the original language (e.g. EN -> FR),
+  // use the pristine original text.
+  if (
+    el.dataset.currentLang &&
+    effectiveSourceLang === currentLang &&
+    effectiveSourceLang !== (el.dataset.originalLang || "en")
+  ) {
+    return (el.textContent || "").trim();
+  }
+  return (el.dataset.originalText || el.textContent || "").trim();
