+function restoreElementContent(el: HTMLElement) {
+  if (el.dataset.originalSaved === "true") {
+    if (el.dataset.originalHtml !== undefined) {
+      el.innerHTML = el.dataset.originalHtml;
+    } else if (el.dataset.originalText !== undefined) {
+      el.textContent = el.dataset.originalText;
+    }
+    const origLang = el.dataset.originalLang;
+    if (origLang && origLang !== "en") {
+      el.setAttribute("lang", origLang);
+    } else {
+      el.removeAttribute("lang");
+    }
+    delete el.dataset.currentLang;
+    delete el.dataset.translated;
+  }
