+/**
+ * Collects all translatable HTML elements for the main article on the page.
+ */
+export function getArticleTranslatableElements(): HTMLElement[] {
+  if (typeof document === "undefined") return [];
+  const elements: HTMLElement[] = [];
+  const seen = new Set<HTMLElement>();
+
+  const addEl = (el: HTMLElement | null) => {
+    if (!el || seen.has(el)) return;
+    if (el.querySelector("script, style")) return;
+    const text = (el.dataset.originalText || el.textContent || "").trim();
+    if (!text) return;
+    seen.add(el);
+    elements.push(el);
+  };
