+  // Explicit article metadata elements (category, title, summary, caption)
+  document
+    .querySelectorAll<HTMLElement>(
+      '[data-translate-article="category"], [data-translate-article="title"], [data-translate-article="summary"], [data-translate-article="caption"]'
+    )
+    .forEach(addEl);
