+  if (slugFilter) {
+    const cards = document.querySelectorAll<HTMLElement>(
+      `[data-teaser-card="${CSS.escape(slugFilter)}"]`
+    );
+    cards.forEach((card) => {
+      card
+        .querySelectorAll<HTMLElement>(
+          "[data-teaser-category], [data-teaser-title], [data-teaser-summary]"
+        )
+        .forEach(addEl);
+    });
+    return elements;
+  }
