+  return elements;
+}
+
+export function getSampleTextFromPage(scope: TranslationScope = "all"): string {
+  const articleEls =
+    scope === "teasers" ? [] : getArticleTranslatableElements();
+  const teaserEls =
+    scope === "article" ? [] : getTeaserTranslatableElements();
