+    updateGlobalState({
+      error: "No translatable article or teaser content found on this page.",
+    });
+    return;
+  }
+
+  updateGlobalState({
+    sourceLanguage,
+    targetLanguage,
+    scope,
+    isTranslating: true,
+    downloadProgress: null,
+    translatedCount: 0,
+    totalCount: targetElements.length,
+    error: null,
+  });
+
+  try {
+    let effectiveSource = sourceLanguage;
+    if (sourceLanguage === "auto") {
+      const sampleText = getSampleTextFromPage(scope);
+      const detected = await detectLanguage(sampleText);
+      effectiveSource = detected.language;
+      updateGlobalState({ detectedLanguage: detected });
+    }
+
+    if (effectiveSource === targetLanguage) {
+      // If translating back to the original language ("en"), restore original content
+      const isOriginalLang = targetElements.every(
+        (el) => (el.dataset.originalLang || "en") === targetLanguage
+      );
+      if (isOriginalLang) {
+        restorePageContent(scope);
+        return;
+      }
+    }
