+        sourceLanguage: effectiveSource,
+        targetLanguage,
+        signal: abortController.signal,
+        useStreaming,
+        onDownloadProgress: (percent) => {
+          updateGlobalState({ downloadProgress: percent });
+        },
+        onPartial: (partialText) => {
+          el.textContent = partialText;
+        },
+      });
