+    if (!abortController.signal.aborted) {
+      const updatedTeasers = { ...globalState.translatedTeasers };
+      if (scope !== "article") {
+        document
+          .querySelectorAll<HTMLElement>("[data-teaser-card]")
+          .forEach((card) => {
+            const slug = card.dataset.teaserCard;
+            if (slug) {
+              updatedTeasers[slug] = targetLanguage;
+            }
+          });
+      }
+
+      updateGlobalState({
+        isTranslating: false,
+        downloadProgress: null,
+        activeLanguage: targetLanguage,
+        translatedTeasers: updatedTeasers,
+      });
+    }
+  } catch (err: any) {
+    if (err?.name === "AbortError" || abortController.signal.aborted) {
+      updateGlobalState({
+        isTranslating: false,
+        downloadProgress: null,
+      });
+      return;
+    }
+    updateGlobalState({
+      isTranslating: false,
+      downloadProgress: null,
+      error: err?.message || "Failed to translate content.",
+    });
+  } finally {
+    if (activeAbortController === abortController) {
+      activeAbortController = null;
+    }
+  }
+}
+
+export function restorePageContent(scope: TranslationScope = "all"): void {
+  if (typeof document === "undefined") return;
+
+  if (activeAbortController) {
+    activeAbortController.abort();
+    activeAbortController = null;
+  }
+
+  const articleElements =
+    scope === "teasers" ? [] : getArticleTranslatableElements();
+  const teaserElements =
+    scope === "article" ? [] : getTeaserTranslatableElements();
+  const targetElements = [...articleElements, ...teaserElements];
+
+  targetElements.forEach(restoreElementContent);
+
+  const updatedTeasers =
+    scope === "article" ? { ...globalState.translatedTeasers } : {};
+
+  updateGlobalState({
+    isTranslating: false,
+    downloadProgress: null,
+    activeLanguage: null,
+    translatedCount: 0,
+    totalCount: 0,
+    error: null,
+    translatedTeasers: updatedTeasers,
+  });
+}
+
+/**
+ * Translates a single teaser card (identified by `data-teaser-card={slug}`)
+ */
+export async function translateSingleTeaser(
+  slug: string,
+  options?: {
+    sourceLanguage?: string;
+    targetLanguage?: string;
+  }
+): Promise<void> {
+  const elements = getTeaserTranslatableElements(slug);
+  if (elements.length === 0) return;
+
+  const sourceLanguage = options?.sourceLanguage ?? globalState.sourceLanguage;
+  const targetLanguage = options?.targetLanguage ?? globalState.targetLanguage;
+
+  let effectiveSource = sourceLanguage;
+  if (sourceLanguage === "auto") {
+    const sample = elements
+      .map((el) => (el.textContent || "").trim())
+      .join(" ");
+    const detected = await detectLanguage(sample);
+    effectiveSource = detected.language;
+  }
+
+  if (effectiveSource === targetLanguage) {
+    restoreSingleTeaser(slug);
+    return;
+  }
+
+  let usedNative = false;
+  for (const el of elements) {
+    const sourceText = getSourceTextForElement(el, effectiveSource);
+    if (!sourceText) continue;
+
+    const result = await translateSingleText(sourceText, {
+      sourceLanguage: effectiveSource,
+      targetLanguage,
+    });
+
+    el.textContent = result.translatedText;
+    el.setAttribute("lang", targetLanguage);
+    el.dataset.currentLang = targetLanguage;
+    el.dataset.translated = "true";
+    if (result.usedNativeApi) usedNative = true;
+  }
+
+  updateGlobalState({
+    usedNativeApi: usedNative,
+    translatedTeasers: {
+      ...globalState.translatedTeasers,
+      [slug]: targetLanguage,
+    },
+  });
+}
+
+export function restoreSingleTeaser(slug: string): void {
+  const elements = getTeaserTranslatableElements(slug);
+  elements.forEach(restoreElementContent);
+
+  const nextTeasers = { ...globalState.translatedTeasers };
+  delete nextTeasers[slug];
+
+  updateGlobalState({
+    translatedTeasers: nextTeasers,
+  });
+}

