+import http from "node:http";
+import fs from "node:fs/promises";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+import dns from "node:dns/promises";
+import {
+  NONCE_COOKIE_NAME,
+  NONCE_TTL_MS,
+  rewardsAccounts,
+  isValidDnsLabel,
+  isBareOrigin,
+  isValidDnsIssuerDomain,
+  isSafeIssuerUrl,
+  readBoundedJson,
+  validateClaims,
+  createSessionNonce,
+  consumeSessionNonce,
+  verifyEmailVerificationToken,
+  getRequestOrigin,
+  escapeHtml,
+  handleRewardsVerificationRequest,
+} from "./verifier.js";
+
+export {
+  NONCE_COOKIE_NAME,
+  NONCE_TTL_MS,
+  rewardsAccounts,
+  isValidDnsLabel,
+  isBareOrigin,
+  isValidDnsIssuerDomain,
+  isSafeIssuerUrl,
+  readBoundedJson,
+  validateClaims,
+  createSessionNonce,
+  consumeSessionNonce,
+  verifyEmailVerificationToken,
+  handleRewardsVerificationRequest,
+};
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+const PORT = Number(process.env.PORT) || 11222;
+
+async function renderIndexHtml(nonce, bannerHtml = "") {
+  const indexPath = path.join(__dirname, "index.html");
+  let html = await fs.readFile(indexPath, "utf8");
+  html = html.replace(/__EVP_NONCE__/g, escapeHtml(nonce));
+  html = html.replace(
+    /(<input\b[^>]*\bautocomplete=["']email-verification-token["'][^>]*\bnonce=["'])[^"']*(["'][^>]*>)/i,
+    `$1${escapeHtml(nonce)}$2`
+  );
+  html = html.replace(
+    /(<input\b[^>]*\bnonce=["'])[^"']*(["'][^>]*\bautocomplete=["']email-verification-token["'][^>]*>)/i,
+    `$1${escapeHtml(nonce)}$2`
+  );
+  if (bannerHtml) {
+    html = html.replace("<!-- EVP_STATUS_BANNER -->", bannerHtml);
+  }
+  return html;
+}
+
+const MIME_TYPES = {
+  ".html": "text/html; charset=utf-8",
+  ".css": "text/css; charset=utf-8",
+  ".js": "application/javascript; charset=utf-8",
+  ".mjs": "application/javascript; charset=utf-8",
+  ".json": "application/json; charset=utf-8",
+  ".png": "image/png",
+  ".jpg": "image/jpeg",
+  ".jpeg": "image/jpeg",
+  ".svg": "image/svg+xml",
+  ".ico": "image/x-icon",
+};
+
+export function createAppServer(options = {}) {
+  const dnsResolver = options.dnsResolver || dns;
+  const fetchImpl = options.fetchImpl || fetch;
+
+  return http.createServer(async (req, res) => {
+    try {
+      const handled = await handleRewardsVerificationRequest(req, res, {
+        ...options,
+        dnsResolver,
+        fetchImpl,
+        renderIndexHtml,
+      });
+      if (handled) {
+        return;
+      }
+
+      const url = new URL(req.url || "/", getRequestOrigin(req, PORT));
+      const pathname = url.pathname;
+
+      // Serve homepage with fresh session-bound nonce cookie and populated nonce attribute
+      if ((req.method === "GET" || req.method === "HEAD") && (pathname === "/" || pathname === "/index.html")) {
+        const nonce = createSessionNonce();
+        res.setHeader(
+          "Set-Cookie",
+          `${NONCE_COOKIE_NAME}=${encodeURIComponent(nonce)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=300`
+        );
+        const html = await renderIndexHtml(nonce);
+        res.writeHead(200, {
+          "Content-Type": "text/html; charset=utf-8",
+          "Cache-Control": "no-cache",
+        });
+        if (req.method === "HEAD") {
+          res.end();
+        } else {
+          res.end(html);
+        }
+        return;
+      }
+
+      // Serve other static files safely from workspace root
+      if (req.method === "GET" || req.method === "HEAD") {
+        const safePath = path.normalize(pathname).replace(/^(\.\.(\/|\\|$))+/, "");
+        const filePath = path.join(__dirname, safePath);
+        if (!filePath.startsWith(__dirname)) {
+          res.writeHead(403, { "Content-Type": "text/plain; charset=utf-8" });
+          res.end("Forbidden");
+          return;
+        }
+        try {
+          const stat = await fs.stat(filePath);
+          if (stat.isFile()) {
+            const ext = path.extname(filePath).toLowerCase();
+            const contentType = MIME_TYPES[ext] || "application/octet-stream";
+            const data = await fs.readFile(filePath);
+            res.writeHead(200, { "Content-Type": contentType });
+            if (req.method === "HEAD") {
+              res.end();
+            } else {
+              res.end(data);
+            }
+            return;
+          }
+        } catch {
+          // Fall through to 404
+        }
+      }
+
+      res.writeHead(404, { "Content-Type": "application/json; charset=utf-8" });
+      res.end(JSON.stringify({ error: "Not found" }));
+    } catch (err) {
+      res.writeHead(500, { "Content-Type": "application/json; charset=utf-8" });
+      res.end(
+        JSON.stringify({
+          error: err instanceof Error ? err.message : "Internal server error",
+        })
+      );
+    }
+  });
+}
+
+// Start the server only when executed directly (e.g. `node server.js` or `npm start`)
+if (process.argv[1] && path.resolve(process.argv[1]) === __filename) {
+  const server = createAppServer();
+  server.listen(PORT, () => {
+    console.log(`Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}
