+import test from "node:test";
+import assert from "node:assert/strict";
+import fs from "node:fs/promises";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+import { createHash } from "node:crypto";
+import { generateKeyPair, exportJWK, SignJWT } from "jose";
+import { EventEmitter } from "node:events";
+import {
+  verifyEmailVerificationToken,
+  createSessionNonce,
+  consumeSessionNonce,
+  isBareOrigin,
+  isValidDnsIssuerDomain,
+  isSafeIssuerUrl,
+  handleRewardsVerificationRequest,
+} from "../verifier.js";
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+async function createMockEvtPlusKb({
+  email = "alex@coffee.example",
+  emailVerified = true,
+  issuerOrigin = "https://accounts.coffee.example",
+  rpOrigin = "https://dailygrind.example",
+  nonce = "session-nonce-12345",
+  includeKid = true,
+  alg = "EdDSA",
+}) {
+  const issuerKeys = await generateKeyPair(alg);
+  const browserKeys = await generateKeyPair(alg);
+
+  const issuerPublicJwk = await exportJWK(issuerKeys.publicKey);
+  issuerPublicJwk.alg = alg;
+  if (includeKid) {
+    issuerPublicJwk.kid = "issuer-key-2026";
+  }
+
+  const browserPublicJwk = await exportJWK(browserKeys.publicKey);
+  browserPublicJwk.alg = alg;
+
+  const now = Math.floor(Date.now() / 1000);
+
+  const evtHeader = {
+    alg,
+    typ: "evt+jwt",
+    ...(includeKid ? { kid: "issuer-key-2026" } : {}),
+  };
+
+  const evtJwt = await new SignJWT({
+    iss: issuerOrigin,
+    iat: now,
+    exp: now + 300,
+    cnf: {
+      jwk: browserPublicJwk,
+    },
+    email,
+    email_verified: emailVerified,
+  })
+    .setProtectedHeader(evtHeader)
+    .sign(issuerKeys.privateKey);
+
+  // SD-JWT format separates the Issuer-signed JWT and Key Binding JWT with "~"
+  const sdJwtPrefix = `${evtJwt}~`;
+  const sdHash = createHash("sha256").update(sdJwtPrefix).digest("base64url");
+
+  const kbJwt = await new SignJWT({
+    aud: rpOrigin,
+    nonce,
+    iat: now,
+    sd_hash: sdHash,
+  })
+    .setProtectedHeader({
+      alg,
+      typ: "kb+jwt",
+    })
+    .sign(browserKeys.privateKey);
+
+  return {
+    rawToken: `${sdJwtPrefix}${kbJwt}`,
+    issuerPublicJwk,
+  };
+}
+
+test("index.html includes Daily Grind rewards sign-up form with Email Verification Protocol fields", async () => {
+  const htmlPath = path.join(__dirname, "..", "index.html");
+  const html = await fs.readFile(htmlPath, "utf8");
+
+  assert.match(html, /<form[^>]*id=["']rewards-signup-form["'][^>]*>/i);
+  assert.match(html, /<input[^>]*type=["']email["'][^>]*autocomplete=["']email["'][^>]*>/i);
+  assert.match(html, /<input[^>]*type=["']hidden["'][^>]*autocomplete=["']email-verification-token["'][^>]*>/i);
+  assert.match(html, /nonce=["'][^"']+["']/i);
