+const SDJwtInstance = SdJwtInstance;
+
+export const NONCE_COOKIE_NAME = "evp_rp_nonce";
+export const NONCE_TTL_MS = 5 * 60 * 1000; // 5 minutes
+
+// Store active session-bound nonces in memory (alongside HTTP-only cookie validation)
+const activeNonces = new Map();
+
+// Registered rewards accounts store
+export const rewardsAccounts = new Map();
+
+const DNS_LABEL_CHARS_RE = /^[a-z0-9-]+$/;
+
+export function isValidDnsLabel(label) {
+  return (
+    typeof label === "string" &&
+    label.length >= 1 &&
+    label.length <= 63 &&
+    !label.startsWith("-") &&
+    !label.endsWith("-") &&
+    DNS_LABEL_CHARS_RE.test(label)
+  );
+}
+
+/**
+ * Verifies that an issuer identifier is a bare origin (e.g. "https://accounts.google.com")
+ * with no trailing slash, path, query, fragment, or embedded credentials.
+ */
+export function isBareOrigin(urlStr) {
+  try {
+    const parsed = new URL(urlStr);
+    if (parsed.username || parsed.password) {
+      return false;
+    }
+    return parsed.origin !== "null" && parsed.origin === urlStr;
+  } catch {
+    return false;
+  }
+}
+
+/**
+ * Validates the `iss=` domain value from a `_email-verification.<domain>` DNS TXT record.
+ */
+export function isValidDnsIssuerDomain(domain) {
+  if (!domain || typeof domain !== "string" || domain.length > 253 || domain !== domain.toLowerCase()) {
+    return false;
+  }
+  if (net.isIP(domain) !== 0) {
+    return false;
+  }
+  const labels = domain.split(".");
+  if (labels.length < 2) {
+    return false;
+  }
+  return labels.every(isValidDnsLabel);
+}
+
+/**
+ * Validates that an outbound discovery or JWKS URL is safe to fetch (protecting against SSRF).
+ */
+export function isSafeIssuerUrl(urlStr, isProd = process.env.NODE_ENV === "production") {
+  try {
+    const parsed = new URL(urlStr);
+    if (parsed.username || parsed.password) {
+      return false;
+    }
+    const host = parsed.hostname.toLowerCase();
+    const isLocalDev = !isProd && (host === "localhost" || host === "127.0.0.1");
+    if (isLocalDev) {
+      return parsed.protocol === "https:" || parsed.protocol === "http:";
+    }
+    if (parsed.protocol !== "https:") {
+      return false;
+    }
+    if (host.endsWith(".localhost") || host.endsWith(".local") || host.endsWith(".internal")) {
+      return false;
+    }
+    return isValidDnsIssuerDomain(host);
+  } catch {
+    return false;
+  }
+}
+
+/**
+ * Reads and parses a JSON response body while enforcing an upper byte limit (`maxBytes`).
+ */
+export async function readBoundedJson(response, url, maxBytes = 65536) {
+  const contentLength = response.headers.get("content-length");
+  if (contentLength && Number(contentLength) > maxBytes) {
+    throw new Error(`Response from ${url} exceeds maximum allowed size of ${maxBytes} bytes.`);
+  }
+  const text = await response.text();
+  if (Buffer.byteLength(text, "utf8") > maxBytes) {
+    throw new Error(`Response from ${url} exceeds maximum allowed size of ${maxBytes} bytes.`);
+  }
+  return JSON.parse(text);
+}
+
+/**
+ * Validates standard JWT claims including expiration, issued-at presence, and freshness window.
+ */
+export function validateClaims(payload, maxAgeSeconds = 300, clockSkewSeconds = 60) {
+  const currentTime = Math.floor(Date.now() / 1000);
+  const exp = typeof payload.exp === "number" ? payload.exp : undefined;
+  const iat = typeof payload.iat === "number" ? payload.iat : undefined;
+
+  if (exp && currentTime > exp + clockSkewSeconds) {
+    throw new Error(`The token has expired (exp: ${exp}, current: ${currentTime}).`);
+  }
+  if (!iat) {
+    throw new Error("Required issued-at ('iat') claim is missing.");
+  }
+  if (exp && iat >= exp) {
+    throw new Error(`Token timestamps are inconsistent (iat: ${iat} >= exp: ${exp}).`);
+  }
+  const age = currentTime - iat;
+  if (age > maxAgeSeconds + clockSkewSeconds) {
+    throw new Error(`Token is too old (issued ${age} seconds ago, max limit: ${maxAgeSeconds}s).`);
+  }
+  if (age < -clockSkewSeconds) {
+    throw new Error(`Token has a future issuance timestamp (iat: ${iat}, current: ${currentTime}).`);
+  }
