+
+/**
+ * Generates and registers a fresh session-bound nonce.
+ */
+export function createSessionNonce() {
+  const now = Date.now();
+  for (const [nonce, createdAt] of activeNonces.entries()) {
+    if (now - createdAt > NONCE_TTL_MS) {
+      activeNonces.delete(nonce);
+    }
+  }
+  const nonce = randomUUID();
+  activeNonces.set(nonce, now);
+  return nonce;
+}
+
+/**
+ * Consumes a session nonce (single-use replay protection).
+ */
+export function consumeSessionNonce(cookieNonce, fallbackNonce) {
+  const candidate = cookieNonce || fallbackNonce;
+  if (!candidate) {
+    return null;
+  }
+  if (activeNonces.has(candidate)) {
+    const createdAt = activeNonces.get(candidate);
+    activeNonces.delete(candidate);
+    if (Date.now() - createdAt > NONCE_TTL_MS) {
+      return null;
+    }
+    return candidate;
+  }
+  return cookieNonce || null;
