+        }
+      }
+      return false;
+    },
+    // Verifier for the Key Binding JWT (KB-JWT)
+    kbVerifier: async (data, sig) => {
+      try {
+        const browserJwkKey = evtJwtDecodedPayload.cnf?.jwk;
+        if (!browserJwkKey) return false;
+        const pubKey = await importJWK(browserJwkKey, decodedSdJwt.kbJwt.header.alg || "ES256");
+        await compactVerify(`${data}.${sig}`, pubKey);
+        return true;
+      } catch {
+        return false;
+      }
+    },
+  });
+
+  // Ensure KB-JWT audience and nonce match expected values
+  if (expectedAudience && kbJwtDecodedPayload.aud !== expectedAudience) {
+    throw new Error(
+      `Security Exception: Invalid Key Binding audience (expected '${expectedAudience}', got '${kbJwtDecodedPayload.aud}').`
+    );
+  }
+  if (kbJwtDecodedPayload.nonce !== expectedNonce) {
+    throw new Error("Security Exception: Invalid or mismatched Key Binding nonce.");
+  }
+
+  const result = await sdJwt.verify(rawToken, {
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    kb: {
+      expectedNonce,
+      expectedAudience,
+      required: true,
+    },
+  });
+
+  // Validate KB-JWT freshness and expiration claims
+  validateClaims(kbJwtDecodedPayload, 300);
+
+  return {
+    verified: true,
+    email: result.payload.email,
+    issuer: iss,
+    isPrivateEmail: Boolean(result.payload.is_private_email),
+    evtPayload: result.payload,
+    kbPayload: kbJwtDecodedPayload,
+  };
+}
+
+export function parseCookies(cookieHeader) {
+  const cookies = {};
+  if (!cookieHeader) return cookies;
+  for (const part of cookieHeader.split(";")) {
+    const idx = part.indexOf("=");
+    if (idx !== -1) {
+      const key = part.slice(0, idx).trim();
+      const val = decodeURIComponent(part.slice(idx + 1).trim());
+      cookies[key] = val;
+    }
+  }
+  return cookies;
+}
+
+export async function readRequestBody(req, maxBytes = 65536) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let total = 0;
+    req.on("data", (chunk) => {
+      total += chunk.length;
+      if (total > maxBytes) {
+        reject(new Error("Request body too large"));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
+    req.on("error", reject);
+  });
+}
+
+export function parseFormOrJsonBody(rawBody, contentType = "") {
+  const ct = contentType.toLowerCase();
+  if (ct.includes("application/json")) {
+    return JSON.parse(rawBody || "{}");
+  }
+  if (ct.includes("application/x-www-form-urlencoded")) {
+    return Object.fromEntries(new URLSearchParams(rawBody));
+  }
+  try {
+    return JSON.parse(rawBody);
+  } catch {
+    return Object.fromEntries(new URLSearchParams(rawBody));
+  }
+}
+
+export function getRequestOrigin(req, defaultPort = 11222) {
+  if (req.headers.origin && isBareOrigin(req.headers.origin)) {
+    return req.headers.origin;
+  }
+  const proto = (req.headers["x-forwarded-proto"] || "http").split(",")[0].trim();
+  const host = req.headers["x-forwarded-host"] || req.headers.host || `localhost:${defaultPort}`;
+  return `${proto}://${host}`;
+}
+
+export function escapeHtml(str) {
+  return String(str)
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#39;");
+}
+
+/**
+ * Handles `/api/rewards/nonce` and `/api/rewards/signup` (and aliases) HTTP requests.
+ */
+export async function handleRewardsVerificationRequest(req, res, options = {}) {
+  const dnsResolver = options.dnsResolver || dns;
+  const fetchImpl = options.fetchImpl || fetch;
+  const url = new URL(req.url || "/", getRequestOrigin(req));
+  const pathname = url.pathname;
+  const cookies = parseCookies(req.headers.cookie);
+
+  // Endpoint to fetch a fresh session-bound nonce for client-side progressive enhancement
+  if (req.method === "GET" && pathname === "/api/rewards/nonce") {
+    const nonce = createSessionNonce();
+    res.setHeader(
+      "Set-Cookie",
+      `${NONCE_COOKIE_NAME}=${encodeURIComponent(nonce)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=300`
+    );
+    res.writeHead(200, {
+      "Content-Type": "application/json; charset=utf-8",
+      "Cache-Control": "no-store",
+    });
+    res.end(JSON.stringify({ nonce }));
+    return true;
+  }
+
+  // Rewards sign-up & Email Verification Protocol (EVP) verification endpoints
+  const isVerifyEndpoint =
+    pathname === "/api/rewards/signup" ||
+    pathname === "/api/rewards/register" ||
+    pathname === "/api/verify-email" ||
+    pathname === "/rewards/signup";
+
+  if (req.method === "POST" && isVerifyEndpoint) {
+    const rawBody = await readRequestBody(req);
+    const body = parseFormOrJsonBody(rawBody, req.headers["content-type"]);
+
+    const fullName = (body.name || body.fullName || body["full-name"] || "").trim();
+    const submittedEmail = (body.email || body["email-address"] || "").trim();
+    const favoriteDrink = (body.favoriteDrink || body["favorite-drink"] || "Maple Oat Latte").trim();
+    const rawToken = (body.token || body["email-verification-token"] || body.evt || "").trim();
+
+    const expectedNonce = consumeSessionNonce(cookies[NONCE_COOKIE_NAME], body.sessionNonce);
+    // Clear used nonce cookie and issue a fresh one for subsequent renders
+    const nextNonce = createSessionNonce();
+    res.setHeader(
+      "Set-Cookie",
+      `${NONCE_COOKIE_NAME}=${encodeURIComponent(nextNonce)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=300`
+    );
+
+    const expectedAudience = options.expectedAudience || getRequestOrigin(req);
+    const acceptsJson =
+      (req.headers.accept || "").includes("application/json") ||
+      (req.headers["content-type"] || "").includes("application/json");
+
+    if (!submittedEmail || !submittedEmail.includes("@")) {
+      if (acceptsJson) {
+        res.writeHead(400, { "Content-Type": "application/json; charset=utf-8" });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            verified: false,
+            error: "Please enter a valid email address.",
+            nonce: nextNonce,
+          })
+        );
+      } else if (options.renderIndexHtml) {
+        const html = await options.renderIndexHtml(
+          nextNonce,
+          `<div class="rewards-alert rewards-alert-error" role="alert">Please enter a valid email address.</div>`
+        );
+        res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
+        res.end(html);
+      } else {
+        res.writeHead(400, { "Content-Type": "text/plain; charset=utf-8" });
+        res.end("Please enter a valid email address.");
+      }
+      return true;
+    }
+
+    if (!rawToken) {
+      const message =
+        "No browser Email Verification Token (EVT) was received. Make sure you are signed in to an EVP-supported email provider in your browser so your email can be verified automatically without an OTP or magic link.";
+      if (acceptsJson) {
+        res.writeHead(400, { "Content-Type": "application/json; charset=utf-8" });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            verified: false,
+            error: message,
+            nonce: nextNonce,
+          })
+        );
+      } else if (options.renderIndexHtml) {
+        const html = await options.renderIndexHtml(
+          nextNonce,
+          `<div class="rewards-alert rewards-alert-error" role="alert">${escapeHtml(message)}</div>`
+        );
+        res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
+        res.end(html);
+      } else {
+        res.writeHead(400, { "Content-Type": "text/plain; charset=utf-8" });
+        res.end(message);
+      }
+      return true;
+    }
+
+    try {
+      const verification = await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience,
+        dnsResolver,
+        fetchImpl,
+      });
+
+      const account = {
+        id: randomUUID(),
+        name: fullName || submittedEmail.split("@")[0],
+        email: verification.email,
+        favoriteDrink,
+        emailVerified: true,
+        verificationMethod: "email-verification-protocol",
+        issuer: verification.issuer,
+        welcomePoints: 150,
+        createdAt: new Date().toISOString(),
+      };
+      rewardsAccounts.set(verification.email.toLowerCase(), account);
+
+      if (acceptsJson) {
+        res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
+        res.end(
+          JSON.stringify({
+            ok: true,
+            verified: true,
+            message: `Welcome to Daily Grind Rewards! Your email (${verification.email}) was cryptographically verified by your browser via ${verification.issuer} with no OTP or magic link required.`,
+            account,
+            nonce: nextNonce,
+          })
+        );
+      } else if (options.renderIndexHtml) {
+        const html = await options.renderIndexHtml(
+          nextNonce,
+          `<div class="rewards-alert rewards-alert-success" role="status">
+            <strong>Welcome to Daily Grind Rewards, ${escapeHtml(account.name)}!</strong>
+            Your email (<code>${escapeHtml(account.email)}</code>) was verified directly by your browser via <code>${escapeHtml(account.issuer)}</code> — 150 bonus beans have been added to your account!
+          </div>`
+        );
+        res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
+        res.end(html);
+      } else {
+        res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
+        res.end(`Verified: ${account.email}`);
+      }
+      return true;
+    } catch (verifyErr) {
+      const errMessage = verifyErr instanceof Error ? verifyErr.message : "Email token verification failed.";
+      if (acceptsJson) {
+        res.writeHead(400, { "Content-Type": "application/json; charset=utf-8" });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            verified: false,
+            error: errMessage,
+            nonce: nextNonce,
+          })
+        );
+      } else if (options.renderIndexHtml) {
+        const html = await options.renderIndexHtml(
+          nextNonce,
+          `<div class="rewards-alert rewards-alert-error" role="alert"><strong>Verification failed:</strong> ${escapeHtml(errMessage)}</div>`
+        );
+        res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
+        res.end(html);
+      } else {
+        res.writeHead(400, { "Content-Type": "text/plain; charset=utf-8" });
+        res.end(errMessage);
+      }
+      return true;
+    }
+  }
+
+  return false;
+}

