+export class CoffeeOrderDrawer extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._items = [];
+    this._open = false;
+    this._lastTrigger = null;
+    this._onOrderAdd = this._onOrderAdd.bind(this);
+    this._onDrawerToggle = this._onDrawerToggle.bind(this);
+    this._onKeyDown = this._onKeyDown.bind(this);
+  }
+
+  connectedCallback() {
+    document.addEventListener('coffee-order-add', this._onOrderAdd);
+    document.addEventListener('coffee-order-toggle', this._onDrawerToggle);
+    document.addEventListener('keydown', this._onKeyDown);
+    this.render();
+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('coffee-order-add', this._onOrderAdd);
+    document.removeEventListener('coffee-order-toggle', this._onDrawerToggle);
+    document.removeEventListener('keydown', this._onKeyDown);
+  }
+
+  get totalCount() {
+    return this._items.reduce((sum, item) => sum + item.quantity, 0);
+  }
+
+  get subtotal() {
+    return this._items
+      .reduce((sum, item) => sum + item.price * item.quantity, 0)
+      .toFixed(2);
+  }
+
+  _onOrderAdd(event) {
+    const detail = event.detail || {};
+    const key = `${detail.title || 'Coffee'}__${detail.size || '12oz'}__${detail.milk || 'Default'}`;
+    const existing = this._items.find((i) => i.key === key);
+
+    if (existing) {
+      existing.quantity += 1;
+    } else {
+      this._items.push({
+        key,
+        title: detail.title || 'Coffee',
+        size: detail.size || '12oz',
+        milk: detail.milk || '',
+        price: typeof detail.price === 'number' ? detail.price : parseFloat(detail.price || '4.50'),
+        quantity: 1
+      });
+    }
+
+    this._emitOrderUpdated();
+    this.render();
+  }
+
+  _onDrawerToggle(event) {
+    this._lastTrigger = event.detail?.trigger || document.activeElement;
+    if (this._open) {
+      this.close();
+    } else {
+      this.open();
+    }
+  }
+
+  _onKeyDown(event) {
+    if (this._open && event.key === 'Escape') {
+      event.preventDefault();
+      this.close();
+    }
+  }
+
+  open() {
+    this._open = true;
+    this.setAttribute('open', '');
+    this.render();
+    const closeBtn = this.shadowRoot.querySelector('.drawer-close');
+    if (closeBtn) {
+      closeBtn.focus();
+    }
+  }
+
+  close() {
+    this._open = false;
+    this.removeAttribute('open');
+    this.render();
+    if (this._lastTrigger && typeof this._lastTrigger.focus === 'function') {
+      this._lastTrigger.focus();
+    }
+  }
+
+  updateQuantity(key, delta) {
+    const idx = this._items.findIndex((i) => i.key === key);
+    if (idx === -1) return;
+    this._items[idx].quantity += delta;
+    if (this._items[idx].quantity <= 0) {
+      this._items.splice(idx, 1);
+    }
+    this._emitOrderUpdated();
+    this.render();
+  }
+
+  clearOrder() {
+    this._items = [];
+    this._emitOrderUpdated();
+    this.render();
+  }
+
+  _emitOrderUpdated() {
+    document.dispatchEvent(
+      new CustomEvent('coffee-order-updated', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          count: this.totalCount,
+          subtotal: this.subtotal,
+          items: [...this._items]
+        }
+      })
+    );
+  }
+
+  render() {
+    const count = this.totalCount;
+    const subtotal = this.subtotal;
+
+    this.shadowRoot.innerHTML = `
+      <style>
+        :host {
+          --drw-primary: var(--primary, #4e342e);
+          --drw-secondary: var(--secondary, #d7ccc8);
