+              <div class="spec-item">
+                <strong>Origin</strong>
+                <span>${profile.origin}</span>
+              </div>
+              <div class="spec-item">
+                <strong>Recommended Method</strong>
+                <span>${profile.brewMethod}</span>
+              </div>
+              <div class="spec-item">
+                <strong>Water Temp</strong>
+                <span>${profile.temp}</span>
+              </div>
+              <div class="spec-item">
+                <strong>Body &amp; Acidity</strong>
+                <span>${profile.body} / ${profile.acidity}</span>
+              </div>
+            </div>
+          </div>
+
+          <div class="calculator-box" aria-label="Interactive Brew Calculator">
+            <h4>Interactive Brew Guide</h4>
+
+            <div class="control-group">
+              <label for="cups-slider">
+                <span>Servings (8 oz cups)</span>
+                <span id="cups-val">${this._cups} ${this._cups === 1 ? 'cup' : 'cups'}</span>
+              </label>
+              <input
+                id="cups-slider"
+                type="range"
+                class="cups-range"
+                min="1"
+                max="8"
+                step="1"
+                value="${this._cups}"
+                aria-valuemin="1"
+                aria-valuemax="8"
+                aria-valuenow="${this._cups}"
+              />
+            </div>
+
+            <div class="control-group">
+              <label>Brew Strength</label>
+              <div class="strength-group" role="group" aria-label="Select brew strength">
+                ${['mellow', 'standard', 'bold']
+                  .map(
+                    (st) => `
+                  <button
+                    type="button"
+                    class="strength-btn"
+                    data-strength="${st}"
+                    aria-pressed="${this._strength === st ? 'true' : 'false'}"
+                  >
+                    ${st.charAt(0).toUpperCase() + st.slice(1)}
+                  </button>
+                `
+                  )
+                  .join('')}
+              </div>
+            </div>
+
+            <div class="metrics-output" role="status" aria-live="polite">
+              <div>
+                <span class="metric-val">${coffeeGrams}g</span>
+                <span class="metric-lbl">Whole Bean Coffee</span>
+              </div>
+              <div>
+                <span class="metric-val">${waterMl}ml</span>
+                <span class="metric-lbl">Filtered Water</span>
+              </div>
+              <div>
+                <span class="metric-val">1:${effectiveRatio}</span>
+                <span class="metric-lbl">Golden Ratio</span>
+              </div>
+            </div>
+
+            <div class="recommend-bar">
+              <span>Featured Cafe Match: <strong>${profile.recommendedDrink}</strong></span>
+              <a href="${profile.recommendedHref}" class="recommend-link">Explore on Menu</a>
+            </div>
+          </div>
+        </div>
+      </section>
+    `;
+
+    this._bindEvents();
+  }
+
+  _bindEvents() {
+    const tablist = this.shadowRoot.querySelector('.tablist');
+    if (tablist) {
+      tablist.addEventListener('keydown', (e) => this.handleTabKeydown(e));
+    }
+
+    this.shadowRoot.querySelectorAll('.tab-btn').forEach((btn) => {
+      btn.addEventListener('click', () => {
+        this.selectRoast(btn.getAttribute('data-roast-tab'), false);
+      });
+    });
+
+    const cupsSlider = this.shadowRoot.querySelector('.cups-range');
+    if (cupsSlider) {
+      cupsSlider.addEventListener('input', (e) => {
+        this._cups = parseInt(e.target.value, 10) || 2;
+        this._updateCalculatorDisplay();
+      });
+    }
+
+    this.shadowRoot.querySelectorAll('.strength-btn').forEach((btn) => {
+      btn.addEventListener('click', () => {
+        this._strength = btn.getAttribute('data-strength') || 'standard';
+        this.shadowRoot.querySelectorAll('.strength-btn').forEach((b) => {
+          b.setAttribute(
+            'aria-pressed',
+            b.getAttribute('data-strength') === this._strength ? 'true' : 'false'
+          );
+        });
+        this._updateCalculatorDisplay();
+      });
+    });
+  }
+
+  _updateCalculatorDisplay() {
+    const profile = this.activeProfile;
+    const { waterMl, coffeeGrams, effectiveRatio } = this.calculateBrewMetrics(profile);
+    const cupsVal = this.shadowRoot.querySelector('#cups-val');
+    const slider = this.shadowRoot.querySelector('.cups-range');
+    const metricsOutput = this.shadowRoot.querySelector('.metrics-output');
+
+    if (cupsVal) {
+      cupsVal.textContent = `${this._cups} ${this._cups === 1 ? 'cup' : 'cups'}`;
+    }
+    if (slider) {
+      slider.setAttribute('aria-valuenow', String(this._cups));
+    }
+    if (metricsOutput) {
+      metricsOutput.innerHTML = `
+        <div>
+          <span class="metric-val">${coffeeGrams}g</span>
+          <span class="metric-lbl">Whole Bean Coffee</span>
+        </div>
+        <div>
+          <span class="metric-val">${waterMl}ml</span>
+          <span class="metric-lbl">Filtered Water</span>
+        </div>
+        <div>
+          <span class="metric-val">1:${effectiveRatio}</span>
+          <span class="metric-lbl">Golden Ratio</span>
+        </div>
+      `;
+    }
+  }
+}
+
+if (!customElements.get('coffee-roast-explorer')) {
+  customElements.define('coffee-roast-explorer', CoffeeRoastExplorer);
+}
