+import React from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+
+export interface ArticleUtilityMeta {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  readingTime?: number;
+  relatedArticles?: Array<{
+    slug: string;
+    title: string;
+    summary: string;
+    category: string;
+  }>;
+}
+
+interface Props {
+  article?: ArticleUtilityMeta;
+}
+
+const GET_ARTICLE_CONTENT_SCHEMA = {
+  type: 'object',
+  properties: {},
+} as const;
+
+const GET_ARTICLE_CONTENT_ANNOTATIONS = {
+  readOnlyHint: true,
+} as const;
+
+const BOOKMARK_CURRENT_ARTICLE_SCHEMA = {
+  type: 'object',
+  properties: {},
+} as const;
+
+const BOOKMARK_CURRENT_ARTICLE_ANNOTATIONS = {
+  readOnlyHint: false,
+} as const;
+
+const SHARE_CHANNELS = ['copy', 'facebook', 'x', 'whatsapp', 'email'] as const;
+
+const SHARE_CURRENT_ARTICLE_SCHEMA = {
+  type: 'object',
+  properties: {
+    channel: {
+      type: 'string',
+      enum: SHARE_CHANNELS,
+      default: 'copy',
+      description: 'Destination channel for sharing the article link.',
+    },
+  },
+} as const;
+
+const SHARE_CURRENT_ARTICLE_ANNOTATIONS = {
+  readOnlyHint: true,
+} as const;
+
+const LIST_ARTICLES_SCHEMA = {
+  type: 'object',
+  properties: {
+    category: {
+      type: 'string',
+      description: 'Optional category name to filter articles by.',
+    },
+  },
+} as const;
+
+const LIST_ARTICLES_ANNOTATIONS = {
+  readOnlyHint: true,
+} as const;
+
+export default function ArticleUtilities({ article }: Props) {
+  const isArticlePage = Boolean(article?.slug);
+
+  useWebMCP<Record<string, never>, unknown>({
+    name: 'get-current-article',
+    description: 'Extracts the full text, metadata, reading time, and related stories of the article currently open on the page.',
+    inputSchema: GET_ARTICLE_CONTENT_SCHEMA,
+    annotations: GET_ARTICLE_CONTENT_ANNOTATIONS,
+    enabled: isArticlePage,
+    execute: () => {
+      if (!article) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      const proseEl = document.querySelector('article .prose');
+      const bodyText = proseEl?.textContent?.trim() ?? '';
+      const headings = Array.from(document.querySelectorAll('article .prose h2, article .prose h3')).map(
+        (h) => h.textContent?.trim() ?? ''
+      );
+      const wordCount = bodyText ? bodyText.split(/\s+/).length : 0;
+
+      return {
+        slug: article.slug,
+        title: article.title,
+        summary: article.summary,
+        author: article.author,
+        date: article.date,
+        category: article.category,
+        readingTimeMinutes: article.readingTime ?? Math.max(1, Math.ceil(wordCount / 200)),
+        wordCount,
+        headings,
+        bodyText,
+        relatedArticles: article.relatedArticles ?? [],
+        url: window.location.href,
+      };
+    },
+  });
+
+  useWebMCP<Record<string, never>, unknown>({
+    name: 'bookmark-current-article',
+    description: 'Toggles the reading list bookmark status for the article currently open on the page.',
+    inputSchema: BOOKMARK_CURRENT_ARTICLE_SCHEMA,
+    annotations: BOOKMARK_CURRENT_ARTICLE_ANNOTATIONS,
+    enabled: isArticlePage,
+    execute: async (_input, { signal }) => {
+      if (!article?.slug) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      try {
+        const response = await fetch(`${import.meta.env.BASE_URL}api/reading-list.json`, {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ slug: article.slug }),
+          signal,
+        });
+        if (!response.ok) {
+          return { error: `Failed to update bookmark (status ${response.status}).` };
+        }
+        const data = await response.json();
+        const readingList: string[] = Array.isArray(data.readingList) ? data.readingList : [];
+        const isBookmarked = readingList.includes(article.slug);
+
+        window.dispatchEvent(
+          new CustomEvent('reading-list-updated', { detail: { readingList } })
+        );
+
+        return {
+          slug: article.slug,
+          title: article.title,
+          action: isBookmarked ? 'bookmarked' : 'removed',
+          isBookmarked,
+          readingList,
+        };
+      } catch (err) {
+        if (signal.aborted) {
+          throw err;
+        }
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+  });
+
+  useWebMCP<{ channel?: (typeof SHARE_CHANNELS)[number] }, unknown>({
+    name: 'share-current-article',
+    description: 'Generates a shareable link or copies the URL for the article currently open on the page.',
+    inputSchema: SHARE_CURRENT_ARTICLE_SCHEMA,
+    annotations: SHARE_CURRENT_ARTICLE_ANNOTATIONS,
+    enabled: isArticlePage,
+    execute: async (input) => {
+      if (!article) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      const channel = input?.channel ?? 'copy';
+      if (!SHARE_CHANNELS.includes(channel)) {
+        return {
+          error: 'Pass a supported share channel.',
+          supportedChannels: SHARE_CHANNELS,
+        };
+      }
+      const url = window.location.href;
+      const encodedUrl = encodeURIComponent(url);
+      const encodedTitle = encodeURIComponent(article.title);
+
+      let shareUrl = url;
+      let copiedToClipboard = false;
+
+      if (channel === 'copy') {
+        if (navigator.clipboard?.writeText) {
+          try {
+            await navigator.clipboard.writeText(url);
+            copiedToClipboard = true;
+          } catch {
+            copiedToClipboard = false;
+          }
+        }
+      } else if (channel === 'facebook') {
+        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`;
+      } else if (channel === 'x') {
+        shareUrl = `https://x.com/intent/tweet?url=${encodedUrl}&text=${encodedTitle}`;
+      } else if (channel === 'whatsapp') {
+        shareUrl = `https://api.whatsapp.com/send?text=${encodedTitle}%20${encodedUrl}`;
+      } else if (channel === 'email') {
+        shareUrl = `mailto:?subject=${encodedTitle}&body=${encodedUrl}`;
+      }
+
+      return {
+        slug: article.slug,
+        title: article.title,
+        channel,
+        url,
+        shareUrl,
+        copiedToClipboard,
+      };
+    },
+  });
+
+  useWebMCP<{ category?: string }, unknown>({
+    name: 'list-articles',
+    description: 'Lists published articles across The DevTools Times, optionally filtered by category.',
+    inputSchema: LIST_ARTICLES_SCHEMA,
+    annotations: LIST_ARTICLES_ANNOTATIONS,
+    execute: async (input, { signal }) => {
+      const categoryFilter = typeof input?.category === 'string' ? input.category.trim().toLowerCase() : '';
+      try {
+        const response = await fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal });
+        if (!response.ok) {
+          return { error: `Failed to fetch articles (status ${response.status}).` };
+        }
+        const catalog: Array<{
+          slug: string;
+          title: string;
+          summary: string;
+          category?: string;
+          author?: string;
+          readingTime?: number;
+        }> = await response.json();
+
+        const filtered = categoryFilter
+          ? catalog.filter((a) => (a.category ?? '').toLowerCase() === categoryFilter)
+          : catalog;
+
+        return {
+          count: filtered.length,
+          category: categoryFilter || 'all',
+          articles: filtered.map((a) => ({
+            slug: a.slug,
+            title: a.title,
+            summary: a.summary,
+            category: a.category,
+            author: a.author,
+            readingTime: a.readingTime,
+            url: `${import.meta.env.BASE_URL}articles/${a.slug}`,
+          })),
+        };
+      } catch (err) {
+        if (signal.aborted) {
+          throw err;
+        }
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+  });
+
+  return null;
+}
